(function(root){const data={"version":1,"updated":"2026-10-16","modules":[{"id":"01","title":"先建立通用 AI 使用与选择能力","displayTitle":"先建立通用 AI 使用与选择能力","count":4,"short":"通用 AI 使用与选择","description":"先判断适合什么任务，再学会选择工具与核对结果。","prerequisites":[],"lessons":[{"id":"01.01","title":"什么任务适合交给 AI"},{"id":"01.02","title":"先做一次资料整理与方案比较"},{"id":"01.03","title":"怎样选择工具、模型与输入形式"},{"id":"01.04","title":"账号、费用与资料边界"}]},{"id":"02","title":"用 Codex 尽早做出可用小作品","displayTitle":"用 Codex 尽早做出可用小作品","count":6,"short":"用 Codex 做出小作品","description":"做出能添加、完成与保存任务的本地小工具。","prerequisites":["01"],"lessons":[{"id":"02.01","title":"认识项目、对话与操作范围"},{"id":"02.02","title":"写出一个最小需求"},{"id":"02.03","title":"第一次打开和修改页面"},{"id":"02.04","title":"第一次添加任务与改变状态"},{"id":"02.05","title":"第一次让数据留下来"},{"id":"02.06","title":"检查、修改与恢复早期作品"}]},{"id":"03","title":"计算机与最小代码阅读能力","displayTitle":"计算机与最小代码阅读能力","count":9,"short":"计算机与代码阅读","description":"找到文件、读懂关键代码、解释动作与数据的关系。","prerequisites":["02"],"lessons":[{"id":"03.01","title":"文件、目录与引用路径"},{"id":"03.02","title":"浏览器、编辑器与终端"},{"id":"03.03","title":"本地文件、服务与端口"},{"id":"03.04","title":"变量、对象与数组"},{"id":"03.05","title":"函数、条件与事件"},{"id":"03.06","title":"等待、异步与错误"},{"id":"03.07","title":"运行时、依赖与配置"},{"id":"03.08","title":"命令、工作目录与报错"},{"id":"03.09","title":"版本差异与 Git"}]},{"id":"04","title":"建立准确的 AI 基础理解","displayTitle":"准确的 AI 基础理解","count":7,"short":"理解 AI 的工作方式","description":"理解 AI 的能力边界、常见误区与正确用法。","prerequisites":["01"],"lessons":[{"id":"04.01","title":"从 AI 到大模型的概念地图"},{"id":"04.02","title":"从数据到能力：训练与使用"},{"id":"04.03","title":"文本如何成为输入：Token 与向量"},{"id":"04.04","title":"神经网络、注意力与 Transformer"},{"id":"04.05","title":"回答如何生成：概率与变化"},{"id":"04.06","title":"上下文、历史与记忆"},{"id":"04.07","title":"能力边界与可信判断"}]},{"id":"05","title":"学会指挥、质疑与验证 AI","displayTitle":"学会指挥、质疑与验证 AI","count":6,"short":"指挥、质疑与验证 AI","description":"把目标说清楚，用证据纠偏，换一个任务也能继续。","prerequisites":["01","04"],"lessons":[{"id":"05.01","title":"明确成果与验收条件"},{"id":"05.02","title":"补充上下文：AI 为什么会答非所问"},{"id":"05.03","title":"限制、示例与冲突处理"},{"id":"05.04","title":"小步计划与变更控制"},{"id":"05.05","title":"长任务、工具结果与项目交接"},{"id":"05.06","title":"纠偏与独立需求练习"}]},{"id":"06","title":"前端与基本设计判断","displayTitle":"前端与基本设计判断","count":7,"short":"前端与设计判断","description":"把结构、表现和交互接起来，检查电脑与手机体验。","prerequisites":["02","03","05"],"lessons":[{"id":"06.01","title":"HTML：内容结构与语义"},{"id":"06.02","title":"读参考图，作出设计判断"},{"id":"06.03","title":"CSS：布局与响应式"},{"id":"06.04","title":"JavaScript：状态与渲染"},{"id":"06.05","title":"表单与边界状态"},{"id":"06.06","title":"开发者工具与有关证据"},{"id":"06.07","title":"完善交互与体验验收"}]},{"id":"07","title":"本地数据：从显示到可靠保存","displayTitle":"本地数据：从显示到可靠保存","count":4,"short":"本地保存与恢复","description":"让任务可靠留下来，理解保存范围并练习异常恢复。","prerequisites":["06"],"lessons":[{"id":"07.01","title":"运行中的状态与文件"},{"id":"07.02","title":"浏览器存储与 JSON"},{"id":"07.03","title":"数据异常、导出与恢复"},{"id":"07.04","title":"从本地工具提出联网需求"}]},{"id":"08","title":"后端与 API：跟踪一条请求","displayTitle":"后端与 API：跟踪一条请求","count":7,"short":"后端与 API","description":"跟踪请求、响应与后端规则，处理等待和失败。","prerequisites":["07"],"lessons":[{"id":"08.01","title":"一次点击怎样变成网络请求"},{"id":"08.02","title":"后端负责什么，在哪里运行"},{"id":"08.03","title":"先约定接口，再让两端实现"},{"id":"08.04","title":"从后端读取任务"},{"id":"08.05","title":"把修改交给后端验证"},{"id":"08.06","title":"等待、失败与重复操作"},{"id":"08.07","title":"用证据定位联调问题"}]},{"id":"09","title":"数据库：组织、约束与恢复数据","displayTitle":"数据库：组织、约束与恢复数据","count":7,"short":"数据库","description":"组织、查询与约束记录，验证持久保存和恢复。","prerequisites":["08"],"lessons":[{"id":"09.01","title":"从一条任务认识数据库"},{"id":"09.02","title":"表、字段、类型与主键"},{"id":"09.03","title":"用户、任务与关联"},{"id":"09.04","title":"用查询完成增删改查"},{"id":"09.05","title":"约束与索引各解决什么"},{"id":"09.06","title":"多步修改、事务与并发"},{"id":"09.07","title":"结构变更、备份与持久验收"}]},{"id":"10","title":"用户身份与数据隔离","displayTitle":"用户身份与数据隔离","count":5,"short":"身份与数据隔离","description":"区分身份与权限，用两个账户核对允许和拒绝。","prerequisites":["09"],"lessons":[{"id":"10.01","title":"识别身份与判断权限"},{"id":"10.02","title":"登录状态怎样被使用"},{"id":"10.03","title":"将规则落实到数据访问"},{"id":"10.04","title":"密钥、配置与浏览器可见信息"},{"id":"10.05","title":"两账户独立验收"}]},{"id":"11","title":"部署上线：从自己的电脑到真实访问","displayTitle":"部署上线：从自己的电脑到真实访问","count":7,"short":"部署上线","description":"把前后端和数据库发布到实际可访问的环境。","prerequisites":["10"],"lessons":[{"id":"11.01","title":"拆清部署对象与环境"},{"id":"11.02","title":"准备可重复的发布版本"},{"id":"11.03","title":"准备线上数据库"},{"id":"11.04","title":"部署后端与配置环境"},{"id":"11.05","title":"发布前端并接通服务"},{"id":"11.06","title":"域名、HTTPS 与访问路径"},{"id":"11.07","title":"换设备完成上线验收"}]},{"id":"12","title":"验证、更新与恢复","displayTitle":"验证、更新与恢复","count":5,"short":"更新与恢复","description":"验证小步变更，定位问题，演练版本回退和数据恢复。","prerequisites":["11"],"lessons":[{"id":"12.01","title":"从手动清单到有意义的测试"},{"id":"12.02","title":"用请求与日志定位线上问题"},{"id":"12.03","title":"小步更新与版本回退"},{"id":"12.04","title":"备份有效性与恢复演练"},{"id":"12.05","title":"面向小规模真实试用的交接"}]},{"id":"13","title":"独立创作与迁移验收","displayTitle":"独立创作与迁移验收","count":6,"short":"独立创作","description":"更换真实需求，独立完成设计、实现、上线与复盘。","prerequisites":["12"],"lessons":[{"id":"13.01","title":"选择一个新的真实问题"},{"id":"13.02","title":"独立写需求与确认原型"},{"id":"13.03","title":"解释架构与数据决定"},{"id":"13.04","title":"推进实现并处理失败"},{"id":"13.05","title":"上线、变更与恢复验收"},{"id":"13.06","title":"演示、解释与复盘"}]}],"routes":{"R1":["01","04","05"],"R2":["01","02","03","04","05","06","07"],"R3":["01","02","03","04","05","06","07","08","09","10","11","12","13"]},"routeInfo":{"R1":{"label":"通用 AI","description":"用资料整理与方案比较，建立选择、协作与核实能力。"},"R2":{"label":"本地创作","description":"用 Codex 制作可修改、可保存、可恢复的本地工具。"},"R3":{"label":"联网应用","description":"从基础理解，到带数据库的联网作品。"}},"lessons":[{"id":"01.01","title":"什么任务适合交给 AI","lead":"你有一页活动记录、一条今天的通知和一张费用表，为什么不该把三件事都交给同一种回答方式？","goals":["给三个日常任务各写一张处理卡：公开活动记录整理、最新开放时间核实、三项费用求和","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"先把任务拆成输入与结果","paragraphs":["适合交给 AI 的任务通常有可以提供的输入，也有你能检查的结果。把活动记录整理成三项待办，输入是记录，输出是待办清单；你能逐条回查人名、动作和期限。任务越模糊，模型需要自行补的假设越多，结果就越可能偏离真实需要。","例如把“帮我办好活动”改成“仅依据下方记录提取已确定的时间和负责人，未确定项单列”，就把不可检查的愿望变成可比较的结果。反例是让模型直接决定谁承担责任：材料没有授权时，它写得肯定也不能使决定生效。"]},{"title":"按证据选择处理方式","paragraphs":["生成指根据输入组织新的表达，搜索指检索已有资料。搜索解决的是到哪里找资料，生成解决的是如何组合表达，计算器或表格解决的是按确定规则处理数字。这些能力可以组合，但不能互相代替。最新开馆时间需要当前官方公告，已有公告的摘要可由 AI 帮忙，费用求和则应让表格公式计算并抽查。","你不是在评选最聪明的工具，而是在选择最短的可靠证据链。让模型凭记忆报出今日票价，缺少时效依据；让它调用计算工具也仍须核对输入是否漏了一行。先明确错误会在哪里发生，再决定让哪种工具承担哪段工作。"]},{"title":"创意草稿也有验收","paragraphs":["文字、图片和音视频都可先用于探索，草稿的价值是让抽象想法变得可以讨论。评价海报创意时要看信息层级与用途，评价音频时要听姓名发音与停顿，不能只因第一次看见新奇画面就判定任务完成。","例如为社区读书会写三种开场语，允许表达变化，但地点和时间仍应一致。反例是图片视觉很好却把日期写错。生成媒介改变了产出方式，没有消除事实、可读性与使用场景的检查责任。"]},{"title":"按后果决定人要参与多深","paragraphs":["错误代价越大、越难发现或越难撤回，越需要独立资料和人的判断。可用性不是只有“能做”与“不能做”，还包含可否限定为草稿、是否能先在演示材料上试、谁负责最终确认。","整理十条公开留言可抽查原文；涉及个人利益的决定不能仅凭摘要执行。先用小样本找到常见错误，再扩大范围，比一次处理所有材料更容易定位问题。完成依据应是核对记录，而不是回答长度或语气自信。"]}],"glossary":[{"term":"证据链","meaning":"从结论回到输入、处理步骤与核对资料的可追溯关系。"},{"term":"验收","meaning":"按事先写明的条件检查结果是否达到用途。"},{"term":"生成","meaning":"根据输入组织出新的表达或内容，结果仍需按用途核对。"}],"predict":{"question":"需要知道今天活动是否因天气取消，手边只有上月宣传文。先做什么？","options":[{"text":"查主办方当前公告，记录日期后再整理","correct":true,"feedback":"取消状态随时间变化，旧文不能提供今日证据。"},{"text":"先让模型根据往年规律给结论","correct":false,"feedback":"规律可以提示风险，不能替代本次主办方决定。"},{"text":"把上月宣传文总结得更短","correct":false,"feedback":"旧宣传文仍只包含上月信息，压缩篇幅不能提供今天是否取消的依据。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"资料完整","input":"记录：小林周五18点前提交书单；场地尚未确定。","question":"对于本次活动资料和费用核对，最适合先交付什么？","options":[{"text":"一份含场地的完整执行计划","correct":false,"feedback":"地点未经确认却被填满，完整计划的外观会掩盖这项关键证据缺失。"},{"text":"带来源的待办与未定事项","correct":true,"feedback":"输入足以提取负责人和期限，但不支持补出场地。"},{"text":"先等待场地确认，再提取全部待办","correct":false,"feedback":"场地未知不阻止提取小林已有的负责人和期限，可先交确定项并单列待确认。"}],"output":"教学推演：提取小林提交书单这一待办，期限为周五18点；场地单列待确认，不凭常见活动安排补地点。","evidence":["原文有负责人和期限","结果没有擅自填入场地"]},{"name":"数字需要确定计算","input":"费用：场地120元、资料80元、茶水35元；有人声称合计225元。","question":"对于本次活动资料和费用核对，怎样最可靠地处理？","options":[{"text":"选两次回答中重复的数字","correct":false,"feedback":"多次回答可能沿用同一算式错误，应逐个核对三个加数而不是数赞成票。"},{"text":"只润色225元的说明","correct":false,"feedback":"润色只改变说法，原来的225元仍与三个加数合计235元不符。"},{"text":"用确定计算得到235元并对照三行","correct":true,"feedback":"加法结果可独立检查，需确认三项都进入计算。"}],"output":"教学推演：三个加数120、80、35的确定合计为235元；原来的225元少10元，润色不能纠正这个数字差异。","evidence":["列出三个加数","反向核对235-120-80=35"]}]},"practice":{"intro":"给三个日常任务各写一张处理卡：公开活动记录整理、最新开放时间核实、三项费用求和。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["写出每项的原始输入、想得到的结果和错误代价","分别选择对话生成、官方搜索、表格或人工核对，可组合使用","用本课演示资料先完成活动待办，给每条标原文位置","独立算出费用，记录与草稿差异，再为自己的任务写同类核对办法"],"prompt":"本次练习是 01.01《什么任务适合交给 AI》。给三个日常任务各写一张处理卡：公开活动记录整理、最新开放时间核实、三项费用求和。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：写出每项的原始输入、想得到的结果和错误代价；分别选择对话生成、官方搜索、表格或人工核对，可组合使用；用本课演示资料先完成活动待办，给每条标原文位置；独立算出费用，记录与草稿差异，再为自己的任务写同类核对办法。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：三张处理卡与选择理由；含原文位置的待办清单；至少一项已纠正的错误与独立核对依据。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["三张处理卡与选择理由","含原文位置的待办清单","至少一项已纠正的错误与独立核对依据"],"troubleshooting":[{"symptom":"AI 总结补出了地点","check":"核对地点能否指向材料中的一句话","action":"删除无依据地点，标为待确认，并重新检查其他专有名词。"},{"symptom":"不同回答给出不同费用","check":"核对加数、单位和遗漏行","action":"改用表格或计算器，保留算式，不用多数票决定金额。"}]},"checks":[{"question":"把相同材料重复问三次且答案相同，能证明什么？","options":[{"text":"只能说明这几次输出一致","correct":true,"feedback":"一致性可观察，但事实正确还需原文或外部证据。"},{"text":"事实已经得到三次独立验证","correct":false,"feedback":"三次结果共享模型与输入，不能视作来自三个独立渠道的事实核验。"},{"text":"必须换一个更长提示词才能判断","correct":false,"feedback":"提示词写长可以表达要求，却不能替代原始公告、算式等独立核对依据。"}]},{"question":"要写活动邀请语，时间地点已经确认，哪种安排合适？","options":[{"text":"把每一种措辞都作为必须执行的决定","correct":false,"feedback":"邀请语的措辞是草稿建议，没有改变活动安排或授权执行的效力。"},{"text":"让 AI 提供风格草稿，再核对固定信息","correct":true,"feedback":"表达可以探索，事实仍按确认材料验收。"},{"text":"先删去固定信息避免它影响创意","correct":false,"feedback":"删去已确认时间地点会让模型有更多空白可猜，反而增加误补事实机会。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/prompt-engineering","checked":"2026-10-16"}]},{"id":"01.02","title":"先做一次资料整理与方案比较","lead":"两份摘要都写得顺畅，其中一份却凭空多了一项服务，怎样在选择方案前发现它？","goals":["用本课 A/B 资料制作一张可追溯的比较表，并在需求变化后修订","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"总结先受材料约束","paragraphs":["来源是事实对应的原始材料或出处。总结是压缩和组织已有信息，补充事实则是引入材料以外的内容。两者可能出现在同一段回答里，所以要先约定哪些事实只能来自给定材料。把资料编号为 A、B，要求每个结论注明编号，可以让核对工作从凭印象阅读变成逐项查找。","本课材料 A 为社区教室：周六可用，20个座位，费用100元；材料 B 为咖啡馆：周日可用，12个座位，费用80元。材料没有说投影设备。如果摘要写了“教室含投影”，即使听起来合理，仍属于无依据补充。"]},{"title":"比较标准先于推荐","paragraphs":["推荐是在目标和标准下作判断，不能只把两个简介并排。先写硬条件，例如周六、至少15人；再写偏好，例如费用低。硬条件不满足的方案应明确标出，不能因为便宜就悄悄降低容量要求。","在上述材料中，A 满足时间和座位要求，B 虽便宜却不满足两项硬条件。若需求改为周日10人，结论会变化。变化来自使用条件改变，不是模型前后矛盾；没有写明条件的“最佳方案”往往无法复用。"]},{"title":"事实、推断与建议分开表达","paragraphs":["事实是材料明确提供的内容；推断是依据事实和规则得到的判断；建议是为下一步提出的行动。把三者分开，读者才能知道哪些可直接引用，哪些需要确认。事实可附材料编号，推断可附判断规则，建议应说明前提。","“A有20座”是事实，“可容纳15人”是基于人数的推断，“预订前询问投影”是建议。反例是把建议写成“已提供投影”，这把尚未发生的确认动作变成了事实，也会让后续方案比较失真。"]},{"title":"缺信息要影响结论的强度","paragraphs":["未知项不应当作零，也不能默认满足。若投影是必要条件而两份材料都没写，当前只能形成候选排序，不能给出已满足全部要求的最终推荐。先列待确认问题，能防止下一位协作者把暂定结论当成定案。","检查时不必逐字挑同义改写，而要核对数量、时间、否定词和条件。将“可用”改成“已预订”就是意义变化。验收一份摘要时，可要求每项都能回到材料，并故意加入一个无答案问题，检验它是否诚实保留未知。"]}],"glossary":[{"term":"硬条件","meaning":"不满足就不能采用的要求，例如必须周六开放。"},{"term":"推断","meaning":"以已有信息和明确规则推出的判断，强度受前提限制。"},{"term":"来源","meaning":"某项事实对应的原始材料或出处，可用于回查依据。"}],"predict":{"question":"需周六15人，B 周日12座却更便宜，推荐应怎样写？","options":[{"text":"B最低价，所以总体最适合","correct":false,"feedback":"B便宜20元，但周日和12座仍不满足周六15人的实际使用门槛。"},{"text":"把缺少投影信息记作没有投影","correct":false,"feedback":"资料未提设备只是未知；写没有设备则新增了原文不存在的否定事实。"},{"text":"先排除不满足硬条件的B，A待确认其他必要项","correct":true,"feedback":"费用属于偏好，不能抵消无法在指定时间容纳指定人数的硬性失败。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"硬条件已知","input":"A：周六20座100元；B：周日12座80元。需求周六15人，无设备要求。","question":"在当前场地资料与门槛下，哪项判断有依据？","options":[{"text":"A满足已知门槛，B不满足","correct":true,"feedback":"A的周六与20座满足门槛，B的周日与12座分别不满足时间与人数。"},{"text":"A一定比B安静","correct":false,"feedback":"资料只列时间容量费用，没有噪声或安静程度，不能据此比较声音环境。"},{"text":"B可以临时增加三把椅子","correct":false,"feedback":"能否增加椅子属于新增容量条件，原文没授权也没提供可扩容证据。"}],"output":"教学推演：A满足周六与15人的已知门槛；B因周日开放且只有12座被排除；噪声环境未提供，不纳入确定推荐理由。","evidence":["时间逐项匹配","人数20≥15，12\u003c15"]},{"name":"必要信息缺失","input":"仍用A/B资料，但新增硬条件：必须可投影。","question":"在当前场地资料与门槛下，接下来怎么办？","options":[{"text":"继续把A标为全部满足","correct":false,"feedback":"旧结论仅基于日期人数，新增投影门槛后必须补设备证据才能最终推荐。"},{"text":"先询问设备，保留暂定候选","correct":true,"feedback":"两份资料都没说设备，因此只能保留候选并询问，不能判定全部满足。"},{"text":"认定两家都无设备","correct":false,"feedback":"资料沉默只说明未提供信息，不足以推出两家都没有设备这一否定结论。"}],"output":"教学推演：新增投影硬条件后，A只是暂定候选；两家设备均未知，需先询问，不能把原来满足日期人数写成全部满足。","evidence":["新增条件单独列出","没有把未知填成是或否"]}]},"practice":{"intro":"用本课 A/B 资料制作一张可追溯的比较表，并在需求变化后修订。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["复制 A/B 原文，为每句编号","写周六15人的硬条件与费用偏好","整理事实、推断、建议三栏，并追溯每项来源","加入投影必要条件，记录旧结论为何需要降为暂定"],"prompt":"本次练习是 01.02《先做一次资料整理与方案比较》。用本课 A/B 资料制作一张可追溯的比较表，并在需求变化后修订。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：复制 A/B 原文，为每句编号；写周六15人的硬条件与费用偏好；整理事实、推断、建议三栏，并追溯每项来源；加入投影必要条件，记录旧结论为何需要降为暂定。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：原始材料与编号；两版比较表和变化理由；发现并删除无依据投影描述的记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["原始材料与编号","两版比较表和变化理由","发现并删除无依据投影描述的记录"],"troubleshooting":[{"symptom":"表格看起来完整但出现新服务","check":"逐格询问对应原文位置","action":"将找不到位置的内容移入待确认，不为填满表格猜答案。"},{"symptom":"更改人数后推荐没变化","check":"核对实际用于比较的需求版本","action":"重列硬条件再逐行判断，说明旧结论是否仍成立。"}]},"checks":[{"question":"材料写“可容纳20人”，摘要写“已确认有20人参加”，问题在哪？","options":[{"text":"只是更自然的表达","correct":false,"feedback":"容量与报名人数属于不同事实对象，表达再自然也不能把两者互换。"},{"text":"需要把20改成约20即可","correct":false,"feedback":"把20改成约20仍在声称报名人数，未纠正把容量当参加人数的对象错误。"},{"text":"把场地容量换成了实际报名事实","correct":true,"feedback":"20座是最多容纳能力，不代表已经有20人报名参加，数字相同也不能混同。"}]},{"question":"两方案都缺设备信息，最合理的表格值是什么？","options":[{"text":"未知，附待询问事项","correct":true,"feedback":"未知一栏明确指出尚需询问的设备信息，能让下一步收集证据有具体目标。"},{"text":"都填否，比较才完整","correct":false,"feedback":"填否表示确认没有设备，但原文只是不提设备，两者证据强度不同。"},{"text":"都填是，反正之后还会核对","correct":false,"feedback":"后续核对可能遗漏，当前应保留真实状态。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/prompt-engineering","checked":"2026-10-16"}]},{"id":"01.03","title":"怎样选择工具、模型与输入形式","lead":"同一个模型在两个产品里给出不同结果，差异一定来自模型本身吗？","goals":["设计并实际执行一个两种处理方式的小比较；工具不可用时保留方案并标记未执行","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"产品包着模型与工具","paragraphs":["模型是根据输入生成结果的计算系统，产品是让人使用它的软件。产品还可能提供搜索、文件读取、代码执行和保存记录。模型名称相同，不代表产品提供相同资料、权限和操作入口；观察到的差异可能发生在这些环节。","例如一个对话入口只能看到你粘贴的三行文字，另一个入口实际读取完整文件。后者摘要更完整，并不能单独证明模型更强。先记录输入与可用工具，再比较输出，才能避免把资料差异误当作能力差异。"]},{"title":"用自己的任务设计比较","paragraphs":["选择前先写一组有答案依据的小任务：原文提取、缺失信息处理和需求改变。每个候选使用相同材料和标准，记录产品、模型可见名称、日期、是否启用搜索。模型版本未显示时就写未显示，不能凭界面外观补出。","一次回答很惊艳可能是任务恰好熟悉，也可能是随机变化。至少保留成功和失败样本，并比较错误类型、修改成本和完成时间。反例是依据别人展示的一张成功截图做全面排名：你看不到未展示的任务与失败条件。"]},{"title":"输入形式影响信息损失","paragraphs":["文字便于准确复制，文件保留篇幅和结构，截图可表达布局，但小字可能看不清。选择输入形式的依据是任务需要保留什么信息。查合同中的具体条款应尽量提供可搜索原文，讨论界面位置则可用截图并标明目标区域。","截图里看见一个按钮，不代表产品工具能点击它；上传文件成功也不等于所有页都已被读取。要求先列读取范围、复述两条关键内容，再继续判断，可以发现截断、识别错误或错误附件。"]},{"title":"用限制与成本作最后筛选","paragraphs":["比较不只看结果质量，还要看当前账号能否访问、是否支持所需媒介、资源限制和资料使用条件。先排除不能满足必要条件的候选，再在可用候选中选稳定、可核验且成本可控的一种。没有必要为简单提取任务追逐名称更新。","把最终选择写成“在这批材料和这些条件下采用此方式”，比写“它永远最好”更准确。以后资料变成扫描件、要处理更多页或使用条件改变，复用相同小测试即可重新选择。课程不提供未经当日核验的价格与账号保证。"]}],"glossary":[{"term":"模型","meaning":"把输入转化为预测或生成结果的系统，不等于整个软件。"},{"term":"基准任务","meaning":"用于公平比较的一组固定输入与检查标准。"},{"term":"搜索","meaning":"检索资料的动作，不等于已理解或核实找到的每个页面。"}],"predict":{"question":"比较两个摘要工具，A读全文，B只收到前页，怎样解释差异？","options":[{"text":"A输出更长，模型必定更强","correct":false,"feedback":"全文工具可见资料更多，输出更长可能只反映输入范围，不能单独证明模型更强。"},{"text":"先统一读取范围再评价","correct":true,"feedback":"输入不等使当前结果不能单独归因于模型。"},{"text":"B必定不适合任何摘要","correct":false,"feedback":"一次不同条件的结果不能推广到所有任务。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"文字输入","input":"输入：A周六20座；B周日12座。统一要求只提取时间容量，不补缺项。","question":"在这次两种处理方式比较中，公平比较首先控制什么？","options":[{"text":"相同回答字数","correct":false,"feedback":"两份摘要字数相同仍可能各漏不同事实，公平性更需要相同材料和检查标准。"},{"text":"只需相同模型名称，不必统一材料","correct":false,"feedback":"名称相同也可能因可见材料与工具不同影响结果，公平比较仍要统一输入。"},{"text":"相同原文和相同提取标准","correct":true,"feedback":"统一材料与评价标准可以减少比较干扰，使差异更可能来自实际处理方式。"}],"output":"教学推演：按时间、容量、无依据新增三项建立核对表；本教材不伪造两模型成绩。","evidence":["原文完全一致","检查项目事先固定"]},{"name":"截图条件变化","input":"截图小字把12座看成72座，原始文本文件仍写12。","question":"在这次两种处理方式比较中，下一步优先做什么？","options":[{"text":"核对原文并提供清晰文字","correct":true,"feedback":"先修复输入识别问题，再评价比较推理。"},{"text":"多问几次投票决定座位数","correct":false,"feedback":"同一模糊截图可能反复误读12为72，多问几次并不能创造清晰数字证据。"},{"text":"换更有说服力的推荐语","correct":false,"feedback":"换推荐语只能改变表达，容量仍被误读，需要先对照可搜索原文纠正数字。"}],"output":"教学推演：先用可搜索原文把容量恢复为12座，并记录截图识别差异；这次输入误读不构成对模型全部能力的排名。","evidence":["引用原文12座","记录输入形式造成的信息差异"]}]},"practice":{"intro":"设计并实际执行一个两种处理方式的小比较；工具不可用时保留方案并标记未执行。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["准备含明确答案和一项未知信息的十行公开或自编资料","固定三个标准：事实对应、未知处理、修改后响应","在可用的两种方式中提交相同输入，记录日期、可见版本和工具状态","逐条记录结果与原文差异，再写只适用于该任务的选择结论"],"prompt":"本次练习是 01.03《怎样选择工具、模型与输入形式》。设计并实际执行一个两种处理方式的小比较；工具不可用时保留方案并标记未执行。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：准备含明确答案和一项未知信息的十行公开或自编资料；固定三个标准：事实对应、未知处理、修改后响应；在可用的两种方式中提交相同输入，记录日期、可见版本和工具状态；逐条记录结果与原文差异，再写只适用于该任务的选择结论。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：相同输入和固定评价表；真实输出或明确未执行说明；包含失败样本、限制和选择理由的记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["相同输入和固定评价表","真实输出或明确未执行说明","包含失败样本、限制和选择理由的记录"],"troubleshooting":[{"symptom":"找不到模型版本","check":"检查产品是否真实显示名称或版本","action":"写未显示并保留产品与日期，不猜测版本。"},{"symptom":"文件已上传但摘要漏后半段","check":"要求列实际读取章节并核对末尾一句","action":"缩小到相关段落重试，记录读取范围后再比较。"}]},"checks":[{"question":"讨论界面布局时选截图的主要理由是什么？","options":[{"text":"截图能证明操作已经成功","correct":false,"feedback":"截图只记录画面，不能自动证明动作链。"},{"text":"保留位置关系并补充必要文字","correct":true,"feedback":"位置是任务需要的信息，文字可弥补小字识别。"},{"text":"图片输入通常比文字事实更准确","correct":false,"feedback":"图片与文字准确性依赖清晰度、格式和任务，不能把某种媒介一概当成更准确。"}]},{"question":"一份小测试全对，可推出什么？","options":[{"text":"所有同类任务都不再需要核对","correct":false,"feedback":"小测试未覆盖的语言、篇幅或文件格式仍可能产生新错误，不能取消后续核对。"},{"text":"该模型一定比其他所有模型好","correct":false,"feedback":"没有相同条件下对其他模型的完整比较，不能由一次成功推出全面优胜。"},{"text":"在该测试条件下达到标准","correct":true,"feedback":"当前样本通过只说明这些条件下达到标准，换材料与需求后仍应复测。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/evaluation-best-practices","checked":"2026-10-16"}]},{"id":"01.04","title":"账号、费用与资料边界","lead":"你已经购买对话订阅，为什么外部程序的调用或数据库仍可能出现另一张账单？","goals":["完成一份资源和资料使用清单，先采用不新增收费资源的资料任务","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"把资源与付款位置分开","paragraphs":["订阅是某个产品的使用安排，API 是程序访问服务的接口，托管是让程序在远处运行的资源，数据库是保存与查询记录的资源。它们可能属于不同账户或不同计费系统。拥有其中一项，不代表其余项目已包含。","先画一张资源表：谁提供服务、谁拥有账户、在哪里查用量、怎样停止。本课不提供固定价格或免费保证。公开价目也不一定等于你的账户实际条件，最终应核对所在地区、计划、额度及当前账单说明。"]},{"title":"额度、提醒和硬上限不是一回事","paragraphs":["额度是可用资源的某种限制，提醒只是告知接近某个值，硬上限则是在适用条件下阻止继续消耗。不能因为设置提醒就推断费用绝不会超过目标。应按服务的官方说明核对限制的实际作用。","例如一项练习只需整理公开资料，完全可以不接入 API、托管或数据库。若选择外部项目，应先用少量演示数据，记录预算与停止方法，再开始操作。反例是删除本地文件后以为远程服务已关闭：文件与远程资源不在同一个位置。"]},{"title":"本次必要输入决定资料范围","paragraphs":["资料边界先问本次任务究竟需要哪些字段。让 AI 比较场地不需要参加者手机号，测试任务管理不需要真实客户姓名。删除身份信息或使用演示数据，可以保留任务结构，又减少不必要的资料流转。","仅把姓名换成编号并不保证无法识别；地址、罕见事件和单位组合也可能暴露身份。先判断是否有权提供，随后查数据如何传输和使用。不要把技术上能够上传当作已经获得资料使用授权。"]},{"title":"输入用途与服务政策分别核对","paragraphs":["你说“只用于摘要”表达的是任务要求，服务怎样保存或使用输入则由产品、账户条件、设置和政策共同决定。提示词不能自动改写服务政策，也不能把所有服务一概看作保密容器。","实际核对时记下官方页面、查看日期和与你账户有关的适用范围。无法确认时，先使用虚构资料完成学习，把未确认项写清。停止资源也要留证据：关闭服务、撤销不再需要的访问或按官方步骤取消资源，并再看状态。"]}],"glossary":[{"term":"API","meaning":"供程序按约定请求服务的接口，可能单独计费。"},{"term":"数据最小化","meaning":"只提供完成当前任务确有必要的信息。"},{"term":"托管","meaning":"让程序在远程资源上运行的服务，与本地文件不同。"}],"predict":{"question":"只有对话订阅，想让自写程序调用模型。先确认什么？","options":[{"text":"该接口的账户、计费和凭据条件","correct":true,"feedback":"当前对话订阅的权益不能自动扩展到API调用，应核对接口的账户和计费条件。"},{"text":"直接调用，因为都是同一品牌","correct":false,"feedback":"同一品牌的对话产品与程序接口可能采用独立账户或计费，需分别查权益。"},{"text":"删除本地聊天就能停止所有远程费用","correct":false,"feedback":"聊天记录与运行资源不属于同一控制点。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"资料可替换","input":"比较场地，只需日期、座位与费用，表中额外有联系人手机号。","question":"按本次资源和资料范围，怎样准备输入？","options":[{"text":"把手机号改字体颜色后上传原文件","correct":false,"feedback":"改字体颜色只影响显示，文件内部仍可能包含可恢复的手机号等个人字段。"},{"text":"移除无关个人字段，保留必要资料","correct":true,"feedback":"不影响比较任务，同时减少不必要暴露。"},{"text":"保留手机号方便模型更理解场地","correct":false,"feedback":"本次只按日期容量费用比较，联系电话不参与这些判断，没有必要提供。"}],"output":"教学推演：输入只保留演示场地、时间、容量与费用，另记来源，不上传联系人表。","evidence":["必要字段清单","已移除字段清单"]},{"name":"资源仍在运行","input":"本地项目删掉了，但远程测试服务状态仍显示运行。","question":"按本次资源和资料范围，合理的下一步是什么？","options":[{"text":"再次删除浏览器历史","correct":false,"feedback":"浏览器历史记录保存访问痕迹，不负责停止远程服务或终止其资源消耗。"},{"text":"只退出本地编辑器","correct":false,"feedback":"编辑器退出只结束本地工作，远程托管服务仍可能继续运行并产生用量。"},{"text":"按官方资源管理步骤停止并核对状态","correct":true,"feedback":"计费对象在远程，需对那个资源采取操作。"}],"output":"教学推演：资源停止列为待实际执行项目；课程不声称已经替学习者关闭任何服务。","evidence":["资源归属与标识","官方停止说明及实际状态待记录"]}]},"practice":{"intro":"完成一份资源和资料使用清单，先采用不新增收费资源的资料任务。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["列出本次对话、搜索及可选外部资源，分别记账户与计费位置","从当前官方页面核对用途、额度、数据使用及停止方式，未知项明确写未知","用虚构联系人与场地资料演练，移除不必要字段","设定个人可接受预算并写出停止触发条件；本练习不要求购买或新建服务"],"prompt":"本次练习是 01.04《账号、费用与资料边界》。完成一份资源和资料使用清单，先采用不新增收费资源的资料任务。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：列出本次对话、搜索及可选外部资源，分别记账户与计费位置；从当前官方页面核对用途、额度、数据使用及停止方式，未知项明确写未知；用虚构联系人与场地资料演练，移除不必要字段；设定个人可接受预算并写出停止触发条件；本练习不要求购买或新建服务。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：带官方链接和日期的资源表；脱敏前后字段对照与理由；预算、未知项和停止步骤说明。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["带官方链接和日期的资源表","脱敏前后字段对照与理由","预算、未知项和停止步骤说明"],"troubleshooting":[{"symptom":"页面价格与账户显示不同","check":"核对地区、套餐、税费及适用日期","action":"以自己的账户条件和官方说明继续核实，未确认前不启动收费练习。"},{"symptom":"删去姓名后仍可能认出个人","check":"检查地址、独特经历和组合字段","action":"换成完全自编演示数据，记录替换范围。"}]},"checks":[{"question":"提示词写“不要保存我的信息”，能证明服务未保存吗？","options":[{"text":"不能，需要核对服务政策和账户设置","correct":true,"feedback":"任务提示表达了输入用途，不能单凭一句要求证明服务的存储行为已改变。"},{"text":"能，因为模型已答应","correct":false,"feedback":"模型文字承诺不是服务存储控制，需要查适用政策、账户条件与实际设置。"},{"text":"只要会话短就一定不会保存","correct":false,"feedback":"即使消息很短，服务仍按适用政策处理，长度不能证明保存与否。"}]},{"question":"用量提醒邮件到达后，怎样判断是否已停止扣费？","options":[{"text":"收到提醒就表示硬上限生效","correct":false,"feedback":"提醒负责告知状态，硬上限负责限制消耗，是否存在及如何生效须分别确认。"},{"text":"查看限制作用和资源实际运行状态","correct":true,"feedback":"提醒邮件只是通知，需另查资源状态及上限行为才能确认是否停止消耗。"},{"text":"关闭通知以免后续继续收费","correct":false,"feedback":"通知开关影响是否收到消息，不会自动停止仍在运行的远程资源。"}]}],"sources":[{"label":"官方或原始资料：help.openai.com","url":"https://help.openai.com/en/articles/9039756-managing-billing-for-chatgpt-and-the-api-platform","checked":"2026-10-16"},{"label":"OpenAI API 数据控制官方说明（仅适用于该平台，须核对账户条件）","url":"https://developers.openai.com/api/docs/guides/your-data","checked":"2026-10-16"}]},{"id":"02.01","title":"认识项目、对话与操作范围","lead":"对话里说“已经创建”，为什么项目文件夹里仍可能没有那个文件？","goals":["在新练习目录内确认操作范围并创建可重新找到的 note.txt","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"项目是实际文件的范围","paragraphs":["项目是本次工作相关文件与运行说明的集合，对话是讨论和发出请求的记录。两者会联系，但不是同一对象。模型可以在回答里展示代码，却尚未写入磁盘；也可能写到了另一个目录，所以必须先确认当前项目的绝对路径。","先新建只用于学习的文件夹，如 ai-task-practice。打开后请 Codex 只读列出里面的文件，并对照你实际看到的目录。目录为空应如实报告，不能把产品自带的示例画面当作你的作品已经存在。"]},{"title":"先明确允许修改的边界","paragraphs":["操作范围包含允许读写的目录、允许执行的动作和应保留的内容。把边界写进任务，是为了避免名字相近的旧项目被当成练习对象。权限表示工具可能做什么，而任务授权表示这轮实际应该做什么，两者不能混为一谈。","例如明确“只在练习目录创建说明文件，不安装软件，不访问其他项目”。如果路径不清楚，先让工具报告当前位置再行动。反例是仅说“整理一下电脑上的项目”，这样无法判断哪些文件可动，也很难恢复误改。"],"code":"ai-task-practice/\n└─ note.txt  // 只在这个练习目录写入，重开核对内容"},{"title":"理解请求、执行与结果的区别","paragraphs":["任务输入表达意图，工具执行尝试把意图变成动作，执行结果提供动作是否成功的证据。聊天中出现一段命令只是建议，看到执行记录也还要检查退出状态或文件内容，不能跳过中间环节。","你可以请求创建 note.txt，内容是“练习目录已确认”。随后在文件管理器找到文件并重新打开，才知道写入发生在预期位置。教材不提供与你当前客户端完全一致的界面截图；入口若有差异，以官方指南和实际可见界面核对。"]},{"title":"记录起点让问题可恢复","paragraphs":["第一次操作就记录路径、现有文件和本次目标，会让后续排错更简单。若文件没出现，可以依次问是否真的执行、执行是否成功、是否写在另一处；这比不断重复“再试一次”能更快找到断点。","本课先不创建界面，也不启动服务。成果是一份范围说明和一个可重新找到的小文件。这个小动作把“我能聊天”推进为“我能确认文件操作确实发生”，后续运行网页与恢复版本都依赖这条证据链。"]}],"glossary":[{"term":"绝对路径","meaning":"从磁盘或文件系统根开始标明位置的完整地址。"},{"term":"操作范围","meaning":"本次明确允许读取、修改与执行的边界。"},{"term":"项目","meaning":"围绕当前工作组织的实际文件、数据和运行说明。"}],"predict":{"question":"Codex 回复“文件内容如下”，但未见执行记录。能认定已写入吗？","options":[{"text":"能，回复中已有文件名","correct":false,"feedback":"回答可在纯文字里写任意文件名，只有实际目录和内容才能证明文件已落盘。"},{"text":"先再次发送相同创建请求，不查目录","correct":false,"feedback":"重复请求可能在错误位置生成重复文件，应先核对是否执行及实际路径。"},{"text":"先核对目录和实际文件内容","correct":true,"feedback":"回答可能只展示草稿，写入需要文件证据。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"只有回答","input":"练习目录为空；回答中展示 note.txt 内容，没有文件写入证据。","question":"根据当前文件操作证据，当前状态应怎样记录？","options":[{"text":"有内容草稿，写入未确认","correct":true,"feedback":"当前只有文本草稿，实际写入尚待核对，不能把表达内容当作文件动作完成。"},{"text":"文件已创建但暂时隐藏","correct":false,"feedback":"没有文件或执行证据，不能把缺失解释为隐藏状态，这仍是未经核对的假设。"},{"text":"把聊天中的内容直接当作已落盘文件","correct":false,"feedback":"草稿可复制为文件但当前没有写入证据，不能提前记录实际创建成功。"}],"output":"教学推演：当前只有note.txt的内容草稿，真实文件写入未确认；实操保持未完成，下一步在准确目录核对文件和执行状态。","evidence":["缺少文件证据","已有内容草稿"]},{"name":"目录不同","input":"请求写入练习A；执行记录指向练习B；A中找不到文件。","question":"根据当前文件操作证据，先定位哪个问题？","options":[{"text":"直接更改note.txt内容再检查A目录","correct":false,"feedback":"当前已知路径指向B，改内容不纠正位置差异，应先确认授权目录。"},{"text":"当前工作路径与授权范围不一致","correct":true,"feedback":"执行写到了B而要求是A，位置不一致即可解释A中找不到文件的现象。"},{"text":"继续重复同一写入请求，不看执行路径","correct":false,"feedback":"同一错误路径可能重复写到B，先对齐目录才能解释并消除A中找不到的问题。"}],"output":"教学推演：停止继续修改，确认A路径，单独处理误放文件并记录，不假设可任意移动。","evidence":["请求路径A","执行路径B"]}]},"practice":{"intro":"在新练习目录内确认操作范围并创建可重新找到的 note.txt。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["创建空的 ai-task-practice 文件夹并记录完整路径","请 Codex 只读报告当前位置、文件清单和允许范围","仅创建 note.txt，写入练习日期及目录用途","在文件管理器重新定位并打开文件，对照执行结果与内容"],"prompt":"本次练习是 02.01《认识项目、对话与操作范围》。在新练习目录内确认操作范围并创建可重新找到的 note.txt。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：创建空的 ai-task-practice 文件夹并记录完整路径；请 Codex 只读报告当前位置、文件清单和允许范围；仅创建 note.txt，写入练习日期及目录用途；在文件管理器重新定位并打开文件，对照执行结果与内容。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：练习目录完整路径与初始清单；实际存在的 note.txt 内容；工具动作与重开文件核对记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["练习目录完整路径与初始清单","实际存在的 note.txt 内容","工具动作与重开文件核对记录"],"troubleshooting":[{"symptom":"文件找不到","check":"核对实际写入路径与当前打开目录","action":"先只读查找任务报告中的精确位置，再在正确目录重新操作。"},{"symptom":"界面与教程不同","check":"核对客户端、日期和当前官方快速开始","action":"按可见入口进入同一功能，记录差异，不凭想象寻找截图中的按钮。"}]},"checks":[{"question":"允许读取整个项目，是否意味着可以改所有文件？","options":[{"text":"可以，读取和修改是同一授权","correct":false,"feedback":"读取与修改对文件的影响不同，允许读整个项目不能自动扩大本轮写入范围。"},{"text":"完全不能读取任何文件","correct":false,"feedback":"用户已允许只读核对项目，可以读取所需文件，不应把边界误解为完全禁止观察。"},{"text":"仍应遵守本轮明确的修改范围","correct":true,"feedback":"工具能够访问更多文件，只表示能力范围；实际操作仍受本轮任务边界限制。"}]},{"question":"文件真实存在且可重开，能证明什么？","options":[{"text":"这次写入在核对目录成功","correct":true,"feedback":"文件重开证明本次写入可定位，但不能顺带证明页面或其他功能已经实现。"},{"text":"可以把该目录内其他文件也记为已验证","correct":false,"feedback":"重开note.txt只覆盖一个文件，不代表其他文件或页面行为已经检查。"},{"text":"后续无需再核对每次写入位置","correct":false,"feedback":"后续任务可能改变目录与文件名，首次成功不能取消对新操作范围的核对。"}]}],"sources":[{"label":"官方或原始资料：learn.chatgpt.com","url":"https://learn.chatgpt.com/docs/quickstart","checked":"2026-10-16"}]},{"id":"02.02","title":"写出一个最小需求","lead":"“做一个专业的任务工具”听起来明确，为什么开始后会出现登录、日历和分享等额外功能？","goals":["写出个人任务页的一页需求，完成复述纠偏与单张原型确认","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"先限定使用者与场景","paragraphs":["需求表达的是谁在什么情境完成什么事，不是先列技术名词。一个人在当前浏览器记录今天要做的事，与多人协作安排项目有不同数据和权限要求。不明确使用者，协作者就可能按常见产品习惯补出账号或团队功能。","本轮明确为个人练习，无登录、无联网、无跨设备同步；目标是能看见任务页，后续添加、完成和保存。这些限制不是降低质量，而是让第一次成果能在一个可以检查的范围内完成。"]},{"title":"最小功能要能形成小闭环","paragraphs":["最小不是只剩一张漂亮截图，而是在选定范围内能完整走通一个过程。早期先确定页面结构和必要状态，再分课实现交互与保存，能让每次变化都有具体目的。功能之间的先后关系要写出来。","本课只产出需求与视觉原型，确认后才实施网页。把“支持添加”写成“输入非空文字并提交后，列表多一条”，比写“交互流畅”更容易验收。空输入、完成后的显示也应在需求中先有约定。"],"code":"使用者：个人\n本轮：需求和一张待确认原型\n后续验收：非空添加、完成切换、当前浏览器恢复"},{"title":"复述能暴露错误假设","paragraphs":["让 Codex 先复述使用者、成果、范围和未决项，是为了看见它怎样理解你的话。复述没有价值在于字数，而在于是否指出会改变结果的假设。你要找出至少一个可能误解的地方并作明确决定。","比如它默认任务存在服务器，你应纠正为当前浏览器保存，并说明清理浏览器后可能丢失。如果它建议技术框架，先询问是否为实现必须；不要把协作者提出的方案自动写成用户原始需求。"]},{"title":"视觉原型与行为验收各管一层","paragraphs":["视觉原型是把布局和风格做成可见方案，供人在实现前讨论。视觉原型用来确认布局、文字和风格，行为清单用来确认点击、状态与保存。原型里画着“保存成功”不意味着保存机制已经存在。先确认一张小原型，再实现与核对行为，可以减少误解后大规模返工。","验收应写能观察的前后变化：初始无任务；输入“买书”后出现一条；切换完成后文字状态变化；刷新恢复另课验收。反例是只说“与原型一致就通过”，这样无法发现所有按钮都是静态装饰。"]}],"glossary":[{"term":"最小需求","meaning":"能在限定场景交付并检查的一小组必要行为。"},{"term":"假设","meaning":"需求没有明确给出、却被暂时当作前提的判断。"},{"term":"视觉原型","meaning":"用于讨论布局与风格的可见方案，不代表功能已经实现。"}],"predict":{"question":"Codex复述包含多人登录，而你只想本地个人练习，先做什么？","options":[{"text":"先实现登录，之后可以不用","correct":false,"feedback":"登录会引入身份与保存设计，当前个人本地场景未要求，会扩大开发与验收范围。"},{"text":"纠正使用者和范围，再确认原型","correct":true,"feedback":"多人登录意味着用户、权限与远程数据问题，需先纠正这个改变规模的错误假设。"},{"text":"只把登录按钮藏起来","correct":false,"feedback":"藏按钮只改变画面，仍保留了错误的使用场景与实现安排，没有真正纠偏。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"含糊愿望","input":"输入：做一个专业、现代、功能强大的任务工具。","question":"面对本轮个人任务页需求，最该补充哪类信息？","options":[{"text":"再增加三个形容词","correct":false,"feedback":"专业和现代没有规定谁做什么、何时算完成，继续加形容词不会明确行为。"},{"text":"先指定数据库品牌","correct":false,"feedback":"当前尚未决定要联网或共享，直接指定远程数据库跳过了是否需要它的判断。"},{"text":"使用场景、最小行为和可观察验收","correct":true,"feedback":"使用者、最小行为与验收确定实际交付内容，能限制协作者自行扩展功能。"}],"output":"教学推演：先改写为个人当前浏览器的任务页，列添加和完成，保存另步推进。","evidence":["使用者明确","边界和验收可核对"]},{"name":"原型未确认","input":"需求已复述，刚生成一张原型，用户尚未看过。","question":"面对本轮个人任务页需求，后续安排是什么？","options":[{"text":"展示原型并等待明确确认","correct":true,"feedback":"文字确认只说明需求方向，真实视觉原型仍需用户明确看过并确认。"},{"text":"立即扩展全部页面","correct":false,"feedback":"原型未经用户看过就扩展多页，会将同一视觉误解传播到更多后续素材。"},{"text":"先把原型样例作为最终验收结果","correct":false,"feedback":"原型呈现的是方案表现，按钮与数据行为仍需实现后实际执行验证。"}],"output":"教学推演：本轮停在一张可供讨论的视觉原型与可执行行为清单，等待明确确认后再实施网页，不能由文字需求确认跳过视觉检查。","evidence":["视觉确认记录尚缺","行为清单已可审阅"]}]},"practice":{"intro":"写出个人任务页的一页需求，完成复述纠偏与单张原型确认。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["写使用者、当前场景和三项必要行为","给添加、完成、保存分别写输入和预期结果，明确分步实施","请 Codex 复述并列假设，修正至少一个会扩大范围的假设","只制作一张原型供确认，将确认结果和未展示行为写入说明"],"prompt":"本次练习是 02.02《写出一个最小需求》。写出个人任务页的一页需求，完成复述纠偏与单张原型确认。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：写使用者、当前场景和三项必要行为；给添加、完成、保存分别写输入和预期结果，明确分步实施；请 Codex 复述并列假设，修正至少一个会扩大范围的假设；只制作一张原型供确认，将确认结果和未展示行为写入说明。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：一页需求和排除范围；一次错误假设纠正记录；单张原型与实际确认状态。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["一页需求和排除范围","一次错误假设纠正记录","单张原型与实际确认状态"],"troubleshooting":[{"symptom":"需求越写越多","check":"核对每项是否支持本轮个人场景","action":"将不必要项列为以后考虑，保留本轮验收。"},{"symptom":"原型看起来对但行为不清楚","check":"对每个控件写出点击前后状态","action":"补行为清单，不用再生成更多外观代替行为讨论。"}]},"checks":[{"question":"“用某数据库”最先属于什么？","options":[{"text":"用户必需功能的天然证明","correct":false,"feedback":"同一用户需求可能由本地保存满足，数据库是候选技术而非天然必要功能。"},{"text":"技术方案，需说明为何支持需求","correct":true,"feedback":"它是实现选择，不能直接代替用户目标。"},{"text":"只要技术名词明确就算用户目标明确","correct":false,"feedback":"技术名称没有说明使用者要完成的行为，也不等于可观察的成果标准。"}]},{"question":"最小工具初版只实现一条完整流程，有什么好处？","options":[{"text":"可以省去所有失败情况","correct":false,"feedback":"小闭环仍要防止空任务等必要错误，最小范围不等于只检查正常输入。"},{"text":"以后无需修改需求","correct":false,"feedback":"初版范围明确后仍可根据试用反馈更新，需记录变化而不是假设永不修改。"},{"text":"能更早检查实际行为并控制返工范围","correct":true,"feedback":"一条可运行完整流程能更早暴露理解与实现问题，让后续修改有真实依据。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/prompt-engineering","checked":"2026-10-16"}]},{"id":"02.03","title":"第一次打开和修改页面","lead":"编辑器里的标题已经改了，浏览器却还是旧字，问题可能出在哪条连接上？","goals":["在已确认的起始页面副本中只修改主标题，并验证打开的是同一份文件","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"源码是页面的输入之一","paragraphs":["源码是描述页面结构、样式或行为的文件内容，浏览器读取它们再显示结果。HTML 中的标题文字与 JavaScript 动态生成的文字可能来自不同位置，所以先定位实际负责显示的那一处，而不是全项目搜索后全部替换。","最小静态片段可以写成 \u003ch1>今日任务\u003c/h1>，其中 h1 表示主标题。将标签中间文字换成“本周任务”，预计只改变标题内容；标签的意义与样式规则仍在。这个实验让一处输入对应一处可见变化。"]},{"title":"保存、加载与观察是三个动作","paragraphs":["编辑器中的更改尚未保存时，磁盘仍可能保留旧内容；浏览器已经加载过页面时，也可能还显示先前版本。先确认保存，再重新加载正确地址，才能建立修改到结果的证据链。不要把刷新作为所有问题的唯一解释。","若项目有两份 index.html，改A却打开B会一直看不到变化。请同时记录编辑文件绝对路径和浏览器地址。若使用本地服务，还要确认该服务实际对应哪个目录；具体端口以真实启动输出为准。"],"code":"\u003ch1>今日任务\u003c/h1>\n\u003c!-- 仅把标签内文字改为本周任务，不重写整个页面 -->"},{"title":"只改一个值方便定位原因","paragraphs":["第一次修改选择标题文字，不同时换颜色、布局和数据逻辑。这样如果画面变化超出预期，就容易把问题定位到当前差异。先保存可返回副本，再观察修改前后，让实验具有可逆性。","修改后检查标题变了，但原有输入框和按钮仍能看见。反例是为替换一行标题重写整个页面：即使视觉相近，也可能丢掉已经确认的结构或脚本引用，难以判断哪项变化造成故障。"]},{"title":"看见变化不等于全部通过","paragraphs":["标题改变证明这份源码与该页面的显示有联系，不证明添加、保存或联网已经完成。验收只覆盖本次目标，同时做有限回归：页面仍能打开、必要控件还在、没有新出现的相关报错。","若尚无已确认的原型和起始页面，先返回02.02，不能把此处代码当作自动批准的新设计。本课仅在已确认页面上作局部文字变更，真实截图应由学习者实际操作采集，不由教材生成代替。"]}],"glossary":[{"term":"源码","meaning":"浏览器或程序读取的文本指令与结构描述。"},{"term":"回归检查","meaning":"变更后重查原有关键功能，观察是否被意外破坏。"},{"term":"HTML","meaning":"用于描述网页内容与结构的标记语言。"}],"predict":{"question":"改了A/index.html，浏览器地址指向B/index.html，优先检查什么？","options":[{"text":"打开的是否同一份文件","correct":true,"feedback":"编辑A却访问B时浏览器读不到此次修改，路径差异本身已是具体解释。"},{"text":"继续改A中的文字直到B页面变化","correct":false,"feedback":"浏览器访问B时读不到A，继续修改同一路径不会修复入口不一致。"},{"text":"先清理缓存，暂不核对A与B的路径","correct":false,"feedback":"缓存可能影响加载，但当前已有明确路径差异，应先确认读取的是同一文件。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"正确单点修改","input":"起始片段：\u003ch1>今日任务\u003c/h1>；只把文字改成本周任务并保存。","question":"在这次标题单点修改中，预计改变什么？","options":[{"text":"标题与浏览器标签文字都会自动一致","correct":false,"feedback":"h1与文档title是不同位置，仅修改h1不能自动推断标签页标题也被更新。"},{"text":"主标题文字改变，其他控件不应因此变化","correct":true,"feedback":"标签内部文字变化只影响主标题内容，未改输入控件、数组与其他结构。"},{"text":"此改动会同时更新所有任务的title字段","correct":false,"feedback":"页面主标题文字与任务对象字段不是同一数据位置，不能由一次文本替换推断同步更新。"}],"output":"教学推演：在同一文件保存并重载后，主标题应变为本周任务，输入框与按钮结构不因文本变化而消失；其他行为仍需单独核对。","evidence":["差异只有文字","控件结构未改"]},{"name":"未保存","input":"编辑器显示新字，磁盘文件仍是旧字，浏览器重新读取磁盘。","question":"在这次标题单点修改中，合理结果是什么？","options":[{"text":"必定显示新字","correct":false,"feedback":"编辑缓冲尚未保存就不是磁盘文件内容，重新加载不会自动读取它。"},{"text":"页面一定打不开","correct":false,"feedback":"磁盘中的旧HTML仍合法时页面可以继续打开，未保存不必然造成加载失败。"},{"text":"仍显示旧字","correct":true,"feedback":"浏览器当前读取的是旧磁盘内容，未保存的新字不会自然进入这次加载。"}],"output":"教学推演：浏览器重新读取的仍是旧磁盘内容，因此显示旧字；先保存编辑缓冲，再重载正确入口，才能观察新标题。","evidence":["磁盘内容旧","编辑缓冲内容新"]}]},"practice":{"intro":"在已确认的起始页面副本中只修改主标题，并验证打开的是同一份文件。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["记录页面文件路径和访问地址，保存修改前副本","请 Codex 定位主标题来源并解释最小片段","只改标题文字并保存，重新加载实际页面","对照前后文字、控件与相关错误，再恢复一次并确认"],"prompt":"本次练习是 02.03《第一次打开和修改页面》。在已确认的起始页面副本中只修改主标题，并验证打开的是同一份文件。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：记录页面文件路径和访问地址，保存修改前副本；请 Codex 定位主标题来源并解释最小片段；只改标题文字并保存，重新加载实际页面；对照前后文字、控件与相关错误，再恢复一次并确认。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：修改前后源码差异；真实访问地址和页面前后记录；恢复后的标题与页面可打开记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["修改前后源码差异","真实访问地址和页面前后记录","恢复后的标题与页面可打开记录"],"troubleshooting":[{"symptom":"刷新仍是旧字","check":"核对保存状态、文件路径和服务根目录","action":"先把三者对齐，再考虑缓存，不扩大重写页面。"},{"symptom":"其他控件也消失","check":"查看差异是否删除了标签或脚本","action":"恢复副本，再只改文字节点重试。"}]},"checks":[{"question":"标题变了，能确认任务保存了吗？","options":[{"text":"不能，保存需要独立写入和恢复检查","correct":true,"feedback":"标题显示变化没有检查任务写入与恢复，不能据此宣告数据保存通过。"},{"text":"能，页面已经重新加载","correct":false,"feedback":"刷新会重建运行状态，若未实现保存恢复，原来的内存任务可能因此丢失。"},{"text":"只需检查页面重新打开仍显示新标题","correct":false,"feedback":"标题可来自源码文件，而任务来自运行数据，两者需分别验证保存恢复。"}]},{"question":"最有帮助的求助证据是哪组？","options":[{"text":"一句“怎么没效果”","correct":false,"feedback":"缺少文件路径和实际访问地址，协作者无法判断修改是否作用于正在看的页面。"},{"text":"文件路径、源码差异、实际地址与页面结果","correct":true,"feedback":"路径、差异和页面结果分别对应修改、加载与观察，能定位中间哪段断开。"},{"text":"只提供修改后的整页截图，不给路径或差异","correct":false,"feedback":"截图可说明画面，却难区分未保存、打开错文件或加载旧内容，仍需定位链路。"}]}],"sources":[{"label":"官方或原始资料：developer.mozilla.org","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/What_is_JavaScript","checked":"2026-10-16"}]},{"id":"02.04","title":"第一次添加任务与改变状态","lead":"页面上有一个“添加”按钮，为什么点了却可能什么也没发生？","goals":["在已确认页面副本实现并实际检查添加、空值提示与完成切换","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"按钮需要动作处理","paragraphs":["按钮只是页面中的结构，点击时还需程序监听事件。事件是一次可被程序接收的动作通知；处理函数是收到通知后执行的一段步骤。若按钮没有连接函数，外观再像可点击控件，也不会自动把输入变成任务。","一条简化链路是：点击提交，读取输入，检查空值，写入任务列表，再更新页面。每个环节都可单独失败。观察到按钮变色只能说明某种视觉响应，不能证明列表已收到新任务。"]},{"title":"状态记录事实，页面显示状态","paragraphs":["状态指当前程序记住的数据，例如任务内容与是否完成。点击完成时，应先改变对应任务的 done 布尔值；布尔值只有真或假，再根据数据绘制划线或标记。显示是状态的表达，不应成为唯一事实来源。","如果只给文字加划线而没有改任务数据，下次重新绘制就可能恢复原样。反过来，只改数据不更新显示，用户会以为没有生效。因此检查必须同时关注当前数据与可见列表是否一致。"],"code":"const title = input.value.trim();\nif (!title) { showHint(); return; }\n// 只有后续追加代码才会增加任务；return不会自动显示提示"},{"title":"空值判断保护数据","paragraphs":["输入只含空格时，直接保存会制造看不见的任务。trim 是去掉文本两端空白的操作，先得到有效文字，再判断是否为空。空输入应给出可理解提示，不追加任务；有效输入才进入添加分支。","本课最小阅读是：const title = input.value.trim(); if (!title) return;。它表示先取文字再检查，没有有效内容时提前结束。提示展示可以由后续一行承担，不能把 return 本身理解为用户一定看见了错误说明。"]},{"title":"切换应当能来回验证","paragraphs":["完成状态最好用同一任务往返检查：未完成→完成→未完成。只测试第一次点击，可能漏掉无法取消的问题。同名任务还应互不干扰，因此每条需要稳定标识，不能仅靠显示文字定位。","添加后输入框清空可以作为辅助反馈，但不能当作添加成功的唯一证据。至少查看列表数量增加且内容正确；完成操作再核对目标任务的状态。刷新保存留到下一课，不要把本课内存变化夸大为长期保存。"]}],"glossary":[{"term":"事件","meaning":"点击、输入等由环境通知程序的动作。"},{"term":"状态","meaning":"程序当前保存并用于决定显示或行为的数据。"},{"term":"布尔值","meaning":"只有真或假两种值的数据类型，适合表示是否完成。"}],"predict":{"question":"只给文字加了划线，重新绘制后恢复原样，最可能缺什么？","options":[{"text":"只在绘制结束后再次强制加划线","correct":false,"feedback":"每次绘制后补装饰仍未更新任务done，下一次状态计算或保存仍可能错误。"},{"text":"把完成文字写进标题，不再保留done字段","correct":false,"feedback":"标题和状态职责不同，混写会让筛选和取消变复杂，应修正真正状态更新。"},{"text":"对应任务数据的状态更新","correct":true,"feedback":"数据仍为未完成时，重新绘制会按旧状态显示，说明缺少真实状态更新。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"空白输入","input":"输入为三个空格，先trim，再判断空字符串。","question":"按当前任务添加与切换条件，应出现什么行为？","options":[{"text":"提示无有效内容且列表不增加","correct":true,"feedback":"只有空格不提供可执行任务内容，trim后应判为空并阻止追加。"},{"text":"添加一条看不见的任务","correct":false,"feedback":"空白任务会占一条记录并影响数量，用户却看不到有效文字，造成数据污染。"},{"text":"把空输入替换为默认标题后直接新增","correct":false,"feedback":"这改变了本课空值应拒绝的需求，不能用默认任务掩盖输入缺少有效内容。"}],"output":"教学推演：trim后有效文字为空，添加分支不应执行，列表数量保持不变；是否出现提示还取决于提示代码，而非return自行显示。","evidence":["列表数量不变","空值分支被触发"]},{"name":"两条同名任务","input":"演示数组中t1和t2两条任务都叫买书；只点击t2完成，t1未被选中。","question":"按当前任务添加与切换条件，怎样算正确？","options":[{"text":"两条一起完成","correct":false,"feedback":"两个标题相同的对象仍可有不同id，名称相同不能成为一起完成的理由。"},{"text":"只有t2的完成状态改变","correct":true,"feedback":"稳定id负责区分记录，标题允许重复，点击t2只应改变t2的done字段。"},{"text":"先给其中一条自动改名","correct":false,"feedback":"用户要求切换完成状态，没有要求改标题，自动改名会引入无关数据变化。"}],"output":"教学推演：t1仍未完成，只有t2的done为true；再次点击t2应回到false，不能因标题相同让两条同时改变。","evidence":["核对两条标识","核对状态来回切换"]}]},"practice":{"intro":"在已确认页面副本实现并实际检查添加、空值提示与完成切换。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["请 Codex 先指出输入、按钮事件、任务数组和绘制位置","阅读空值判断片段，先写空格输入和有效输入的预测","加入一条读书任务，确认数量和文字，再添加一条同名任务","只完成第二条再取消，记录数据与显示；本课不要求刷新保留"],"prompt":"本次练习是 02.04《第一次添加任务与改变状态》。在已确认页面副本实现并实际检查添加、空值提示与完成切换。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：请 Codex 先指出输入、按钮事件、任务数组和绘制位置；阅读空值判断片段，先写空格输入和有效输入的预测；加入一条读书任务，确认数量和文字，再添加一条同名任务；只完成第二条再取消，记录数据与显示；本课不要求刷新保留。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：空输入提示且无新增记录；有效添加后的内容和数量；同名任务独立切换与取消记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["空输入提示且无新增记录","有效添加后的内容和数量","同名任务独立切换与取消记录"],"troubleshooting":[{"symptom":"点击没反应","check":"核对事件是否绑定到实际按钮、是否有相关报错","action":"沿点击到函数入口定位，先不更换整套界面。"},{"symptom":"同名任务一起改变","check":"核对是否按标题查找或批量匹配","action":"改用稳定id定位单条记录，再重复两条同名测试。"}]},"checks":[{"question":"输入框清空但列表没变化，能算添加通过吗？","options":[{"text":"能，程序已经响应点击","correct":false,"feedback":"点击有反应只能证明某种处理发生，不代表目标任务已进入列表。"},{"text":"只需再点一次直到出现","correct":false,"feedback":"事件可能已写入隐藏数据，再点可能制造重复，应先定位实际追加与绘制状态。"},{"text":"不能，需检查任务数据和列表增加","correct":true,"feedback":"输入框清空是辅助反馈，还需核对数组与列表确实新增了正确内容。"}]},{"question":"点击完成后再取消的主要目的是什么？","options":[{"text":"验证状态转换可往返且目标正确","correct":true,"feedback":"取消完成覆盖了相反方向的状态转换，可发现只能完成却不能撤销的问题。"},{"text":"证明数据跨设备同步","correct":false,"feedback":"本课没有远程服务读写，完成状态来回切换不能证明跨设备同步。"},{"text":"确认第一次点击时按钮曾有视觉反馈","correct":false,"feedback":"按钮反馈不覆盖完成到取消的反向状态变化，仍需核对任务done和显示。"}]}],"sources":[{"label":"官方或原始资料：developer.mozilla.org","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/Events","checked":"2026-10-16"}]},{"id":"02.05","title":"第一次让数据留下来","lead":"任务刚添加时明明在列表中，刷新后为什么又回到空白？","goals":["给演示任务页加入成对写读，只在专用键下验证刷新和关闭重开","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"内存与持久保存不同","paragraphs":["页面运行时的任务数组通常在内存里，内存是当前运行过程临时使用的空间。重新加载会重新执行程序，数组若又从空值开始，刚才的任务就不见了。这不必然表示添加失败，而是尚未把数据写到能跨加载保留的位置。","本课采用当前浏览器的 localStorage，意思是按网站来源保存少量字符串数据的浏览器空间。它适合演示本地保存，但不是云端数据库；换浏览器、改变来源或清理站点数据，都可能看不到原来的记录。"]},{"title":"写入与读取必须成对","paragraphs":["写入把当前状态放入存储，读取在下次启动时取回状态。只写不读，刷新后页面仍可能空白；只读不写，则永远恢复旧值。把这两个动作标在时间线上，可以判断哪一端缺失。","最小片段为 localStorage.setItem('practice:tasks', JSON.stringify(tasks));。setItem 按键名写值；JSON.stringify 把数组转换成文本。下次用 getItem 取回，并用 JSON.parse 还原为数据。这里只认识职责，更完整的异常处理放到模块07。"],"code":"localStorage.setItem('practice:tasks', JSON.stringify(tasks));\n// 下次启动另行读取、解析、绘制；不是此行自动完成\nconst saved = localStorage.getItem('practice:tasks');"},{"title":"保存完整状态而非只存名称","paragraphs":["任务不仅有标题，还包括标识与完成状态。如果只存标题，下次虽然看到同样文字，完成标记却会丢失，同名任务也可能无法区分。选择要存的字段，应根据重新打开后需要恢复什么来决定。","先添加两条演示任务，完成其中一条，刷新后逐项比对：数量、标题、id、done。反例是只检查“还有字”，这会漏掉状态重置。读取成功后还需绘制页面，否则数据已经恢复也看不见。"]},{"title":"浏览器来源限定保存范围","paragraphs":["来源通常由协议、主机和端口共同决定。即使页面文件相同，端口不同也可能使用另一份本地存储。用文件地址直接打开时的本地存储行为不应假定一致，练习尽量保持同一个实际本地服务地址。","正常关闭重开可测试浏览器保留，但私密模式、存储禁用或容量问题会改变结果。不要为测试而清空自己的真实站点数据。只操作专用演示键，保存失败应给提示并保留当前可见数据，不把失败报告为成功。"]}],"glossary":[{"term":"持久保存","meaning":"让数据在本次运行结束后仍可再读取，保留范围由介质决定。"},{"term":"序列化","meaning":"把数组等结构转换成可保存或传输的文本。"},{"term":"localStorage","meaning":"按来源在当前浏览器保存少量字符串数据的空间。"}],"predict":{"question":"程序已setItem，但启动始终tasks=[]，刷新会怎样？","options":[{"text":"保存动作会自动绘制所有任务","correct":false,"feedback":"存储接口只保存文本，不负责按任务结构绘制列表，启动仍需读取和渲染。"},{"text":"页面仍可能空白，因为没有读取恢复","correct":true,"feedback":"数据已写在浏览器不表示启动代码使用过它，缺少读取仍会显示空数组。"},{"text":"先换一个新键名，暂不检查启动读取","correct":false,"feedback":"换键会让读写更可能不一致，当前应先核对已写数据是否被启动逻辑读取。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"完整写读","input":"专用键已写入两条任务，其中t2 done=true；启动读取、解析并绘制。","question":"对于这次浏览器保存恢复，预期恢复什么？","options":[{"text":"只恢复最近一条","correct":false,"feedback":"输入写了两条完整记录，没有只取最后一条的规则，应恢复两条而非一条。"},{"text":"自动同步到手机","correct":false,"feedback":"localStorage属于当前浏览器来源，没有模型或服务端提供跨设备同步。"},{"text":"两条标题和t2的完成状态","correct":true,"feedback":"标题和done都被序列化保存，并在启动读取后绘制，因此能恢复完整状态。"}],"output":"教学推演：读取同一专用键并成功解析后，应恢复两条任务的标题、标识和t2完成状态，再由绘制逻辑显示；真实结果需独立操作验证。","evidence":["写入字段含done","启动确实读取同一键"]},{"name":"地址改变","input":"原来访问localhost:8000，改为localhost:8001，代码文件相同。","question":"空列表一定说明原记录被删除吗？","options":[{"text":"不一定，可能处在另一来源","correct":true,"feedback":"端口是来源的一部分，改变后可能使用另一存储空间，不能直接判原数据被删。"},{"text":"一定，文件相同就共享保存","correct":false,"feedback":"本地存储按来源而非磁盘文件身份划分。"},{"text":"一定是JSON无法解析","correct":false,"feedback":"没有解析错误或损坏文本证据，应先查地址变化而不是断言JSON失败。"}],"output":"教学推演：先返回原来的8000地址核对专用键，8001可能是另一来源的空空间；不清空真实数据，也不从空列表推断原记录已删除。","evidence":["记录原访问地址","对比协议、主机和端口"]}]},"practice":{"intro":"给演示任务页加入成对写读，只在专用键下验证刷新和关闭重开。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["使用专用键practice:tasks，记录实际访问地址","请 Codex 标出添加和切换后写入、启动时读取与绘制的位置","添加两条不同状态任务，记录字段，再刷新逐项比对","关闭后重开同一地址，说明本地范围与未覆盖条件"],"prompt":"本次练习是 02.05《第一次让数据留下来》。给演示任务页加入成对写读，只在专用键下验证刷新和关闭重开。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：使用专用键practice:tasks，记录实际访问地址；请 Codex 标出添加和切换后写入、启动时读取与绘制的位置；添加两条不同状态任务，记录字段，再刷新逐项比对；关闭后重开同一地址，说明本地范围与未覆盖条件。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：写入和读取位置及专用键；刷新前后数量、标题、完成状态对照；关闭重开结果和不支持跨设备的说明。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["写入和读取位置及专用键","刷新前后数量、标题、完成状态对照","关闭重开结果和不支持跨设备的说明"],"troubleshooting":[{"symptom":"刷新后空白但存储有值","check":"核对读取键、解析结果和绘制顺序","action":"只追查启动恢复链路，先保留原数据文本再修复。"},{"symptom":"换地址后记录不见","check":"核对协议、主机、端口和浏览器配置","action":"回到原来源核对；不要误以为删除再覆盖旧数据。"}]},"checks":[{"question":"看到localStorage中有字符串能证明什么？","options":[{"text":"整个保存流程已经通过","correct":false,"feedback":"文本存在尚未验证是否可解析、字段是否完整以及能否正确绘制到页面。"},{"text":"该键有文本，仍需验证能解析并恢复","correct":true,"feedback":"只看到键值只能证明有文本，不能保证结构合法或恢复逻辑真的使用它。"},{"text":"数据已有异地备份","correct":false,"feedback":"数据仍在同一浏览器环境中，没有独立远端副本，不能称为异地备份。"}]},{"question":"完成状态丢了但标题恢复，优先检查什么？","options":[{"text":"先把浏览器存储键名改成新名字","correct":false,"feedback":"字段缺失应先查保存内容与恢复默认值，换键不能补回未保存的done。"},{"text":"把标题加上已完成三个字","correct":false,"feedback":"把状态写进标题会混合两种职责，难以可靠筛选，也掩盖done字段恢复错误。"},{"text":"保存字段与恢复时done默认值","correct":true,"feedback":"若只存标题或恢复时强制done=false，会出现文字回来但完成状态丢失。"}]}],"sources":[{"label":"官方或原始资料：developer.mozilla.org","url":"https://developer.mozilla.org/en-US/docs/Web/API/Window/localStorage","checked":"2026-10-16"}]},{"id":"02.06","title":"检查、修改与恢复早期作品","lead":"页面现在能用，怎样证明小改动没有破坏保存，而且还可以回到原来版本？","goals":["完成V0检查、一次局部变更和一次可验证的恢复","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"看见、验收与版本保存不同","paragraphs":["看见一次成功是观察，按清单覆盖必要路径是验收，保存可返回的文件与说明是版本保存。三者彼此支持，却不能替代。一个作品在当前标签页中看起来正常，并不能证明关闭后仍可恢复数据或源码。","V0的清单应覆盖非空添加、空值拒绝、完成与取消、刷新恢复。每项写输入、预期和实际。暂时不能测的项目标未验证，不用“总体没问题”把缺项抹掉。"]},{"title":"先建立已知可用基线","paragraphs":["基线是已经检查且能定位到的状态。初学者可先复制整个练习目录，命名带日期并附说明；后续再学 Git。副本需要包含运行必需文件，并记录启动方式，不只是截一张画面。","源码副本未必包含浏览器里的任务记录；浏览器数据也不会自动因复制目录而备份。若这轮涉及数据，应另存演示数据与恢复步骤。先明确要恢复的对象，才能判断副本是否足够。"],"code":"V0检查：\n1. 非空添加，空格拒绝\n2. 完成，再取消\n3. 刷新恢复标题与状态\n4. 局部恢复后重复以上步骤"},{"title":"用无害变更练习定位","paragraphs":["选择一处标题或提示文字作变更，先写预期，再看差异。为演练错误，可在副本中把主标题改成错字；这种错误可观察且不涉及删除记录。不要为了排错练习破坏私人数据或修改系统设置。","错误出现后记录准确步骤和最近改动，再恢复指定文件。恢复不是不断执行随机命令直到看起来正常，而是回到明确版本并验证目标差异消失。若还夹有新工作，先保存它，避免恢复时一起丢失。"]},{"title":"恢复后要重跑原流程","paragraphs":["文件回到旧版只是恢复动作的结果，作品能否继续使用仍需检查。重新启动正确页面，重跑添加、切换与刷新，才能发现引用路径或保存键是否在恢复中变化。把恢复前后结果并列记录，下一次就能复用方法。","通过V0只表示本地早期工具达到本轮标准，不等于已经上线、支持多用户或永久保存。写一条限制和一条下一步改进，会让成果交接更诚实，也能避免为暂时不需要的功能扩大实现范围。"]}],"glossary":[{"term":"基线","meaning":"有明确位置且经过约定检查的可用状态。"},{"term":"恢复","meaning":"按指定依据把目标文件或数据回到可用状态并重新验证。"},{"term":"版本保存","meaning":"把可定位的文件状态与说明保存为以后返回的依据。"}],"predict":{"question":"复制源码文件夹后，可否认定浏览器任务也已备份？","options":[{"text":"不能，需分别确认数据副本","correct":true,"feedback":"源码是磁盘文件，任务可能在浏览器存储，复制目录未必复制了后者。"},{"text":"可以，页面能显示数据","correct":false,"feedback":"当前页面可能从原浏览器读取数据，不能证明复制出的源码目录包含这些记录。"},{"text":"只有截图才是可靠备份","correct":false,"feedback":"截图只保留画面像素，不能恢复完整源码、可编辑结构与任务记录。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"局部错误","input":"副本已保存；本轮只把标题改成错字，任务逻辑未动。","question":"面对当前局部修改与副本，最小恢复范围是什么？","options":[{"text":"清空全部任务数据","correct":false,"feedback":"本次只把标题改错，没有证据说明数据损坏，清空任务会产生无关损失。"},{"text":"恢复标题差异，再做有限回归","correct":true,"feedback":"已知差异只在标题，应恢复对应文字，再有限检查旧功能是否仍正常。"},{"text":"重建整个项目","correct":false,"feedback":"重建整个项目会引入更多条件，难以判断原错误是否被精确修复。"}],"output":"教学推演：只还原标题差异后，核对输入框与按钮仍在，并重跑添加、切换和刷新；不能仅因文件复制成功就认定运行完全恢复。","evidence":["差异定位到标题","核心流程重查"]},{"name":"夹有新工作","input":"可用副本之后新增一条帮助说明，又发生标题错误。","question":"面对当前局部修改与副本，恢复前先做什么？","options":[{"text":"直接覆盖全部目录","correct":false,"feedback":"整目录覆盖可能删除基线之后的帮助说明等有效新工作，应先查看并保存。"},{"text":"用页面截图代替帮助段的文本副本","correct":false,"feedback":"截图难恢复完整可编辑说明与代码，应保留文件或差异后再覆盖恢复。"},{"text":"单独保存帮助说明并查看差异","correct":true,"feedback":"先隔离需要保留的新说明，可避免恢复标题时把有效成果也一并撤销。"}],"output":"教学推演：先保存需要保留的帮助说明，隔离有效新增与标题错误，再恢复目标差异，最后确认帮助段仍在且原核心流程可用。","evidence":["保留内容清单","恢复范围明确"]}]},"practice":{"intro":"完成V0检查、一次局部变更和一次可验证的恢复。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["记录当前目录、启动地址和V0四类检查结果","保存带日期的完整源码副本与运行说明，另记演示数据保留范围","在副本中只把标题改错，写预期、实际和复现步骤","保存任何要保留的新工作，恢复标题并重跑添加、完成、刷新"],"prompt":"本次练习是 02.06《检查、修改与恢复早期作品》。完成V0检查、一次局部变更和一次可验证的恢复。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：记录当前目录、启动地址和V0四类检查结果；保存带日期的完整源码副本与运行说明，另记演示数据保留范围；在副本中只把标题改错，写预期、实际和复现步骤；保存任何要保留的新工作，恢复标题并重跑添加、完成、刷新。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：V0正常与失败路径检查表；可定位副本、运行说明和恢复范围；错误复现、源码差异及恢复后重测结果。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["V0正常与失败路径检查表","可定位副本、运行说明和恢复范围","错误复现、源码差异及恢复后重测结果"],"troubleshooting":[{"symptom":"恢复后仍显示错字","check":"核对实际打开目录、保存状态和地址","action":"确认正在运行恢复后的副本，再核对标题来源。"},{"symptom":"副本打开不了","check":"核对是否漏复制脚本、样式或运行说明","action":"从仍完好的版本补齐必需文件，再按同一步骤验证。"}]},"checks":[{"question":"恢复文件后为什么还要刷新测试？","options":[{"text":"恢复动作不能直接证明运行结果","correct":true,"feedback":"恢复后实际入口、引用和数据条件可能变化，文件回去不保证行为自动通过。"},{"text":"确认文件时间变回旧日期就足够","correct":false,"feedback":"文件时间不直接证明浏览器读取正确版本或核心功能仍可运行。"},{"text":"因为恢复一定会清空数据","correct":false,"feedback":"Git或副本恢复源码不等于清空浏览器数据，应分别说明各自恢复范围。"}]},{"question":"V0通过后最准确的交付描述是什么？","options":[{"text":"已具备企业级可靠性","correct":false,"feedback":"V0只覆盖本轮本地清单，没有长期、规模与用户隔离证据，不能宣称企业级。"},{"text":"本地添加、切换与当前浏览器恢复已按清单检查","correct":true,"feedback":"交付描述逐项对应已做的本地行为检查，没有把未实现范围写成成果。"},{"text":"已经支持任何设备的数据共享","correct":false,"feedback":"尚未建立远程数据通路，不能从当前浏览器恢复推出不同设备共享数据。"}]}],"sources":[{"label":"官方或原始资料：git-scm.com","url":"https://git-scm.com/book/en/v2/Git-Basics-Viewing-the-Commit-History","checked":"2026-10-16"}]},{"id":"03.01","title":"文件、目录与引用路径","lead":"图片还在电脑里，为什么移动到另一个文件夹后网页却显示不出来？","goals":["在练习副本移动一张演示图片，预测、定位并恢复引用","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"文件名还包含类型信息","paragraphs":["文件是被保存的一份内容，目录是组织文件的位置。扩展名是文件名末尾的类型提示，例如 .html、.css、.js；改名不会自动转换内部内容。把文本命名为图片扩展名，不能让浏览器获得真正的图像数据。","首次排错先确认实际文件名，避免系统隐藏扩展名后出现 index.html.txt。文字乱码则要考虑编码，即文本与字节之间的对应规则。页面和保存方式统一采用 UTF-8，可以减少同一文件被不同规则解释的情况。"]},{"title":"相对路径依赖出发点","paragraphs":["相对路径是从当前文件或约定位置出发寻找资源，绝对路径则给出完整定位。若 index.html 中写 images/book.png，浏览器会按页面所在位置找 images 目录。文件仍在磁盘，不代表这个引用仍然能找到它。","把 book.png 移到 assets 目录后，要么修改引用为 assets/book.png，要么把文件移回。不能因为搜索电脑找得到图片就认定链接正确。图片名大小写在某些环境下也可能影响引用，应保持一致，避免本地看似正常而换环境失败。"],"code":"\u003cimg src=\"images/book.png\" alt=\"书封面\">"},{"title":"入口决定实际打开哪份内容","paragraphs":["入口是开始访问或执行项目的文件或地址。目录中可能有旧版、备份和新版本，双击不同入口会读到不同内容。要把编辑路径、引用路径与浏览器访问地址同时记下，才能确认正在核对同一项目。","最小片段 \u003cimg src=\"images/book.png\" alt=\"书封面\"> 中，src 是资源地址，alt 是图片无法使用时仍有意义的文字。看见替代文字可能说明资源没加载，但具体原因还要核对实际请求路径，不能只凭画面断定文件已经删除。"]},{"title":"恢复引用比重建项目更准确","paragraphs":["路径错误属于定位问题，先沿着浏览器实际寻找的地址检查，再看文件是否在该处。一次只移动一张演示图片并保存原位置，可以清楚观察条件变化；不要用批量重命名把问题扩大。","实际修复后重新加载并检查图片显示，确认替代文字和页面其他资源没有异常。若通过本地服务访问，需检查服务根目录；若通过文件地址，需对照该入口所在目录。两种出发点不同，恢复办法都应有路径依据。"]}],"glossary":[{"term":"扩展名","meaning":"文件名中用于提示类型的后缀，并不会自动转换内容。"},{"term":"相对路径","meaning":"以当前页面或约定目录为出发点的资源位置。"},{"term":"编码","meaning":"把文字保存为字节并从字节还原文字的规则。"}],"predict":{"question":"index.html引用images/book.png，图片移到assets而引用没改，会怎样？","options":[{"text":"浏览器会按相同文件名搜索整个磁盘","correct":false,"feedback":"网页引用没有被授权也没有规则去任意搜索磁盘。"},{"text":"先把图片复制多份，不检查引用位置","correct":false,"feedback":"同一文件复制多份不保证src指向其中任何一份，仍需核对实际解析地址。"},{"text":"原引用可能加载失败，先核对实际地址","correct":true,"feedback":"浏览器仍按旧位置寻找，不会自动遍历其他目录。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"移动文件","input":"index.html含images/book.png；文件实际只在assets/book.png。","question":"在这个图片路径实验中，最小修复应针对什么？","options":[{"text":"让引用与实际位置重新对应","correct":true,"feedback":"恢复原位置或修正src都围绕同一个定位问题。"},{"text":"把PNG扩展名改成HTML","correct":false,"feedback":"改名不能把图像变成网页，也不修正旧引用。"},{"text":"只把图片文件名改短而保留旧src","correct":false,"feedback":"改名又产生新的引用差异，若src不更新，浏览器仍按旧地址寻找资源。"}],"output":"教学推演：修正src为assets/book.png后才具备找到图片的条件，还需实际加载验证格式与访问。","evidence":["对照src字符串","对照实际目录清单"]},{"name":"打开旧副本","input":"新副本引用已修好，但浏览器地址仍指向旧备份目录。","question":"在这个图片路径实验中，下一步应优先核对什么？","options":[{"text":"继续刷新旧入口，不核对其所在目录","correct":false,"feedback":"旧页面持续读取旧副本，刷新次数不能让它自动改用新目录文件。"},{"text":"实际入口是否为修复后的文件","correct":true,"feedback":"旧入口使用旧引用，不能反映新副本的修复效果。"},{"text":"将alt文字删除","correct":false,"feedback":"删除替代文字只会掩盖现象，不会修复资源定位。"}],"output":"教学推演：打开新副本的正确入口，再观察已修复引用；旧页面现象不能作为新版本失败证据。","evidence":["访问地址含目录","编辑文件路径含目录"]}]},"practice":{"intro":"在练习副本移动一张演示图片，预测、定位并恢复引用。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["记录入口路径、图片路径和img引用；没有图片时使用自制演示图","只移动图片到assets，保持原引用，先写预测再访问","请 Codex 解释浏览器寻找的地址，选恢复位置或改引用","重新加载并保存成功与失败时的路径对照"],"prompt":"本次练习是 03.01《文件、目录与引用路径》。在练习副本移动一张演示图片，预测、定位并恢复引用。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：记录入口路径、图片路径和img引用；没有图片时使用自制演示图；只移动图片到assets，保持原引用，先写预测再访问；请 Codex 解释浏览器寻找的地址，选恢复位置或改引用；重新加载并保存成功与失败时的路径对照。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：起始目录与引用片段；故障时实际地址和画面；修复差异及重新加载结果。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["起始目录与引用片段","故障时实际地址和画面","修复差异及重新加载结果"],"troubleshooting":[{"symptom":"磁盘有图片但页面不显示","check":"核对src、入口位置和真实文件名","action":"沿实际解析地址查找，不对整个项目作无依据重写。"},{"symptom":"中文文件名乱码","check":"核对编辑器保存编码和页面声明","action":"在副本统一UTF-8并重新加载，保留原文件用于对照。"}]},"checks":[{"question":"改扩展名能把文本转成图片吗？","options":[{"text":"能，浏览器只按后缀生成画面","correct":false,"feedback":"后缀只是类型提示，不能为原本的文本添加PNG等图像格式需要的编码字节。"},{"text":"用另存为修改后缀就完成格式转换","correct":false,"feedback":"若保存动作只改名称而不重新编码，内部内容依旧不是合法图像格式。"},{"text":"不能，内部字节内容仍需符合图像格式","correct":true,"feedback":"扩展名是提示，内容格式才决定能否解码。"}]},{"question":"修好新文件但旧标签页不变，最有用的证据是什么？","options":[{"text":"编辑路径与访问入口的逐项对应","correct":true,"feedback":"它能判断浏览器是否实际读取了此次修改。"},{"text":"项目文件的总数量","correct":false,"feedback":"文件总数即使相同，浏览器也可能打开不同目录中的入口，数量不能定位身份。"},{"text":"页面文件名相同就视为同一入口","correct":false,"feedback":"不同目录可有同名index.html，应核对完整路径而非只比较末尾文件名。"}]}],"sources":[{"label":"官方或原始资料：developer.mozilla.org","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Environment_setup/Dealing_with_files","checked":"2026-10-16"}]},{"id":"03.02","title":"浏览器、编辑器与终端","lead":"代码在编辑器里，启动信息在终端里，页面在浏览器里，哪一个才代表实际运行成功？","goals":["把一次标题修改的文件、运行与页面证据按职责连成记录","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"三种工具承担三种职责","paragraphs":["编辑器负责查看和修改文本，终端负责向命令行程序提交指令并呈现输出，浏览器负责请求资源、执行页面脚本和显示交互。它们可以同时工作，但看到编辑器有代码并不说明代码已经运行，看到终端有输出也不说明网页行为正确。","用一次标题修改连起来看：编辑器保存HTML，终端中的本地服务提供文件，浏览器读取地址后显示标题。每一段都有自己的证据。若改了标题没变化，要先判断断在保存、服务位置还是页面读取，而不是笼统说程序坏了。"]},{"title":"输出必须结合正在做的动作","paragraphs":["终端中“正在监听”的信息通常说明服务持续运行，未返回命令提示符不一定是卡死。一次性检查命令结束后会返回结果，持续服务则等待请求。判断成功要依据命令的预期工作方式，而不是只看是否停止。","教材示意行“服务地址：http://localhost:8000”只帮助理解信息类型，不是你电脑已经启动的证据。实际地址和端口必须从真实执行输出获取；不能把预制说明复制成验收记录。"],"code":"// 编辑器保存此行；服务提供文件；浏览器读取后显示\nconsole.log('practice ready');"},{"title":"浏览器显示也有不同证据层","paragraphs":["页面能打开说明至少有资源被读取，按钮能工作说明某条交互路径通过，刷新恢复又涉及独立存储。浏览器的开发者控制台是查看页面脚本消息与错误的位置，页面画面与控制台要在同一次操作中对应。","比如点击添加没反应，终端服务仍在运行，说明不能仅靠重启服务定位。应在浏览器检查按钮事件、相关脚本错误和输入条件。反例是终端出现一个无关提示就当成点击失败原因，时间接近不代表因果相同。"]},{"title":"形成可交接的三点记录","paragraphs":["求助时给出修改文件及差异、执行命令与当前目录、访问地址及复现动作。三点足以让协作者建立从文件到运行再到观察的路径；只发一张页面图，通常无法分辨代码没保存还是打开错位置。","先做一项小修改，逐个观察三个工具中真正变化了什么。静态文字变更可能不让终端增加明显输出，这是正常现象；不能强求所有工具都出现同一文字。证据是职责对应，不是三张截图看起来一样。"]}],"glossary":[{"term":"终端","meaning":"向命令行程序输入命令并读取其输出的窗口。"},{"term":"控制台","meaning":"浏览器中显示页面脚本消息与错误的调试区域。"},{"term":"持续进程","meaning":"启动后继续等待或处理工作、不会立刻结束的程序。"}],"predict":{"question":"本地服务显示监听地址且未返回提示符，能立即判定卡死吗？","options":[{"text":"能，任何命令都应马上退出","correct":false,"feedback":"持续服务和一次性检查命令的生命周期不同。"},{"text":"不能，服务通常需要持续等待请求","correct":true,"feedback":"是否结束应与这条命令的工作方式对应判断。"},{"text":"只要不退出就证明页面交互通过","correct":false,"feedback":"服务存活并未覆盖浏览器中的按钮行为。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"修改成功链路","input":"编辑器已保存新标题；服务提供该目录；浏览器访问该地址并重载。","question":"哪组对应最能说明修改生效？","options":[{"text":"终端显示服务启动完成即算标题修改通过","correct":false,"feedback":"服务可用不代表目标文件已保存或浏览器读取了新标题，仍需页面对应结果。"},{"text":"编辑器列出所有目录","correct":false,"feedback":"目录可见不代表浏览器读取了目标文件。"},{"text":"文件差异与同地址页面标题一致","correct":true,"feedback":"源码和实际读取结果建立了具体对应关系。"}],"output":"教学推演：标题变化可用于核对文件到页面的联系，添加与保存仍应按各自行为单独检查。","evidence":["保存的标题文本","浏览器实际地址和标题"]},{"name":"交互局部失败","input":"服务可访问，页面显示正常，但点添加时出现脚本错误。","question":"在当前文件到页面的链路中，优先收集什么？","options":[{"text":"点击步骤、浏览器错误和相关脚本位置","correct":true,"feedback":"当前断点发生在页面交互，而不是已工作的服务访问。"},{"text":"先重启仍正常访问的服务，不收集浏览器错误","correct":false,"feedback":"已有证据指向点击后的脚本失败，重启服务会略过更直接的事件错误信息。"},{"text":"只截服务仍在运行的画面","correct":false,"feedback":"它说明服务状态，遗漏了实际失败的交互证据。"}],"output":"教学推演：保留同次点击的错误，再定位事件处理函数；不能只因服务正常就宣告作品完成。","evidence":["点击时间与步骤","相关错误位置"]}]},"practice":{"intro":"把一次标题修改的文件、运行与页面证据按职责连成记录。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["在练习副本记录编辑文件路径，找到主标题片段","按项目已有说明启动或确认本地服务，保留命令、目录与实际地址","保存一处标题变更，在浏览器重载并比较","点击一次添加，分别说明终端存活与交互通过各证明什么"],"prompt":"本次练习是 03.02《浏览器、编辑器与终端》。把一次标题修改的文件、运行与页面证据按职责连成记录。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：在练习副本记录编辑文件路径，找到主标题片段；按项目已有说明启动或确认本地服务，保留命令、目录与实际地址；保存一处标题变更，在浏览器重载并比较；点击一次添加，分别说明终端存活与交互通过各证明什么。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：实际源码差异；真实命令、目录及服务输出；访问地址、标题变化和一次点击结果。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["实际源码差异","真实命令、目录及服务输出","访问地址、标题变化和一次点击结果"],"troubleshooting":[{"symptom":"不知道在哪里改","check":"确认当前位置是编辑器、终端还是浏览器","action":"先找到项目真实文件再修改，不把终端输出当源码编辑。"},{"symptom":"终端有文字却页面访问不了","check":"核对输出是否成功地址、错误或普通提示","action":"按地址访问并保留错误，分开验证服务与页面。"}]},"checks":[{"question":"网页能打开，终端里无新增日志，是否必定失败？","options":[{"text":"必定失败，三处必须同时变化","correct":false,"feedback":"职责不同并不要求显示完全相同的信息。"},{"text":"不一定，服务可能不记录每次请求","correct":true,"feedback":"日志策略不同，仍需按页面结果核对目标行为。"},{"text":"可以因此省去全部页面检查","correct":false,"feedback":"缺少请求日志可能是记录策略，页面行为是否正确仍需实际点击与结果。"}]},{"question":"最适合求助的材料是哪组？","options":[{"text":"只说我按教程做了","correct":false,"feedback":"没有命令、文件与动作，就无法重建起点并判断具体在哪一环节失败。"},{"text":"只提供终端启动成功截图，不记录点击过程","correct":false,"feedback":"终端截图说明服务状态，无法复现页面交互失败，需要动作与浏览器结果。"},{"text":"文件差异、真实命令目录、地址与复现动作","correct":true,"feedback":"能把修改、执行和观察串成可定位链路。"}]}],"sources":[{"label":"官方或原始资料：nodejs.org","url":"https://nodejs.org/learn/getting-started/introduction-to-nodejs","checked":"2026-10-16"}]},{"id":"03.03","title":"本地文件、服务与端口","lead":"同一份页面双击能看到，换成一个localhost地址却打不开，这是页面坏了吗？","goals":["比较文件与HTTP访问，并安全停止、恢复自己启动的前台服务","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"地址描述访问方式","paragraphs":["URL 是定位资源的地址，常见部分包括协议、主机、端口与路径。file 表示从文件系统打开，http 表示通过服务请求；localhost 通常指当前计算机。不同访问方式可能触发不同的浏览器限制和资源解析行为。","例如 file:///某目录/index.html 与 http://localhost:8000/index.html 都可能显示标题，但后者要求有服务在8000端口接收请求。端口可理解为同一台计算机上区分网络服务的编号，不是文件夹名，也不保证固定为教程里的数字。"]},{"title":"服务是正在运行的程序","paragraphs":["本地文件即使存在，HTTP服务没启动也不会自动响应。启动服务后，它会按配置的根目录提供文件；根目录错误时，地址能访问却可能显示另一项目。先核对真实启动输出，再打开其中给出的地址。","服务进程结束后，原来已加载的页面可能仍留在标签页，但重新加载会无法取得资源。这个现象能帮助区分“眼前还有页面”和“服务现在仍可访问”。不要用旧标签页的静止画面证明当前服务正常。"],"code":"http://localhost:8000/index.html\n// http是协议；localhost是主机；8000是端口；/index.html是路径"},{"title":"三类失败应分开定位","paragraphs":["连接失败通常先检查服务是否运行及主机端口，找不到资源先检查路径与服务根目录，页面加载后交互异常则检查页面脚本。分类不是绝对诊断，但能指导优先收集哪种证据，减少无目的改源码。","若地址把8000写成8001，先改回真实监听端口，不应重做添加按钮。若服务返回了目标页面但点击报错，也不能仅用换端口解决。让证据对应到失败环节，比凭错误文字的严重程度猜更有用。"]},{"title":"停止与恢复都要限定范围","paragraphs":["练习只停止由自己按课程启动的前台服务，通常可在那个终端按 Ctrl+C 请求结束。先确认终端和进程归属，不关闭无关服务，也不使用批量结束进程的方式。停止后刷新观察，再按原命令与目录恢复。","如果端口被占用，先查是否是自己已有的练习服务，必要时使用明确的新端口并记录变化。改变端口可能改变浏览器存储来源，所以任务列表为空不一定表示原数据被删。可返回02.05核对原来源。"]}],"glossary":[{"term":"URL","meaning":"描述访问方式、主机与资源位置的地址。"},{"term":"端口","meaning":"同一主机上区分不同网络服务的编号。"},{"term":"服务根目录","meaning":"服务用来寻找并提供资源的起始目录。"}],"predict":{"question":"页面文件存在，但目标端口没有服务，HTTP地址会自动打开文件吗？","options":[{"text":"不会，应先按说明启动对应服务","correct":true,"feedback":"文件存在不等于该端口已有程序响应请求。"},{"text":"会，浏览器能搜索本机所有文件","correct":false,"feedback":"HTTP访问不会自动遍历本机文件系统。"},{"text":"只要刷新很多次就会启动服务","correct":false,"feedback":"浏览器重试请求不等于执行服务启动命令。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"服务已停止","input":"自己启动的前台服务已用Ctrl+C结束；旧页面还停在屏幕上。","question":"针对这个本地服务访问现象，怎样验证当前仍能访问？","options":[{"text":"只看标签页标题","correct":false,"feedback":"标签标题可以保留旧状态，无法验证新请求。"},{"text":"重新加载并记录请求结果","correct":true,"feedback":"静止画面可能来自之前加载，不能证明现在服务存活。"},{"text":"先改所有HTML路径","correct":false,"feedback":"已知条件变化是服务停止，不是文件路径变更。"}],"output":"教学推演：新请求无法从已停止服务取得页面；按原目录与命令恢复后，再实际访问核对。","evidence":["服务终止记录","重新加载后的真实结果待采集"]},{"name":"访问错端口","input":"真实监听地址localhost:8000，浏览器输入localhost:8001。","question":"针对这个本地服务访问现象，优先修正哪里？","options":[{"text":"重写页面添加逻辑以修复连接问题","correct":false,"feedback":"连接错误发生在请求目标层，任务数组逻辑尚未执行，不能改变监听端口。"},{"text":"把同一个错误端口加入书签再尝试","correct":false,"feedback":"书签只重复已有错误地址，应先与真实监听端口对齐，不能替代服务定位。"},{"text":"把访问地址与实际监听端口对齐","correct":true,"feedback":"服务在8000监听而请求8001，目标不一致；先对齐真实地址再查其他层。"}],"output":"教学推演：先访问8000并核对根目录，若仍失败再根据新证据继续，不把错端口判为代码故障。","evidence":["真实启动输出8000","实际请求地址8001"]}]},"practice":{"intro":"比较文件与HTTP访问，并安全停止、恢复自己启动的前台服务。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["在副本记录文件打开地址及项目启动说明","请 Codex 解释真实启动命令的目录、服务和端口后再执行","用真实HTTP地址访问，记录主机、端口与页面","仅停止自己启动的前台服务，重载观察，再按原方式恢复"],"prompt":"本次练习是 03.03《本地文件、服务与端口》。比较文件与HTTP访问，并安全停止、恢复自己启动的前台服务。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：在副本记录文件打开地址及项目启动说明；请 Codex 解释真实启动命令的目录、服务和端口后再执行；用真实HTTP地址访问，记录主机、端口与页面；仅停止自己启动的前台服务，重载观察，再按原方式恢复。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：file与HTTP两种地址对照；真实启动与限定停止记录；停止后、恢复后同地址重载结果。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["file与HTTP两种地址对照","真实启动与限定停止记录","停止后、恢复后同地址重载结果"],"troubleshooting":[{"symptom":"连接被拒绝","check":"核对服务是否存活和访问端口","action":"先恢复目标服务，不对已经存在的页面作无依据重写。"},{"symptom":"页面能开但内容不是我的","check":"核对服务根目录和浏览器路径","action":"停止自己的错误服务，在正确目录重启并核对新地址。"}]},"checks":[{"question":"换端口后任务为空，首先应怎样判断？","options":[{"text":"核对来源变化与原端口存储","correct":true,"feedback":"端口会影响本地存储范围，空列表不等于原记录删除。"},{"text":"立刻认定保存代码永久失效","correct":false,"feedback":"端口变化可能换了存储空间，必须先排除不同来源，不能立刻判保存失效。"},{"text":"删除原端口所有数据","correct":false,"feedback":"删除会破坏证据，也不解释当前来源差异。"}]},{"question":"停止练习服务最合适的范围是什么？","options":[{"text":"结束所有同名运行时进程","correct":false,"feedback":"多个项目可能同时使用同一运行时名称，批量结束会误伤无关服务。"},{"text":"只停止自己本次启动的前台进程","correct":true,"feedback":"范围明确，能避免影响其他正在运行的工作。"},{"text":"重启整台机器作为唯一办法","correct":false,"feedback":"影响范围过大，也不能提供精确故障定位。"}]}],"sources":[{"label":"官方或原始资料：developer.mozilla.org","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/What_is_a_URL","checked":"2026-10-16"}]},{"id":"03.04","title":"变量、对象与数组","lead":"两条任务都叫“买书”，程序怎样只完成第二条，而不会把第一条也一起改掉？","goals":["阅读两条同名任务，预测改字段与换顺序，然后在独立副本验证","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"变量帮助指认当前值","paragraphs":["变量是程序给某个值起的名字，便于后续读取或更新。名字不是页面本身，也不会自动把内容显示出来。字符串是文本，例如'买书'；布尔值只有true或false，适合表示是否完成。理解类型能避免把文本'false'误当成真正的假值。","读 const title = '买书' 时，先指出变量名title、文本值和它用于什么。不要把等号机械理解为永久相等的数学声明，它在这里进行赋值。const约束的是该绑定不能重新指向别的值，不代表对象内部字段从此不可改。"]},{"title":"对象把一条记录的字段放一起","paragraphs":["对象是一组带名称的字段，可表示一条任务。{id:'t1', title:'买书', done:false}把标识、标题和状态分开，因为它们有不同职责。id用于定位，title用于展示，done用于行为和状态表达。","如果将标题直接当标识，两条同名任务会发生歧义；如果把“已完成”塞进标题，筛选就难以可靠判断。字段分开不是为了让代码更复杂，而是使修改范围可以准确说明：只改t2的done，不改title与其他记录。"],"code":"const tasks = [\n  { id: 't1', title: '买书', done: false },\n  { id: 't2', title: '买书', done: false }\n];\ntasks[1].done = true;\nconsole.log(tasks.length, tasks[0].done, tasks[1].done);"},{"title":"数组表示有顺序的一组记录","paragraphs":["数组把多条数据排成列表，索引是从零开始的位置编号。tasks[0]表示当前第一条，tasks.length表示数量；位置可能因排序、筛选或删除而变化，所以长期定位任务更适合稳定id。数组不是表格截图，而是程序可读取的结构。","给数组追加t3后数量增加，但原任务不会自动变成t3；修改其中一个对象字段，也不等于新增记录。每次阅读时分别问：改了哪条记录、哪个字段、数量是否变化。这样可区分添加、更新与重新排序。"]},{"title":"数据和页面需要绘制连接","paragraphs":["数据变化只有经过绘制逻辑才会变成页面文字或控件状态。把done从false改成true，页面可能通过复选框或划线表达，也可能因未重新绘制而暂时不变。反过来，直接改页面文字并不一定更新数组。","可先手算两条数据的结果，再用增强样课 data-literacy.html 核对字段、标识与渲染关系。页面中的预制规则实验只验证给定示例；独立Codex项目实操仍需保存真实数据差异和页面结果，不能把样课通过当作外部作品已完成。"]}],"glossary":[{"term":"变量","meaning":"给程序当前可读取的值起的名字。"},{"term":"对象","meaning":"用多个具名字段描述一条记录的数据结构。"},{"term":"数组","meaning":"按顺序保存多项数据的结构，索引通常从零开始。"}],"predict":{"question":"t1与t2同名，想只完成t2，应该定位并修改什么？","options":[{"text":"把所有title等于买书的记录都完成","correct":false,"feedback":"标题可以重复，这会改变用户没有选择的记录。"},{"text":"只把第二条显示文字改成已完成","correct":false,"feedback":"页面文字变化未必同步到真实任务状态。"},{"text":"按id找到t2，只改它的done","correct":true,"feedback":"稳定标识区分同名记录，完成状态由专门字段承担。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"改字段","input":"tasks=[{id:'t1',title:'买书',done:false},{id:'t2',title:'买书',done:false}]；仅t2.done=true。","question":"结果数量与状态怎样变化？","options":[{"text":"仍为两条，只有t2完成","correct":true,"feedback":"更新字段没有执行数组追加，也没修改t1。"},{"text":"变为三条，新增完成记录","correct":false,"feedback":"字段赋值只更新现有对象，题中没有push等新增对象动作，因此数量不增加。"},{"text":"两条都完成，因为标题相同","correct":false,"feedback":"给定修改按t2定位，不按标题批量匹配。"}],"output":"教学推演：数量2；t1的done为false；t2的done为true；显示变化还需相应绘制逻辑。","evidence":["数组长度不变","仅t2.done发生差异"]},{"name":"改顺序","input":"原数组[t1,t2]改成[t2,t1]，两者字段未改。","question":"根据当前任务数组变化，什么会发生变化？","options":[{"text":"t1自动改名为t2","correct":false,"feedback":"数组换序只是位置改变，id字段没有赋值操作，不会因索引变化自动改名。"},{"text":"位置改变，稳定id仍对应各自记录","correct":true,"feedback":"顺序调整不会自动改变记录身份或完成状态。"},{"text":"所有任务恢复未完成","correct":false,"feedback":"题中只改变数组顺序，没有修改done值，因此不能推出任务全部变为未完成。"}],"output":"教学推演：索引0现在指向t2，原来的t1仍存在于索引1；按旧位置定位可能误改目标。","evidence":["新旧顺序对照","每条id与done保持对应"]}]},"practice":{"intro":"阅读两条同名任务，预测改字段与换顺序，然后在独立副本验证。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["复制案例数据到练习说明，标出变量、数组、对象和三个字段","先手写只改t2.done后的数量、标题与状态","请 Codex 在副本中提供最小可运行数据阅读示例并解释输出","分别执行字段修改和顺序交换，核对实际结果，另可进入增强样课复习"],"prompt":"本次练习是 03.04《变量、对象与数组》。阅读两条同名任务，预测改字段与换顺序，然后在独立副本验证。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：复制案例数据到练习说明，标出变量、数组、对象和三个字段；先手写只改t2.done后的数量、标题与状态；请 Codex 在副本中提供最小可运行数据阅读示例并解释输出；分别执行字段修改和顺序交换，核对实际结果，另可进入增强样课复习。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：手工预测与字段职责说明；实际最小代码和真实结果；同名定位与顺序变化的两份差异记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["手工预测与字段职责说明","实际最小代码和真实结果","同名定位与顺序变化的两份差异记录"],"troubleshooting":[{"symptom":"改一条却两条一起变","check":"核对查找条件是否用title而非id","action":"先确定唯一id，再只更新目标对象并复查另一条。"},{"symptom":"数据变了页面没变","check":"核对是否调用了使用当前数组的绘制逻辑","action":"分开检查状态与渲染，不把显示滞后当作赋值一定失败。"}]},"checks":[{"question":"删除第一条后，旧的tasks[1]还一定是原第二条吗？","options":[{"text":"一定，索引与身份永久绑定","correct":false,"feedback":"删除会改变数组位置，不能依赖旧索引。"},{"text":"所有id也必须跟着重排","correct":false,"feedback":"id应保持稳定，不应仅因位置变化重编号。"},{"text":"不一定，索引会随列表变化","correct":true,"feedback":"位置是当前顺序的结果，稳定身份需要id。"}]},{"question":"'false'与false有什么关键差别？","options":[{"text":"前者是文本，后者是布尔值","correct":true,"feedback":"文本看似相同也不等于程序中的假值类型。"},{"text":"两者在所有判断中完全相同","correct":false,"feedback":"类型影响判断，不能只看显示出来的字母。"},{"text":"后者只是页面装饰文字","correct":false,"feedback":"布尔值可直接承担状态与条件判断职责。"}]}],"sources":[{"label":"官方或原始资料：developer.mozilla.org","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/Variables","checked":"2026-10-16"}]},{"id":"03.05","title":"函数、条件与事件","lead":"点击后提示出现了却没有新增任务，可能是错误，也可能是程序正确地拒绝了空输入，怎样区分？","goals":["阅读并验证按钮到trim、空值分支、return与追加的最小轨迹","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"函数把操作组织成步骤","paragraphs":["函数是一段可以被调用的步骤，输入值参与处理，返回或副作用构成结果。处理添加任务时，函数可读取输入、判断是否有效、追加记录并绘制。不是页面所有代码都会因为一次点击重新执行，要先找这次点击实际调用的函数。","事件监听器把按钮动作与函数连接起来，例如button.addEventListener('click', addTask)。这里写的是函数引用，表示点击时再执行。仅有函数定义而未绑定入口，就像写了流程但没有人启动它，按钮不会自动知道应该调用哪段代码。"]},{"title":"条件决定走哪条分支","paragraphs":["条件是程序根据当前值作出的判断。const title = input.value.trim()先读取并去掉两端空白；if (!title)在没有有效文字时进入拒绝分支。相同按钮面对不同输入可以走不同路径，这是设计行为，不一定是随机故障。","空格经过trim后成为空字符串；文字“买书”处理后仍有内容。先预测这两种输入分别会不会进入追加步骤，再观察运行轨迹，可以把条件与结果联系起来。只背if语法却不理解输入怎样变化，无法判断为什么某次点击被拦住。"],"code":"function addTask() {\n  const title = input.value.trim();\n  if (!title) { showHint(); return; }\n  tasks.push({ id: makeId(), title, done: false });\n  render();\n}\nbutton.addEventListener('click', addTask);"},{"title":"return只结束当前函数调用","paragraphs":["在空值分支中执行return，会结束本次addTask函数调用，后面的追加和绘制步骤不再沿此调用继续执行。它不会自动关闭页面、结束所有程序或取消未来按钮事件。页面仍可等待下一次有效输入。","例如if (!title) { showHint(); return; }之后才写tasks.push(...)。空值时提示出现、数量不变，正是分支目标；再次输入有效文字并点击，函数会从入口重新开始，不会永久停留在上次return的位置。"]},{"title":"跟踪入口、判断、状态与显示","paragraphs":["阅读最小代码时按四个位置做标记：事件入口、条件表达式、数据修改和显示更新。若空输入也新增，检查判断是否在追加之后；若有效输入无变化，检查是否提前返回或入口未绑定。每种现象都能对应不同断点。","本课不需要背写整段程序，而要能根据运行轨迹指出执行到哪里。课堂按钮轨迹是受控规则演示，不能代表任意项目都运行成功；在自己的副本应保留真实输入、命中分支和数组数量，形成可重现证据。"]}],"glossary":[{"term":"函数","meaning":"接到调用后按定义执行的一组步骤。"},{"term":"条件分支","meaning":"依据当前判断结果选择执行不同步骤。"},{"term":"return","meaning":"结束当前函数的本次调用，可同时返回一个值。"}],"predict":{"question":"空白输入命中return后，下一次输入文字再点击会怎样？","options":[{"text":"所有程序都已结束，必须重启电脑","correct":false,"feedback":"当前函数退出不等于页面或系统被关闭。"},{"text":"会发起新的函数调用并重新判断","correct":true,"feedback":"return结束上一调用，不会永久禁用事件监听器。"},{"text":"会从上次return下一行接着运行","correct":false,"feedback":"新点击从函数入口开始，不延续已经结束的调用。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"空格被拦截","input":"点击添加；input.value='   '；trim后title=''；空值分支先提示再return；push在后。","question":"在本次按钮函数轨迹中，应怎样预测数量？","options":[{"text":"增加一条空任务","correct":false,"feedback":"空白经过trim后为空，并在push前return，本次调用不能继续到追加步骤。"},{"text":"页面从此不再接收任何点击","correct":false,"feedback":"退出本次调用不取消监听器或后续事件。"},{"text":"保持原数量，追加步骤不执行","correct":true,"feedback":"本次调用在到达push之前已由return结束。"}],"output":"教学推演：轨迹为点击→读取→trim为空→提示→return；本次不经过追加，页面可继续接收操作。","evidence":["trim结果为空","return在push之前"]},{"name":"有效输入","input":"下一次点击；input.value=' 买书 '；trim后title='买书'；不命中空值分支。","question":"在本次按钮函数轨迹中，应进入哪一步？","options":[{"text":"追加有效任务，再更新显示","correct":true,"feedback":"判断不为空后才进入后续数据修改与绘制。"},{"text":"继续执行上次空值提示","correct":false,"feedback":"本次输入与分支重新计算，不沿用上次结论。"},{"text":"有效输入也提前return，不再追加记录","correct":false,"feedback":"当前空值判断没有命中，应继续执行追加；无条件return会拒绝有效输入。"}],"output":"教学推演：轨迹为新点击→读取→trim得买书→通过检查→push→绘制；任务数量应增加一条。","evidence":["新调用重新读取输入","数组长度增加且标题为买书"]}]},"practice":{"intro":"阅读并验证按钮到trim、空值分支、return与追加的最小轨迹。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["请 Codex 在副本定位事件绑定及addTask函数，只展示相关短片段","标出trim、if、return、push和绘制，口述每个职责","先预测三个空格的路径再点击，记录数量不变与提示","再输入带两端空格的买书，记录新调用的路径和新增结果"],"prompt":"本次练习是 03.05《函数、条件与事件》。阅读并验证按钮到trim、空值分支、return与追加的最小轨迹。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：请 Codex 在副本定位事件绑定及addTask函数，只展示相关短片段；标出trim、if、return、push和绘制，口述每个职责；先预测三个空格的路径再点击，记录数量不变与提示；再输入带两端空格的买书，记录新调用的路径和新增结果。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：最小代码中四类职责标记；空白输入被拦截的真实轨迹；再次有效输入可新增且文字已去两端空白。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["最小代码中四类职责标记","空白输入被拦截的真实轨迹","再次有效输入可新增且文字已去两端空白"],"troubleshooting":[{"symptom":"空白仍被新增","check":"核对trim是否在判断前、push是否在return后","action":"调整顺序并重测空格与有效文字两个条件。"},{"symptom":"有效文字也不新增","check":"核对事件入口、实际title和提前return位置","action":"一次只定位一个断点，不把全部界面重写作为首选。"}]},"checks":[{"question":"把push移到空值判断前会带来什么？","options":[{"text":"return会回滚当前函数全部动作","correct":false,"feedback":"普通return不提供事务或自动撤销机制。"},{"text":"可能先新增空记录再返回","correct":true,"feedback":"return不能自动撤销此前已经执行的数据修改。"},{"text":"trim会自动删除数组中的空记录","correct":false,"feedback":"trim只处理调用它的字符串，不清理整个数组。"}]},{"question":"函数定义存在但按钮不触发，先核对什么？","options":[{"text":"先检查push内部数据，暂不核对事件入口","correct":false,"feedback":"若函数根本未触发，追加逻辑还没执行，应先确认按钮确实绑定目标函数。"},{"text":"只手动调用函数，不再核对真实按钮绑定","correct":false,"feedback":"手动调用可测试函数，却不能证明页面按钮能触发，仍需验证事件连接。"},{"text":"事件是否绑定到实际按钮和目标函数","correct":true,"feedback":"定义步骤与建立触发入口是两个独立环节。"}]}],"sources":[{"label":"官方或原始资料：developer.mozilla.org","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/Events","checked":"2026-10-16"}]},{"id":"03.06","title":"等待、异步与错误","lead":"页面显示“加载中”，两秒后出现提示，这两秒内哪些动作已经完成，哪些还没有？","goals":["在本地副本运行可控延迟的成功与失败示例，并记录状态时间线","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"异步把开始与完成分开","paragraphs":["异步是发起某项工作后，结果稍后才到来，程序可以在等待期间处理别的事。发出请求不等于拿到结果，显示加载中也不是成功状态。把开始、等待、成功或失败写成四个状态，可以准确描述当前进度。","例如读取一份演示资料可能延迟两秒，按钮点击已经发生，但内容尚不可用。若此时让页面声称“保存成功”，用户可能关闭窗口而丢失工作。状态文字应对应真实完成点，而不应只对应点击瞬间。"]},{"title":"await等待的是某个结果","paragraphs":["Promise 可理解为一份将来会成功或失败的结果凭据；await让当前异步函数等待它结束。等待不表示整个电脑停止，也不保证结果一定成功。后续依赖结果的代码应放在等待成功之后。","最小示例为const data = await loadDemo(); show(data);。show要用data，因此需要等待；若loadDemo拒绝并抛出错误，通常不会按正常路径继续show。教材中的延迟可由本地模拟构造，不应冒充真实网络访问。"],"code":"async function readDemo() {\n  setLoading(true);\n  try { const data = await loadDemo(); show(data); }\n  catch (error) { showFailure(error.message); }\n  finally { setLoading(false); }\n}"},{"title":"错误改变后续控制流","paragraphs":["try包含可能失败的动作，catch接收该范围内抛出的错误，finally适合结束加载状态等无论结果如何都要做的清理。错误处理不仅是打印红字，还要让用户知道能否重试、当前数据是否保留。","例如读取失败后显示“暂未取得资料，可重试”，并恢复按钮；不能显示空清单而不说明失败，否则用户会把没读到误当成没有数据。反例是catch中吞掉错误又显示成功，这让排错和用户判断同时失去依据。"]},{"title":"用同一操作的证据定位","paragraphs":["等待太久、明确失败和返回内容不符是三类现象。记录输入、开始时间、当前状态、相关错误位置和调用步骤，才能知道断在请求前、等待中还是结果处理。不要只看一行错误就删除与它无关的代码。","先用可控的成功延迟和失败延迟各一次，比较页面状态和最终结果。重复点击可能制造并发操作，因此加载中应有明确策略，如暂时禁用重复提交。更复杂的请求取消与并发在后续项目中学习，本课先能解释等待与完成。"]}],"glossary":[{"term":"异步","meaning":"工作开始后结果稍后到来，开始与完成不是同一时刻。"},{"term":"Promise","meaning":"表示将来可能成功或失败的结果对象。"},{"term":"错误处理","meaning":"在失败时保存证据、恢复状态并提供下一步的逻辑。"}],"predict":{"question":"刚点击就显示保存成功，但异步写入随后失败，问题在哪里？","options":[{"text":"把发起动作误当成完成证据","correct":true,"feedback":"成功提示必须建立在实际完成结果上，而不是点击时间。"},{"text":"等待两秒就天然保证保存成功","correct":false,"feedback":"时间经过并不能决定异步结果是成功还是失败。"},{"text":"保留成功文字，只延长加载动画两秒","correct":false,"feedback":"动画时长不保证实际写入完成，成功反馈应由异步结果决定。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"延迟成功","input":"loadDemo将在2秒后成功返回两条演示记录，当前只完成了调用。","question":"按这次异步读取时间线，等待期间应怎样表达？","options":[{"text":"先显示读取完成","correct":false,"feedback":"调用刚发出时结果尚未知，异步操作仍可能失败，不能提前显示读取完成。"},{"text":"显示加载中，不宣称已有最终结果","correct":true,"feedback":"结果尚未到来，应保留等待状态并避免误导。"},{"text":"把旧列表当作本次新结果","correct":false,"feedback":"旧清单来自先前状态，不能证明当前请求已经成功返回并取得新内容。"}],"output":"教学推演：先出现加载状态，2秒后读取成功再显示两条；时间与返回均为预制演示条件。","evidence":["返回前后的状态区别","最终条数与输入约定一致"]},{"name":"延迟失败","input":"loadDemo将在2秒后抛出错误；catch给提示，finally结束加载。","question":"按这次异步读取时间线，最终怎样才算合理？","options":[{"text":"仍显示成功并隐藏错误","correct":false,"feedback":"会把未完成的结果写成完成，使后续判断失真。"},{"text":"永远保持加载中","correct":false,"feedback":"错误已明确到来，继续等待无法帮助用户恢复。"},{"text":"显示失败与重试入口，并结束加载","correct":true,"feedback":"失败需要说明，界面也应从等待状态恢复。"}],"output":"教学推演：失败提示出现，按钮恢复；两条记录不应被伪造为已读取，相关错误位置应可核对。","evidence":["catch处理失败","finally恢复加载状态"]}]},"practice":{"intro":"在本地副本运行可控延迟的成功与失败示例，并记录状态时间线。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["请 Codex 使用本地演示数据构造2秒成功或失败，不访问外部服务","先阅读await、try、catch、finally各自位置并预测时间线","执行成功条件，记录点击、加载、内容出现三点","切换为失败条件，记录提示、相关错误与按钮恢复，再重试"],"prompt":"本次练习是 03.06《等待、异步与错误》。在本地副本运行可控延迟的成功与失败示例，并记录状态时间线。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：请 Codex 使用本地演示数据构造2秒成功或失败，不访问外部服务；先阅读await、try、catch、finally各自位置并预测时间线；执行成功条件，记录点击、加载、内容出现三点；切换为失败条件，记录提示、相关错误与按钮恢复，再重试。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：两种条件的预测时间线；真实加载与终态记录；相关错误位置与成功重试结果。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["两种条件的预测时间线","真实加载与终态记录","相关错误位置与成功重试结果"],"troubleshooting":[{"symptom":"一直显示加载中","check":"核对是否进入finally及是否有未结束的Promise","action":"缩小到本地可控示例，确认结束路径后再接真实请求。"},{"symptom":"失败也显示成功","check":"核对成功提示是否写在等待完成前或catch中","action":"把成功反馈移到确实成功的分支，并重测失败条件。"}]},"checks":[{"question":"有了catch就能证明数据已保存吗？","options":[{"text":"不能，它只说明安排了失败处理路径","correct":true,"feedback":"实际写入是否成功仍需结果与读取验证。"},{"text":"能，catch会自动修复所有错误","correct":false,"feedback":"catch执行定义的处理，不会自动完成原任务。"},{"text":"只有没有catch才算异步","correct":false,"feedback":"异步描述结果到来的时间关系，catch描述失败处理，二者不是同一个判断。"}]},{"question":"错误明确后仍空白无提示，主要风险是什么？","options":[{"text":"说明数据一定已被删除","correct":false,"feedback":"失败读取不能单独证明底层数据不存在。"},{"text":"用户无法区分没数据与没读到数据","correct":true,"feedback":"两种状态需要不同恢复动作，应明确表达。"},{"text":"空列表就可作为读取到零条记录处理","correct":false,"feedback":"读取失败与成功返回空列表含义不同，缺少提示会误导用户以为数据不存在。"}]}],"sources":[{"label":"官方或原始资料：developer.mozilla.org","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Async_JS/Promises","checked":"2026-10-16"}]},{"id":"03.07","title":"运行时、依赖与配置","lead":"文件一份没少，换台电脑却提示找不到命令或模块，这些缺失分别在说什么？","goals":["在隔离副本阅读运行说明、依赖声明和配置，再复现一个本地模块缺失","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"运行时负责执行某类代码","paragraphs":["运行时是执行代码所需的环境，例如浏览器执行页面脚本，Node.js可在浏览器之外执行JavaScript。源码文件像流程说明，运行时像能执行该说明的工作环境；文件存在不等于环境已就绪。版本不同还可能影响支持的语法或接口。","先读项目说明，再记录实际运行时版本。若终端说找不到node命令，优先检查运行时是否安装以及命令是否可被当前终端找到；不要直接修改任务数组，因为程序甚至还没开始执行项目代码。"]},{"title":"依赖是项目引用的外部组件","paragraphs":["依赖是项目使用、却不全由本项目自己编写的代码包。package.json可声明所需包和启动脚本，锁定文件进一步记录解析后的具体版本信息。声明说明需求，实际安装才把需要的代码准备到当前环境，二者不是同一动作。","例如package.json有scripts.start为node server.js，执行npm start会按这个定义启动，不应猜测它一定构建网站。若提示缺少模块，先对照声明和锁定文件，再选择项目官方推荐安装方式，避免随意安装同名但不同用途的包。"],"code":"{ \"scripts\": { \"start\": \"node server.js\" } }"},{"title":"配置连接代码与环境","paragraphs":["配置是会因环境而变化的输入，如端口、路径或运行模式。它可能来自文件、命令参数或环境变量。配置错误可能让完整代码访问错误位置，所以先记录配置来源与适用范围，再决定改哪里。","例如PORT设置为8001，浏览器仍访问8000，看起来像服务不工作；实际应核对真实启动输出。凭据属于敏感配置，不能为求助把整个环境文件发出。展示缺项名称与脱敏错误通常比分享秘密值更有帮助。"]},{"title":"依据错误作最小修复","paragraphs":["找不到命令、缺少依赖、版本不兼容和配置缺失需要不同处理。先记录原始错误和执行目录，复述它指向哪一层，再做一个可验证变更。反复删除锁定文件、升级所有包会同时改变多个条件，使成功原因和新故障都难以解释。","故障演练应在独立副本中进行，且不要求联网下载。可用一个明确引用不存在本地文件的短示例观察模块缺失，再恢复该文件。真实安装只有在项目确实需要、来源和步骤清楚时执行；课程不把一条成功安装日志当作页面验收。"]}],"glossary":[{"term":"运行时","meaning":"实际执行某类代码的环境，而非源码本身。"},{"term":"依赖","meaning":"项目运行或构建要使用的外部代码组件。"},{"term":"锁定文件","meaning":"记录依赖解析后的具体版本等信息，帮助重现安装。"}],"predict":{"question":"终端找不到node，代码还没执行，优先核对哪层？","options":[{"text":"先修改入口脚本中的业务数据","correct":false,"feedback":"找不到node发生在运行时查找阶段，入口业务代码尚未开始执行。"},{"text":"先删除项目依赖目录再重装全部包","correct":false,"feedback":"当前连node命令都未找到，应先准备运行时，重装项目包并不解决命令入口。"},{"text":"运行时与当前命令查找环境","correct":true,"feedback":"错误发生在寻找执行程序时，尚未进入任务业务逻辑。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"缺本地模块","input":"入口demo.cjs含require('./helper.cjs')，副本目录没有helper.cjs。","question":"针对当前环境缺项证据，先核对什么？","options":[{"text":"引用路径与缺失文件是否匹配","correct":true,"feedback":"已给出本地文件依赖，先查路径和文件存在性。"},{"text":"立即安装名字叫helper的网络包","correct":false,"feedback":"本地相对引用与同名外部包不是同一个对象。"},{"text":"升级所有系统软件","correct":false,"feedback":"变化范围过大，且没有证据指向系统版本。"}],"output":"教学推演：加载在本地helper缺失处失败；恢复对应文件后重跑，才能确认这一原因是否已消除。","evidence":["相对require路径","目录中缺少目标文件"]},{"name":"配置不同","input":"启动配置PORT=8001，真实输出监听8001，浏览器仍访问8000。","question":"针对当前环境缺项证据，最小纠正是什么？","options":[{"text":"删掉全部依赖重新安装","correct":false,"feedback":"依赖已支持启动，重装不解决错误访问目标。"},{"text":"访问实际地址并记录配置","correct":true,"feedback":"请求目标应与当前运行配置对应，不先改业务代码。"},{"text":"先删锁定文件再升级依赖以恢复8000","correct":false,"feedback":"服务已经在配置的8001正常监听，升级依赖不会自动让错误访问端口正确。"}],"output":"教学推演：先对齐地址；如果仍有问题再采集新的错误，不能把配置差异直接判为依赖故障。","evidence":["配置来源PORT","真实监听与访问地址差异"]}]},"practice":{"intro":"在隔离副本阅读运行说明、依赖声明和配置，再复现一个本地模块缺失。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["记录项目运行说明与实际运行时版本，不安装未知软件","读package.json中一条启动脚本，让Codex逐项解释实际动作","在独立demo子目录创建入口和本地helper，先确认正常","暂把helper改名，保存真实缺失错误，再恢复名称并重跑"],"prompt":"本次练习是 03.07《运行时、依赖与配置》。在隔离副本阅读运行说明、依赖声明和配置，再复现一个本地模块缺失。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：记录项目运行说明与实际运行时版本，不安装未知软件；读package.json中一条启动脚本，让Codex逐项解释实际动作；在独立demo子目录创建入口和本地helper，先确认正常；暂把helper改名，保存真实缺失错误，再恢复名称并重跑。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：运行时版本与启动脚本解释；缺失前后目录及原始错误；恢复后同命令结果与配置范围说明。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["运行时版本与启动脚本解释","缺失前后目录及原始错误","恢复后同命令结果与配置范围说明"],"troubleshooting":[{"symptom":"提示找不到命令","check":"核对所需运行时与当前终端的命令查找","action":"按官方安装说明准备环境，重开终端后先查版本。"},{"symptom":"修一项又出现很多新错","check":"核对是否同时升级、删锁文件或改配置","action":"回到已知副本，保留原错误并一次只改一个条件。"}]},"checks":[{"question":"package.json声明依赖是否代表本机已装好？","options":[{"text":"代表，文字声明会自动下载","correct":false,"feedback":"文件内容本身不会无条件执行安装动作。"},{"text":"复制package.json后可省略实际依赖准备","correct":false,"feedback":"声明文件列出需要什么，当前机器仍需按说明准备运行时与实际依赖。"},{"text":"不代表，声明与实际安装状态不同","correct":true,"feedback":"应按项目说明核对当前环境的准备结果。"}]},{"question":"锁定文件的主要帮助是什么？","options":[{"text":"记录解析版本以提高环境重现性","correct":true,"feedback":"它减少安装时版本漂移，但仍需实际运行验证。"},{"text":"自动替代所有配置文件","correct":false,"feedback":"依赖版本记录不包含每个环境的运行配置。"},{"text":"保证所有未来版本都兼容","correct":false,"feedback":"锁定具体版本不能保证未知未来版本的行为。"}]}],"sources":[{"label":"官方或原始资料：docs.npmjs.com","url":"https://docs.npmjs.com/cli/v11/configuring-npm/package-json/","checked":"2026-10-16"}]},{"id":"03.08","title":"命令、工作目录与报错","lead":"同一条命令在两个目录里结果不同，为什么先问“你在哪里运行”比先问“你输入了什么”还重要？","goals":["先解释一条实际命令，再在副本复现找不到脚本的无害失败并修复","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"命令包含动作、参数与范围","paragraphs":["命令行请求由程序名和参数组成；参数进一步说明处理哪个文件或采用哪个选项。工作目录是执行时的当前位置，相对文件参数通常从这里解析。只抄命令文字却忽略目录，很容易读到错误文件或找不到目标。","例如node demo.cjs表示让Node.js执行当前目录定位到的demo.cjs。若终端位于父目录，就可能找不到它；若父目录恰有同名文件，又可能执行了别的内容。运行前先打印或查看当前位置，并列出目标文件。"]},{"title":"先解释再执行降低误操作","paragraphs":["看到命令先确认它读取、修改还是删除什么，是否持续运行，预期输出是什么。命令能被输入不代表适合当前项目。未知参数应查看对应官方帮助，不要按名字猜测，尤其涉及覆盖、递归和远程操作时。","本课只用只读版本查询和执行自制演示脚本。可以先让Codex逐项解释node demo.cjs的程序名、文件参数与范围，复述“在练习目录执行”。理解命令的目的，比记住一串字符更能迁移到其他项目。"],"code":"node demo.cjs\n// 在练习目录执行；此处是一条命令，不是网页代码"},{"title":"输出、退出与持续运行合看","paragraphs":["输出是程序写出的消息，退出码是进程结束时报告的状态；通常0表示成功，非0需按程序约定查原因。提示、警告和错误未必只靠颜色区分，持续服务暂时没有退出码也不表示失败。","比如脚本打印“准备开始”后抛错，不能因为出现第一行文字就算通过。要看最终是否结束成功及关键输出是否存在。另一方面，服务显示监听后继续运行是预期行为，不能不断强行重启直到它立刻退出。"]},{"title":"保留最小可重现记录","paragraphs":["最小记录包括命令、工作目录、运行环境、输入文件、原始错误与最近改动。准确错误行常含文件路径和位置，能帮助区分找不到文件与文件内部语法问题。不要只截最后一句或改写成“不能用”。","无害失败可以通过在副本执行不存在的demo-missing.cjs触发，不需要破坏真实项目。修复时改为正确文件名并重复同一流程，记录错误消失和预期输出出现。成功应来自可解释的条件变化，而不是盲目轮流尝试命令。"]}],"glossary":[{"term":"工作目录","meaning":"命令执行时用于解释相对路径的当前位置。"},{"term":"参数","meaning":"传给命令程序、用于说明对象或选项的内容。"},{"term":"退出码","meaning":"程序结束时报告的状态值，含义按程序约定解释。"}],"predict":{"question":"脚本先打印开始，再因语法错误退出，是否算运行成功？","options":[{"text":"算，终端已经有内容出现","correct":false,"feedback":"出现开始消息只说明执行到该位置，后续语法或运行错误仍会使任务失败。"},{"text":"不算，应结合最终状态与预期输出","correct":true,"feedback":"中间消息只能说明执行到某步，不能覆盖后续失败。"},{"text":"只看开始消息，不记录后续退出结果","correct":false,"feedback":"开始消息只说明执行到中间位置，后续失败仍使完整任务没有完成。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"目录错误","input":"demo.cjs在practice目录，终端当前位置却是另一个空目录。","question":"node demo.cjs失败后先查什么？","options":[{"text":"先改demo.cjs中输出文字再试","correct":false,"feedback":"终端尚未找到目标脚本，修改内部输出不解决工作目录与相对路径不匹配。"},{"text":"先增加新的package.json启动脚本","correct":false,"feedback":"直接命令在错误目录找不到文件，增加脚本不如先核对当前目录与目标位置。"},{"text":"当前目录与脚本实际路径","correct":true,"feedback":"相对文件参数需要正确出发点才能定位。"}],"output":"教学推演：切到明确的练习目录或使用经核对的路径后重跑，记录真实结果，不改无关业务文件。","evidence":["实际当前位置","脚本真实文件位置"]},{"name":"脚本内部失败","input":"目录正确，demo.cjs存在，但真实错误指向该文件第三行语法。","question":"根据这次命令与目录记录，下一步检查哪里？","options":[{"text":"读取第三行附近并与最近差异对应","correct":true,"feedback":"路径已正确且文件已找到，应根据行号检查文件内容的语法，而不是继续找路径。"},{"text":"继续在所有目录搜索同名文件","correct":false,"feedback":"已有精确文件位置，应先检查给出的语法证据。"},{"text":"把所有报错统一忽略","correct":false,"feedback":"忽略错误会隐藏程序未执行完成的事实，使后续协作者误以为结果可用。"}],"output":"教学推演：对准该行作最小修复，再用同目录同命令复测；文件存在与内容有效分别检查。","evidence":["原始错误位置","最近编辑差异"]}]},"practice":{"intro":"先解释一条实际命令，再在副本复现找不到脚本的无害失败并修复。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["准备只打印practice ready的demo.cjs，记录完整路径","请Codex解释node demo.cjs的动作、参数和执行目录","先在正确目录运行，再把参数改成不存在的文件名观察错误","恢复正确参数并重跑，比较最终状态与预期输出"],"prompt":"本次练习是 03.08《命令、工作目录与报错》。先解释一条实际命令，再在副本复现找不到脚本的无害失败并修复。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：准备只打印practice ready的demo.cjs，记录完整路径；请Codex解释node demo.cjs的动作、参数和执行目录；先在正确目录运行，再把参数改成不存在的文件名观察错误；恢复正确参数并重跑，比较最终状态与预期输出。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：命令逐项解释与工作目录；完整原始错误和可重现步骤；恢复后的真实输出与退出状态。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["命令逐项解释与工作目录","完整原始错误和可重现步骤","恢复后的真实输出与退出状态"],"troubleshooting":[{"symptom":"同命令在别处失败","check":"核对当前目录和相对参数指向","action":"确认路径后再运行，不随机安装依赖。"},{"symptom":"只有输出截图看不出是否结束","check":"核对命令性质、提示符和最终退出状态","action":"补充持续运行或已退出的说明，并保留关键末尾信息。"}]},"checks":[{"question":"报错给出文件和行号，最有帮助的下一步是什么？","options":[{"text":"立即粘贴整个私人项目到网上","correct":false,"feedback":"范围过大且可能包含与定位无关的信息。"},{"text":"查看相关短片段与最近改动","correct":true,"feedback":"位置证据能缩小检查范围，避免无目的重写。"},{"text":"只发一句失败让AI猜原因","correct":false,"feedback":"缺少执行范围和具体错误，难以建立可复现条件。"}]},{"question":"服务未返回命令提示符，一定是失败吗？","options":[{"text":"一定，所有成功命令都瞬间结束","correct":false,"feedback":"服务的工作方式通常需要继续运行等待请求。"},{"text":"只要持续运行就无需访问检查","correct":false,"feedback":"进程继续存活只说明它未退出，仍需实际发请求和检查核心行为。"},{"text":"不一定，要看它是否应持续监听","correct":true,"feedback":"持续工作与一次性命令应采用不同完成判断。"}]}],"sources":[{"label":"官方或原始资料：nodejs.org","url":"https://nodejs.org/learn/getting-started/introduction-to-nodejs","checked":"2026-10-16"}]},{"id":"03.09","title":"版本差异与 Git","lead":"准备恢复标题错误时，又写了一段有用说明，怎样只撤销错误而不丢掉新工作？","goals":["在独立练习仓库查看差异、记录可用版本，并只恢复一次指定标题修改","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"版本记录保存可解释的变化","paragraphs":["Git是记录文件版本变化的工具，仓库是保存这类记录与当前工作的地方。提交表示把选定的一组变化存成可定位快照，并附说明。它与复制文件夹都能帮助返回，但Git还能查看连续差异和每次变更的目的。","提交并不自动把代码上传到远程，也不说明程序已经正确。一个带错误的版本同样可以被记录。先验收再保存可用基线，并在说明中写清检查范围，能让以后恢复时有可靠依据。"]},{"title":"工作区、暂存与提交分层","paragraphs":["工作区是正在编辑的文件状态，暂存区是准备放进下一次提交的选定内容，提交历史是已经记录的版本。git status用于查看当前变化，git diff用于比较内容。它们是只读观察入口，适合在恢复前先执行。","如果只改了标题和帮助段落，差异会让你看到两处变化。不要因为都在同一个文件就把它们当成一个决定。先确定哪些应保留、哪些应撤销，再选定恢复范围；暂存也不能代替最终提交。"],"code":"git status\ngit diff\ngit log --oneline\n# 这些命令用于观察；恢复命令先根据需保留内容另行确定"},{"title":"恢复是有对象和基准的操作","paragraphs":["恢复要说清从哪个版本取什么内容、覆盖哪里。整文件恢复可能连同有用的新段落一起覆盖，所以恢复前应保存未提交工作或只回退明确片段。不能把“撤销最近改动”当作范围充分的指令。","本课在练习仓库用无害标题错误演练，不使用清理未跟踪文件或强制重置作为初学默认方案。先让Codex解释拟执行动作的影响，展示差异后再恢复目标；对已有用户仓库要特别保留无关工作。"]},{"title":"版本证据与运行证据成对","paragraphs":["查看提交历史可定位已保存版本，恢复后还要启动页面并检查目标行为。Git记录的是文件内容，浏览器本地存储、远程数据库和未纳入仓库的文件不一定包含其中。恢复代码不会自动恢复所有运行数据。","你应能交付提交标识、差异说明和重测结果。反例是看到“工作区干净”就说任务保存可靠：干净只说明跟踪文件与记录的关系，不说明添加、完成或刷新行为已经通过。版本管理是恢复依据，不是功能正确性的替代品。"]}],"glossary":[{"term":"仓库","meaning":"保存Git版本记录及相关工作状态的项目范围。"},{"term":"暂存区","meaning":"为下一次提交选择和组织内容的中间状态。"},{"term":"提交","meaning":"把选定文件变化保存为可定位的历史快照。"}],"predict":{"question":"同文件里既有标题错误又有新说明，整文件恢复有什么风险？","options":[{"text":"可能把应保留的新说明一起覆盖","correct":true,"feedback":"恢复对象的范围若过大，会同时撤销有效与无效变化。"},{"text":"只会恢复浏览器任务数据","correct":false,"feedback":"Git文件恢复不自动作用于浏览器存储。"},{"text":"暂存后所有变化会自动变正确","correct":false,"feedback":"暂存只是选择内容，不会检查或修复业务行为。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"差异可分","input":"基线标题为今日任务；现改成今日任物，同时新增一段已验证帮助。","question":"按这次差异与版本范围，恢复应怎样安排？","options":[{"text":"直接覆盖整个目录","correct":false,"feedback":"会扩大范围并可能丢掉其他未记录工作。"},{"text":"先保留帮助段，只修正标题差异","correct":true,"feedback":"两处变化目的不同，需要分别决定保留与撤销。"},{"text":"只提交错误以让它消失","correct":false,"feedback":"提交记录现状，不会自动撤销错误文本。"}],"output":"教学推演：先看差异并保存帮助段，再还原标题，最后重查帮助仍在、页面可用；真实命令另行记录。","evidence":["两处差异独立标注","恢复后有效段落保留"]},{"name":"干净但未测","input":"git status没有变化，最近提交从未运行过页面。","question":"按这次差异与版本范围，能否据此认定功能通过？","options":[{"text":"可以，Git会自动执行全部测试","correct":false,"feedback":"是否执行测试取决于项目安排，Git本身不作此保证。"},{"text":"说明浏览器数据也已有备份","correct":false,"feedback":"未提供浏览器数据被导出或纳入版本的证据。"},{"text":"不能，仍需实际运行验收","correct":true,"feedback":"文件与提交一致只说明版本状态，不说明行为正确。"}],"output":"教学推演：记录可定位版本后运行添加、切换、刷新，成功或失败都按实际结果报告，不从干净状态推断功能。","evidence":["版本状态与运行状态分开","验收清单尚未执行"]}]},"practice":{"intro":"在独立练习仓库查看差异、记录可用版本，并只恢复一次指定标题修改。只在自己新建的练习副本操作；如果运行环境还未准备好，先完成 P01/P03，阅读教学推演不算完成真实实操。","steps":["确认练习仓库范围，先用status与diff只读查看当前变化","核对可用页面后，让Codex解释并保存仅属于练习的提交","加入标题错字和有用帮助两项变更，保存差异并说明保留目标","只恢复标题，保留帮助，再运行页面与核心流程，记录版本依据"],"prompt":"本次练习是 03.09《版本差异与 Git》。在独立练习仓库查看差异、记录可用版本，并只恢复一次指定标题修改。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：确认练习仓库范围，先用status与diff只读查看当前变化；核对可用页面后，让Codex解释并保存仅属于练习的提交；加入标题错字和有用帮助两项变更，保存差异并说明保留目标；只恢复标题，保留帮助，再运行页面与核心流程，记录版本依据。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：可定位提交及其检查说明；恢复前后具体差异；有效新工作保留和功能重测结果。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["可定位提交及其检查说明","恢复前后具体差异","有效新工作保留和功能重测结果"],"troubleshooting":[{"symptom":"恢复后帮助段也没了","check":"核对是否整文件覆盖及是否保存差异","action":"先从保留副本找回有效工作，再缩小到标题片段重做。"},{"symptom":"Git记录与浏览器任务不同步","check":"核对浏览器数据是否独立存储","action":"分开备份与恢复数据，不把源码提交当作浏览器备份。"}]},"checks":[{"question":"暂存后尚未提交，能称为已保存历史版本吗？","options":[{"text":"不能，暂存是提交前的选择状态","correct":true,"feedback":"还需完成提交并确认历史中有相应记录。"},{"text":"能，暂存与历史完全同义","correct":false,"feedback":"暂存只选择下一次提交内容，提交才形成历史快照，不能把两种状态混称完成。"},{"text":"只有上传远程后才可能有本地历史","correct":false,"feedback":"本地提交即可形成历史，上传是另一动作。"}]},{"question":"恢复代码后任务记录没回到昨天，主要原因可能是什么？","options":[{"text":"重新提交当前源码以恢复昨天任务","correct":false,"feedback":"提交记录当前文件，不会重建独立浏览器空间中未被备份的昨日数据。"},{"text":"数据保存在Git未覆盖的独立位置","correct":true,"feedback":"先确认数据存储与备份范围，不能只回退源码。"},{"text":"只切回昨天分支，不核对数据存储位置","correct":false,"feedback":"切换文件版本未必覆盖独立数据，仍需找到对应备份与恢复范围。"}]}],"sources":[{"label":"官方或原始资料：git-scm.com","url":"https://git-scm.com/book/en/v2/Git-Basics-Viewing-the-Commit-History","checked":"2026-10-16"}]},{"id":"04.01","title":"从 AI 到大模型的概念地图","lead":"垃圾邮件识别器、图片生成器和任务管理软件都带“智能”，它们究竟是不是同一类东西？","goals":["用八张自编案例卡建立概念地图，并解释两张容易混淆的卡片","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"AI是范围较宽的目标与方法集合","paragraphs":["人工智能关注让计算系统完成通常需要识别、预测、规划等能力的任务，并不只指聊天。一个按规则筛选邮件的系统也可能属于广义AI应用，是否使用大模型需要看具体实现，而不是看产品宣传中有没有智能二字。","先用输入和输出描述案例：输入邮件得到垃圾或正常的标签，是分类；输入历史数量估计未来值，是预测；输入说明产生一段新文本，是生成。能力分类帮助判断该找哪类证据，不能只靠品牌名判断技术类别。"]},{"title":"机器学习从例子中调整规则","paragraphs":["机器学习是AI的一类方法，通过数据让系统调整可用的模式，而非把所有判断规则逐条手写。训练与测试必须分开看：记住已经见过的例子，不等于能处理不同条件下的新例子。模式学习有适用范围，也会受数据分布影响。","例如分类器从已标注邮件中学习词语与垃圾标签的关系，换成新语言或新诈骗写法可能变差。反例是认为“用过数据”就一定使用机器学习：表格把固定税率乘金额也读取数据，但并不因此学习了规则。"]},{"title":"深度学习使用多层神经网络","paragraphs":["神经网络是由许多可调整数值连接组成的计算系统，多层结构能逐步形成对输入有用的表示。深度学习通常使用这种多层网络；这里的深度不是人格深刻或像人一样思考。大模型强调规模和能力范围，但不是所有AI都需要大模型。","概念关系可用包含关系理解：机器学习属于AI，深度学习属于机器学习。生成式AI按产出能力分类，与这些方法层次有交叉，不能机械画成永远只有一条线的等级榜。一个传统分类模型不因不能写诗就失去实际价值。"]},{"title":"多模态与产品功能另有维度","paragraphs":["模态是信息形式，例如文字、图像、音频。多模态系统能处理不止一种形式，但支持图片输入不一定支持生成图片，更不等于可以操作屏幕上的控件。模型能力与产品为它连接的工具需要分别确认。","资料练习可把八张自编案例卡按输入、输出、任务类型和可能方法分类；没有实现资料时写不能判断。分类的目标是解释用途和边界，不是猜出某个产品内部全部结构。承认未知比把名字当成技术证据更准确。"]}],"glossary":[{"term":"机器学习","meaning":"从训练数据调整模式、用于处理新输入的一类方法。"},{"term":"深度学习","meaning":"通常利用多层神经网络学习表示与任务规律的方法。"},{"term":"模态","meaning":"文字、图像或音频等信息的形式。"}],"predict":{"question":"一个系统按固定公式计算总价，能仅凭读入数据认定它在机器学习吗？","options":[{"text":"能，任何数据处理都属于机器学习","correct":false,"feedback":"计算器也处理数据，但不必从例子更新规则。"},{"text":"只要公式结果正确就认定程序学会规则","correct":false,"feedback":"固定公式可正确处理输入，但正确结果不证明通过训练数据调整过参数。"},{"text":"不能，读取数据不等于学习模式","correct":true,"feedback":"固定规则处理输入与用训练数据调整模型是不同过程。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"分类任务","input":"输入十封邮件；输出每封是垃圾或正常；实现资料未提供。","question":"根据本例已知的输入输出，目前能确定什么？","options":[{"text":"任务属于分类，具体学习方法未知","correct":true,"feedback":"输入输出足以判断任务类型，但不够识别内部架构。"},{"text":"一定采用Transformer大模型","correct":false,"feedback":"分类可以由不同方法实现，名称不能凭空补充。"},{"text":"一定能够生成邮件正文","correct":false,"feedback":"分类标签输出不证明具备生成内容的能力。"}],"output":"教学推演：案例标记为邮件分类；是否采用机器学习、深度网络或手写规则，需实现资料补证。","evidence":["输入是邮件","输出是类别标签"]},{"name":"图片输入","input":"某产品可读图片并回答文字，但文档未说明图像生成或界面操作。","question":"根据本例已知的输入输出，能合理承诺什么？","options":[{"text":"可以替用户点击图片里所有按钮","correct":false,"feedback":"看到按钮不等于获得操作真实界面的工具。"},{"text":"只在已确认范围内说支持图片理解","correct":true,"feedback":"输入能力、生成能力和执行工具是不同维度。"},{"text":"能生成任何尺寸图片","correct":false,"feedback":"读取图片后输出文字的能力，与根据文字生成新图像属于不同输入输出任务。"}],"output":"教学推演：能力表只勾已确认的图像输入与文字输出，图像生成、屏幕操作均保留待核对。","evidence":["输入输出维度分开","产品工具权限单独核实"]}]},"practice":{"intro":"用八张自编案例卡建立概念地图，并解释两张容易混淆的卡片。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["写邮件分类、销量预测、文本生成、图片理解等八张卡的输入输出","按任务类型归组，再用公开实现资料判断是否知道所用方法","画文字版包含关系：AI、机器学习、深度学习，并为生成式和多模态单列维度","挑固定公式计算与图片理解两卡，说明能与不能推出什么"],"prompt":"本次练习是 04.01《从 AI 到大模型的概念地图》。用八张自编案例卡建立概念地图，并解释两张容易混淆的卡片。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：写邮件分类、销量预测、文本生成、图片理解等八张卡的输入输出；按任务类型归组，再用公开实现资料判断是否知道所用方法；画文字版包含关系：AI、机器学习、深度学习，并为生成式和多模态单列维度；挑固定公式计算与图片理解两卡，说明能与不能推出什么。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：八张案例卡与分类理由；含未知项的概念关系表；两个反例及各自所需补充证据。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["八张案例卡与分类理由","含未知项的概念关系表","两个反例及各自所需补充证据"],"troubleshooting":[{"symptom":"把产品名当技术类别","check":"核对是否有输入输出和实现资料","action":"先描述任务，再判断方法；未知内部实现就保留未知。"},{"symptom":"关系图越画越乱","check":"核对是否把任务、方法和媒介混为同一层","action":"改成三个平行问题分别回答，再说明交叉关系。"}]},"checks":[{"question":"生成式AI与深度学习是什么关系最准确？","options":[{"text":"所有深度学习都必须生成文本","correct":false,"feedback":"深度神经网络也可输出类别或数值预测，并非所有深度学习都生成文本。"},{"text":"只要生成新内容就无需训练数据","correct":false,"feedback":"生成能力不能证明系统形成能力时没用训练。"},{"text":"前者按生成能力描述，后者按方法描述","correct":true,"feedback":"两种分类维度可以交叉，不能简单视作品牌等级。"}]},{"question":"图片问答成功一次能证明能操作网页吗？","options":[{"text":"不能，还需实际执行工具与权限证据","correct":true,"feedback":"理解图像与对真实网页采取动作是不同环节。"},{"text":"能，看到控件就等于点击控件","correct":false,"feedback":"视觉输入没有自动产生执行工具和授权。"},{"text":"能，只要回答写我已点击","correct":false,"feedback":"回答说已经点击只是文字内容，真实操作仍需执行工具返回与界面结果。"}]}],"sources":[{"label":"官方或原始资料：developers.google.com","url":"https://developers.google.com/machine-learning/crash-course/neural-networks","checked":"2026-10-16"}]},{"id":"04.02","title":"从数据到能力：训练与使用","lead":"把一页项目说明放进对话，模型第二次更懂你了，是不是已经被你重新训练？","goals":["把三个改善回答的情境按改变对象分类，并实际检验补背景的作用","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"训练用数据调整参数","paragraphs":["参数是模型内部参与计算的可调整数值，训练通过大量例子及目标反复调整这些数值。可以把训练理解为改变处理输入的规则系统，但不是把每个例子原封不动存成可随意查询的资料库。模型也可能记住部分片段，所以不能据此保证隐私。","预训练通常帮助形成较广泛的语言与知识模式，训练数据、目标和计算条件共同影响能力。模型能回答某个问题不等于它确切看过哪份资料；不能从一次输出反推出某个人的私人文件一定进入过训练。"]},{"title":"后训练调整更符合使用目标的行为","paragraphs":["后训练是在已有模型基础上进一步调整，例如学习遵循指令、比较不同回答或改进特定任务。它仍属于改变模型的训练过程，与在聊天里提醒一次格式不同。具体方法与效果依模型和公开资料而异。","让回答更愿意拒绝不确定信息，可能来自后训练和产品安排，但并不保证每次都可靠。反例是把礼貌口吻当成事实核验机制：行为倾向改善不等于增加了当前新闻来源，也不等于每项结论自动经过搜索。"]},{"title":"推理使用当前模型处理输入","paragraphs":["推理在本课指使用已有模型计算输出，不是特指人类式思考过程。你提供项目说明时，模型可以在这次输入条件下利用它；这通常不等于你直接更新了模型参数。是否有数据反馈用于后续训练，则需另外看服务政策。","例如告诉模型“读者是初学者，避免缩写”，回答变通俗可以由当前上下文解释。不能据此推断未来新会话、不同产品或另一账户都会永久保持同样行为；记忆和保存是产品层面另外的机制。"]},{"title":"产品设置改变体验的其他环节","paragraphs":["同一个模型可因搜索、文件读取、系统要求和保存设置不同而表现不同。观察到结果改变，先列可能改变的是参数、当前输入还是产品工具，再用实际记录缩小判断范围。不要因为效果好就把所有改善都叫训练。","R1可用三张流程卡练习：开发者运行训练作业、用户补一页背景、用户启用搜索。分别标出改变对象和所需证据。没有训练作业或模型版本依据时，不要宣称已重新训练；没有工具结果时，也不要宣称完成了搜索。"]}],"glossary":[{"term":"参数","meaning":"模型内部在训练中可调整、用于计算结果的数值。"},{"term":"预训练","meaning":"在较广泛数据与目标下形成基础能力的训练阶段。"},{"term":"推理","meaning":"使用当前模型与输入计算结果的过程，不等于更新参数。"}],"predict":{"question":"补充读者背景后回答更通俗，最有依据的解释是什么？","options":[{"text":"模型已永久为你更新全部参数","correct":false,"feedback":"没有训练过程、模型产物或版本变化证据。"},{"text":"当前输入改变了生成条件","correct":true,"feedback":"仅这次对话现象不足以证明发生参数训练。"},{"text":"所有未来用户都会看到同样风格","correct":false,"feedback":"个人当前输入不能直接推出其他用户的行为。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"补背景","input":"用户新增：整理场地材料，只面向周六15人的活动，不补未知设备。","question":"根据本次改变对象的证据，这首先改变什么？","options":[{"text":"模型全部训练历史","correct":false,"feedback":"输入新要求不能直接改写已有训练过程。"},{"text":"已训练出只服务本项目的新模型版本","correct":false,"feedback":"题目仅补对话背景，没有训练作业或新检查点，不能宣称产生专用模型。"},{"text":"本次推理可使用的上下文","correct":true,"feedback":"新增限制进入输入，能影响当前结论而不需重训。"}],"output":"教学推演：推荐按新需求重评，缺设备仍标未知；这种条件变化不能单独证明参数发生更新。","evidence":["新增输入内容","无训练作业证据"]},{"name":"执行训练","input":"研究者对训练数据运行优化，得到参数不同的新模型检查点。","question":"它与补背景的关键区别是什么？","options":[{"text":"产生了参数更新后的模型产物","correct":true,"feedback":"训练改变参数，而补背景通常改变一次调用的输入。"},{"text":"只是把聊天记录复制得更长","correct":false,"feedback":"明确发生优化与新检查点，不是单纯输入增长。"},{"text":"一定保证所有任务都更好","correct":false,"feedback":"新参数仍要评估，也可能在某些任务退步。"}],"output":"教学推演：归类为训练；是否更适用需固定测试验证，不能把参数变化直接等同全面质量提升。","evidence":["优化过程记录","新检查点与独立评估"]}]},"practice":{"intro":"把三个改善回答的情境按改变对象分类，并实际检验补背景的作用。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["写训练作业、补项目说明、启用搜索三张流程卡","标出各自可能改变的参数、输入或产品工具，列需要的证据","用自编场地资料先提问，再补人数日期限制，保存真实对话或标记未执行","解释结论变化，并写不能据此证明已重训或永久记住"],"prompt":"本次练习是 04.02《从数据到能力：训练与使用》。把三个改善回答的情境按改变对象分类，并实际检验补背景的作用。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：写训练作业、补项目说明、启用搜索三张流程卡；标出各自可能改变的参数、输入或产品工具，列需要的证据；用自编场地资料先提问，再补人数日期限制，保存真实对话或标记未执行；解释结论变化，并写不能据此证明已重训或永久记住。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：三类改变对象及证据表；同材料补背景前后的真实记录；对参数、当前输入和产品记录的边界说明。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["三类改变对象及证据表","同材料补背景前后的真实记录","对参数、当前输入和产品记录的边界说明"],"troubleshooting":[{"symptom":"把任何改善都叫训练","check":"核对是否真有参数更新和新模型产物","action":"改用当前输入或工具变化解释已有证据，不扩大结论。"},{"symptom":"新会话又忘了限制","check":"核对产品记忆设置与本次输入是否提供","action":"重新补充关键说明，分开核对保存与实际使用。"}]},"checks":[{"question":"模型回答礼貌可证明已核实最新事实吗？","options":[{"text":"可以，后训练会消除全部错误","correct":false,"feedback":"后训练不提供全知识和每次事实验证保证。"},{"text":"不能，语气与时效证据是不同维度","correct":true,"feedback":"需要当前可靠来源或实际查询结果支持事实。"},{"text":"只要回答够长就等同搜索","correct":false,"feedback":"长度不证明工具被调用或来源仍然有效。"}]},{"question":"新检查点在一项测试提升，可推出什么？","options":[{"text":"所有输入都必定得到更好答案","correct":false,"feedback":"单项测试不覆盖其他任务、语言与输入分布，不能把局部提升推成全面优胜。"},{"text":"参数更新一定没有任何代价","correct":false,"feedback":"训练可能改变多维表现，应分别测试质量、资源成本与行为变化，不能默认无代价。"},{"text":"该测试条件下表现提升，仍要看其他任务","correct":true,"feedback":"训练效果需按覆盖范围和独立评估说明。"}]}],"sources":[{"label":"官方或原始资料：arxiv.org","url":"https://arxiv.org/abs/2203.02155","checked":"2026-10-16"}]},{"id":"04.03","title":"文本如何成为输入：Token 与向量","lead":"为什么同样十个字可能占不同数量的Token，而两段很相似的话又能表达相反事实？","goals":["制作Token观察表与语义反例表，无需编程或付费调用","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"Token是分词规则得到的处理单位","paragraphs":["Token可理解为模型输入输出使用的片段单位，不固定等于一个字或一个词。分词器依据特定编码规则把文本转换为编号；空格、标点、语言与罕见组合都可能影响结果。数字编号是映射标识，不是字词的重要性分数。","官方Tiktoken示例中，同一个长词antidisestablishmentarianism在r50k_base下为5个Token，在cl100k_base下为6个。这里名称指具体编码，不代表所有当前模型都采用它们；这个真实公开示例说明计数必须注明规则。"]},{"title":"字数不能固定换算计数","paragraphs":["一个汉字可能落在一个或多个片段里，片段也可能覆盖多个字符，不能把字数乘某常数当成精确Token数。对话还可能包含系统要求、工具信息等结构开销，所以只数正文也未必得到实际请求总量。","R1不必安装工具，可先查看官方示例，再用当前可用的官方分词工具对“读书会”“读书会2026”与一段英文做比较。若工具不可用，保留待测表，不编造精确数字；需要费用估算时更要按具体服务计量核对。"]},{"title":"向量让内容进入数值计算","paragraphs":["向量是一串数值，可以作为文本的某种表示。嵌入模型把一段文本映射为向量，使系统能计算相似程度并检索相关内容。这里的相似来自模型与度量选择，不是数学上自动等于事实正确。","“活动在周六”和“活动不在周六”共享大部分词语，却有相反含义；表示可能仍较相近。检索得到相关段落只是把候选材料找出来，还需要读否定词、日期与条件。把距离最近直接当成答案，会把相关性误当正确性。"]},{"title":"输入表示与知识来源分开","paragraphs":["Token编号帮助模型接收文本，向量帮助数值处理关系；它们不是指向官方事实的引用地址。即使词语表示很稳定，也不能从内部编号推出今日价格、合同效力或某条通知真伪。事实需要外部来源与原文对照。","本课的相似性案例是明确标注的概念推演，不提供伪造的真实向量得分。若实际使用嵌入服务，应记录模型、输入、度量与真实返回，再检查反例。零基础学习者先能解释“相似不等于正确”，已经掌握本课关键判断。"]}],"glossary":[{"term":"Token","meaning":"按具体分词编码得到的模型处理片段。"},{"term":"向量","meaning":"由多个数值组成、可参与计算的表示。"},{"term":"嵌入","meaning":"把文本等内容映射到数值向量的过程或结果。"}],"predict":{"question":"两段话向量相近，能直接证明它们事实相同吗？","options":[{"text":"不能，还需检查否定、数量和条件","correct":true,"feedback":"相似表示便于找相关内容，但未承担事实验证。"},{"text":"能，距离最近就是事实一致","correct":false,"feedback":"度量相关性与逻辑真假不是同一个判断。"},{"text":"先选择相似度较高者，不再读原文","correct":false,"feedback":"相似度高仍可能只差一个否定词，必须核对命题、对象和条件。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"编码改变","input":"同一长词antidisestablishmentarianism；官方示例r50k_base为5，cl100k_base为6。","question":"针对这个文本表示反例，这个例子支持哪项结论？","options":[{"text":"所有英文词永远都是5个Token","correct":false,"feedback":"单词长度与编码都会变化，例子不能作固定换算。"},{"text":"Token数量依赖具体编码规则","correct":true,"feedback":"文字相同但编码不同，分片与数量可以变化。"},{"text":"当前所有模型必定使用cl100k_base","correct":false,"feedback":"例子展示编码差异，没有确认当前模型配置。"}],"output":"教学推演：依据已查阅的官方历史示例比较5与6；这不是本课程现场运行分词器的输出。","evidence":["同一文本输入","两个明确编码名称"]},{"name":"意思相反","input":"资料A：活动在周六举行；资料B：活动不在周六举行；检索示意均与活动日期相关。","question":"针对这个文本表示反例，怎样确认日期结论？","options":[{"text":"选词语重合最多的一段","correct":false,"feedback":"两句共享活动日期等词，但否定词能反转命题，词语重合不能保证事实相同。"},{"text":"按检索排名直接采用第一段日期结论","correct":false,"feedback":"排名反映相关性而非真假，冲突段落仍需对照原文和来源版本。"},{"text":"阅读原文否定和适用对象再核对","correct":true,"feedback":"相关段落仍可能相互冲突，需要事实层判断。"}],"output":"教学推演：两句相关却不能同时当作同一活动日期事实；需核对来源、版本与否定，不能用相似替代。","evidence":["关键差异是不字","相似示意未声称真实得分"]}]},"practice":{"intro":"制作Token观察表与语义反例表，无需编程或付费调用。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["查看本课官方分词示例，记文本、编码与计数","在可用官方分词工具中输入一段中文、英文和罕见组合，保存真实结果；不可用则标待测","写三组仅改否定词、数字或日期的句子","逐组解释相似之处与事实差别，说明检索后还应怎样核对"],"prompt":"本次练习是 04.03《文本如何成为输入：Token 与向量》。制作Token观察表与语义反例表，无需编程或付费调用。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：查看本课官方分词示例，记文本、编码与计数；在可用官方分词工具中输入一段中文、英文和罕见组合，保存真实结果；不可用则标待测；写三组仅改否定词、数字或日期的句子；逐组解释相似之处与事实差别，说明检索后还应怎样核对。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：注明编码的真实观察或待测状态；三组最小条件变化反例；相似性用途与事实验证边界说明。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["注明编码的真实观察或待测状态","三组最小条件变化反例","相似性用途与事实验证边界说明"],"troubleshooting":[{"symptom":"和教程Token数不同","check":"核对编码、空格、标点与完整输入","action":"统一条件后比较，不用字数固定换算否定真实结果。"},{"symptom":"检索段落相关却答错","check":"核对否定、时间、对象和原文版本","action":"将相关性筛选与事实核对分开，保留冲突来源。"}]},"checks":[{"question":"Token编号更大能证明词更重要吗？","options":[{"text":"不能，编号是映射标识而非重要性排名","correct":true,"feedback":"重要性需看任务与计算过程，不能按编号大小猜。"},{"text":"能，编号天然等于可信度","correct":false,"feedback":"分词编号用于文本映射，不承载来源是否可靠或命题是否真实的验证含义。"},{"text":"只对中文一定成立","correct":false,"feedback":"语言并不把编号变成可信度或重要性分数。"}]},{"question":"只统计正文Token能精确代表整次请求吗？","options":[{"text":"一定，因为工具信息不占任何资源","correct":false,"feedback":"工具与其他消息可能进入上下文或计量。"},{"text":"不一定，还可能有其他消息与结构开销","correct":true,"feedback":"需按实际模型与请求格式核对完整输入。"},{"text":"不用编码也能由字数准确得到","correct":false,"feedback":"相同文本在不同编码下已经有计数差异。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/cookbook/examples/how_to_count_tokens_with_tiktoken","checked":"2026-10-16"},{"label":"OpenAI 官方向量嵌入说明","url":"https://developers.openai.com/api/docs/guides/embeddings","checked":"2026-10-16"}]},{"id":"04.04","title":"神经网络、注意力与 Transformer","lead":"句子里出现两个“它”，模型为什么需要前后信息，又为什么一张连线图不能证明它像人一样理解？","goals":["用两组指代歧义句，制作背景变化前后的判断与概念连线说明","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"神经网络对表示作多层变换","paragraphs":["神经网络由可调整数值和计算步骤组成，输入经过多层变换得到有用的表示与输出。可以把每层看作对已有信息重新组合，但不能把某一个节点简单标成人类的一个想法。层内数值含义通常依整个系统和任务而定。","例如识别某句中谁做了什么，需要组合词语、位置和上下文。训练让这些计算在许多样本上更有用；一次正确回答只提供输出层证据，不能证明某个内部单元专门理解了人、物或因果。"]},{"title":"注意力按关系组合当前信息","paragraphs":["注意力是一类根据相关性为不同位置的信息分配计算权重并组合的机制。它让某个位置的表示可以结合其他位置，而不只孤立处理眼前一个词。权重由模型在当前输入下计算，不是人手为每句话写好的固定箭头。","句子“小林把书放进箱子，它很重”里，“它”可能指书或箱子。补充“箱子装满了”会改变相关信息。这个行为说明上下文能影响判断，却不能单凭答案反推出某条注意力权重一定是多少，更不能直接等同人的注意或意识。"]},{"title":"Transformer把多种计算组织起来","paragraphs":["Transformer是一种神经网络架构，原始论文用注意力与前馈网络等部件处理序列关系。序列是有顺序的信息；位置信息也很重要，否则“狗追人”和“人追狗”会被当成只含同样词语的一袋材料。现代模型可能有不同变体。","自注意力表示同一序列内各位置相互参考，多个注意力头可在不同表示空间组合信息。这里的“头”只是计算分组，不是几个独立人格。普通使用者不必推导矩阵，但应知道答案来自多层计算，并非简单复制某条训练句子。"]},{"title":"图示、行为与机制证据分层","paragraphs":["箭头图可以帮助理解可能的信息关系，但如果没有实际提取模型内部数值，就只是概念示意。即便拿到真实注意力图，也不能把每条强连线当成完整因果解释；最终输出还受其他层、参数和生成方式影响。","R1可用纸笔画“它”对应的候选对象，改变一句背景后重新判断，并记录仍有歧义的地方。教材案例不给伪造注意力数值。若模型回答不同，只能先报告观察到的输出变化，不能声称已经读出完整内部推理。"]}],"glossary":[{"term":"神经网络","meaning":"由参数化连接与多层计算组成、可通过训练调整的系统。"},{"term":"注意力","meaning":"按当前相关性组合不同位置表示的一类计算机制。"},{"term":"Transformer","meaning":"利用注意力等部件组织序列处理的神经网络架构。"}],"predict":{"question":"给句子补背景后指代判断变了，能据此知道内部权重吗？","options":[{"text":"能，答案里提到谁权重就是百分百","correct":false,"feedback":"输出文字不是注意力权重的直接数值报告。"},{"text":"因此模型一定具有人的意识","correct":false,"feedback":"行为表现不能直接证明主观体验或人类式机制。"},{"text":"不能，只能先确认行为受背景影响","correct":true,"feedback":"实际权重需独立提取，输出变化不提供完整内部证据。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"歧义未解","input":"小林把书放进箱子，它很重。没有其他背景。","question":"对于当前句子与背景线索，最合理的处理是什么？","options":[{"text":"指出书与箱子均可能，保留歧义","correct":true,"feedback":"代词与两个对象都可能关联，原文未唯一限定。"},{"text":"断言它只能指最近的名词","correct":false,"feedback":"距离可作线索，但自然语言指代不由距离单独决定。"},{"text":"声称已看到模型内部连线","correct":false,"feedback":"没有内部数值提取或模型计算记录，只能分析语言现象，不能宣称看到真实连线。"}],"output":"教学推演：列出两个候选与需补充的信息；此处展示语言分析方法，不声称是真实模型输出。","evidence":["两个可指对象","没有唯一限定背景"]},{"name":"背景改变","input":"小林把书放进箱子，它很重。补充：箱子早已装满砖块，小林搬不动。","question":"对于当前句子与背景线索，判断应怎样变化？","options":[{"text":"仍只按最近名词判断，不使用新增背景","correct":false,"feedback":"最近位置可作线索，但新增语境与箱子重量直接相关，不能忽略有用信息。"},{"text":"箱子成为更有依据的候选，仍说明语境依据","correct":true,"feedback":"新增背景与箱子重量有关，提供额外指代线索。"},{"text":"把自己的连线图作为模型实际计算记录","correct":false,"feedback":"自己绘制的关系图是解释辅助，没有内部提取过程，不能标为模型真实轨迹。"}],"output":"教学推演：解释新增信息支持箱子这一候选；这不是完整机制证据，也不能证明任何指定权重。","evidence":["新增背景具体指箱子","行为判断与机制数值分开"]}]},"practice":{"intro":"用两组指代歧义句，制作背景变化前后的判断与概念连线说明。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["复制本课原句，列出两个候选并说明歧义来源","只增加一句与一个候选相关的背景，先预测判断会怎样改变","用可用对话工具实际询问并保存结果；未询问则只保留个人分析","画文字版信息关系，明确标注概念示意，不写未经提取的权重"],"prompt":"本次练习是 04.04《神经网络、注意力与 Transformer》。用两组指代歧义句，制作背景变化前后的判断与概念连线说明。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：复制本课原句，列出两个候选并说明歧义来源；只增加一句与一个候选相关的背景，先预测判断会怎样改变；用可用对话工具实际询问并保存结果；未询问则只保留个人分析；画文字版信息关系，明确标注概念示意，不写未经提取的权重。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：两个候选与背景差异；真实对话或明确未执行记录；图示边界及不能从输出推出的三项结论。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["两个候选与背景差异","真实对话或明确未执行记录","图示边界及不能从输出推出的三项结论"],"troubleshooting":[{"symptom":"AI一开始就断言唯一指代","check":"核对原句是否真的排除了另一候选","action":"要求列依据与备选解释，不把确定语气当作消歧证据。"},{"symptom":"图被误读成真实内部过程","check":"核对有无实际模型数据与提取说明","action":"将图改标概念示意，删除伪造数值和意识类推断。"}]},"checks":[{"question":"多个注意力头意味着多个独立人格吗？","options":[{"text":"意味着每个头都能独立作最终决定","correct":false,"feedback":"最终结果还经过架构其他计算，不由单头直接决定。"},{"text":"意味着模型从不使用位置信息","correct":false,"feedback":"头数与位置信息承担不同职责，不能互相推断。"},{"text":"不意味着，它们是计算结构中的分组","correct":true,"feedback":"结构名称是技术术语，不对应人类人格或意识。"}]},{"question":"词语相同但顺序改变，为什么仍需重新判断？","options":[{"text":"位置关系可能改变主客体与句意","correct":true,"feedback":"序列处理需要使用顺序信息，不能只数出现过的词。"},{"text":"因为每次都必须重新训练模型","correct":false,"feedback":"一次新输入通常通过当前模型推理，不需重训。"},{"text":"因为相同词不可能表达不同意思","correct":false,"feedback":"同一组词语的主客体和否定位置能改变句意，因此顺序变化需要重新解释。"}]}],"sources":[{"label":"官方或原始资料：arxiv.org","url":"https://arxiv.org/abs/1706.03762","checked":"2026-10-16"}]},{"id":"04.05","title":"回答如何生成：概率与变化","lead":"同一个问题连问三遍都答得一样，为什么仍可能三遍都错？","goals":["用自编短材料收集可追溯的重复输出，分开观察表达、事实和一致错误","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"生成逐步依赖已有内容","paragraphs":["语言模型生成文本时，根据当前上下文和已经生成的片段计算后续候选的分布，再由生成方式选出下一部分。分布可理解为候选获得不同权重，并不是先从一份保证真实的答案库取出完整结论。","前面若误写日期，后面可能继续围绕这个错误补细节，于是整段看起来连贯。连贯是语言关系上的表现，事实正确则要回到资料。模型善于延续模式，并不意味着每次延续都以官方事实为前提。"]},{"title":"候选选择使输出有变化","paragraphs":["采样是按某种规则从候选分布选择结果的过程；温度等设置在某些服务中影响选择的集中或分散程度。具体可用参数与行为需看模型文档，不能假定所有产品都公开或接受同样设置。低变化也不等于低错误。","同一材料可能被概括成不同措辞，只要事实、条件和重点符合要求，都可合格。反例是把措辞不一样当成模型不可靠：应先判断变化发生在表达、重点还是事实；不同层面的变化有不同验收方式。"]},{"title":"一致错误会稳定重复","paragraphs":["如果上下文包含错误前提，或模型对某种关联形成稳定倾向，多次回答可能重复同一错误。重复询问共享模型和输入，不能视作多份独立来源。多数票在某些评估中有用途，但不能替代外部事实核对。","例如材料写活动周日，提问却反复说“周六活动”，模型可能顺着错误前提作答。把问题改成“请引用材料中的日期”并回看原文，比只问“确定吗”更容易发现断点。仍应保留不确定项，而不是诱导更自信的口吻。"]},{"title":"比较真实输出要保留条件","paragraphs":["要研究真实变化，应记录产品、可见模型版本、日期、完整输入、可用工具及输出。没有真实调用条件时，教材可以展示预制候选辨析，但不能声称它们是某模型三次真实回答，更不能伪造成功率。","R1实操可选一段无敏感信息的材料，重复提交相同任务，标出措辞变化、事实变化和共同错误。至少用原文核对关键日期与数量。若只获得一次输出，就诚实记录一次，不能为凑齐对比而自行编造另外两份。"]}],"glossary":[{"term":"分布","meaning":"为多个候选赋予不同权重或概率的表示。"},{"term":"采样","meaning":"依据候选权重和规则选择下一输出的过程。"},{"term":"一致性","meaning":"多次结果相同或相近的表现，不等于事实正确。"}],"predict":{"question":"三次回答都把原文周日写成周六，应该怎样判断？","options":[{"text":"多数相同，所以改原文为周六","correct":false,"feedback":"模型重复同一日期不等于主办方更新了原文，活动安排仍应按可靠来源核对。"},{"text":"共同错误仍需按原文纠正","correct":true,"feedback":"一致只能说明重复结果，不能覆盖明确来源中的日期。"},{"text":"多问一次并只保留最自信的日期回答","correct":false,"feedback":"自信与重复可能沿用同一错误，仍需回原文纠正周日与周六的冲突。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"表达变化","input":"原文：周日10点读书会；候选甲写周日上午十点，乙写周日10:00。","question":"按本次候选与原文对照，两份结果应怎样评价？","options":[{"text":"乙一定事实更正确","correct":false,"feedback":"数字格式更简短不使日期更符合原文，应核对日期时间而非排版风格。"},{"text":"甲是新事实因为字数更长","correct":false,"feedback":"同一事实的不同措辞不等于引入新信息。"},{"text":"日期时间相同，可视为表达差异","correct":true,"feedback":"表示法变化没有改变关键事实，应按用途判断格式。"}],"output":"教学推演：两份预制候选均保持周日10点；若任务规定格式，可再检查格式，不把它混成事实错误。","evidence":["日期相同","时间相同但记法不同"]},{"name":"共同错误","input":"原文仍为周日10点；三份预制候选均写周六10点。","question":"按本次候选与原文对照，应该采用哪项核对依据？","options":[{"text":"回到原文纠正三份共同错误","correct":true,"feedback":"同一错误被重复不会产生新的来源支持，应对照原文纠正而非多数投票。"},{"text":"用三比一多数票否定原文","correct":false,"feedback":"三份生成候选没有活动安排的决定权，共同输出不能作为独立事实来源。"},{"text":"只选写得最长的一份","correct":false,"feedback":"长答案也可能把周日写成周六，篇幅不能成为日期准确性的判断依据。"}],"output":"教学推演：三份都在日期维度不合格；本例由作者预制，不是某模型的真实三次输出或错误率统计。","evidence":["日期与原文冲突","候选来源明确为预制"]}]},"practice":{"intro":"用自编短材料收集可追溯的重复输出，分开观察表达、事实和一致错误。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["写含一个日期、一个数量和一项未知信息的材料","固定任务与输入，在可用工具中做最多三次提交并记实际条件","逐项标表达变化与事实变化，核对未知是否被补成事实","按原文纠正共同错误，记录样本小与版本未知等限制"],"prompt":"本次练习是 04.05《回答如何生成：概率与变化》。用自编短材料收集可追溯的重复输出，分开观察表达、事实和一致错误。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：写含一个日期、一个数量和一项未知信息的材料；固定任务与输入，在可用工具中做最多三次提交并记实际条件；逐项标表达变化与事实变化，核对未知是否被补成事实；按原文纠正共同错误，记录样本小与版本未知等限制。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：完整输入与实际可见调用条件；真实输出份数和差异表；原文核对与共同错误纠正记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["完整输入与实际可见调用条件","真实输出份数和差异表","原文核对与共同错误纠正记录"],"troubleshooting":[{"symptom":"几次都一样就不想再核对","check":"核对是否存在独立来源支持关键事实","action":"至少检查日期、数字与否定，不用一致性代替准确性。"},{"symptom":"没有三份真实输出","check":"核对实际可用工具与提交记录","action":"按实际份数报告，预制例子只标为教材推演。"}]},"checks":[{"question":"低变化设置最直接说明什么？","options":[{"text":"所有回答已由外部搜索确认","correct":false,"feedback":"采样设置并不自动执行搜索或资料核验。"},{"text":"候选选择可能更集中，事实仍需验证","correct":true,"feedback":"生成变化和事实可靠性是两个不同维度。"},{"text":"模型不会再有共同错误","correct":false,"feedback":"更稳定的生成也可能稳定重复同一错误。"}]},{"question":"两份摘要措辞不同但事实相同，应先做什么？","options":[{"text":"选字数更多的一份当事实标准","correct":false,"feedback":"不同篇幅都可能保留或遗漏事实，需要逐项回查原文，不按字数选真相。"},{"text":"要求逐字相同才算理解材料","correct":false,"feedback":"摘要允许同义改写，只要事实和必要条件一致，不必逐字复制才算合格。"},{"text":"按目标和格式检查，不直接判一份错误","correct":true,"feedback":"合格表达可以有多种，重点是保留必要信息。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/evaluation-best-practices","checked":"2026-10-16"}]},{"id":"04.06","title":"上下文、历史与记忆","lead":"你昨天已经写过“不联网”，今天摘要里没提，继续工作时为什么又冒出云同步？","goals":["修复一份遗漏关键条件的交接摘要，并用它继续资料比较","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"上下文是这次实际可用的输入","paragraphs":["上下文是模型本次处理时能够使用的信息，包括当前消息及产品实际提供的相关内容。完整聊天记录、磁盘文件与外部资料可能存在，却不一定全部进入当前输入。要区分“在哪里保存”和“本次是否被读取”。","如果说明文件写着不联网，但工具没有读取它，模型可能沿常见产品习惯建议云同步。首先补回关键限制并要求复述，而不是只说“你应该记得”。复述能暴露遗漏，却还需要核对后续方案是否真的遵守。"]},{"title":"容量有限使选择与压缩必要","paragraphs":["上下文窗口是一次处理能容纳的信息范围，具体容量与计量依模型和产品而定。长任务可能通过筛选、检索或摘要保留关键内容。压缩会丢细节，因此摘要不能只记录进度，还要保留决定下一步的限制和未决事项。","一份摘要写“任务页已完成，下一步改善保存”，若漏掉“只用当前浏览器、不能同步”，就可能导致下一步方向错误。摘要短不一定不好，关键在于是否保留了会改变决定的信息；长历史也不保证每项都被正确使用。"]},{"title":"历史与记忆属于不同机制","paragraphs":["历史通常是可查看的往来记录，记忆可能是产品跨对话保存与使用某些信息的功能。它们是否启用、保存什么、如何调用与删除，都依具体产品条件。不能从一次记住姓名推断全部项目要求已永久保存。","把“我偏好简短回答”作为长期偏好，与“本项目暂不联网”作为项目限制，适用范围不同。长期偏好不能覆盖当前明确需求；当前任务记录也不应写成所有未来项目都适用。记录范围能避免把一个情境的要求误带到另一个。"]},{"title":"最小交接包抵抗遗忘","paragraphs":["继续任务时提供当前目标、已确认决定、实际版本、关键文件或材料、未完成项和验证结果。让协作者先列它已读的依据与仍缺的信息，再推进下一步，能减少依赖模糊记忆的风险。","R1资料任务也适用：带上A/B原文、最新比较标准和未确认设备，不需写代码。创作路线另加文件路径、运行方式与实际检查。交接包的价值不是文档越多，而是下一位能定位证据并作出与当前要求一致的决定。"]}],"glossary":[{"term":"上下文窗口","meaning":"单次处理可容纳信息的范围，依实际系统条件而定。"},{"term":"历史","meaning":"保留供查看的对话或操作记录，不保证全部进入本次输入。"},{"term":"交接包","meaning":"供继续工作定位目标、版本、依据、限制和待办的最小资料。"}],"predict":{"question":"文件在磁盘上就能证明AI本次使用过其中限制吗？","options":[{"text":"不能，要核对实际读取与后续采用","correct":true,"feedback":"存在、读取和正确应用是三个需要分别验证的状态。"},{"text":"能，项目内文件天然全进上下文","correct":false,"feedback":"实际输入范围取决于产品和工具读取过程。"},{"text":"只要文件名写重要就必定使用","correct":false,"feedback":"文件名提示不能代替真正的读取与应用证据。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"摘要遗漏","input":"原要求只用当前浏览器、不联网；摘要仅写下步改善保存；新建议为云同步。","question":"面对这次摘要与当前标准，先修正哪一层？","options":[{"text":"直接实现云同步再隐藏入口","correct":false,"feedback":"会违背当前范围并扩大未经确认的工作。"},{"text":"补回限制并要求按它重评下一步","correct":true,"feedback":"遗漏的是会改变方案的条件，不先引入远程实现。"},{"text":"继续追加旧对话而不整理当前限制","correct":false,"feedback":"历史数量增加不保证关键不联网条件突出，应明确当前生效要求与下一步。"}],"output":"教学推演：交接摘要补入不联网、当前版本和待验收项，下一步回到本地写读核对，而非云同步。","evidence":["原限制与摘要差异","下一步方案重新对应限制"]},{"name":"资料任务续做","input":"已保存A/B资料；新比较标准从周六15人变为周日10人，旧推荐为A。","question":"面对这次摘要与当前标准，交接时必须突出什么？","options":[{"text":"只保留旧推荐结论","correct":false,"feedback":"只保留旧推荐会丢失周日10人的新前提，无法解释为何需要重新判断。"},{"text":"删除所有来源以保持简洁","correct":false,"feedback":"删除来源后就难核对时间容量，也无法证明修订是否符合原文条件。"},{"text":"最新标准及旧结论适用条件","correct":true,"feedback":"标准变了需要重新评估，不能无条件沿用旧推荐。"}],"output":"教学推演：把旧推荐标为旧条件下结论，附最新标准和原资料，重新比较；是否有设备仍保留未知。","evidence":["标准版本明确","原资料可追溯"]}]},"practice":{"intro":"修复一份遗漏关键条件的交接摘要，并用它继续资料比较。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["复制A/B资料与周六15人条件，写一份故意漏条件的三行摘要","请协作者依据摘要给下一步建议，保存真实结果或标未执行","补回日期人数、未知设备与来源，明确哪些结论属于旧条件","切换到周日10人，要求复述最新条件并重新比较，逐项核对"],"prompt":"本次练习是 04.06《上下文、历史与记忆》。修复一份遗漏关键条件的交接摘要，并用它继续资料比较。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：复制A/B资料与周六15人条件，写一份故意漏条件的三行摘要；请协作者依据摘要给下一步建议，保存真实结果或标未执行；补回日期人数、未知设备与来源，明确哪些结论属于旧条件；切换到周日10人，要求复述最新条件并重新比较，逐项核对。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：遗漏前后摘要与关键差异；实际读取依据或明确未执行说明；按新条件重评结果及来源核对。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["遗漏前后摘要与关键差异","实际读取依据或明确未执行说明","按新条件重评结果及来源核对"],"troubleshooting":[{"symptom":"补了文件仍走旧方案","check":"核对是否实际读取最新版本并复述限制","action":"提供精确位置或粘贴必要段落，再检查后续决定是否改变。"},{"symptom":"摘要越来越长却难续做","check":"核对目标、决定、版本、待办是否突出","action":"去掉无关聊天，保留会改变下一步的条件与证据。"}]},"checks":[{"question":"历史里出现过限制，当前回答没遵守，先做什么？","options":[{"text":"核对当前可用摘要与实际依据并补关键条件","correct":true,"feedback":"先定位信息是否传达和使用，不只要求更认真。"},{"text":"认为只要历史里出现过就不需要重申","correct":false,"feedback":"历史存在不保证本次全部可用，应核对摘要、读取与实际采用是否遗漏。"},{"text":"认为长对话天然保证不遗忘","correct":false,"feedback":"容量、筛选与压缩都可能改变实际可用信息。"}]},{"question":"长期偏好与当前任务冲突时，怎样处理？","options":[{"text":"永远让旧偏好覆盖新要求","correct":false,"feedback":"旧偏好若机械覆盖当前明确目标，会让协作偏离本次需求，应写明适用范围。"},{"text":"明确当前任务优先关系与适用范围","correct":true,"feedback":"不同层级要求应有清楚边界，避免机械套用。"},{"text":"把冲突藏进摘要不再提","correct":false,"feedback":"冲突未解决却隐藏起来，会让后续协作者继续猜哪条生效，问题仍会复现。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/conversation-state","checked":"2026-10-16"}]},{"id":"04.07","title":"能力边界与可信判断","lead":"一条事实、一张界面图和一段代码建议都看似合理，为什么需要三种不同的核对方式？","goals":["为事实、界面图和代码建议各制作一张验证卡，并迁移到自己的资料任务","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"幻觉是无依据内容，不只是奇怪语言","paragraphs":["本课把幻觉理解为生成了缺乏可靠依据或与事实不符的内容，可能表现为不存在的引用、错误日期或编造功能。语言流畅不构成证据，承认不确定也并不自动解决问题，还需选择可执行的核对办法。","若回答给出一篇文章，应打开原文确认标题、作者和相关结论，而不是只检查链接长得像网址。若资料没有答案，应保留缺项或搜索可靠来源。反例是为了让表格完整就猜填数字，这使整洁外观掩盖证据缺失。"]},{"title":"时效与偏差需要不同检查","paragraphs":["时效问题是事实可能随时间改变，优先核对当前官方资料与生效日期。偏差是样本、表达或系统行为对某些群体或情况产生不均衡影响，需要换条件和检查覆盖范围；单查一个日期不能检测所有偏差。","例如工具可用性要查当前账户与地区条件；摘要是否忽略少数意见则要对照原文观点分布。不能把这两类问题都归咎于提示词太短，也不能用一个成功样本证明对所有人都公平或可用。"]},{"title":"图像与代码各有实际验证","paragraphs":["图像理解可能误读小字、状态和遮挡，先与清晰原图或可搜索文本核对。截图只证明画面中的状态，不证明按钮真的被点、文件真的保存。代码建议则需阅读范围，在副本运行并检查正常、失败与恢复路径。","把界面图中的“已保存”当作后端真实持久化证据，会漏掉假提示；把一段能运行的代码当作数据安全证明，会漏掉权限与边界。验证对象是什么，决定了证据应来自原文、画面还是实际执行结果。"]},{"title":"信任是分层的可修订判断","paragraphs":["合理表述应包含已确认部分、未确认部分和下一步动作。对来源可靠但没有覆盖的条件保留限制，对高后果操作增加独立核对。不是所有问题都要无限检查，而是让证据强度与错误代价相匹配。","R1可用三个公开或自编样本制作核对卡：事实找原文、图片查文字、建议写可运行验收；最后选择一个自己的任务迁移。若无法执行，就记录待验证，而非把理解了步骤写成已验证。学习的目标是知道何时继续、何时补证。"]}],"glossary":[{"term":"幻觉","meaning":"缺乏可靠依据或与事实不符、却被生成出来的内容。"},{"term":"时效","meaning":"信息是否仍适用于当前时间与条件。"},{"term":"偏差","meaning":"在某些条件或群体上出现系统性不均衡的表现。"}],"predict":{"question":"截图显示已保存，怎样进一步确认实际记录留住了？","options":[{"text":"截图中有绿色图标就已经足够","correct":false,"feedback":"视觉状态可能与底层操作脱节，不能独立保证写入。"},{"text":"让模型把截图描述三次","correct":false,"feedback":"重复描述并未执行实际的保存恢复检查。"},{"text":"重开或重新读取并核对具体记录","correct":true,"feedback":"提示画面与实际持久化是两个不同证据层。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"最新事实","input":"回答说某场馆今天开放，但引用是去年公告，没有当前通知。","question":"对照当前声称与证据类型，下一步核对什么？","options":[{"text":"查当前官方公告与适用日期","correct":true,"feedback":"去年的安排可能已变，不能由旧公告直接推出今天开放，应核对当前资料。"},{"text":"只检查文章语法通顺","correct":false,"feedback":"语法通顺不包含当前运营证据，今天是否开放仍需要适用日期的官方通知。"},{"text":"把今天改为通常以便直接采用","correct":false,"feedback":"降格措辞可以说明限制，但仍不能回答今天是否开放。"}],"output":"教学推演：今天状态保持未确认，找到当前适用公告后再更新；不声称教材已核验某场馆实时状态。","evidence":["引用日期与目标日期","官方来源适用范围"]},{"name":"代码建议","input":"建议修改保存逻辑，文字解释完整，但尚未在副本运行。","question":"对照当前声称与证据类型，当前应如何记录？","options":[{"text":"整个功能已完成并可直接交付","correct":false,"feedback":"缺少真实执行结果，完成状态被提前宣告。"},{"text":"方案已提出，实际行为待验证","correct":true,"feedback":"解释是依据之一，运行、失败和恢复还需另验。"},{"text":"因为代码来自AI所以必定错误","correct":false,"feedback":"来源不能代替对具体代码与行为的检查。"}],"output":"教学推演：先审查修改范围，在副本验证正常保存、失败提示与读取恢复，再按实际结果决定采用。","evidence":["实现差异待审查","正常和失败路径待执行"]}]},"practice":{"intro":"为事实、界面图和代码建议各制作一张验证卡，并迁移到自己的资料任务。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["选择不含私人信息的三个演示样本，写它们各自声称什么","事实卡写原始来源与日期，图像卡写清晰文字和缺失画面","建议卡写副本范围、正常与失败验收；R1无需执行代码，只说明证据类型","实际完成可用的一张资料核对卡，记录确认、未确认和下一步"],"prompt":"本次练习是 04.07《能力边界与可信判断》。为事实、界面图和代码建议各制作一张验证卡，并迁移到自己的资料任务。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：选择不含私人信息的三个演示样本，写它们各自声称什么；事实卡写原始来源与日期，图像卡写清晰文字和缺失画面；建议卡写副本范围、正常与失败验收；R1无需执行代码，只说明证据类型；实际完成可用的一张资料核对卡，记录确认、未确认和下一步。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：三张不同证据类型的核对卡；一项实际原文核对记录；未确认条件与具体下一步动作。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["三张不同证据类型的核对卡","一项实际原文核对记录","未确认条件与具体下一步动作"],"troubleshooting":[{"symptom":"链接打不开仍想引用","check":"核对是否找到原文及它是否支持结论","action":"将该项标未核实，寻找可访问原始来源或删除断言。"},{"symptom":"执行失败却被解释成环境偶然","check":"核对命令、目录、错误与最近改动","action":"保留失败证据，缩小问题重现，未通过前不标完成。"}]},"checks":[{"question":"换一批群体样本主要帮助检查什么？","options":[{"text":"证明今天价格仍有效","correct":false,"feedback":"时效需要当前价目与生效条件，不由群体样本决定。"},{"text":"自动消除所有偏差","correct":false,"feedback":"发现和消除不同，仍需分析原因并复测。"},{"text":"观察覆盖差异与可能的系统性偏差","correct":true,"feedback":"不同条件样本能暴露单个成功例没有覆盖的问题。"}]},{"question":"不能实际运行建议时，最准确的表述是什么？","options":[{"text":"已审阅方案，运行与恢复尚待验证","correct":true,"feedback":"把已完成与缺项分开，便于下一步继续。"},{"text":"既然解释合理就等于运行通过","correct":false,"feedback":"审阅只能形成方案判断，实际运行是否成功还需执行、观察与恢复证据。"},{"text":"把该建议从待办直接标为外部实操通过","correct":false,"feedback":"理解方案有价值，但未运行仍应保留待验证，不能提前记录实际通过。"}]}],"sources":[{"label":"官方或原始资料：openai.com","url":"https://openai.com/index/why-language-models-hallucinate/","checked":"2026-10-16"},{"label":"OpenAI 官方图像理解的限制","url":"https://developers.openai.com/api/docs/guides/images-vision","checked":"2026-10-16"}]},{"id":"05.01","title":"明确成果与验收条件","lead":"“整理得更有用”“页面更专业”都表达了愿望，为什么协作者仍不知道什么时候可以停？","goals":["把一项模糊愿望改成一页可由他人执行和验收的任务书","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"成果说明要服务谁、解决什么","paragraphs":["愿望表达方向，成果说明把方向变成可交付对象。先写使用者和使用时刻，再确定输出。例如“给周六读书会负责人比较场地”比“做个好总结”清楚，因为它解释了哪些事实会影响下一步决定。","R1交付一页比较说明，创作路线交付可操作任务页，两者都应有明确输入和目标。不要先把某种数据库或排版方式写成必需，除非它确实来自使用要求；技术和表现形式要说明与目标的关系。"]},{"title":"功能、方案和验收各有职责","paragraphs":["功能是使用者能够做的事，方案是怎样实现，验收是判断行为是否达到目标的办法。比如“刷新后保留任务”是行为要求，“用localStorage”是候选方案，“新增两条、完成一条再刷新核对”是验收步骤。","资料任务同样可拆：“按人数日期比较”是功能，“使用三栏表”是输出方案，“每个事实能回到A/B原文”是验收。把这些混在一行，可能导致实现了表格外观，却没有真正按标准比较。"]},{"title":"可观察标准减少主观分歧","paragraphs":["一个可执行标准应包含起始条件、操作和预期。写“摘要不乱编”还不够，可改成“原文未提供设备时，设备栏写未知，并列询问建议”。这样另一位协作者不必猜你的偏好，就能复核结果。","标准不宜为所有细节设死，也不能只检查最容易的一条。对本轮关键风险安排正常与失败条件即可。反例是只要求字数不少于500字：它可机械检查篇幅，却无法判断资料是否可追溯或比较是否遵守人数门槛。"]},{"title":"未决项要显式留下","paragraphs":["不确定的决定列为未决项，说明由谁确认、影响什么、在确认前可做什么。视觉方案要有实际原型确认；数据去向和收费资源也要明确，不能由“尽快做完”推导无限范围。验收清单是协作合同，随变更更新。","最后用一次交换检查检验说明是否可用：让协作者只看任务书，复述会交什么和怎样判定。发现歧义就修订，并保留被替换的条件。交付时按清单报告已验、未验和限制，避免把实现建议当成已经发生的成果。"]}],"glossary":[{"term":"成果","meaning":"要交付且能被查看或使用的具体对象。"},{"term":"功能","meaning":"使用者在给定条件下能够完成的行为。"},{"term":"验收条件","meaning":"用输入、动作和预期描述可复核的完成标准。"}],"predict":{"question":"“采用某框架”与“输入空格不新增”哪项更接近验收条件？","options":[{"text":"采用框架名称本身就是功能通过","correct":false,"feedback":"采用技术框架只是实现选择，不能直接证明空输入拒绝等用户行为已经通过。"},{"text":"输入空格后列表不增加并有提示","correct":true,"feedback":"它描述可观察行为，而框架通常属于实现方案。"},{"text":"输出越长越代表全部需求完成","correct":false,"feedback":"答案写得长仍可能漏来源或按钮失效，篇幅不覆盖关键行为的验收。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"资料成果","input":"任务：依据A周六20座100元、B周日12座80元，为周六15人比较，不补未知设备。","question":"按本轮成果和行为门槛，哪项验收最具体？","options":[{"text":"读起来像专家报告","correct":false,"feedback":"语气无法独立判断结论是否有材料支持。"},{"text":"必须采用数据库保存比较表","correct":false,"feedback":"当前资料任务没有提出远程保存的必要条件。"},{"text":"事实附来源，按门槛判断，设备未知单列","correct":true,"feedback":"覆盖材料追溯、比较规则与无依据补充三类风险。"}],"output":"教学推演：A满足已知门槛；B不满足时间人数；设备均未知；以上结论逐项对应原文与标准。","evidence":["每格来源可查","未知项未被猜成事实"]},{"name":"项目成果","input":"任务：个人本地工具支持添加与完成；页面与原型一致，但按钮尚未连接。","question":"按本轮成果和行为门槛，是否达到功能验收？","options":[{"text":"没有，仍需实际点击与状态检查","correct":true,"feedback":"视觉符合只覆盖表现层，不能替代行为证据。"},{"text":"已经达到，因为控件都画出来了","correct":false,"feedback":"画出按钮只提供视觉结构，未绑定事件就不能证明添加与完成实际可用。"},{"text":"只要截图标注添加成功即可","correct":false,"feedback":"在截图旁写成功只是说明文字，不会产生任务数组增加或状态切换证据。"}],"output":"教学推演：视觉可单独记录为已确认，添加与完成保留未验；下一步按输入与点击流程收集结果。","evidence":["视觉和行为分开记录","按钮未连接是已知缺项"]}]},"practice":{"intro":"把一项模糊愿望改成一页可由他人执行和验收的任务书。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["R1选资料比较，或创作路线选任务页；写使用者和用途","分列成果、必要功能、候选方案和本轮不做项","每项关键行为写起点、操作、预期，并加一个失败条件","请协作者复述并检查一项歧义，修订后按清单验收"],"prompt":"本次练习是 05.01《明确成果与验收条件》。把一项模糊愿望改成一页可由他人执行和验收的任务书。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：R1选资料比较，或创作路线选任务页；写使用者和用途；分列成果、必要功能、候选方案和本轮不做项；每项关键行为写起点、操作、预期，并加一个失败条件；请协作者复述并检查一项歧义，修订后按清单验收。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：修订前后任务书；功能、方案、验收分类及理由；一次歧义纠正和实际可用检查记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["修订前后任务书","功能、方案、验收分类及理由","一次歧义纠正和实际可用检查记录"],"troubleshooting":[{"symptom":"协作者只追问专业是什么意思","check":"核对是否只有形容词没有行为","action":"补具体使用场景和可观察变化，保留必要主观偏好供原型讨论。"},{"symptom":"实现完成却无法验收","check":"核对每项是否有输入、动作和预期","action":"补清单并实际执行，未测试项不标通过。"}]},"checks":[{"question":"把采用三栏表写成用户目标，有什么风险？","options":[{"text":"会自动提高所有事实的准确度","correct":false,"feedback":"表格形式不会自动补足证据或纠正错误。"},{"text":"形式可能完成却没解决比较决策","correct":true,"feedback":"应说明表格怎样支持来源与标准，而非只检查外形。"},{"text":"不再需要说明资料范围","correct":false,"feedback":"不说明资料范围仍可能混入常识猜测，格式要求不能代替来源约束。"}]},{"question":"设备信息未知又是硬条件，怎样写当前完成状态？","options":[{"text":"直接说全部完成以免影响进度","correct":false,"feedback":"全部完成的说法会让下一位把未知设备当成满足，进而按未证实条件行动。"},{"text":"删除设备条件使结果看似通过","correct":false,"feedback":"设备是当前真实门槛，未经讨论删除会改变需求，让原本未满足被伪装成通过。"},{"text":"比较框架完成，最终选择待设备确认","correct":true,"feedback":"已做与未决分开，结论强度与证据匹配。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/prompt-engineering","checked":"2026-10-16"}]},{"id":"05.02","title":"补充上下文：AI 为什么会答非所问","lead":"同样一句“帮我做任务页”，为什么有人得到本地清单，有人却得到复杂的团队协作系统？","goals":["对一项自选资料任务补齐背景，纠正一个实际错误假设；项目路线可选用Codex","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"背景决定未说出口的选择","paragraphs":["上下文是本次可用的背景与限制，会改变协作者怎样解释任务。用户、场景、已有成果和不能做的事缺失时，AI可能按常见模式补假设。答非所问有时不是执行能力不足，而是双方想的成果不同。","例如“个人当天自用、当前浏览器保存、不登录”与“团队跨设备协作”都能叫任务页。只重复名称不会消除差异；补上会改变数据位置和交互的条件，才使方案收敛。资料比较中日期与人数也承担相同作用。"]},{"title":"长提示词不等于必要信息齐全","paragraphs":["提示词再长，若都是“专业、严谨、细致”也可能缺少关键前提。先列下一步决定需要什么：当前输入、目标、限制、已确认决定和验收。把相关材料放在可定位位置，比堆砌无关经历更有用。","反例是附上完整历史却漏掉最新人数已从15变10。协作者可能准确总结旧记录，却按旧标准给出错误推荐。有效背景要突出当前版本和取代关系，不把新旧要求混为一份同时生效的说明。"]},{"title":"让复述暴露假设","paragraphs":["要求先复述成果与限制，并列出仍需确认的假设。复述是一种理解检查，不是最终结果认证。你要实际核对是否提到读者、资料范围、保存位置等关键条件，再检查后续行动是否采用。","如果它复述成需要云同步，明确纠正为当前浏览器，并解释为何这会改变方案。不要只说“不是这样”或“认真点”，而要给出被误解项、正确条件及验收。纠偏后的方案变化才是新增信息产生作用的证据。"]},{"title":"用条件对照定位哪条信息有用","paragraphs":["先记录模糊输入会留下哪些自由选择，再一次补一个会改变决定的条件。这样能看出改善是否来自背景，而不是同时改模型、标准和材料后把效果归到某个神奇句式。","现有增强样课可用于复习上下文对比，其规则输出是教学实验，不是现场模型回答。本课仍提供完整资料任务：先比较A/B，再补周六15人，最后改周日10人。外部对话或Codex实操要独立保存输入、错误假设、纠正和实际结果。"]}],"glossary":[{"term":"上下文","meaning":"本次处理能实际使用的背景、材料与限制。"},{"term":"错误假设","meaning":"未确认却被当成事实，导致方案偏离的前提。"},{"term":"条件对照","meaning":"在尽量相同输入下改变一个条件并比较影响的方法。"}],"predict":{"question":"提示词写很长仍推荐周日场地，而活动必须周六，最先补什么？","options":[{"text":"明确当前日期门槛并要求重评","correct":true,"feedback":"缺失的是决定可用性的条件，不是抽象认真程度。"},{"text":"再加入十个专业形容词","correct":false,"feedback":"更多形容词仍没给出周六门槛，模型无法据此排除只在周日可用的B。"},{"text":"立刻让它完成全部预订动作","correct":false,"feedback":"错误前提未纠正，扩大执行会放大偏差。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"信息不足","input":"A：周六20座100元；B：周日12座80元；只说选便宜又合适的。","question":"根据这次需求背景变化，当前最该确认什么？","options":[{"text":"先认定B永远最好","correct":false,"feedback":"只按价格忽略日期容量，结论超出资料。"},{"text":"活动日期、人数和不能妥协的条件","correct":true,"feedback":"合适依赖用途，价格不能替代缺失的使用条件。"},{"text":"先按价格推荐B，日期人数以后再补","correct":false,"feedback":"价格不能保证可用，日期人数可能直接排除B，应先补会改变结论的背景。"}],"output":"教学推演：先列缺失背景与暂定比较，不能给无条件最佳；本例不冒充真实模型的第一轮回答。","evidence":["日期人数尚缺","价格只是一个维度"]},{"name":"背景改变","input":"补充：必须周六15人；之后又明确改为周日10人，设备不要求。","question":"根据这次需求背景变化，合理的结论变化是什么？","options":[{"text":"维持A因为第一次已推荐","correct":false,"feedback":"旧结论只适用于旧条件，不应无条件固化。"},{"text":"认为两次不同结论必有一次胡编","correct":false,"feedback":"场地事实不变而需求改变，适配判断可以合法变化，不能只因答案不同就判胡编。"},{"text":"按最新条件重评，B从不满足变为满足","correct":true,"feedback":"场地事实未变，需求改变可改变适配结果。"}],"output":"教学推演：周六15人时A匹配已知门槛；周日10人时B匹配；应说明变化由最新需求造成。","evidence":["原资料保持相同","生效需求有明确版本"]}]},"practice":{"intro":"对一项自选资料任务补齐背景，纠正一个实际错误假设；项目路线可选用Codex。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["写最初请求与希望成果，列可能被误解的三处","补目标读者、当前材料、硬条件、已确认决定和验收，不加无关隐私","请可用对话工具或Codex复述并列假设，找出一项真实误解并纠正","比较纠正后的结果，指出新增条件影响哪项决定；可进入原上下文增强样课复习"],"prompt":"本次练习是 05.02《补充上下文：AI 为什么会答非所问》。对一项自选资料任务补齐背景，纠正一个实际错误假设；项目路线可选用Codex。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：写最初请求与希望成果，列可能被误解的三处；补目标读者、当前材料、硬条件、已确认决定和验收，不加无关隐私；请可用对话工具或Codex复述并列假设，找出一项真实误解并纠正；比较纠正后的结果，指出新增条件影响哪项决定；可进入原上下文增强样课复习。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：初始与补充后的输入；错误假设及明确纠正记录；实际结果变化、来源核对和未验证限制。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["初始与补充后的输入","错误假设及明确纠正记录","实际结果变化、来源核对和未验证限制"],"troubleshooting":[{"symptom":"补充后仍答非所问","check":"核对是否实际读到最新说明并正确复述","action":"只针对错的一项提供原文与正确条件，缩小任务重试。"},{"symptom":"输入越来越长但重点不清","check":"核对哪些信息真正改变下一步决定","action":"整理为目标、材料、限制、当前状态、验收五块，移走无关历史。"}]},"checks":[{"question":"资料不变但人数变化后推荐改变，说明什么？","options":[{"text":"适配结论受需求条件影响","correct":true,"feedback":"应比较条件与理由，而不只比较最终推荐名称。"},{"text":"模型必须永远保持第一次答案","correct":false,"feedback":"第一次推荐受旧条件限制，固守它会忽略后来明确生效的日期人数要求。"},{"text":"只要答案变化就证明资料已被改写","correct":false,"feedback":"需求变化即可解释，不必假设原文事实改变。"}]},{"question":"复述正确后就能省掉结果核对吗？","options":[{"text":"能，复述相当于自动通过验收","correct":false,"feedback":"复述只验证表达层理解，仍要核对实际结果是否保留事实并遵守当前条件。"},{"text":"不能，还要看行动与结果是否遵守条件","correct":true,"feedback":"说出要求和正确执行要求是两个不同层面的证据。"},{"text":"复述正确后只检查输出篇幅是否达到要求","correct":false,"feedback":"篇幅不检查事实与条件采用，仍要按来源和行为验收，不应以字数代替。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/prompt-engineering","checked":"2026-10-16"}]},{"id":"05.03","title":"限制、示例与冲突处理","lead":"旧要求写“越详细越好”，新要求写“只要一页”，为什么把两句都粘贴回去反而更难得到满意结果？","goals":["为资料任务提供一正一反示例，修改一条旧要求并更新当前说明","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"约束缩小可接受答案的范围","paragraphs":["约束是产出必须遵守的边界，如只依据指定资料、不暴露个人字段、只在副本修改。目标告诉协作者往哪走，约束排除不允许的路径。约束应有理由和可检查表现，避免变成互相矛盾的口号。","资料摘要中“未知设备写未知”比“不要乱说”更可操作；项目中“只改标题文件”比“尽量别动太多”范围清楚。约束不是越多越好，若阻碍目标，应先解释冲突并调整，而不是悄悄忽略某一条。"]},{"title":"正反示例把边界具体化","paragraphs":["正例展示合格输出，反例展示容易误用的形式，并解释差异。示例应服务于规则，不是要求机械复制里面的事实。用一个短正例和一个有理由的反例，通常比列许多没有解释的样稿更容易迁移。","例如正例“设备：未知，资料未提及”；反例“设备：投影齐全，因为教室通常有”。关键不是有没有某几个固定字，而是不能从常识补出具体服务。换成停车位或网络速度时，也应沿同一证据规则判断。"]},{"title":"要求变化必须标明取代关系","paragraphs":["新旧要求冲突时，要确定生效版本和优先级，即先遵守哪一条。不能仅把新句放在长材料末尾，假设所有协作者都能判断是否取消旧条件。明确写“本轮一页替代旧版不限篇幅，仍保留来源要求”。","这样既避免按旧标准继续扩写，也避免误以为新要求取消全部旧条件。反例是让模型“综合两者”，结果得到两页半：折中可能同时违背新上限和旧完整性预期，需要人明确取舍，而不是靠措辞含混。"]},{"title":"检查冲突如何传播到成果","paragraphs":["要求更新后，任务说明、比较表和验收都要一致。若人数改为10但检查表仍写15，就可能实现对却被旧表判失败。把被替换项与保留项列成短记录，可帮助后续交接避免旧条件复活。","R1可将摘要从不限长度改为一页，要求仍保留每个关键事实的来源；项目路线可将任务默认排序改为未完成优先。无论选择哪条，都要用新输入重试并说明哪些旧规则仍生效，不以一次看似满意的例子代替冲突验收。"]}],"glossary":[{"term":"约束","meaning":"可接受产出必须遵守、能够核对的边界。"},{"term":"正反示例","meaning":"分别展示符合和违反规则的短案例，并解释差异。"},{"term":"优先级","meaning":"多个要求冲突时先遵守哪个的明确关系。"}],"predict":{"question":"新的一页要求替代旧的不限篇幅，来源要求未取消，应怎样写？","options":[{"text":"两条取平均写两页","correct":false,"feedback":"新要求明确上限一页，折中成两页仍超出边界，不是解决冲突的正确方式。"},{"text":"删掉全部来源只保留结论","correct":false,"feedback":"减少篇幅只替换长度要求，没有取消关键事实附来源，不能因此删掉追溯。"},{"text":"一页为当前上限，保留来源追溯","correct":true,"feedback":"明确替换项与保留项，避免把新要求理解成全部重置。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"示例迁移","input":"正例：投影未知，材料未提及；新资料仍未说停车位。","question":"按正反示例与当前版本，停车位一栏怎样写？","options":[{"text":"未知并列待询问，不凭常见配置补全","correct":true,"feedback":"规则约束的是事实依据，不是只针对投影这个词。"},{"text":"默认有，因为多数场地有","correct":false,"feedback":"一般经验不能证明这个场地的具体配置。"},{"text":"删除整份资料不再比较","correct":false,"feedback":"未知一项可以单独保留，不必丢弃其他明确事实。"}],"output":"教学推演：停车位记未知；时间、座位等明确字段仍可比较；正例规则被迁移而非逐字照抄。","evidence":["缺信息字段被保留未知","已有事实未被删除"]},{"name":"冲突更新","input":"旧版：详细比较不限篇幅；新版：一页内；另有旧规则：每个关键事实附来源。","question":"按正反示例与当前版本，正确任务说明包含什么？","options":[{"text":"写尽量一页但两三页也可","correct":false,"feedback":"把硬边界降为偏好，可能违背当前要求。"},{"text":"一页替代不限篇幅，来源规则继续生效","correct":true,"feedback":"局部更新明确范围，避免旧新要求同时造成歧义。"},{"text":"只保留最新一句其余全部删除","correct":false,"feedback":"来源要求与一页上限可同时执行，未冲突条款应保留，不能只留最新一句。"}],"output":"教学推演：更新任务书与验收表，篇幅核对一页，事实仍逐项回查材料；不能只改聊天不改交接记录。","evidence":["被替换项明确","保留项同步到检查表"]}]},"practice":{"intro":"为资料任务提供一正一反示例，修改一条旧要求并更新当前说明。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["写当前目标和三条可观察约束，说明各自保护什么","用未知设备制作正例与反例，解释依据差别","把篇幅从详细不限改成一页，明确替代与继续生效项","请协作者按新说明输出，用停车位未知这个新条件检查迁移"],"prompt":"本次练习是 05.03《限制、示例与冲突处理》。为资料任务提供一正一反示例，修改一条旧要求并更新当前说明。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：写当前目标和三条可观察约束，说明各自保护什么；用未知设备制作正例与反例，解释依据差别；把篇幅从详细不限改成一页，明确替代与继续生效项；请协作者按新说明输出，用停车位未知这个新条件检查迁移。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：正反示例及解释；标注版本与取代关系的任务书；新条件输出和按新标准核对记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["正反示例及解释","标注版本与取代关系的任务书","新条件输出和按新标准核对记录"],"troubleshooting":[{"symptom":"新旧要求反复出现","check":"核对是否明确哪条失效及当前版本","action":"在任务说明与交接摘要同时替换，不只追加一条聊天。"},{"symptom":"AI照抄例子事实","check":"核对例子是否被误当作本次真实资料","action":"把规则与样本分区，要求每项本次事实回指当前材料。"}]},"checks":[{"question":"正例中的场地名能直接用于新任务吗？","options":[{"text":"能，正例已经被证明合格","correct":false,"feedback":"合格格式不使其中事实自动适用于其他场景。"},{"text":"只要字数相同就可以替换","correct":false,"feedback":"字数与事实适用范围没有这种对应关系。"},{"text":"不能，例子示范规则而非提供本次事实","correct":true,"feedback":"新任务的名称和配置仍需来自当前输入。"}]},{"question":"新要求只改人数，其他限制怎样处理？","options":[{"text":"逐项保留未冲突规则并更新验收人数","correct":true,"feedback":"局部变更应有范围，避免误删有效条件。"},{"text":"默认所有旧限制都作废","correct":false,"feedback":"只改人数不表示其他约束失效，默认清空旧限制会无依据扩大允许范围。"},{"text":"所有旧数字永远优先","correct":false,"feedback":"旧数字若永远优先，会阻止明确人数更新生效，应修订当前标准与验收。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/prompt-engineering","checked":"2026-10-16"}]},{"id":"05.04","title":"小步计划与变更控制","lead":"刚要验收资料比较，临时又想加入报名表，为什么直接一起做往往更慢？","goals":["将资料比较拆成四个可检查小步，并处理中途新增的报名需求","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"计划按可检查成果拆分","paragraphs":["小步不是把一句话拆成许多动词，而是每一步都有可观察成果和通过条件。先确认材料，再提出比较规则，再制作结果，最后核对来源，能把错误限制在对应环节。没有检查点的长计划看似完整，却可能直到末尾才发现起点理解错了。","资料任务可把第一步成果设为带编号原文，第二步为硬条件表；项目任务可先读现有代码再只改一项功能。每一步都应知道如果失败，回到哪里，不能把“等待AI完成”当成唯一进度描述。"]},{"title":"观察、方案、修改与验证分开","paragraphs":["观察收集现状与证据，方案解释准备改变什么，修改实际写入产物，验证检查目标是否达成。分清阶段能避免还没理解错误就叠加修补，也能让用户在关键决定前看见具体可审阅内容。","例如摘要漏了设备未知项，先核对原文和现有输出，再确定补字段，而不是直接重写整套比较报告。视觉工作先原型确认，收费、发布或资料外传等越出原任务范围的行为另行明确；范围内可逆小修改按已授权任务推进。"]},{"title":"新增需求要有明确去向","paragraphs":["变更控制是把新要求纳入当前计划或有记录地推迟，并评估影响。临时加报名表可能引入个人数据、保存与权限，不是多写一段文字那么简单。先解释它影响哪些已有标准，再决定当前范围。","如果新需求并不阻碍本轮目标，可以放到后续列表，先交付已能验收的场地比较。反例是嘴上说稍后考虑，执行时却悄悄实现：这会使范围、费用和验收同时漂移，也让用户难以判断当前成果。"]},{"title":"保留基线与检查历史","paragraphs":["每次通过一个小步就保存可定位版本和检查说明；下一步失败时，能回到明确起点。资料任务可保留版本文件，代码项目可用Git。关键是记录变化理由和验收结果，而非只按时间堆副本。","结束时说明本轮已完成、加入的变更、明确推迟项与限制。一次小步通过不应自动表示整项目通过。若新条件推翻了旧结论，应更新旧记录的适用范围，保留为什么改的说明，而不是删除历史让变化无法解释。"]}],"glossary":[{"term":"检查点","meaning":"有具体成果、判断标准和下一步依据的阶段边界。"},{"term":"变更控制","meaning":"明确记录新要求的去向、影响与生效范围。"},{"term":"基线","meaning":"经过已知检查、可作为后续修改起点的版本。"}],"predict":{"question":"临时加报名表会引入个人字段，当前只做场地比较，先怎样处理？","options":[{"text":"顺手实现以显示效率","correct":false,"feedback":"未经梳理扩展会放大范围与验收的不确定性。"},{"text":"评估影响，明确纳入或推迟并记录","correct":true,"feedback":"新增行为会改变资料与保存范围，需要有清楚决定。"},{"text":"把整个原任务删除重来","correct":false,"feedback":"新需求未必推翻原成果，应先判断依赖关系。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"小步纠错","input":"比较表已有来源与费用，但漏列设备未知；其他事实已核对。","question":"下一步最合适的范围是什么？","options":[{"text":"重写所有资料与标准","correct":false,"feedback":"会引入不必要变化，难以判断新错误来源。"},{"text":"只调整报告结构，不补缺少的设备未知项","correct":false,"feedback":"结构变化不增加设备事实边界，应补未知栏并检查是否影响推荐强度。"},{"text":"补设备未知栏并回查相关结论","correct":true,"feedback":"问题局部且证据明确，先作最小变更再验证。"}],"output":"教学推演：补上设备未知并调整最终结论强度；费用、时间来源保持不变，完成后再检查新增栏。","evidence":["定位到缺失字段","旧有效结论按条件保留"]},{"name":"临时扩范围","input":"原目标只做匿名场地比较，新增请求要收参与者姓名电话并在线报名。","question":"面对本轮小步计划与新增项，计划应怎样变化？","options":[{"text":"先列新增资料与系统影响，当前范围明确决定","correct":true,"feedback":"报名引入不同对象与风险，不能无记录地顺手合并。"},{"text":"把电话号码直接塞进比较表","correct":false,"feedback":"资料用途和必要性不同，混入会扩大输入范围。"},{"text":"把新增请求写进待办就称已完成","correct":false,"feedback":"记录需求不是实现和验证，状态必须区分。"}],"output":"教学推演：登记新需求及依赖，若本轮推迟则仍交付匿名比较；若纳入需重定范围和验收后推进。","evidence":["新旧目标差别","纳入或推迟的明确记录"]}]},"practice":{"intro":"将资料比较拆成四个可检查小步，并处理中途新增的报名需求。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["列观察、方案、制作、验证四步，每步写成果和检查方法","完成资料编号与硬条件表后保存版本","模拟新增报名请求，说明资料、保存和权限影响，明确本轮推迟","完成比较与来源核对，交付当前成果、未完成项和继续条件"],"prompt":"本次练习是 05.04《小步计划与变更控制》。将资料比较拆成四个可检查小步，并处理中途新增的报名需求。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：列观察、方案、制作、验证四步，每步写成果和检查方法；完成资料编号与硬条件表后保存版本；模拟新增报名请求，说明资料、保存和权限影响，明确本轮推迟；完成比较与来源核对，交付当前成果、未完成项和继续条件。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：四步计划与通过依据；可定位基线与本轮差异；新增需求去向和最终范围记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["四步计划与通过依据","可定位基线与本轮差异","新增需求去向和最终范围记录"],"troubleshooting":[{"symptom":"计划很多但看不出进度","check":"核对每步是否能交出具体对象","action":"把抽象动作改成可查看成果，并写通过与失败条件。"},{"symptom":"新功能破坏旧结果","check":"核对是否有基线和独立验收","action":"保存新工作后回到可用版本，缩小变更再重试。"}]},"checks":[{"question":"“继续完善”适合作为唯一下一步吗？","options":[{"text":"足够，AI会自动确定所有取舍","correct":false,"feedback":"未写明的取舍可能与用户时间和范围优先级冲突，不能全部交由模型猜测。"},{"text":"不够，应写清目标变化与验收证据","correct":true,"feedback":"没有边界的动作难判断何时完成或是否偏离。"},{"text":"用更详细的工作动词代替成果与验收","correct":false,"feedback":"动作写多仍可能看不出交付对象，要给出结果与可核对条件。"}]},{"question":"新条件使旧推荐不再成立，怎样保留历史？","options":[{"text":"删除所有旧依据只留最终口号","correct":false,"feedback":"删除来源与旧条件会失去解释变化、定位版本和恢复判断的依据。"},{"text":"维持旧推荐以保持一致","correct":false,"feedback":"一致不能优先于已经明确生效的新条件。"},{"text":"注明旧结论适用条件并保存修订原因","correct":true,"feedback":"注明旧条件能解释历史推荐，也能防止后续把它无条件用于新需求。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/evaluation-best-practices","checked":"2026-10-16"}]},{"id":"05.05","title":"长任务、工具结果与项目交接","lead":"协作者说“读过文件、测试通过”，下一位为什么还需要看到具体路径和真实结果？","goals":["制作一份能由另一位协作者续做的资料交接包，并验证一条来源","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"长任务需要外部可定位记录","paragraphs":["聊天可能很长，人员或会话可能更换，单靠回忆难以判断当前版本。交接记录把目标、已确认决定、当前产物和下一步放到稳定位置，让后来者不必从全部历史中猜测。记录重点是继续所需信息，而不是逐句复述讨论过程。","R1交接A/B资料、最新门槛和比较表；项目路线另附文件路径、启动方式、已知问题与版本。两者都应说明哪些经过实际核对，哪些只是方案。没有这一区分，下一位可能在未验证基础上继续扩大工作。"]},{"title":"工具请求不等于工具结果","paragraphs":["工具是执行读取、搜索或运行等动作的接口，请求是尝试，返回结果才说明发生了什么。读取可能失败或只得到一部分，命令可能退出失败，网络资料可能与问题无关。不能把准备调用写成已经完成。","例如记录写“已检查场馆公告”，却没有链接、日期或相关段落，下位协作者无法核实。代码任务写“测试通过”却无命令、目录和结果，也无法知道覆盖了哪个版本。要求最小证据，不必保存大量无关日志。"]},{"title":"文件存在、读取与采用分别核对","paragraphs":["说明文件存在只是可获得条件；实际读取说明本轮工具拿到内容；后续行为遵守内容才说明正确采用。可以让协作者先列已读取材料和当前关键限制，然后检查方案是否对应。不要把列表当成全部事实正确的证明。","交接时若发现旧版人数仍为15而新要求为10，应更新当前任务书，并注明旧推荐的适用范围。仅新增“最新请注意”一行可能留下冲突；用明确版本、失效项与保留项更利于继续。"]},{"title":"交接验收要能重新启动","paragraphs":["好的交接能让他人从指定起点重做一项关键检查。资料任务应能追到一条事实，代码任务应能按说明运行并验证一条核心流程。若无法重现，先补缺失起点或资料，不要用“昨天没问题”代替。","最后记录未解决问题、已试方法和停止条件，防止下一位反复尝试无效路径。交接不包含凭据或私人数据，演示记录足够说明结构；需要访问受限资料时明确缺项。可复制不代表可无边界传播，输入仍遵守本轮必要范围。"]}],"glossary":[{"term":"工具结果","meaning":"工具执行后真实返回的内容、状态或错误。"},{"term":"交接记录","meaning":"帮助下一位定位目标、版本、依据与待办的说明。"},{"term":"可重现","meaning":"按相同起点、输入和步骤能够再次检查某项行为。"}],"predict":{"question":"记录只说测试通过，没有命令和版本，最缺什么？","options":[{"text":"可对应当前产物的具体验证依据","correct":true,"feedback":"通过声明不能说明测了哪份代码和哪些行为。"},{"text":"请协作者再次承诺测试通过，不补记录","correct":false,"feedback":"重复承诺不提供当前版本、命令或结果，仍无法核对究竟测了什么。"},{"text":"把所有私人日志不筛选地上传","correct":false,"feedback":"大量无关与敏感内容并不能替代最小定位信息。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"资料交接","input":"文件夹有A/B原文、旧周六15人比较表，新消息改为周日10人。","question":"为让下一位继续本次工作，交接首先应明确什么？","options":[{"text":"只保留旧推荐A","correct":false,"feedback":"丢掉条件会使旧结论被错误用于新场景。"},{"text":"最新标准、旧表适用范围与原文位置","correct":true,"feedback":"后续需要知道哪个条件生效，以及事实从哪里取得。"},{"text":"说所有资料都读过就结束","correct":false,"feedback":"没有定位与关键限制，下一位仍无法核对。"}],"output":"教学推演：交接包标当前标准为周日10人，旧表为历史；保留A/B来源并安排重新比较，不声称已复评。","evidence":["版本与标准可定位","待办状态没有提前完成"]},{"name":"执行失败","input":"工具返回读取文件失败，摘要却写已读完并据此继续修改。","question":"为让下一位继续本次工作，应怎样纠正？","options":[{"text":"保留摘要以维持进度一致","correct":false,"feedback":"一致的假记录会把错误前提传给后续工作。"},{"text":"换个文件名猜测内容","correct":false,"feedback":"没有读取依据就不能当成真实项目事实。"},{"text":"改为读取未完成，先解决路径或提供必要内容","correct":true,"feedback":"返回结果与摘要矛盾，不能在假设已读的基础上推进。"}],"output":"教学推演：撤回已读声明，记录具体失败与缺项；在真实读取或明确粘贴内容后，才恢复后续判断。","evidence":["工具失败状态","交接摘要如实修订"]}]},"practice":{"intro":"制作一份能由另一位协作者续做的资料交接包，并验证一条来源。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["准备当前任务书、A/B原文、最新比较表和版本日期","写已完成、未完成、关键限制、已试方法与下一步，不含私人字段","请协作者先列实际读取材料与关键条件，再继续一个小步","要求给出一条结论的原文依据，检查执行失败是否如实记录；项目路线可另附运行命令"],"prompt":"本次练习是 05.05《长任务、工具结果与项目交接》。制作一份能由另一位协作者续做的资料交接包，并验证一条来源。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：准备当前任务书、A/B原文、最新比较表和版本日期；写已完成、未完成、关键限制、已试方法与下一步，不含私人字段；请协作者先列实际读取材料与关键条件，再继续一个小步；要求给出一条结论的原文依据，检查执行失败是否如实记录；项目路线可另附运行命令。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：可定位交接包与当前版本；实际读取和缺项清单；一条重现核对结果及未解决问题记录。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["可定位交接包与当前版本","实际读取和缺项清单","一条重现核对结果及未解决问题记录"],"troubleshooting":[{"symptom":"对方又按旧条件继续","check":"核对任务书、摘要和表格版本是否一致","action":"突出当前标准并标旧项失效，再要求复述后重做相关判断。"},{"symptom":"说执行了却无结果","check":"核对是否只有请求、计划或截断输出","action":"补实际返回状态和关键证据，未执行就明确标记。"}]},"checks":[{"question":"工具返回文件内容就能证明采用了所有限制吗？","options":[{"text":"不能，还需检查方案和行动是否遵守","correct":true,"feedback":"获取信息与正确应用是两段不同的证据链。"},{"text":"能，读取会自动执行所有文字","correct":false,"feedback":"读取只是取得内容，后续方案仍可能误用或忽略限制，需要检查行动与结果。"},{"text":"只需把文件再读十遍","correct":false,"feedback":"重复读取不能替代检查关键限制的实际采用。"}]},{"question":"为让下一位继续本次工作，交接里应优先保留哪项？","options":[{"text":"优先复制完整聊天，暂不整理当前待办","correct":false,"feedback":"聊天可保留背景，但关键版本与下一步不突出会使交接仍依赖猜测。"},{"text":"当前版本、关键限制和可重现的下一步","correct":true,"feedback":"这些帮助下一位继续，不依赖猜测完整历史。"},{"text":"只有最终截图不附来源","correct":false,"feedback":"截图通常不含原始资料与完整执行步骤，无法替代交接所需来源和起点。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/conversation-state","checked":"2026-10-16"}]},{"id":"05.06","title":"纠偏与独立需求练习","lead":"“再认真一点”之后结果还是错，怎样判断应补资料、改说明，还是修正实现？","goals":["独立完成一次条件变化任务，并交付从错误定位到修正验证的G1记录","改变一个条件后，依据输入和可观察证据解释结果，指出不能由当前结果证明的部分。"],"sections":[{"title":"先写预期与实际的具体差别","paragraphs":["纠偏从可观察差异开始，而不是评价协作者态度。写清输入、步骤、预期、实际和最近变化，让问题成为可以复现的对象。资料任务标出错误句和原文，项目任务标出动作与状态，不用“整个都不好”代替定位。","例如预期设备未知，实际写投影齐全，应提供原文没有设备信息这一依据；预期只完成t2，实际t1也变了，应给两条同名任务与点击步骤。具体差别会引导不同修复，不该统一改成一条更长提示词。"]},{"title":"区分资料、说明与实现问题","paragraphs":["资料问题是输入缺少、过时或错误；说明问题是目标、范围或标准表达不清；实现问题是目标已明确但程序或产物未做到。三类可能同时存在，先用现有证据找最靠前的断点，避免只在末端润色。","若场地原文没有容量，先补资料；原文有容量但需求没说人数，先补说明；两者都明确而比较把12当20，则修正处理结果并回查其他数字。分类是排错起点，不是给责任贴标签，判断可以随着新证据改变。"]},{"title":"小步修正后重跑原条件","paragraphs":["一次只改变能解释当前差异的一项，再重复原步骤，观察是否消除错误，同时检查相关旧功能。记录已试方法和结果，防止来回重复无效改动。连续没有进展时，应缩小输入或回到可用基线，而不是叠加更多未经验证补丁。","资料修订后仍需检查来源、条件与未知项；代码修复后仍需检查正常、失败与恢复。反例是只挑一个新成功输入展示，避开原来失败的条件，这不能证明故障已修复，也无法回答变化为什么有效。"]},{"title":"换需求检验能否迁移","paragraphs":["R1将比较场地改为比较两份课程资料，或改变原场地日期人数；创作路线将任务管理迁移到读书记录。迁移要包含新的字段或行为差异，不能只换标题。先写新验收，再自主选择资料和流程，逐步撤去照做提示。","最终提交处理方式选择、输入依据、错误假设纠正、结果核对和可执行验收，形成G1证据。概念题通过不自动代表外部操作完成，自检也不是系统认证。你应说明已能独立完成什么、还依赖什么，以及下次遇到不同输入会怎样继续。"]}],"glossary":[{"term":"复现","meaning":"按明确起点、输入和步骤再次产生待检查现象。"},{"term":"断点","meaning":"处理链路中未按预期继续或产生错误的具体环节。"},{"term":"迁移","meaning":"把已理解的方法用于有实质差异的新需求并验证。"}],"predict":{"question":"原文缺容量，却不断调整摘要语气，为什么难纠正推荐？","options":[{"text":"语气足够坚定就能确定容量","correct":false,"feedback":"模型说得自信不改变场地容量未知，必须补资料或降低当前结论强度。"},{"text":"把摘要写短就一定能避免缺项","correct":false,"feedback":"篇幅减少不会自动获得原文没有的资料。"},{"text":"缺的是决策资料，措辞不能补事实","correct":true,"feedback":"应先获得容量或保留未知，再按人数门槛判断。"}]},"experiment":{"title":"先预测，再核对条件变化","brief":"先遮住结果，阅读每个输入并选择判断，然后逐项核对证据。两个案例只改变有关条件，练习把原因与结果联系起来。","boundary":"以下为预制教学推演，输入、答案和结果由教材作者编写，不是实时模型调用、真实终端输出或真实产品截图；实际操作结果必须另行记录。","cases":[{"name":"资料缺失","input":"A写周六100元但没有座位数；需求周六15人；回答说A完全满足。","question":"根据当前预期与实际差异，应先纠正什么？","options":[{"text":"容量未知，当前不能判完全满足","correct":true,"feedback":"已有时间与费用信息不足以满足人数条件的核对。"},{"text":"只把完全满足改成很可能满足后直接定案","correct":false,"feedback":"降格措辞仍缺少必需容量证据，不能完成最终验收。"},{"text":"只改推荐措辞，不列容量待确认","correct":false,"feedback":"措辞改变不能补足人数门槛的必要资料，应显式标未知并安排核实。"}],"output":"教学推演：将容量标待确认，保留可检查的时间与费用；下一步询问容量，而非继续润色确定推荐。","evidence":["缺失字段明确","结论强度回到证据范围"]},{"name":"实现错误","input":"A20座、B12座；需求15人；规则明确，但结果将B标为满足。","question":"根据当前预期与实际差异，优先修复哪一层？","options":[{"text":"继续询问用户人数","correct":false,"feedback":"人数已给出，重复追问不能解释12被判为足够。"},{"text":"修正比较结果并检查数字处理","correct":true,"feedback":"资料和标准均已明确，当前错误在应用规则的结果。"},{"text":"把需求改成10人让结果通过","correct":false,"feedback":"把15改成10是改变用户门槛来迁就错误，不能证明原比较逻辑已修复。"}],"output":"教学推演：B应不满足人数门槛；修正后用15人原条件重测，再换10人检查结论能否随条件合法改变。","evidence":["12与15的比较","原失败条件和新条件均核对"]}]},"practice":{"intro":"独立完成一次条件变化任务，并交付从错误定位到修正验证的G1记录。R1 可用文本编辑器与能使用的对话工具完成资料任务，无须写代码；Codex 只是可选的协作方式，项目学习者也可把相同检查用于任务工具。","steps":["R1将日期人数改为周日10人，或自选两份公开材料；项目路线可改读书记录需求","先写输入、成果与验收，再请协作者复述，纠正一项实际假设","挑一项不符预期结果，按资料、说明、实现三层定位，保留具体依据","只修相关一项并重跑原失败条件，再加一个新条件验证迁移，整理G1证据"],"prompt":"本次练习是 05.06《纠偏与独立需求练习》。独立完成一次条件变化任务，并交付从错误定位到修正验证的G1记录。请先复述输入、允许范围和验收，不猜测未提供的文件或执行结果。按以下步骤协助我：R1将日期人数改为周日10人，或自选两份公开材料；项目路线可改读书记录需求；先写输入、成果与验收，再请协作者复述，纠正一项实际假设；挑一项不符预期结果，按资料、说明、实现三层定位，保留具体依据；只修相关一项并重跑原失败条件，再加一个新条件验证迁移，整理G1证据。每一步给我可观察的核对点，最后按证据清单报告完成与未完成：新任务说明与处理方式理由；具体错误、分层判断与一次纠正记录；原条件复测、新条件迁移及仍需帮助的说明。如起点缺失先指出缺项；涉及新视觉先出原型等待我确认；不得把示例推演写成实际成功。","evidence":["新任务说明与处理方式理由","具体错误、分层判断与一次纠正记录","原条件复测、新条件迁移及仍需帮助的说明"],"troubleshooting":[{"symptom":"反复修改仍无进展","check":"核对是否保留原错误、每次只变一个条件","action":"回到可用版本或最小资料，列已试方法后缩小重现。"},{"symptom":"只展示新成功例","check":"核对是否重跑原失败条件","action":"先补原步骤的前后结果，再报告修复范围与未覆盖项。"}]},"checks":[{"question":"只换任务页标题为读书记录能证明迁移吗？","options":[{"text":"能，名称不同就是全新需求","correct":false,"feedback":"只换标题未改变数据或交互，无法检验方法能否适应实质不同的新要求。"},{"text":"必须完全不用AI才算迁移","correct":false,"feedback":"课程允许工具协作，关键是判断、证据与独立推进。"},{"text":"不能，还需新字段或行为的实际要求","correct":true,"feedback":"实质变化才能检验是否理解数据与流程职责。"}]},{"question":"修复后为何还要重复原失败步骤？","options":[{"text":"证明改变解释并消除了原来的差异","correct":true,"feedback":"新成功输入不能替代原问题已解决的证据。"},{"text":"只测另一个更容易成功的新输入","correct":false,"feedback":"新输入可能避开原故障，必须重跑原条件才能证明相应差异已消除。"},{"text":"原失败已被删除所以永远不必再测","correct":false,"feedback":"删除记录会丢证据，不代表故障不存在。"}]}],"sources":[{"label":"官方或原始资料：developers.openai.com","url":"https://developers.openai.com/api/docs/guides/evaluation-best-practices","checked":"2026-10-16"}]},{"id":"06.01","title":"HTML：内容结构与语义","lead":"页面上的“添加”已经像按钮，为什么按Tab键却找不到它？先检查它究竟是什么元素。","goals":["区分文档内容、语义结构和CSS外观","用标题、列表、标签和原生按钮组织任务页，并检查键盘操作"],"sections":[{"title":"先看内容能否被找到","paragraphs":["把样式临时关闭后，任务页可能失去颜色和分栏，但“我的任务”、输入框和任务条目仍应能按合理顺序阅读。这说明HTML先描述内容和结构，CSS再决定表现。浏览器把HTML解析成一棵元素树，称为DOM；后面的JavaScript可以查找其中的节点并更新内容。","例如页面主标题用h1，任务区域用h2，一组任务用ul和li，能表达谁属于谁。把所有文字放进同一个div再靠字号模拟层级，视觉上可以相近，却丢失机器可以理解的关系。标题层级也不是字号菜单；为了小一点而随意跳到h5，应改样式而不是改内容的身份。"]},{"title":"按钮的语义也带来行为","paragraphs":["原生button不只是一个带边框的盒子：它通常能获得键盘焦点，也支持常见的键盘激活。可点击div若没有补足键盘与可访问性行为，就可能只有鼠标用户能操作。选择合适元素，能使用浏览器已有的可靠行为，减少自己模拟控件的工作。","在表单里，添加按钮明确设为type=\"submit\"，取消编辑设为type=\"button\"，能避免取消时意外提交。原生元素提供基础行为，但不会自动添加任务；仍要由事件处理函数检查输入并更新状态。因此“它是button”和“它完成了添加业务”是两项要分别验证的事实。"]},{"title":"表单需要能理解的输入关系","paragraphs":["输入框上方放一句“任务标题”，不代表这句话已与控件关联。label的for与input的id相同，才建立明确关系，点击标签也能把焦点移到输入框。占位文字会在输入后消失，不能替代持久的标签；错误说明还要让使用者知道应改哪里。","任务页可以把label、input和提交button放在同一个form中，监听submit事件并阻止不需要的整页跳转。这样按Enter与按按钮能走同一个添加入口。若只监听按钮的click，键盘提交可能绕过自己的检查；反例提醒我们，结构会影响事件，但不能代替事件逻辑。"],"code":"\u003cform id=\"task-form\">\n  \u003clabel for=\"task-title\">任务标题\u003c/label>\n  \u003cinput id=\"task-title\" name=\"title\" required>\n  \u003cbutton type=\"submit\">添加任务\u003c/button>\n  \u003cbutton type=\"button\">取消编辑\u003c/button>\n\u003c/form>"},{"title":"用两类证据判断结构问题","paragraphs":["先在元素面板确认实际标签和父子关系，再关闭样式阅读顺序，最后仅用Tab、Shift+Tab和Enter走一次添加过程。若元素里根本没有任务文字，是内容或渲染问题；若文字存在却被遮住，才继续查CSS。这样能避免让Codex反复改颜色来修一个没有创建节点的问题。","结构正确也不能保证手机布局、颜色对比或任务保存正确。一个语义清晰的表单可能仍被固定宽度挤出屏幕；一个可聚焦按钮可能调用了错误的任务ID。本课只建立可靠结构的检查方法，布局到06.03验证，动作到状态的链路到06.04追踪。"]}],"glossary":[{"term":"语义","meaning":"元素所表达的内容身份或用途，如标题、列表、按钮，不只是外观。"},{"term":"DOM","meaning":"浏览器解析文档后形成的节点树，脚本修改它会影响显示。"},{"term":"焦点","meaning":"当前接收键盘输入或激活操作的控件位置，应有可见提示。"}],"predict":{"question":"“添加”由带click处理的div实现，鼠标可用，Tab却跳过它。优先改什么？","options":[{"text":"换为原生button并验证原事件与键盘操作","correct":true,"feedback":"原生按钮提供基础键盘行为，仍需确认添加逻辑没有在替换时丢失。"},{"text":"在div上增大字号和点击区域","correct":false,"feedback":"更好点中不能建立键盘焦点与激活语义。"},{"text":"给标题增加h1，让页面层级更清楚","correct":false,"feedback":"标题结构值得改，但不能直接解决添加控件无法聚焦。"}]},"experiment":{"title":"同样外观，检查不同结构","brief":"比较两个只有HTML结构不同的任务表单；先预测键盘表现，再读教学结果。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"鼠标能点的盒子","input":"输入框没有label；“添加”是\u003cdiv class=\"button\">添加\u003c/div>，脚本只绑定click。","question":"仅用Tab和Enter，最需要担心什么？","options":[{"text":"任务标题会自动变成页面主标题","correct":false,"feedback":"控件语义改变交互入口，不会把输入的任务文字自动变成页面标题。"},{"text":"浏览器会把div自动替换成button","correct":false,"feedback":"浏览器解析不会替作者补上这项业务意图。"},{"text":"添加入口可能无法获得焦点或被键盘激活","correct":true,"feedback":"div不会因外观像按钮就获得button的默认交互。"}],"output":"教学推演：Tab经过输入框后跳到下一可聚焦控件；鼠标能添加不构成键盘验收通过。","evidence":["检查实际标签仍为div","记录键盘焦点经过哪些元素"]},{"name":"结构正确但业务未接通","input":"输入有对应label；原生submit按钮可聚焦，但form没有自定义提交处理。","question":"由HTML本身能证明哪项事实？","options":[{"text":"既然有form，就无需检查页面是否跳转","correct":false,"feedback":"表单有默认提交行为，应用需根据需求处理。"},{"text":"控件关系更清楚，不能证明已更新任务数组","correct":true,"feedback":"结构与业务状态是不同层次，需继续观察提交后的数据。"},{"text":"按Enter一定会新增本地任务并保存","correct":false,"feedback":"HTML不会自动替应用维护任务数组和存储。"}],"output":"教学推演：标签可定位输入，按钮可聚焦；提交可能触发默认导航，任务功能仍需接入。","evidence":["点击标签观察焦点","对照提交前后的任务状态"]}]},"practice":{"intro":"已完成模块02的V0与模块03、05，在自己的练习项目副本中操作。本课目标：把任务页改为可解释的语义结构","steps":["在V0副本记录入口HTML与添加函数所在文件，保存两条演示任务。","列出主标题、任务分区、列表、标题输入和按钮，检查实际元素；只修结构与标签关系。","把添加统一接到form的submit入口，取消按钮明确不提交；保留原有保存逻辑。","暂时关闭样式核对内容顺序，恢复后仅用键盘添加任务与取消编辑，再刷新检查旧功能。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“把任务页改为可解释的语义结构”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在V0副本记录入口HTML与添加函数所在文件，保存两条演示任务。；列出主标题、任务分区、列表、标题输入和按钮，检查实际元素；只修结构与标签关系。；把添加统一接到form的submit入口，取消按钮明确不提交；保留原有保存逻辑。；暂时关闭样式核对内容顺序，恢复后仅用键盘添加任务与取消编辑，再刷新检查旧功能。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["HTML差异，能指出标签、for/id与按钮类型","键盘操作顺序与实际结果","关闭样式后的内容检查记录及恢复后添加、保存结果"],"troubleshooting":[{"symptom":"按取消也新增任务","check":"查看按钮是否处于form内且缺少type","action":"设为type=\"button\"，重新验证取消与提交各走自己的路径。"},{"symptom":"标签可见却不能定位输入","check":"核对for与id是否完全相同，id是否重复","action":"修正关联并测试点击标签、Tab聚焦与实际输入。"}]},"checks":[{"question":"关闭CSS后，列表文字仍在但变为单列。最合理的解释是？","options":[{"text":"内容结构存在，布局主要由样式决定","correct":true,"feedback":"关闭CSS只影响呈现，标题和任务节点仍保留在DOM中。"},{"text":"任务数据已损坏，需要重建数组","correct":false,"feedback":"单列是失去布局规则后的正常表现，需核对字段才能判断数据损坏。"},{"text":"HTML失效了，只剩浏览器缓存","correct":false,"feedback":"无样式展示也可以是有效HTML的正常表现。"}]},{"question":"取消按钮已能聚焦，但按Enter仍提交编辑。先核对什么？","options":[{"text":"把按钮文本改短","correct":false,"feedback":"缩短按钮文字不改变按钮类型，也不会阻止表单默认提交。"},{"text":"只确认按钮颜色是否符合参考图","correct":false,"feedback":"按钮颜色只影响外观，提交原因应从按钮类型与事件入口核对。"},{"text":"按钮类型与实际提交事件入口","correct":true,"feedback":"可聚焦只证明一部分交互，默认提交可能仍在发生。"}]}],"sources":[{"label":"MDN：用HTML组织内容","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content","checked":"2026-10-16"},{"label":"MDN：网页可访问性","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Accessibility","checked":"2026-10-16"}]},{"id":"06.02","title":"读参考图，作出设计判断","lead":"两张任务页都很漂亮，怎样说明哪张更容易找到“添加”，又怎样避免把截图里没有的行为当成需求？","goals":["用任务与证据解释层级、对比、间距和一致性","把参考图转成可讨论要求，区分静态外观与交互规则"],"sections":[{"title":"从使用者下一步动作读图","paragraphs":["看参考图时先给自己一个具体任务：第一次进入页面，要添加“周五买牛奶”。记录视线先找到哪里，能否找到输入、主按钮和现有任务。设计判断因此有了目的：减少寻找、误解和误操作，而不只是说一张图更高级。","例如A图把装饰标题放得最大，输入区在页尾；B图让标题说明用途，输入和添加按钮相邻，任务紧随其后。B更适合快速添加的理由是操作线索集中。若页面目的是讲故事而不是办事，主次可能不同，所以不能把“所有页面按钮都必须最大”当作通用结论。"]},{"title":"层级和间距共同表达关系","paragraphs":["字体大小、粗细与留白引导阅读顺序。较近的元素常被理解为同一组，分组之间更大的间距可以区分“新建任务”和“筛选已有任务”。当组内比组间还远，使用者可能把某个按钮误认为控制隔壁列表。","在任务页中，让每条任务的标题、完成勾选和编辑按钮形成一组，组与组保持一致节奏；长标题换行后仍能辨认归属。不要只复制参考图的像素值：字体替换、中文长度和手机宽度会改变排版。应描述关系并用真实内容验证，数值是实现手段。"]},{"title":"可辨识状态比单纯配色更关键","paragraphs":["对比既包括文字与背景的明暗差，也包括主操作和次操作的区别。低对比可能让说明难读，所有按钮都同样醒目则难以判断先后。完成状态可以同时使用勾选、文字和适当样式，避免只能靠绿色与灰色辨认。","一致性意味着相同含义使用相同表达。例如每处“删除”都采用一致的文字与确认规则，而不是一处叫移除、一处只有无说明图标。反过来，危险删除与普通保存不该仅为了整齐变得无法区分。颜色对比有量化方法，但测得合格也不能替代实际阅读和键盘检查。"]},{"title":"截图没有记录时间和失败","paragraphs":["静态参考图能显示布局、文字、颜色与某一刻状态，无法证明点击后发生什么、等待多久、失败如何反馈。看见一个垃圾桶图标，只能推测它与删除有关，不能据此断言直接删除、二次确认或支持撤销。这些要写入行为要求并讨论。","把要求写成“手机单列时添加按钮始终有文字；保存失败保留输入并显示原因”，比“像参考图一样专业”更可验收。先制作一张有限原型并与用户确认最终视觉，再实现；如果实现阶段需要明显改变表现形式，应回到原型确认，而不是把文字方向确认当成图像确认。"]}],"glossary":[{"term":"信息层级","meaning":"用结构和视觉差异表达哪些内容先看、哪些内容从属。"},{"term":"视觉一致性","meaning":"同类含义和操作在不同位置保持可预期的表现。"},{"term":"状态反馈","meaning":"向使用者说明正在处理、已成功或失败的可感知信息。"}],"predict":{"question":"参考图只有一个删除图标，没有交互演示。需求中应怎样记录？","options":[{"text":"只要求图标完全一致，行为留给实现时决定","correct":false,"feedback":"是否确认或撤销会改变删除后果，需要在实现前形成明确约定。"},{"text":"记录可见图标，并把确认或撤销规则列为待定行为","correct":true,"feedback":"截图能支持外观判断，不能补出时间过程。"},{"text":"默认点击后立即永久删除，因为图标常这样使用","correct":false,"feedback":"相似产品的习惯只能提供候选方案，不能替代本项目删除规则的确认。"}]},"experiment":{"title":"比较设计证据能支持什么","brief":"以下以文字描述两份页面条件，不虚构真实截图或试学结果。重点是由观察提出可验收要求。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"装饰压过操作","input":"A：大幅装饰占首屏，输入在下方；B：用途标题后接标签、输入、添加按钮。目标是快速记录。","question":"在快速记录的目标下，哪项比较理由最可检查？","options":[{"text":"B让记录入口更容易在首屏定位，应实际验证寻找和操作","correct":true,"feedback":"理由与目标相连，还需原型和使用检查。"},{"text":"A装饰多，所以所有使用者都会更信任","correct":false,"feedback":"装饰数量无法证明使用者信任，仍需结合目标与真实观察验证。"},{"text":"B控件少，因此一定有更完整的功能","correct":false,"feedback":"控件较少可能只是隐藏入口，必须检查行为才能判断功能完整性。"}],"output":"教学推演：选择B的操作布局作为讨论方向，原型确认后检查真实首屏与添加流程；不把推演称作用户研究。","evidence":["两图的入口位置对照","明确任务目标与仍需测试的假设"]},{"name":"单靠颜色表示完成","input":"每条任务文字完全相同；完成只把小圆点变绿色；窄屏截图没有失败提示。","question":"最有价值的补充要求是什么？","options":[{"text":"把所有圆点改得更大就视为体验完成","correct":false,"feedback":"圆点增大也不解释颜色含义，更不能说明保存失败后如何继续。"},{"text":"增加更多绿色使页面保持一致","correct":false,"feedback":"完成和未完成若缺少明确标记，增加同色元素反而可能削弱差异。"},{"text":"补可辨认的完成标记，并定义失败时的文字反馈","correct":true,"feedback":"同时解决状态辨识和截图没有展示的过程。"}],"output":"教学推演：明确完成勾选与状态文字，另写“保存失败保留输入并重试”；这些新增要求需要原型或行为确认。","evidence":["完成与未完成不只靠颜色区分","列出静态图外的行为约定"]}]},"practice":{"intro":"已完成模块02的V0与模块03、05，在自己的练习项目副本中操作。本课目标：把两份参考整理成一张可确认原型与行为说明","steps":["使用自己的V0画面与一份获准参考，写出核心任务和三个可见差异，标注图的来源。","每个修改说明它帮助找到、读懂或操作什么；选两项优先修改，避免一次重画全站。","请Codex先制作一张静态原型供确认；确认前只整理需求，不继续实现或扩展素材。","单独补上等待、空列表、错误、删除与手机排列要求；原型确认后才实现，并核对文字和实际交互。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“把两份参考整理成一张可确认原型与行为说明”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：使用自己的V0画面与一份获准参考，写出核心任务和三个可见差异，标注图的来源。；每个修改说明它帮助找到、读懂或操作什么；选两项优先修改，避免一次重画全站。；请Codex先制作一张静态原型供确认；确认前只整理需求，不继续实现或扩展素材。；单独补上等待、空列表、错误、删除与手机排列要求；原型确认后才实现，并核对文字和实际交互。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["带来源的参考与差异记录","两条由使用目标支持的设计决定及最终原型确认记录","静态图外的行为清单和确认后实现的对照结果"],"troubleshooting":[{"symptom":"反馈只有“不高级”","check":"检查是否说明谁要完成什么操作、哪里难找","action":"将意见改成位置、层级或可读性的具体观察，再给有限原型。"},{"symptom":"实现像图却删错任务","check":"检查行为要求与任务ID处理，而非继续调配色","action":"把逻辑缺陷交回交互链路排查，并补删除对象验收。"}]},"checks":[{"question":"参考图在宽屏可读，能据此认为手机也可用吗？","options":[{"text":"只要按比例缩小即可","correct":false,"feedback":"控件与文字一起缩小可能变得难读难点。"},{"text":"不能，需要检查窄屏下真实内容与操作","correct":true,"feedback":"手机空间缩小后会重新换行和排列，必须检查真实窄屏中的操作。"},{"text":"可以，字体和颜色没有变化","correct":false,"feedback":"即使字体颜色相同，手机容器过窄或按钮遮挡也会使内容难读。"}]},{"question":"两种按钮外观相同，但一个保存一个永久删除。应怎样判断一致性？","options":[{"text":"同类操作一致，后果不同的操作仍需可辨识","correct":true,"feedback":"一致性服务于可预测性，不要求所有后果看起来一样。"},{"text":"所有按钮完全相同才最整齐","correct":false,"feedback":"永久删除和普通保存后果不同，完全同样的表现可能掩盖重要区别。"},{"text":"每个按钮使用不同字体便于区分","correct":false,"feedback":"任意差异又会破坏相同含义的稳定表达。"}]}],"sources":[{"label":"MDN：面向开发者的设计基础","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Design_for_developers","checked":"2026-10-16"},{"label":"MDN：可访问性","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Accessibility","checked":"2026-10-16"}]},{"id":"06.03","title":"CSS：布局与响应式","lead":"电脑上刚好排下的任务页，到了手机为什么横向拖动，删除按钮还被挤走？","goals":["解释盒子尺寸、布局约束和视口变化的关系","按已确认原型修改样式，并用窄屏与长内容检查可用性"],"sections":[{"title":"内容不变，盒子排列可以改变","paragraphs":["HTML提供任务内容与结构，CSS规则选择元素并改变外观和排列。关闭样式仍能读到标题，说明数据没有消失。恢复样式后被遮挡，则要检查尺寸、溢出、定位和层叠，不必先重写任务数组。观察问题在哪一层，比同时改所有文件更有效。","CSS把元素看作有内容、内边距、边框和外边距的盒子。在默认盒模型里，设置宽度后内边距和边框还可能增加总尺寸；border-box让声明宽度包含内边距和边框，便于控制容器。它不是自动适配手机的开关，子元素仍可能有不合理的最小宽度。"]},{"title":"布局表达关系而非固定坐标","paragraphs":["任务列表通常适合纵向排列，每条任务内部再让标题占用剩余空间、操作控件保持可用。Flexbox和Grid可表达这种关系。把每个按钮写死在某个屏幕坐标，截图可能一致，但标题换行、字号放大或任务变多后很容易重叠。","例如flex容器里的标题若不能收缩，超长连续文字可能撑开整行；min-width:0与适当换行规则可让它在分配空间内显示。不要用overflow:hidden一概盖住问题，因为这也会把真正需要操作的按钮裁掉。先解释谁应换行、谁应保持可见，再选择规则。"]},{"title":"响应式是在不同空间作决定","paragraphs":["视口是页面可以使用的显示区域。响应式不是把桌面页面整体缩成小图，而是在空间不足时重排：侧栏变为顶部目录，表单上下排列，按钮允许换行。媒体查询可以按宽度条件切换规则，断点应根据内容开始拥挤的位置选择。","下面片段假设.task-row已经是flex布局，.task-title是标题节点；它只示意收缩与窄屏改列，不是完整页面。还需检查viewport元信息、容器最大宽度和其他规则。某个断点在自己的电脑有效，不代表任意浏览器、缩放和语言都已验证。"],"code":".task-row { display: flex; gap: 0.75rem; }\n.task-title { flex: 1; min-width: 0; overflow-wrap: anywhere; }\n@media (max-width: 38rem) {\n  .task-row { flex-direction: column; }\n}"},{"title":"对照要求，用真实内容压测","paragraphs":["在开发者工具切换宽窄尺寸，至少查看短标题、两行中文、没有空格的长串以及空列表。检查页面是否横向溢出、按钮是否被遮住、焦点是否可见。屏幕截图能记录外观，却不能证明键盘可到达或点击后仍正确，必须实际操作。","视觉修改前保留已确认原型，明显改变布局先给新原型确认。实现后把差异对应到具体要求，例如“窄屏操作列改到标题下方以防遮挡”。如果控件排得整齐但删除了另一条任务，仍是业务错误；布局验收与逻辑验收要分别记录。"]}],"glossary":[{"term":"盒模型","meaning":"元素尺寸由内容、内边距、边框、外边距共同构成的规则。"},{"term":"视口","meaning":"浏览器用于显示页面的区域，可能随设备、窗口和缩放变化。"},{"term":"媒体查询","meaning":"满足某些显示条件时应用一组CSS规则，不负责修改任务数据。"}],"predict":{"question":"窄屏长标题撑开整行，删除按钮跑到屏幕外，下一步最合理的是？","options":[{"text":"给整个页面加overflow:hidden作为完成标准","correct":false,"feedback":"隐藏溢出可能只是遮住按钮，无法操作仍未解决。"},{"text":"把数据库标题截成十个字","correct":false,"feedback":"显示问题不应无依据丢失原始任务内容。"},{"text":"检查标题收缩、换行与容器尺寸，再验证操作仍可见","correct":true,"feedback":"溢出来自布局约束，应查造成宽度的元素。"}]},"experiment":{"title":"改变宽度与内容长度","brief":"推演同一任务行在短标题与长标题、桌面与窄屏的表现，定位布局条件。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"固定宽度遇到窄屏","input":"页面容器width:960px，视口390px，里面只有短标题。","question":"为何短文字也会横向滚动？","options":[{"text":"因为按钮绑定了重复事件","correct":false,"feedback":"监听次数影响操作执行，静态容器溢出仍应查看具体尺寸约束。"},{"text":"容器本身超过可用宽度","correct":true,"feedback":"内容长度不是唯一来源，固定宽度已足以导致溢出。"},{"text":"因为任务数组多了一条","correct":false,"feedback":"条数一般影响高度，当前证据指向宽度。"}],"output":"教学推演：即使只留一条短任务，仍需横向移动；改为受视口约束的容器后再检查内部元素。","evidence":["比较视口与容器计算宽度","删减到一条任务仍复现"]},{"name":"容器适配但内容不收缩","input":"容器最大宽度合理，任务行是flex，标题为很长的连续字符，操作区被挤出。","question":"接下来应检查哪一组条件？","options":[{"text":"标题最小宽度和断行规则","correct":true,"feedback":"子元素的最小尺寸与长串规则仍能撑开容器。"},{"text":"是否把所有任务改成相同标题","correct":false,"feedback":"改成同样短标题只避开长内容，未解决标题收缩和操作可见问题。"},{"text":"只把桌面截图缩小到390像素","correct":false,"feedback":"把截图缩小不会触发媒体查询，必须在实际窄视口观察重新布局。"}],"output":"教学推演：允许标题收缩和换行，窄屏把操作另起一行；原文仍完整保留，按钮可操作。","evidence":["长标题原值没有被截断保存","390px中按钮可见且能聚焦"]}]},"practice":{"intro":"已完成模块02的V0与模块03、05，在自己的练习项目副本中操作。本课目标：修正一处窄屏布局并保留完整任务内容","steps":["在项目副本记录已确认布局，先找到一处实际窄屏问题；若需新布局，先给单张原型确认。","标出造成溢出的容器或子元素，写清它的计算宽度、边距和最小尺寸。","只修改相关CSS，使长标题可读、操作可见，不通过删除任务文字消除溢出。","在1536px与390px视口测试短标题、两行中文、长串、空列表及键盘焦点，恢复常用宽度再检查添加和删除。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“修正一处窄屏布局并保留完整任务内容”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在项目副本记录已确认布局，先找到一处实际窄屏问题；若需新布局，先给单张原型确认。；标出造成溢出的容器或子元素，写清它的计算宽度、边距和最小尺寸。；只修改相关CSS，使长标题可读、操作可见，不通过删除任务文字消除溢出。；在1536px与390px视口测试短标题、两行中文、长串、空列表及键盘焦点，恢复常用宽度再检查添加和删除。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["修改前后的尺寸与溢出证据","相关CSS差异及每条规则的作用","两种宽度、四类内容和实际按钮操作结果"],"troubleshooting":[{"symptom":"加了媒体查询却没有变化","check":"核对CSS是否加载、规则是否匹配或被覆盖","action":"在样式面板查看生效规则和来源，再修改正确文件。"},{"symptom":"没有横向条但按钮不见了","check":"检查父元素overflow和绝对定位裁剪","action":"恢复可见性，修正尺寸根因，逐个操作确认未被遮挡。"}]},"checks":[{"question":"把字体放大后布局重叠，原截图仍很好看，说明什么？","options":[{"text":"用户应只用原字号","correct":false,"feedback":"可用性不能靠固定每个人的阅读设置证明。"},{"text":"HTML数据已自动变化","correct":false,"feedback":"字体放大改变内容占用空间，不会自动修改任务数组中的字段。"},{"text":"现有约束没覆盖内容尺寸变化","correct":true,"feedback":"截图只记录一个条件，应增加变化后的布局检查。"}]},{"question":"媒体查询已命中但标题仍撑开，先做什么？","options":[{"text":"用截图编辑软件把文字缩短","correct":false,"feedback":"编辑截图里的文字只改变图像，浏览器运行时仍受原CSS约束。"},{"text":"查看子元素的计算尺寸与最小宽度","correct":true,"feedback":"父元素媒体查询生效后，子元素仍可能被最小宽度或长串撑开。"},{"text":"再加几个随机断点","correct":false,"feedback":"随机添加断点可能叠加覆盖关系，应先查实际造成溢出的元素。"}]}],"sources":[{"label":"MDN：响应式网页设计","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/CSS_layout/Responsive_Design","checked":"2026-10-16"}]},{"id":"06.04","title":"JavaScript：状态与渲染","lead":"按下“完成”后数据已经变了，页面却没有勾选；另一次页面变了，刷新又恢复。它们断在同一处吗？","goals":["沿事件、状态、渲染解释一次任务操作","用中间证据区分事件未触发与状态未显示，认识保存是另一环节"],"sections":[{"title":"有按钮不等于有操作链路","paragraphs":["浏览器能显示button，是因为HTML节点存在；要让它修改任务，还要监听事件并运行处理函数。事件是发生了什么的通知，例如点击或提交。处理函数收到通知后，可以读取输入、判断条件和决定下一步，按钮外观不能证明这些步骤已经连接。","例如完成按钮带着任务ID，把ID交给toggleTask，而不是把当前行号当成身份。排序或筛选以后，行号对应的记录可能改变，同名任务也不能靠标题区分。定位处理入口时，先记录点的是哪一个控件，再看函数得到的实际ID，避免直接猜渲染有问题。"]},{"title":"状态是程序当前相信的数据","paragraphs":["任务数组记录标题与完成值，筛选条件记录当前看全部还是未完成。状态变化是这些值发生改变。页面是把状态表达给使用者的结果，两者相关却不是同一物。你在元素面板临时改文字，只改了DOM，未必改任务数组。","原生JavaScript中，修改普通数组不会自动调用自己的render函数。常见流程是事件处理后更新数组，再调用render。某些框架提供自己的更新机制，但仍应遵守该框架的状态约定。本课先以原生任务页理解职责，不把框架自动更新能力误说成所有JavaScript的默认行为。"]},{"title":"渲染把当前值变成可见节点","paragraphs":["render读取当前数组和筛选条件，创建或更新列表节点。用textContent写标题，是把输入当文字显示；直接把用户文字拼进innerHTML会让部分字符被当作标签解释。显示过程要保持数据与呈现的边界，不能为了方便把任意输入变成页面结构。","下面toggleTask片段假设tasks数组与render函数已存在，它按ID更新完成状态并重新显示。实际项目还要处理ID不存在的反馈。它没有保存逻辑，所以刷新后是否保留要到模块07检查；不能因为屏幕立刻变化就称为已可靠保存。"],"code":"function toggleTask(id) {\n  tasks = tasks.map(task => task.id === id\n    ? { ...task, done: !task.done }\n    : task);\n  render(); // 重新读取状态并更新列表\n}"},{"title":"沿链路找最早的不一致","paragraphs":["排错时设置少量临时日志：事件入口记录ID，状态更新后记录对应任务，渲染前记录筛选条件。没有入口日志先查监听是否绑定和脚本是否报错；状态正确而列表错误再查render读了什么。一次观察只支持对应环节，不能越过中间证据下结论。","如果切到“未完成”后点击完成，任务消失可能正是正确筛选，并不是删除。切回全部、核对ID与done能解释结果。修复后重跑同一操作，并移除含无关内容的调试日志；再测试取消完成、同名任务和刷新，区分当前显示与后续持久化。"]}],"glossary":[{"term":"事件","meaning":"浏览器对点击、提交等动作发出的通知，处理函数可作出响应。"},{"term":"状态","meaning":"程序当前维护的值，如任务数组、完成值与筛选条件。"},{"term":"渲染","meaning":"读取状态并建立或更新页面显示的过程，不等同于持久保存。"}],"predict":{"question":"点击后入口日志出现，tasks中done从false变true，列表仍未勾选。优先查哪里？","options":[{"text":"render是否运行并读取更新后的状态","correct":true,"feedback":"入口和done更新已被观察到，应继续核对render是否读取最新数组。"},{"text":"把按钮重新绑定十次","correct":false,"feedback":"入口已触发，重复绑定反而可能多次切换。"},{"text":"立即重建数据库","correct":false,"feedback":"本地显示问题目前没有数据库环节证据。"}]},"experiment":{"title":"把两个“点了没反应”拆开","brief":"两例视觉现象相似，但中间证据不同；先找最早没有达到预期的一环。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"事件没有进入","input":"点击完成后没有入口日志；tasks与页面都未变；控制台先前报找不到按钮节点。","question":"没有事件入口日志时，最先查哪一个执行环节？","options":[{"text":"先给render添加更多颜色","correct":false,"feedback":"事件没有进入处理函数时，改变render的颜色无法触发状态更新。"},{"text":"把done的默认值全改为true","correct":false,"feedback":"这样改变初始数据，不能修复动作链路。"},{"text":"脚本执行时节点是否存在，选择器和监听绑定是否正确","correct":true,"feedback":"找不到节点可能使绑定失败，后续状态自然不会改变。"}],"output":"教学推演：修正加载时机或选择器后，入口收到目标ID，再验证状态和显示。","evidence":["原错误位置","修复后一次点击只有一次入口记录"]},{"name":"状态改变但未显示","input":"完成入口收到t2，数组里t2.done变true；render未被调用。","question":"状态正确而显示未变，此时应补哪一环？","options":[{"text":"改任务ID以强迫浏览器保存","correct":false,"feedback":"ID不是刷新页面的信号，也不会自动保存。"},{"text":"在成功更新状态后重渲染，并核对筛选","correct":true,"feedback":"数组已正确更新，但原生页面仍需要render重新读取并呈现当前值。"},{"text":"只改DOM勾选，不让状态参与","correct":false,"feedback":"临时画面可能掩盖下一次重渲染的问题。"}],"output":"教学推演：render读取更新状态后显示完成；若在未完成筛选下则隐藏该行，切回全部可见。","evidence":["同一ID的数据前后值","全部与未完成筛选中的一致结果"]}]},"practice":{"intro":"已完成模块02的V0与模块03、05，在自己的练习项目副本中操作。本课目标：记录并修复事件、状态、渲染链路的一处故障","steps":["复制任务页并保留两条同名但ID不同的演示任务，记录完成与取消完成的预期。","让Codex指出事件监听、状态更新和render的实际位置，只添加必要临时日志。","在副本分别构造监听未绑定与漏调用render，先预测日志和页面，再逐项恢复。","修复后验证一次点击只改变目标任务，筛选后仍按ID更新；单独记录刷新是否保留，不混称渲染成功。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“记录并修复事件、状态、渲染链路的一处故障”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：复制任务页并保留两条同名但ID不同的演示任务，记录完成与取消完成的预期。；让Codex指出事件监听、状态更新和render的实际位置，只添加必要临时日志。；在副本分别构造监听未绑定与漏调用render，先预测日志和页面，再逐项恢复。；修复后验证一次点击只改变目标任务，筛选后仍按ID更新；单独记录刷新是否保留，不混称渲染成功。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["三个环节的代码位置与简短链路说明","两类故障的入口、状态、显示对照记录","修复后同名任务、筛选与取消完成的结果"],"troubleshooting":[{"symptom":"点一次像没变，日志却进入两次","check":"检查监听是否在每次render中重复绑定","action":"只保留合适入口或正确移除旧监听，再核对一次动作一次更新。"},{"symptom":"筛选后改了另一条任务","check":"核对传入的是数组位置还是稳定ID","action":"按ID定位并测试排序、同名与筛选组合。"}]},"checks":[{"question":"元素面板手动把任务标题改了，刷新恢复，为什么？","options":[{"text":"DOM临时变化未必改运行状态或保存来源","correct":true,"feedback":"重新加载会从代码和存储重新建立页面。"},{"text":"浏览器拒绝所有标题修改","correct":false,"feedback":"标题可由应用的状态更新和渲染合法修改，浏览器并未拒绝此功能。"},{"text":"render会自动把改动写回HTML文件","correct":false,"feedback":"浏览器DOM更新不会自动修改源文件。"}]},{"question":"未完成筛选中完成一条任务后该行消失，应怎样验收？","options":[{"text":"只凭消失判断删除成功","correct":false,"feedback":"任务消失可能只是被筛选隐藏，需要检查相同ID是否仍在数组中。"},{"text":"立即关闭筛选功能","correct":false,"feedback":"先依据需求和状态核对，不必取消正确功能。"},{"text":"切回全部核对同一ID仍存在且done为true","correct":true,"feedback":"切回全部仍能找到同一ID且done为true，可证明是筛选而非删除。"}]}],"sources":[{"label":"MDN：事件监听","url":"https://developer.mozilla.org/en-US/docs/Web/API/EventTarget/addEventListener","checked":"2026-10-16"},{"label":"MDN：DOM脚本","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/DOM_scripting","checked":"2026-10-16"}]},{"id":"06.05","title":"表单与边界状态","lead":"普通标题能添加，空格、超长标题、取消编辑和连续点击呢？这些边界决定了工具是否会丢掉有效内容。","goals":["为输入、编辑、删除定义正常与边界规则","检查取消不提交、无效输入不写入、任务标题按文字显示"],"sections":[{"title":"先确定有效输入是什么","paragraphs":["用户输入的空字符串、几个空格和有意义标题看起来不同，但都可能作为字符串进入处理函数。先定义规则：去除首尾空白后不能为空，长度上限应有明确依据，并给出可理解提示。不要把所有空格都删掉，因为标题中间的空格可能是有效内容。","例如“  买 牛奶  ”可以规范成“买 牛奶”，而不是“买牛奶”。长度超过上限时应提示并保留草稿，让用户选择怎样缩短；静默截断会丢失信息。浏览器required可以帮忙，但自定义规则仍需统一到提交入口；后端验证将在08.05补上。"]},{"title":"编辑草稿和已保存状态要分开","paragraphs":["进入编辑后，输入框可以存放草稿。只有用户明确保存且验证通过，才把草稿写入任务数组；取消则丢弃本次草稿，恢复原值。若每输入一个字就覆盖数组，取消按钮即使关闭输入框，也无法再恢复原来的内容。","例如原任务为“周五交报告”，用户临时改成“周五交报”又取消。正确结果应仍是原文，ID与done不变。这里“保存”指应用确认编辑，不自动等于浏览器持久化成功；模块07还要检查写入存储失败时的提示。把两种保存含义说清楚，才能解释状态差异。"]},{"title":"重复动作和删除要有明确后果","paragraphs":["快速按两次Enter可能触发两次提交；本地处理通常很快，可以统一提交入口，在一次处理期间避免重复进入，并在成功后清空输入。是否允许同名任务是业务选择，不能仅因标题相同就把不同事项误当重复。任务身份仍由ID区分。","删除可采用明确确认或可撤销设计，规则应先确定。取消删除后记录必须仍在，删除目标不能依赖筛选后的序号。网络请求中的重复与不确定结果会在08.06继续讲，本课不宣称临时禁用按钮就解决所有跨网络重试问题。"]},{"title":"输入文字不是程序指令","paragraphs":["用户可以输入“\u003cb>买牛奶\u003c/b>”作为标题。使用textContent展示时应看到这些字符，而不是变成加粗标签。把标题拼接到innerHTML会改变解析语义，甚至带来执行或页面结构风险。数据进入页面时，选择正确的写入方式比只过滤几个特殊字符更可靠。","边界验收要覆盖空白、长标题、同名任务、取消编辑、取消删除和连续动作，并在每次后核对数组、页面和刷新结果。若出现错误，先保留输入和证据，再修最早失败的一步。不要通过清空所有记录让页面重新正常，那会把有效数据一起丢掉。"]}],"glossary":[{"term":"校验","meaning":"按明确规则判断输入是否可接受，失败应说明原因。"},{"term":"草稿","meaning":"尚未确认写入正式任务状态的编辑内容。"},{"term":"边界状态","meaning":"接近或超出常用条件的情况，如空值、上限、取消与快速重复。"}],"predict":{"question":"编辑时每次input事件都覆盖任务标题，取消只关闭输入框。最可能有什么问题？","options":[{"text":"将取消按钮调成灰色即可恢复","correct":false,"feedback":"取消按钮变灰只影响外观，不能恢复已被草稿覆盖的原标题。"},{"text":"取消后原任务已被草稿覆盖","correct":true,"feedback":"取消界面动作没有恢复原状态，需把草稿与正式值分开。"},{"text":"只要按钮写“取消”，浏览器就会回滚数组","correct":false,"feedback":"按钮写着取消不会自动回滚数组，程序需要保留正式值或恢复副本。"}]},"experiment":{"title":"正常路径之外还会发生什么","brief":"使用相同任务ID比较“保存草稿”与“取消草稿”，并检查特殊文字。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"无效草稿取消","input":"t7标题“周五交报告”；进入编辑后输入三个空格，随后按取消。","question":"按取消而非保存之后，合理的数据结果是什么？","options":[{"text":"保留原标题，不提交无效草稿","correct":true,"feedback":"取消与保存是不同决定，草稿不应提前覆盖正式值。"},{"text":"把原标题改成空，因为输入框曾为空","correct":false,"feedback":"空白草稿尚未确认保存，写入原标题会破坏取消应保留原值的约定。"},{"text":"删除整条任务，避免空标题","correct":false,"feedback":"空白草稿只应在保存时被拒绝，不能替用户作出删除整条任务的决定。"}],"output":"教学推演：t7的标题、完成值和ID保持不变；取消后再次编辑仍能看到“周五交报告”的完整原文。","evidence":["取消前后同一ID的值","重新进入编辑的内容"]},{"name":"把标签当标题输入","input":"新增标题为“\u003cb>买牛奶\u003c/b>”，渲染使用textContent。","question":"使用textContent后，页面应怎样呈现这段输入？","options":[{"text":"自动变成加粗的买牛奶","correct":false,"feedback":"那是HTML解析的表现，不是文本写入。"},{"text":"因含尖括号就必然导致脚本崩溃","correct":false,"feedback":"尖括号可以是普通字符串内容，正确文本写入不会因此必然崩溃。"},{"text":"逐字显示尖括号和标签文字","correct":true,"feedback":"textContent用于文本，不把输入当HTML结构。"}],"output":"教学推演：显示完整文本，列表结构保持；这只验证本次呈现方式，仍需继续核对存储与导入路径。","evidence":["输入原值与显示一致","没有新增b元素或异常节点"]}]},"practice":{"intro":"已完成模块02的V0与模块03、05，在自己的练习项目副本中操作。本课目标：完善任务表单的输入、取消与文本呈现","steps":["在副本写明空白处理、标题长度上限、同名任务、编辑取消和删除取消的规则；视觉变化先确认原型。","统一表单提交检查；无效输入给出具体提示并保留草稿，成功后才更新目标ID。","编辑使用独立草稿，取消不写正式任务；标题通过文本节点呈现，不拼接用户HTML。","依次试空白、上限边界、超长、同名、尖括号、取消与快速重复，核对有效旧任务没有丢失。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“完善任务表单的输入、取消与文本呈现”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在副本写明空白处理、标题长度上限、同名任务、编辑取消和删除取消的规则；视觉变化先确认原型。；统一表单提交检查；无效输入给出具体提示并保留草稿，成功后才更新目标ID。；编辑使用独立草稿，取消不写正式任务；标题通过文本节点呈现，不拼接用户HTML。；依次试空白、上限边界、超长、同名、尖括号、取消与快速重复，核对有效旧任务没有丢失。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["明确的输入与取消规则","至少七类边界的输入、预期和实际结果","同一ID在取消前后不变，以及特殊文字按文本显示的证据"],"troubleshooting":[{"symptom":"提示错误后输入也没了","check":"检查清空输入是否发生在校验之前或finally里","action":"只在确认成功后清空，失败保留可修改草稿。"},{"symptom":"删除筛选中的第二行却删错","check":"检查是否用显示索引定位原数组","action":"用稳定ID并重新验收筛选、取消删除与同名任务。"}]},"checks":[{"question":"同名“买牛奶”分别代表今天和下周，应怎样处理？","options":[{"text":"把两条强制改成同一个ID","correct":false,"feedback":"同名事项仍需要独立ID，强行共用ID会使更新与删除对象含糊。"},{"text":"按规则允许独立ID，或让用户明确确认重复策略","correct":true,"feedback":"今天与下周的事项可以同名，应按独立身份和业务规则判断重复。"},{"text":"总是保留第一条并无提示吞掉后续输入","correct":false,"feedback":"同名不一定重复，无提示吞掉第二条会让用户误以为记录成功。"}]},{"question":"无效输入被拦住，但已有任务消失了，能否通过？","options":[{"text":"不能，拒绝无效输入还应保护有效状态","correct":true,"feedback":"拒绝无效输入不应删除已有有效任务，两项结果都必须得到保护。"},{"text":"能，因为本课只看提示是否出现","correct":false,"feedback":"显示错误提示只说明有反馈，旧任务丢失仍是不符合要求的后果。"},{"text":"刷新可能回来，所以无需追踪","correct":false,"feedback":"需要核对状态和保存来源，不能靠猜测。"}]}],"sources":[{"label":"MDN：客户端表单校验","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Forms/Form_validation","checked":"2026-10-16"},{"label":"MDN：DOM脚本与文本更新","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/DOM_scripting","checked":"2026-10-16"}]},{"id":"06.06","title":"开发者工具与有关证据","lead":"页面空白时，把整页截图发给Codex常常不够。哪一块证据能说明是图片路径错了，还是脚本先停了？","goals":["按问题选择元素、控制台和网络面板","收集最小复现、实际位置和相关错误，修复后验证同一步骤"],"sections":[{"title":"先用现象限定问题","paragraphs":["“页面不对”包含太多可能：内容缺失、资源未加载、按钮无反应或保存失败。先写清当前地址、入口文件、操作顺序、预期与实际，再打开有关工具。地址还可帮助发现自己修改的是副本A，却打开旧副本B；这个错误不是调JavaScript能解决的。","例如只有图标消失、任务仍能操作，优先看资源加载；整页内容存在但看不见，检查元素和样式；点击后没有变化且控制台报错，追踪脚本。不要每次都把所有面板截图，聚焦同一次操作与最近相关输出，既减轻沟通，也避免暴露无关信息。"]},{"title":"元素面板回答“实际有什么”","paragraphs":["元素面板展示浏览器当前DOM及生效样式，可查看节点、文字、尺寸和被覆盖的规则。它与源码不总相同：脚本可能动态创建节点，浏览器也会修整不完整结构。它适合回答“任务节点是否存在、按钮是否被遮挡”，不直接证明存储里有什么。","在面板临时改标题或关闭一条CSS规则是诊断实验，通常刷新就消失，不等于已保存项目修改。先用它检验假设，再让Codex改正确源码并重载核对。若只提交面板截图说“已经修复”，别人重新打开项目可能仍会看到原问题。"]},{"title":"控制台与网络回答不同环节","paragraphs":["控制台显示脚本错误与调试输出，错误位置和调用栈可指向最早失败的函数。红色提示并不都由自己的代码引起，应结合文件来源和操作时刻判断。先修导致执行中断的相关错误，后续没有事件日志可能只是同一个中断的结果。","网络面板记录资源和请求的地址、方法、状态与响应。图片404说明该请求的资源未找到，不直接说明任务数组坏了；请求根本没出现，则要查触发逻辑。后续模块会用网络面板追踪API，本课先比较静态资源失败与脚本错误，避免混成一种“网络不好”。"]},{"title":"证据要能支持和排除假设","paragraphs":["一份有用的求助记录包含：环境与版本、复现步骤、预期与实际、相关请求或报错、最近改动。可以附短代码上下文，不要只截最后一行“失败”。错误文件与行号可能在刷新或构建后变化，因此记录时应对应当前版本。","修复后从同一地址重跑同一步骤，确认错误消失且目标功能恢复，再检查邻近正常功能。删除日志或关闭错误显示不是修复，缓存旧页面也可能掩盖问题。日志与请求体中若出现私人内容或秘密，只保留匿名化的相关片段；本课不要求上传完整项目或所有网络记录。"]}],"glossary":[{"term":"控制台","meaning":"查看脚本报错和日志的开发者工具区域，可辅助追踪执行。"},{"term":"网络面板","meaning":"记录浏览器发出的资源与接口请求及其响应的工具区域。"},{"term":"最小复现","meaning":"保留足以稳定出现问题的最少步骤、输入和环境说明。"}],"predict":{"question":"任务正常，只有logo不显示，网络面板显示图片请求404。最相关的下一步是？","options":[{"text":"先重写所有任务事件","correct":false,"feedback":"列表交互仍正常，当前直接证据指向图标404，而非所有任务事件。"},{"text":"只截页面空白区域，不附请求地址","correct":false,"feedback":"页面空白区域不能指出请求了哪份图标，需要附完整请求地址和状态。"},{"text":"核对该图片URL与实际文件路径","correct":true,"feedback":"404证据落在资源请求，应检查对应文件和引用。"}]},"experiment":{"title":"同样“缺了一块”，证据指向不同位置","brief":"比较资源404与脚本类型错误，两例都只用演示数据。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"图片找不到","input":"任务列表可编辑；图标空白；GET /assets/icon.svg返回404，控制台没有相关脚本异常。","question":"只有图标请求404，应该从哪一层开始定位？","options":[{"text":"浏览器任务存储JSON","correct":false,"feedback":"图标资源失败而任务操作正常，清空任务数据既无因果依据又有损失。"},{"text":"静态资源引用与服务目录","correct":true,"feedback":"请求已发出，资源路径或文件位置是直接线索。"},{"text":"数据库事务","correct":false,"feedback":"本例失败的是静态图片请求，没有事务或数据库写入环节的证据。"}],"output":"教学推演：修正实际路径或移动回正确资源位置，重载后该请求成功且图标出现。","evidence":["修复前后的相同请求地址与状态","任务交互回归结果"]},{"name":"脚本先中断","input":"添加按钮可见但无反应；控制台显示对null调用addEventListener，文件task.js对应绑定位置。","question":"哪份材料最有助于Codex？","options":[{"text":"报错位置、选择器附近代码、页面地址与加载顺序","correct":true,"feedback":"这些能检验节点不存在或执行过早的假设。"},{"text":"仅告知“按钮不好用”","correct":false,"feedback":"只说按钮不好用，没有地址、错误与代码位置，难以检验绑定失败原因。"},{"text":"导出全部浏览历史","correct":false,"feedback":"完整浏览历史无助于定位当前选择器，还会带入无关私人访问记录。"}],"output":"教学推演：查明选择器或执行时机后修正，重新打开页面，按钮事件进入且能添加。","evidence":["当前版本的完整相关错误","同一步骤修复后成功并无该错误"]}]},"practice":{"intro":"已完成模块02的V0与模块03、05，在自己的练习项目副本中操作。本课目标：用开发者工具整理两份可复现问题报告","steps":["在项目副本记录当前地址与文件，保存可恢复版本；准备一条演示任务。","暂把一个图片引用改错，重载并保存具体请求地址、状态、页面现象，然后恢复。","在副本构造一个找不到节点的事件绑定，保存相关控制台错误和代码位置，不影响原项目。","分别写五行问题报告交给Codex，修复后从原步骤重测，并检查添加、完成和保存未受影响。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“用开发者工具整理两份可复现问题报告”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在项目副本记录当前地址与文件，保存可恢复版本；准备一条演示任务。；暂把一个图片引用改错，重载并保存具体请求地址、状态、页面现象，然后恢复。；在副本构造一个找不到节点的事件绑定，保存相关控制台错误和代码位置，不影响原项目。；分别写五行问题报告交给Codex，修复后从原步骤重测，并检查添加、完成和保存未受影响。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["资源失败的URL、状态、引用位置和恢复结果","脚本错误的文件位置、上下文与复现步骤","两份匿名化求助报告及同一操作的修复前后对照"],"troubleshooting":[{"symptom":"看不到刚发出的请求","check":"检查网络面板是否在操作前开启，筛选是否隐藏资源","action":"清除面板筛选，在练习副本重载或重做动作，避免无关整站清空。"},{"symptom":"面板改好了但刷新又坏","check":"检查是否只修改了DOM或临时样式","action":"把验证过的修改写回正确源码，再重新加载验证。"}]},"checks":[{"question":"控制台没有报错，能证明保存成功吗？","options":[{"text":"能，存储失败一定有红色错误","correct":false,"feedback":"应用可能捕获了错误，也可能根本未写入，需重新读取验证而非只看红字。"},{"text":"只能看按钮颜色","correct":false,"feedback":"按钮颜色可能提前改变，只有写入和重新读取的结果能验证持久化。"},{"text":"不能，还需观察写入与重新读取结果","correct":true,"feedback":"控制台无异常不保证写入发生，应核对目标存储与刷新后的字段。"}]},{"question":"修了图片路径后404消失，按钮仍没反应，怎样继续？","options":[{"text":"反复修改图片路径直到按钮可用","correct":false,"feedback":"图片地址已恢复，继续反复改路径无法解释按钮事件未触发的原因。"},{"text":"把按钮问题单独复现，查事件与相关脚本证据","correct":true,"feedback":"图片成功只覆盖资源环节，按钮仍需事件、状态和渲染的独立证据。"},{"text":"宣布整页已通过","correct":false,"feedback":"目标还包含按钮可操作，404消失不能替代未恢复的添加行为。"}]}],"sources":[{"label":"MDN：什么是浏览器开发者工具","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Tools_and_setup/What_are_browser_developer_tools","checked":"2026-10-16"}]},{"id":"06.07","title":"完善交互与体验验收","lead":"添加、编辑和删除都各自成功过一次，为什么连起来用仍会删错、丢草稿，或在手机找不到操作？","goals":["把视觉、可操作性和业务正确分开验收","用状态组合和边界检查完善任务页，并保留一次修复证据"],"sections":[{"title":"一次成功不是完整使用流程","paragraphs":["功能演示常从干净页面开始，输入短标题后立刻成功。真实使用却会把动作连起来：添加两条同名任务、筛选未完成、编辑其中一条、取消删除再完成。组合后仍要保持目标ID准确和数据一致，不能把每个按钮各点一次就当完整验收。","为每项动作写起始状态、输入、预期数据和可见结果。例如编辑应只改标题，保留ID和完成值；取消编辑应两者都不改变。这样清单能被另一人重跑，也能让Codex知道错误发生在哪一步，而不只是“交互有点怪”。"]},{"title":"视觉、操作和逻辑分别取证","paragraphs":["视觉检查关注层级、可读性、对齐与已确认原型；可操作性检查键盘焦点、控件标签、手机可达；逻辑检查到底改了哪条记录、何时保存、失败是否恢复。三者可以同时好，也可能只有一项好，应分别记录。","一个漂亮删除图标可能点中了旁边按钮，一个能聚焦的删除按钮也可能收到错误ID。相反，逻辑正确的控件若被长标题盖住仍无法使用。修复哪个层次，就重新验证该层与相关流程；不能用另一层的截图替代实际行为证据。"]},{"title":"空列表也是有意义的状态","paragraphs":["空列表可能是确实没有任务，也可能是筛选没有匹配，不应都显示模糊的“出错了”。提示应说明当前状态并给出下一步，例如“没有未完成任务，查看全部”或“还没有任务，添加第一条”。后续联网读取失败又是另一种状态，不能伪装为空。","完成任务后在未完成筛选中消失，是合法反馈，但用户还需要能理解变化。保留当前筛选名称和计数，有助于解释。若删除后焦点停在已移除节点，应将焦点放到合理的下一位置，避免键盘用户迷失；这个细节只能通过实际走流程发现。"]},{"title":"把发现的问题变成可复用验收","paragraphs":["找到一个边界问题后，先固定复现条件，再做小修复，并把该条件加入清单。若编辑长标题导致操作重叠，就同时检查窄屏、换行和键盘；若筛选后删错，就检查稳定ID与同名任务。测试要抓住真实失败，不必机械覆盖每一行源码。","保存可运行版本、说明未完成项，再进入模块07扩大保存与恢复边界。这里的体验验收只是自己的项目记录，不是系统颁发的能力认证。若视觉需明显改变，应先提供一张有限原型与用户讨论确认，再修改；验收不能成为绕过视觉确认的理由。"]}],"glossary":[{"term":"验收条件","meaning":"可以按输入与步骤观察是否达成的完成要求。"},{"term":"回归检查","meaning":"修改后重跑原先有效的相关行为，确认没有破坏。"},{"term":"状态组合","meaning":"筛选、编辑、完成与数据数量等条件共同存在的情形。"}],"predict":{"question":"添加、删除各自可用，但未完成筛选中删除第二行删错记录，最需要补什么？","options":[{"text":"筛选与删除组合下按稳定ID核对","correct":true,"feedback":"独立动作成功未覆盖组合后的定位方式。"},{"text":"增加更漂亮的成功提示","correct":false,"feedback":"成功提示更漂亮也不能修正目标ID，仍可能删除错误的原数组记录。"},{"text":"只在全部筛选中演示删除作为完成","correct":false,"feedback":"只演示全部筛选会绕开已经复现的错位，不能证明组合路径修好。"}]},"experiment":{"title":"把单独功能放进连续流程","brief":"两组推演分别改变筛选条件和输入长度，说明为何验收要覆盖组合。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"筛选后的目标错位","input":"原数组t1已完成、t2未完成、t3未完成；筛选后第二行是t3，删除函数却用原数组下标1。","question":"用筛选下标删除原数组记录，最可能发生什么？","options":[{"text":"正确删掉t3，因为第二行总等于下标1","correct":false,"feedback":"只有在相同数组中才可能成立，原数组不同。"},{"text":"只改变颜色，数组不受影响","correct":false,"feedback":"已知执行了删除操作，需核对实际记录。"},{"text":"删掉t2，说明显示下标不能代替ID","correct":true,"feedback":"筛选改变位置对应关系，应传t3的稳定身份。"}],"output":"教学推演：错误版本删t2；改为按ID删除后只移除t3，切回全部仍保留t1与t2。","evidence":["原数组与筛选列表的ID顺序","删除前后记录集合"]},{"name":"长标题与取消相遇","input":"手机390px，编辑一条两行标题，输入更长草稿后按取消。","question":"完整的通过证据应是什么？","options":[{"text":"草稿被截短并自动保存，页面没溢出","correct":false,"feedback":"避免溢出不能以丢失原值和取消语义为代价。"},{"text":"操作可见可达，取消后原标题和其他字段保持","correct":true,"feedback":"按钮可见可达与取消后字段不变，共同覆盖布局、操作和数据后果。"},{"text":"截图中输入框漂亮即可","correct":false,"feedback":"静态画面不能证明草稿未覆盖原标题，需要比较取消前后的字段。"}],"output":"教学推演：修复后的页面能看见取消，键盘可到达，取消恢复原值；刷新结果另外交给模块07检查。","evidence":["手机操作过程","取消前后同一ID完整字段"]}]},"practice":{"intro":"已完成模块02的V0与模块03、05，在自己的练习项目副本中操作。本课目标：完成一份可重跑的任务页体验验收清单","steps":["用两条同名任务、一条已完成任务与一条长标题建立演示起点，记录ID和字段。","按添加、编辑保存、编辑取消、删除取消、确认删除、完成与取消完成、三种筛选和空列表逐项检查。","在宽屏与390px重复关键流程，并仅用键盘操作；视觉变更须先确认原型。","选一项真实失败，记录复现与根因后修复；重跑失败步骤及相关正常行为，保存版本并列出仍未覆盖的限制。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“完成一份可重跑的任务页体验验收清单”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：用两条同名任务、一条已完成任务与一条长标题建立演示起点，记录ID和字段。；按添加、编辑保存、编辑取消、删除取消、确认删除、完成与取消完成、三种筛选和空列表逐项检查。；在宽屏与390px重复关键流程，并仅用键盘操作；视觉变更须先确认原型。；选一项真实失败，记录复现与根因后修复；重跑失败步骤及相关正常行为，保存版本并列出仍未覆盖的限制。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["含起点、输入、预期、实际的验收清单","一次完整故障复现、修改原因与回归记录","宽窄屏、键盘与数据ID对照，以及可恢复版本说明"],"troubleshooting":[{"symptom":"任务消失后不知道删了还是筛掉","check":"核对当前筛选、原数组ID和完成值","action":"切回全部并追踪相同ID，明确删除与隐藏的不同。"},{"symptom":"改完布局原交互失灵","check":"检查DOM结构变化是否影响选择器或事件绑定","action":"定位最早失效环节，恢复或修正后重跑全套关键操作。"}]},"checks":[{"question":"删除逻辑正确，但键盘不能触达删除按钮，怎样记录？","options":[{"text":"逻辑检查通过，可操作性仍失败","correct":true,"feedback":"按ID删除正确证明逻辑，键盘不可达仍违反操作要求，应分别记录。"},{"text":"整体通过，因为鼠标能用","correct":false,"feedback":"鼠标可用不补足键盘入口，清单里的键盘操作仍需独立修复与验证。"},{"text":"逻辑一定也错误","correct":false,"feedback":"控件无法聚焦与删除目标ID错误是不同问题，需各自证据定位。"}]},{"question":"修复一条长标题重叠后，下一步是什么？","options":[{"text":"仅保留修后截图","correct":false,"feedback":"修后截图只能显示某个时刻，仍需操作验证取消、编辑与原有功能。"},{"text":"将所有标题限制为四个字","correct":false,"feedback":"未经需求依据改变内容范围会掩盖布局问题。"},{"text":"重跑原失败及短标题、编辑等相关正常路径","correct":true,"feedback":"重跑原失败确认修复，再查相关短标题和编辑，能发现修改的副作用。"}]}],"sources":[{"label":"MDN：可访问性","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Accessibility","checked":"2026-10-16"},{"label":"MDN：响应式设计","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/CSS_layout/Responsive_Design","checked":"2026-10-16"}]},{"id":"07.01","title":"运行中的状态与文件","lead":"刚添加的任务已经显示，打开HTML文件却找不到那行文字。刷新后它去哪了？","goals":["区分源码、运行时状态、DOM与已保存记录","依据初始化顺序预测刷新结果，并定位真实读取来源"],"sections":[{"title":"文件是起点，不是运行录像","paragraphs":["源码文件描述页面如何建立和操作任务，运行中的任务数组则存在于浏览器进程的内存。添加一条任务通常是修改数组并更新DOM，而不是让浏览器打开HTML文件把新文字写进去。因而在编辑器搜索不到刚输入的标题，并不奇怪。","假设源码写着初始任务“阅读一页”，运行后添加“买牛奶”。当前数组有两条，页面也有两条，但源码仍只有初始示例。把浏览器想成读取剧本后演出的舞台，有助于理解；边界是程序可以主动写入某些存储，只是这种写入需要明确调用，并非所有状态都自动留下。"]},{"title":"刷新建立的是新一轮运行","paragraphs":["刷新会重新加载页面并执行初始化，原先仅在当前运行里的变量通常不会自动延续。若初始化直接把tasks设为示例数组，页面会重新显示示例；这不是浏览器恶意删除，而是程序没有从持久来源恢复。要说明恢复，就要找读取发生在哪里。","关闭标签后重开也要检查同一机制。某些浏览器可能恢复页面会话或使用缓存，但不能把偶然看到旧画面当成自己的保存方案。可靠验收要加入新任务、变更完成状态、重新加载并确认读取来源，必要时在独立练习环境重现，而不是只凭“我关过一次还在”。"]},{"title":"页面、内存、存储可以暂时不一致","paragraphs":["任务可能已显示但保存失败，也可能已写入存储但页面渲染尚未更新。三处数值一致是应用努力维持的结果，不是天然保证。先分别问：程序当前持有什么、屏幕显示什么、下次启动会从哪里读取，再决定下一步排查。","例如你用元素面板改“买牛奶”为“买面包”，数组和存储仍是旧值，下一次render就可能恢复。反过来，在演示存储里手改标题而不刷新，当前页面也可能仍显示内存值。模块07.02会加入序列化和读写；本课先学会用不同证据识别不同位置。"]},{"title":"初始化优先级决定恢复结果","paragraphs":["一个常见错误是先正确读取保存记录，随后又无条件执行tasks = demoTasks，把恢复结果覆盖。另一个错误是每次启动先清空存储再写示例。这两种程序都可能短暂显示正确内容，最终仍失去用户记录，所以必须查看初始化的执行顺序。","合理顺序是区分首次使用、已有有效数据和读取失败：首次可给示例或空列表，有数据则读取，失败则提示并保护原始记录。不要为了让演示每次一致而清理真实学习者的键。本课实践只在项目副本用专用键或内存示例，避免把诊断变成数据破坏。"]}],"glossary":[{"term":"运行时状态","meaning":"程序运行过程中维护的当前数据，通常在内存中。"},{"term":"持久来源","meaning":"下一次启动仍可读取的数据位置，范围和可靠性需实际验证。"},{"term":"初始化","meaning":"页面开始运行时建立变量、读取数据和呈现初始界面的过程。"}],"predict":{"question":"tasks初始只有A，运行时加B，只改数组和DOM，没有写存储。刷新后更合理的预测是？","options":[{"text":"重新从初始化来源得到A","correct":true,"feedback":"没有持久写入和读取链路，B不会因显示过就留下。"},{"text":"HTML文件自动包含B","correct":false,"feedback":"DOM是当前运行的节点树，修改它不会自动写回编辑器中的HTML文件。"},{"text":"B会进入所有浏览器的任务列表","correct":false,"feedback":"没有共同服务或传输动作，当前标签内存无法把B发送到其他浏览器。"}]},"experiment":{"title":"同样显示两条任务，来源不同","brief":"两例都从任务A开始并添加B，只改变是否持久化及初始化覆盖条件。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"只有内存","input":"启动时tasks=[A]；添加B只push并render；没有存储API。","question":"刷新后应先查哪一个来源？","options":[{"text":"上次关闭时的DOM节点","correct":false,"feedback":"本例重新执行初始数组，旧DOM节点没有作为恢复来源保存下来。"},{"text":"远程数据库","correct":false,"feedback":"输入条件明确没有数据库链路，不能凭刷新行为假设有远程记录。"},{"text":"源码中的初始数组","correct":true,"feedback":"刷新建立新运行，会再次执行源码里的tasks=[A]而不是沿用旧变量。"}],"output":"教学推演：刷新回到A；编辑器文件也未因添加B发生变化，体现文件与运行状态的差别。","evidence":["源码差异为空","刷新前后数组条数与ID"]},{"name":"读取后又被示例覆盖","input":"存储有效含A、B；代码先读取到tasks，后面又执行tasks=[A]并render。","question":"存储读取成功之后，为何B仍没有显示在列表？","options":[{"text":"render一定把B永久删除","correct":false,"feedback":"读取后明确又执行tasks=[A]，先查这次覆盖而不是猜render删除了B。"},{"text":"恢复值被后续初始化覆盖","correct":true,"feedback":"读到了不等于最终使用了，应追踪后续赋值。"},{"text":"存储一定已经丢失B","correct":false,"feedback":"页面少一条也可能是初始化覆盖，需直接核对存储原文是否仍有B。"}],"output":"教学推演：存储仍含两条，最终内存只有A；删除无条件覆盖后再重载，才能使用恢复记录。","evidence":["读取后与render前的数组值","存储原始内容是否变化"]}]},"practice":{"intro":"以模块06的本地任务页副本为起点，只使用无敏感演示任务，先保存当前可恢复版本。本课目标：画出源码、内存、显示与保存来源的关系","steps":["在V1副本记录任务数据初始化、添加函数、render和存储读写位置；若尚无存储明确标无。","准备A任务，再加B并切换完成；分别观察文件差异、当前状态与页面，不做清空原记录的实验。","在专用演示副本仅保留内存方案，预测后刷新；再检查真实保存版是否有初始化覆盖。","用四个框和箭头说明哪里读、哪里写、刷新重新执行哪里，保留当前限制并恢复可用版本。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“画出源码、内存、显示与保存来源的关系”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在V1副本记录任务数据初始化、添加函数、render和存储读写位置；若尚无存储明确标无。；准备A任务，再加B并切换完成；分别观察文件差异、当前状态与页面，不做清空原记录的实验。；在专用演示副本仅保留内存方案，预测后刷新；再检查真实保存版是否有初始化覆盖。；用四个框和箭头说明哪里读、哪里写、刷新重新执行哪里，保留当前限制并恢复可用版本。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["四处位置和读写方向说明","内存版刷新前后同一任务的结果","保存版初始化顺序检查及修复或无缺陷结论"],"troubleshooting":[{"symptom":"刚恢复又变回示例","check":"搜索恢复之后是否有无条件赋值或写示例","action":"移除错误覆盖，区分首次启动，再核对原存储未被抹去。"},{"symptom":"编辑器找不到新增标题","check":"检查是否只是运行时数据，并查看实际存储来源","action":"不要把用户任务硬编码回HTML，先明确持久化要求。"}]},"checks":[{"question":"页面显示B，存储中没有B，应怎样描述？","options":[{"text":"当前显示成功，持久化尚未证实","correct":true,"feedback":"B出现在DOM只说明当前显示，是否持久化要另查目标键和恢复过程。"},{"text":"已保证刷新后仍有B","correct":false,"feedback":"没有写入持久来源，新初始化就没有证据可以恢复运行时新增的B。"},{"text":"浏览器源码已经被改写","correct":false,"feedback":"运行状态变化没有自动写回源码，需文件差异才能证明文件被修改。"}]},{"question":"读取函数返回两条，最终只显示一条，下一步是什么？","options":[{"text":"立刻重装浏览器","correct":false,"feedback":"读取、赋值和渲染均可在当前程序追踪，重装浏览器不能解释覆盖。"},{"text":"把读取函数再调用十次","correct":false,"feedback":"若后面仍覆盖数组或筛选隐藏，额外读取多次仍会得到同样错误结果。"},{"text":"追踪后续赋值、筛选与渲染输入","correct":true,"feedback":"成功读取之后还可能赋值覆盖、筛选或渲染错误，应继续沿数据流检查。"}]}],"sources":[{"label":"MDN：DOM与动态内容","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/DOM_scripting","checked":"2026-10-16"},{"label":"MDN：localStorage","url":"https://developer.mozilla.org/en-US/docs/Web/API/Window/localStorage","checked":"2026-10-16"}]},{"id":"07.02","title":"浏览器存储与 JSON","lead":"任务数组不是字符串，为什么本地存储里却是一大段文字？写进去之后，程序还要怎样把它变回任务？","goals":["解释序列化、解析和数据校验的职责","完成同一来源下的写入与恢复，并说明当前浏览器保存的范围"],"sections":[{"title":"存储保存的是字符串","paragraphs":["localStorage是浏览器提供的按键读写的存储，值以字符串形式保存。任务数组里有对象、布尔值和文本，需要先转换成适合存储的表示。JSON.stringify把可表达的数据转成JSON文字，这个过程称为序列化；它不等于截图，也不保存函数的完整运行环境。","例如[{id:\"t1\",title:\"买牛奶\",done:false}]可变成JSON字符串。直接把普通数组传给setItem可能得到不符合预期的字符串形式，下一次无法按任务结构恢复。日期等对象也需要明确表示约定，不能认为所有JavaScript值都能无损经过JSON往返。"]},{"title":"写入和读取必须各自接通","paragraphs":["添加或修改成功后，程序把当前任务集合序列化并写到固定键；启动时从同一键取回文字，再JSON.parse成数据并验证结构，最后交给render。只有写没有读，刷新仍可能回到示例；只有读没有写，只能反复看到旧记录。","下面仅是基础往返片段，前提是tasks有效，且处于允许存储的同源HTTP页面；它没有异常处理和逐字段验证，下一课补齐。getItem返回null表示没有该键，和有效空数组的字符串\"[]\"应区别处理，不能把空数组误判为需要重新塞入示例。"],"code":"const key = \"task-demo:v1\";\nlocalStorage.setItem(key, JSON.stringify(tasks));\nconst raw = localStorage.getItem(key);\nconst restored = raw === null ? [] : JSON.parse(raw);\n// 验证 restored 的数组和字段结构后，再赋值与 render。"},{"title":"范围由来源与浏览器环境决定","paragraphs":["localStorage按来源划分，来源通常由协议、主机和端口共同决定。http与https、不同端口可能看到不同空间；另一个浏览器配置、另一设备也不自动共享。用稳定的本地HTTP地址验证，比把file地址行为当通用保证更可靠。","同源多个标签可能共享存储，但每个标签的内存状态仍可能不同；一个标签覆盖写入时，另一个标签不一定已经同步渲染。浏览器清理数据、隐私模式结束、配额或权限条件也会影响保留。本地保存适合单人练习，不应承诺永不丢失或多人一致。"]},{"title":"保存成功要通过重新读取证明","paragraphs":["验证时添加不同标题，改变done，记录ID；先看键里是否包含这些字段，再刷新、关闭重开并对照。只看“保存成功”提示不够，提示可能在setItem之前显示，或写错了键。字段必须一起恢复，不能标题在而完成状态重置。","此处只保存无敏感任务，不能把localStorage当秘密保险箱。它由同源页面脚本读取，仍有暴露与清理的边界。需要跨设备同步时，应进入模块08、09建立服务与数据库职责；那也还不等于权限隔离，身份规则在模块10完成。"]}],"glossary":[{"term":"序列化","meaning":"把结构化数据转成可存储或传输的文字表示，如JSON。"},{"term":"解析","meaning":"按JSON格式把文字还原成数据值，不自动证明字段有效。"},{"term":"来源","meaning":"浏览器用于区分存储等边界的协议、主机和端口组合。"}],"predict":{"question":"添加后setItem写成功，刷新仍显示旧示例，最该检查什么？","options":[{"text":"让每条任务都使用同一个ID","correct":false,"feedback":"共用ID会破坏任务身份，无法让缺失的初始化读取自动出现。"},{"text":"启动是否读取同一键并使用恢复数据","correct":true,"feedback":"setItem完成只证明写入，启动仍要getItem、解析、校验并用于render。"},{"text":"只把成功提示保留更久","correct":false,"feedback":"成功提示停留更久也不会改变启动时读取旧示例的程序顺序。"}]},"experiment":{"title":"写入范围与恢复条件","brief":"两例使用同样JSON任务，只改变读取逻辑与访问来源。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"写了没有读","input":"页面在添加后写task-demo:v1；启动仍写死tasks=[]。","question":"只写入不读取的页面，刷新后空列表说明什么？","options":[{"text":"恢复链路缺失，需先核对原存储","correct":true,"feedback":"存储可能已有有效JSON，只是启动没有读取，需直接查看目标键。"},{"text":"JSON不支持数组","correct":false,"feedback":"JSON允许数组和对象，本例问题是恢复链路缺失而不是格式能力不足。"},{"text":"浏览器必然清除了所有键","correct":false,"feedback":"启动空列表也可能是代码写死数组，未查看键不能断言浏览器清空。"}],"output":"教学推演：存储中仍有记录，接上读取、解析、验证与render后恢复；不需重填全部任务。","evidence":["键中原文","启动函数读取路径"]},{"name":"换端口访问","input":"同一电脑同一浏览器，从http://localhost:4100改到http://localhost:4200，新页面没有任务。","question":"同一浏览器换端口后列表为空，首先如何解释？","options":[{"text":"任务已经自动搬到云端","correct":false,"feedback":"更换端口没有增加同步服务，数据不会自动搬到远程或另一来源。"},{"text":"一定是JSON.parse删掉了数据","correct":false,"feedback":"端口变化可能进入独立存储空间，应先核对来源而不是猜解析删数据。"},{"text":"不同来源可能有独立存储，应查看各自键","correct":true,"feedback":"来源包含端口，4100与4200可能拥有独立的localStorage记录。"}],"output":"教学推演：4100下记录仍在，4200没有同一键；恢复原地址后可读到，属于范围不同而非同步失败。","evidence":["两地址完整来源","各自存储键与任务ID"]}]},"practice":{"intro":"以模块06的本地任务页副本为起点，只使用无敏感演示任务，先保存当前可恢复版本。本课目标：实现任务与完成状态的本地JSON往返","steps":["以稳定HTTP地址运行副本，确定专用存储键，记录原数据备份；不要清理真实项目键。","添加时序列化有效数组写入，启动时读取同一键；无记录、有效空数组和解析失败分开处理。","用两条任务、不同done和稳定ID检查存储原文，再刷新和关闭重开，对照字段。","在另一个测试端口或独立浏览器查看范围差异，回原来源确认原记录；把限制写进说明。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“实现任务与完成状态的本地JSON往返”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：以稳定HTTP地址运行副本，确定专用存储键，记录原数据备份；不要清理真实项目键。；添加时序列化有效数组写入，启动时读取同一键；无记录、有效空数组和解析失败分开处理。；用两条任务、不同done和稳定ID检查存储原文，再刷新和关闭重开，对照字段。；在另一个测试端口或独立浏览器查看范围差异，回原来源确认原记录；把限制写进说明。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["写入与读取位置、键名和实际访问来源","刷新及关闭重开后的ID、标题与done对照","独立来源没有自动同步的结果和保留边界说明"],"troubleshooting":[{"symptom":"标题恢复但done全变false","check":"检查序列化字段与恢复时默认值是否覆盖","action":"保留合法布尔值，只为真正缺失字段按版本规则补缺省。"},{"symptom":"换地址任务消失","check":"核对协议、主机、端口和浏览器配置","action":"回原来源检查，不要在未确认前清空或覆盖数据。"}]},"checks":[{"question":"JSON.parse成功返回{hello:1}，能当任务数组吗？","options":[{"text":"再stringify一次就会变数组","correct":false,"feedback":"再次序列化只改变数据表示，不会把hello对象补成合法任务数组。"},{"text":"不能，语法正确还需结构与字段校验","correct":true,"feedback":"JSON.parse接受合法对象，但应用仍需检查它是不是任务数组和有效字段。"},{"text":"能，合法JSON就是合法任务数据","correct":false,"feedback":"合法JSON可以是数字或任意对象，不能直接替代任务字段与类型校验。"}]},{"question":"另一台手机打开同一静态页面为空，说明什么？","options":[{"text":"本地存储没有提供跨设备同步","correct":true,"feedback":"手机与电脑各有浏览器存储，静态文件相同不会自动传输任务记录。"},{"text":"手机一定不支持JavaScript","correct":false,"feedback":"手机可能正常运行并读取了自己的空存储，需用脚本证据判断支持情况。"},{"text":"只要把键名改成一样就会共享","correct":false,"feedback":"相同键只在各自存储空间中定位，不会把不同设备的空间连接起来。"}]}],"sources":[{"label":"MDN：localStorage范围与行为","url":"https://developer.mozilla.org/en-US/docs/Web/API/Window/localStorage","checked":"2026-10-16"},{"label":"MDN：JSON.parse","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/JSON/parse","checked":"2026-10-16"}]},{"id":"07.03","title":"数据异常、导出与恢复","lead":"旧记录少了字段，导入文件里混入错误值，或者浏览器拒绝写入，页面怎样继续可用又不悄悄毁掉数据？","goals":["区分解析失败、结构不合法与存储不可用","在副本完成导出、校验、导入和恢复，保护有效原记录"],"sections":[{"title":"读取失败不只有一种原因","paragraphs":["存储文字可能不是合法JSON，也可能能解析却不是数组，还可能数组里某条done是字符串\"false\"。这三种情况影响不同，不能只在JSON.parse外加catch就说数据安全。解析检查格式，业务校验再检查字段类型、ID唯一性和允许范围。","例如字符串\"false\"在JavaScript条件中仍是真值，若直接转布尔值可能被误当完成。旧版本缺少done也不等于恶意数据，应依据版本约定迁移为false，保留原记录并报告数量。对无法解释的字段不随意猜，先隔离原文或要求用户选择恢复方案。"]},{"title":"存储失败时应用要诚实降级","paragraphs":["读取和写入都可能抛出错误，原因包括浏览器策略或空间条件。写失败不一定要求整页停止，可以继续提供当前内存操作，但必须明确“本次未持久保存，关闭可能丢失”，并提供导出或重试入口。成功提示只能在确认写入后出现。","若程序一遇到异常就先清空整个localStorage，会影响其他数据且失去诊断依据。合理做法是只处理自己的专用键，保护失败原文，避免启动后用空数组无提示覆盖。所谓降级不是伪装一切正常，而是让使用者知道哪些能力仍有、哪些保证已失效。"]},{"title":"导出和导入是一条有规则的通道","paragraphs":["导出可把版本号与任务数组写成JSON文件，供用户保存；导入先读取文件为数据，解析、校验并预览条数和可能冲突，再选择覆盖或合并。覆盖前保留当前副本，合并要定义ID冲突策略，不能只把两个数组连接后忽略重复身份。","导入内容必须作为文本与数据使用，不能eval，也不能把标题拼成HTML执行。文件扩展名是.json并不证明结构有效或内容可信；一个正常标题可以含尖括号，仍应按文字显示。恢复成功的标准是应用能按预期操作，而不是下载到了一个文件就算备份有效。"]},{"title":"在副本做破坏性条件演练","paragraphs":["练习使用专用键和演示文件：一份正常导出、一份截断JSON、一份类型错误、一份旧结构。每次先预测结果，再检查提示、内存、原存储和页面。对不合法导入，应拒绝并保持当前有效任务；对支持迁移的旧结构，应报告补了哪些字段。","恢复后核对ID、标题、完成值与条数，再添加、编辑和刷新。把失败情况与恢复步骤记下来，才能在真实问题中选择小范围处理。课程网站的预制案例不会真的修改你的存储；只有自己的独立副本验证才构成实操证据，不能把阅读推演当完成恢复。"]}],"glossary":[{"term":"结构校验","meaning":"确认数据形状、字段类型和业务规则，而不只看JSON能否解析。"},{"term":"降级","meaning":"某项能力失效时保留可用部分，并明确告知损失的保证。"},{"term":"迁移","meaning":"按明确旧新结构规则转换数据，需保护原记录并核对结果。"}],"predict":{"question":"导入JSON语法正确，但done为字符串\"false\"，应该怎样处理？","options":[{"text":"用Boolean(\"false\")得到false后继续","correct":false,"feedback":"Boolean把非空字符串视为true，所以字符串false会被错误当成已完成。"},{"text":"只要文件名以.json结尾就通过","correct":false,"feedback":"文件叫JSON也可能含错误类型，仍需解析后逐条核对done等字段。"},{"text":"按结构规则拒绝或执行明确版本迁移，不能直接信任","correct":true,"feedback":"字符串和布尔值含义不同，随意转换可能误判。"}]},"experiment":{"title":"损坏与不可保存的两种异常","brief":"比较输入不合法与写入失败，判断何时保持原数据、何时提示内存降级。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"导入被截断","input":"当前有t1和t2；导入文件只有[{\"id\":\"t3\"，缺少后续字符。","question":"按取消而非保存之后，合理的数据结果是什么？","options":[{"text":"把残缺内容当HTML显示并运行","correct":false,"feedback":"任务导入应解析和校验数据，执行文件文字会越过内容与程序的边界。"},{"text":"报告解析失败，当前t1和t2保持","correct":true,"feedback":"完整验证前不替换现有数组，才能让一次失败导入保持t1和t2不变。"},{"text":"先清空任务再报错","correct":false,"feedback":"先清空再解析失败会丢掉原有效任务，导入流程应在验证后才替换。"}],"output":"教学推演：解析失败时拒绝该文件，不覆盖原专用存储；t1、t2仍可操作，用户可重新选择完整导出文件。","evidence":["导入前后ID集合一致","错误明确指向文件格式"]},{"name":"写入被拒绝","input":"添加t3成功进入内存并显示，但专用存储setItem抛错；原存储仍只有t1、t2。","question":"t3仅在内存中且写入失败，应向用户说明什么？","options":[{"text":"当前可继续，但t3未持久保存，提供导出或重试","correct":true,"feedback":"t3已在内存显示却未写入，应明确告诉用户并提供导出或重试。"},{"text":"显示已保存，因为页面有t3","correct":false,"feedback":"页面读取的是当前内存，即使显示t3，存储仍可能停在t1和t2。"},{"text":"无提示退回旧状态并丢掉用户输入","correct":false,"feedback":"无提示回退会丢掉尚可导出的t3，也让用户无法理解真实保存状态。"}],"output":"教学推演：保留当前任务并标出未保存状态，用户导出后在副本验证恢复；不要承诺刷新一定有t3。","evidence":["捕获到的真实错误类别","内存与存储差异及导出结果"]}]},"practice":{"intro":"以模块06的本地任务页副本为起点，只使用无敏感演示任务，先保存当前可恢复版本。本课目标：为本地任务实现可验证的数据恢复通道","steps":["备份副本并使用专用演示键，定义带版本号的导出结构与逐字段校验规则。","实现读取、解析、校验与写入的独立错误提示；失败不无提示覆盖有效原记录。","导入前预览条数并保留当前导出，选择明确的覆盖规则；标题通过文本方式显示，不执行内容。","用正常、截断、错误类型、旧结构文件检查拒绝或迁移；在副本模拟写入抛错，验证降级和导出，再恢复正常。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“为本地任务实现可验证的数据恢复通道”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：备份副本并使用专用演示键，定义带版本号的导出结构与逐字段校验规则。；实现读取、解析、校验与写入的独立错误提示；失败不无提示覆盖有效原记录。；导入前预览条数并保留当前导出，选择明确的覆盖规则；标题通过文本方式显示，不执行内容。；用正常、截断、错误类型、旧结构文件检查拒绝或迁移；在副本模拟写入抛错，验证降级和导出，再恢复正常。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["导出文件的版本、条数与字段说明","四种导入的预期和实际，以及有效原任务未丢失证据","存储失败提示、内存继续使用与恢复后操作及刷新结果"],"troubleshooting":[{"symptom":"坏文件导入后旧任务也没了","check":"检查是否在验证前清空数组或写空存储","action":"从已留副本恢复，改为全部校验通过后才替换。"},{"symptom":"恢复后完成值反了","check":"检查旧结构迁移与字符串布尔值转换","action":"按版本逐项映射，不用任意真假转换，重跑原文件。"}]},"checks":[{"question":"下载出一个JSON文件能否证明备份有效？","options":[{"text":"能，只要文件大小不是零","correct":false,"feedback":"非零文件也可能截断或缺少任务字段，需要实际恢复和操作验证。"},{"text":"改扩展名为txt后就有效","correct":false,"feedback":"把扩展名改成txt不会补全缺失内容，也无法证明恢复后业务可用。"},{"text":"不能，还要在独立副本恢复并核对操作","correct":true,"feedback":"下载证明文件生成，独立副本能恢复字段并正常操作才支持备份有效。"}]},{"question":"存储失败但内存可用，最恰当反馈是？","options":[{"text":"立刻删除所有浏览器数据","correct":false,"feedback":"清理整个浏览器范围超过当前键，还可能删除原记录与其他应用数据。"},{"text":"说明未持久保存并提供保留内容的方法","correct":true,"feedback":"说明未持久保存，用户才知道关闭风险，并能及时导出当前有效内容。"},{"text":"隐藏错误避免困扰","correct":false,"feedback":"隐藏写失败会让用户误信已保存，刷新后丢失新增内容却无准备。"}]}],"sources":[{"label":"MDN：JSON解析与语法错误","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/JSON/parse","checked":"2026-10-16"},{"label":"MDN：localStorage异常与范围","url":"https://developer.mozilla.org/en-US/docs/Web/API/Window/localStorage","checked":"2026-10-16"}]},{"id":"07.04","title":"从本地工具提出联网需求","lead":"电脑上的V1已经可用，手机却没有任务。把网页发给朋友，是不是就能同步，还能让每个人只看自己的数据？","goals":["完整验收本地V1并说明存储边界","把跨设备、多人和网络失败转成新的架构与验收要求"],"sections":[{"title":"先确认本地成果确实成立","paragraphs":["进入联网之前，先验收本地添加、编辑、删除、完成、筛选、刷新与异常恢复。否则把一个尚有本地缺陷的页面接上服务，只会让错误来源更多。V1是独立有收益的小工具，应有运行说明、专用存储范围和一个能返回的版本。","例如同名任务分别修改、空输入提示、长标题显示、坏导入拒绝，都属于本地能力。若这些通过，就能明确下一步新增什么，而不是把联网视为重新做全部功能。自检勾选只记录自己的检查，不代表课程已经远程验证了你的项目。"]},{"title":"网页可访问与共享数据是两件事","paragraphs":["把HTML放到别人能打开的位置，只说明资源可以获得；每个人的localStorage仍在各自浏览器。共享数据需要一个双方能访问的服务，按接口读写共同数据来源。浏览器不应直接把自己的内存当作所有设备的共同真相。","手机同步可写成“电脑新建t1后，手机经服务重新读取能看到同一ID与字段”。这比“支持同步”更可验收。但同一数据来源也带来冲突：两设备先后编辑同一标题，保留谁、是否提醒，都需要明确规则，不能把接通网络当成自动一致。"]},{"title":"新的职责分工带来新风险","paragraphs":["前端负责输入与显示，后端接收请求并执行规则，数据库负责持久组织数据。模块08先用明确标注的临时开发数据建立请求链路，模块09再接持久数据库。每个阶段都需说明重启后会发生什么，不能把后端内存叫可靠保存。","多人使用还要识别请求者并判断能操作哪些记录，这是模块10的身份与权限。仅给任务加user_id或在页面隐藏别人的条目，都不能证明隔离。当前可以列出需求与拒绝路径，但在没有实际权限验收前，联网V2只应在开发测试范围使用。"]},{"title":"网络让结果多了等待与不确定","paragraphs":["本地函数通常能马上得到结果，远程请求可能慢、失败或已写入却未收到响应。界面因此要区分等待、确认成功、明确失败和结果待核对。连续重试创建可能产生重复任务，后端规则与请求策略要共同处理，不能只靠按钮颜色。","把新增条件写成检查场景：断开服务时列表不伪装成空；提交失败保留草稿；换设备能读取同一条记录；不同用户的拒绝路径后续有证据。先有这些条件，再选实现办法。此课只完成需求桥接，不宣称课程页面已经为你创建后端、账号或线上资源。"]}],"glossary":[{"term":"同步","meaning":"不同设备通过约定机制获取并更新共同数据，不等于复制页面文件。"},{"term":"前后端分工","meaning":"前端处理界面，后端接收请求、执行规则并访问服务资源。"},{"term":"数据隔离","meaning":"让每个请求只能按规则接触允许的数据，需要可信身份与权限检查。"}],"predict":{"question":"把静态任务页发给朋友后，他看不到你本地的任务，首先说明什么？","options":[{"text":"页面文件共享没有共享浏览器存储","correct":true,"feedback":"数据仍在各自环境，需服务与共同持久来源。"},{"text":"文件发送不完整所以一定坏了","correct":false,"feedback":"朋友的浏览器没有你的任务记录，即使页面文件完整也可能正常为空。"},{"text":"只需给任务加朋友姓名就完成同步与隔离","correct":false,"feedback":"朋友姓名只是数据值，不会建立同步链路，也不能限制他人请求。"}]},"experiment":{"title":"同一网页，不同数据要求","brief":"对比复制本地页面与共用测试接口，明确新增能力及尚未具备的保障。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"复制页面到手机","input":"电脑在localStorage存有t1；手机打开相同HTML，无后端与导入。","question":"手机没有导入或服务，最合理的任务列表结果是什么？","options":[{"text":"t1通过相同文件名自动传输","correct":false,"feedback":"相同HTML文件名只标识页面，不会把电脑localStorage传到手机。"},{"text":"电脑任务必然被手机覆盖","correct":false,"feedback":"电脑与手机各自存储且没有服务，两者不能凭打开相同文件互相覆盖。"},{"text":"手机按自己的存储初始化，未自动获得t1","correct":true,"feedback":"静态源码不包含电脑运行后新增的存储。"}],"output":"教学推演：两端可独立使用，但列表不同；可以通过手动导出导入转移，仍不是持续同步。","evidence":["两端来源和存储记录","是否实际存在数据传输动作"]},{"name":"共用无身份测试接口","input":"两浏览器都向本机开发服务读取同一组演示任务，没有身份识别与授权。","question":"两端共用无身份测试接口，现在能诚实声称什么？","options":[{"text":"因为经过HTTP，所以数据一定永久保存","correct":false,"feedback":"HTTP说明通信方式，数据若留在服务数组中仍可能在进程重启后丢失。"},{"text":"共用读取链路可测试，用户隔离未完成","correct":true,"feedback":"共同来源解决一部分联通问题，不证明谁有权访问。"},{"text":"只要数据含user_id就已安全隔离","correct":false,"feedback":"user_id表达记录归属，但仍需可信身份与查询写入规则才能限制访问。"}],"output":"教学推演：两端能读到相同任务，但还需验证数据库持久化与后续身份权限；不面向真实多人开放。","evidence":["请求目标与返回的相同ID","服务数据来源及未完成权限说明"]}]},"practice":{"intro":"以模块06的本地任务页副本为起点，只使用无敏感演示任务，先保存当前可恢复版本。本课目标：完成V1验收并写出联网版新增条件","steps":["保留本地V1可恢复版本，按添加、编辑、取消、删除、完成、筛选、刷新、导出导入重跑清单。","在独立浏览器或手机打开相同页面，记录哪些数据没有同步，说明localStorage范围。","画出前端—后端—数据库三个职责，标出模块08临时数据和模块09持久化的阶段差别。","写出跨设备读取、服务失败、提交重试、用户隔离至少四类验收；隔离只列需求，留模块10实际验证。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“完成V1验收并写出联网版新增条件”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：保留本地V1可恢复版本，按添加、编辑、取消、删除、完成、筛选、刷新、导出导入重跑清单。；在独立浏览器或手机打开相同页面，记录哪些数据没有同步，说明localStorage范围。；画出前端—后端—数据库三个职责，标出模块08临时数据和模块09持久化的阶段差别。；写出跨设备读取、服务失败、提交重试、用户隔离至少四类验收；隔离只列需求，留模块10实际验证。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["V1运行入口、版本与完整本地检查记录","两设备或独立环境的数据差异说明","联网职责图、四类新增验收与尚未具备的保障"],"troubleshooting":[{"symptom":"准备联网时本地取消编辑仍丢字","check":"先检查V1草稿与正式状态是否分离","action":"回06.05修复并重跑本地验收，再增加网络变量。"},{"symptom":"朋友打开localhost无法访问我的服务","check":"核对localhost指的是访问设备本身","action":"先在本机完成开发联调，部署到其他设备可达地址在模块11处理。"}]},"checks":[{"question":"任务表已有user_id，能否作为允许多人试用的依据？","options":[{"text":"不能，还需可信身份与每条读写的授权验收","correct":true,"feedback":"记录带user_id不证明请求被验证，必须实际检查他人读写被拒绝。"},{"text":"可以，数据库会自动识别浏览器用户","correct":false,"feedback":"数据库字段名不能识别浏览器用户，后端仍需可信身份来源与授权规则。"},{"text":"只需把他人任务CSS隐藏","correct":false,"feedback":"CSS只改变展示，用户仍可能直接发送他人ID，后端必须独立拒绝。"}]},{"question":"服务断开时，前端把错误变成空数组，问题是什么？","options":[{"text":"能减少界面复杂度所以已满足要求","correct":false,"feedback":"读取失败伪装为空会误导用户以为没有记录，反馈必须区分两种事实。"},{"text":"说明数据库真的已经清空","correct":false,"feedback":"未收到成功响应只能说明读取未完成，不能据此判断数据库已清空。"},{"text":"把读取失败伪装成真实空列表","correct":true,"feedback":"用户会误以为记录不存在，应区分状态。"}]}],"sources":[{"label":"MDN：客户端与服务端概览","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Client-Server_overview","checked":"2026-10-16"},{"label":"MDN：localStorage","url":"https://developer.mozilla.org/en-US/docs/Web/API/Window/localStorage","checked":"2026-10-16"}]},{"id":"08.01","title":"一次点击怎样变成网络请求","lead":"按了“刷新任务”，列表没变。请求没有发出去、服务拒绝了，还是返回的数据没有显示？先跟踪一次完整往返。","goals":["读出URL、方法、请求体、响应与状态码的含义","把一次界面动作与网络证据匹配，区分发送、响应和显示问题"],"sections":[{"title":"点击只是开始，不一定发请求","paragraphs":["浏览器收到点击事件后，处理函数可以只改本地状态，也可以调用fetch发出HTTP请求。HTTP是客户端与服务交换消息的协议。没有请求记录时，先查事件、分支与脚本错误；不能因为按钮写着刷新就认定已经联系后端。","例如列表页启动时请求GET /api/tasks，点击本地“只看未完成”可以直接过滤已有数组而不发请求。两种设计都可能成立，关键是先写清数据来源。开发者工具网络面板要在操作前打开，并用路径、时刻和发起者匹配具体动作，避免误认另一条资源加载。"]},{"title":"地址、方法与内容一起表达意图","paragraphs":["URL指出访问的主机、端口和资源路径，方法表达操作意图，查询参数常用于筛选，请求体可携带创建或修改数据。读取通常用GET；创建通常用POST；本课程约定PATCH修改已有任务，DELETE删除。方法名称本身不会替后端执行业务，服务必须实现对应路由。","例如POST /api/tasks携带{\"title\":\"买牛奶\"}，不同于GET /api/tasks?done=false。前者可能产生新记录，后者读取筛选结果。不要用标题拼出任意路径或把全部操作混成同一个无说明请求；清楚约定能让前后端各自实现而仍相互理解。"]},{"title":"响应成功与业务正确仍要核对","paragraphs":["响应包括状态、头和可选正文。200常用于成功读取，201可表示创建，400可用于输入不合法，404可用于资源不存在，500表示服务端错误。它们提供判断入口，但具体错误正文仍要依接口约定解释。一个200响应也可能字段错误，不能只看绿色状态。","fetch得到HTTP 404时通常仍会返回Response，不会仅因为状态是404就进入catch；程序要检查response.ok或status，再按约定解析正文。若响应不是JSON而是HTML，盲目调用json也会失败。这是HTTP层与正文解析层两个问题，日志应说明分别发生在哪里。"]},{"title":"沿三段证据避免跳结论","paragraphs":["把动作拆为发送前、响应后与显示后：发送前有事件和请求参数；响应后有状态及正文；显示后有前端数组与DOM。响应含t1而页面没有，优先查解析、赋值、筛选与render；没有响应，则保留服务地址和网络错误再查服务。","本课用无身份的本机开发请求，不代表已实现登录、隔离或线上可用。网站里的案例是教学推演；独立实践要在自己的开发工具看到真实请求并记录。涉及私人数据的请求体无需完整上传，只保留能说明结构与错误的演示片段。"]}],"glossary":[{"term":"HTTP请求","meaning":"客户端发给服务的消息，由目标地址、方法、头和可选内容构成。"},{"term":"响应","meaning":"服务对请求的返回消息，含状态与可能的正文。"},{"term":"状态码","meaning":"响应中对结果类别的数字说明，不能单独证明业务数据正确。"}],"predict":{"question":"网络面板显示GET /api/tasks返回200且有t1，页面仍空。下一步优先查哪里？","options":[{"text":"响应解析到状态与render的链路","correct":true,"feedback":"请求已有成功响应，应继续查字段、赋值和筛选是否正确。"},{"text":"反复启动服务直到列表出现","correct":false,"feedback":"服务已回数据，重启没有针对显示链路的因果依据。"},{"text":"把200改成201以触发显示","correct":false,"feedback":"状态码不是页面更新信号，render仍需读取正确数据。"}]},"experiment":{"title":"请求是否发出，返回是否使用","brief":"以读取任务为同一目标，比较没有发送与响应后显示失败。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"事件被空分支截住","input":"点击刷新后无/api/tasks请求；入口日志出现，代码if(!ready)return，ready始终false。","question":"最早未达成的是哪一个环节？","options":[{"text":"数据库查询返回了空列表","correct":false,"feedback":"本例还没有发请求，不能推断数据库的查询结果。"},{"text":"200正文解析失败","correct":false,"feedback":"本例没有发出请求，也没有得到响应，尚未到解析200正文这一环节。"},{"text":"发送前的条件决定阻止了fetch","correct":true,"feedback":"事件进入不等于网络发送，应查ready为何未达到约定。"}],"output":"教学推演：修正初始化条件后出现真实GET请求；再核对响应和显示，不能只因有请求就宣布完成。","evidence":["请求出现前后的网络记录","ready值与分支执行位置"]},{"name":"返回字段没被使用","input":"GET返回200和{\"tasks\":[{\"id\":\"t1\",\"title\":\"买牛奶\",\"done\":false}]}；前端却读取data.items。","question":"最直接的修复依据是什么？","options":[{"text":"认为没有任务并创建一条同名任务","correct":false,"feedback":"已有返回记录，盲目创建会掩盖显示缺陷或制造重复。"},{"text":"统一响应字段并检查渲染输入","correct":true,"feedback":"tasks与items不一致使前端读错位置，需按接口约定修正。"},{"text":"将请求改成DELETE重新读取","correct":false,"feedback":"方法会改变操作含义，不能修复返回字段不一致。"}],"output":"教学推演：读取data.tasks并验证数组后，t1进入状态并显示；接口与页面ID可以逐项对应。","evidence":["原响应字段和前端读取位置","修后状态与显示的t1"]}]},"practice":{"intro":"以模块07的V1副本为起点，在本机开发测试环境操作，不公开服务；先记录当前可恢复版本与启动方法。本课目标：在网络面板追踪一次真实任务读取","steps":["让Codex确认本机练习服务地址与GET /api/tasks约定；尚无服务时先进入08.02准备，不将推演当请求。","打开网络面板，触发一次刷新任务，记录URL、方法、状态、响应正文与发起时刻。","在副本用错误路径复现404并检查response.ok处理，再恢复正确路径。","对照响应中的任务ID、前端状态与页面显示，写明成功读取、失败和空列表的不同证据。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“在网络面板追踪一次真实任务读取”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：让Codex确认本机练习服务地址与GET /api/tasks约定；尚无服务时先进入08.02准备，不将推演当请求。；打开网络面板，触发一次刷新任务，记录URL、方法、状态、响应正文与发起时刻。；在副本用错误路径复现404并检查response.ok处理，再恢复正确路径。；对照响应中的任务ID、前端状态与页面显示，写明成功读取、失败和空列表的不同证据。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["真实请求的目标、方法、状态与匿名化正文","一个ID从响应到前端状态和显示的对照","错误路径复现、错误反馈及恢复同一操作的结果"],"troubleshooting":[{"symptom":"面板里没有接口请求","check":"核对面板筛选和事件分支，查看fetch调用前日志","action":"确认是真未发送还是记录被隐藏，再修最早中断处。"},{"symptom":"catch没捕获404","check":"核对是否显式检查Response.ok","action":"对非成功HTTP状态建立错误分支，保留正文中的有关说明。"}]},"checks":[{"question":"接口200但返回HTML欢迎页，能否当任务读取成功？","options":[{"text":"不能，正文类型与任务结构仍需验证","correct":true,"feedback":"HTTP成功不保证返回的是约定的JSON任务列表。"},{"text":"可以，200意味着业务字段一定齐全","correct":false,"feedback":"状态类别没有验证正文里的具体业务字段。"},{"text":"把HTML字符串直接当数组渲染","correct":false,"feedback":"字符串不等于任务数组，也可能被误当页面结构。"}]},{"question":"点击本地筛选没有新请求，是否一定有错误？","options":[{"text":"一定错误，所有点击都必须联网","correct":false,"feedback":"很多界面操作可以只处理已有的前端状态。"},{"text":"说明服务已删除任务","correct":false,"feedback":"本地筛选未发送请求，不能据此推断服务记录被删除或发生任何写入。"},{"text":"不一定，若约定本地过滤则可以正常","correct":true,"feedback":"先看设计是过滤已有数据还是请求服务重新查询。"}]}],"sources":[{"label":"MDN：HTTP方法","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Methods","checked":"2026-10-16"},{"label":"MDN：状态码","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status","checked":"2026-10-16"},{"label":"MDN：使用Fetch","url":"https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch","checked":"2026-10-16"}]},{"id":"08.02","title":"后端负责什么，在哪里运行","lead":"前端页面还开着，停止终端里的服务后却读取失败。服务器是那台电脑，还是正在运行的程序？","goals":["说明后端进程、端口、路由与资源访问的职责","真实启动和停止本机服务，并区分运行内存与数据库持久化"],"sections":[{"title":"后端是接收请求的程序","paragraphs":["“服务器”有时指提供服务的机器，有时指正在监听请求的程序。本课程关心后端程序：它在某个运行时执行，占用一个监听地址和端口，接收HTTP消息，匹配路径和方法，执行规则，再返回响应。文件存在不等于进程正在运行。","浏览器请求http://localhost:4100/api/tasks时，localhost指当前设备，4100用于找到对应监听服务。终端显示启动成功只是第一步，仍要真实访问接口。给朋友这个地址会指向朋友自己的设备，不能把本机联通说成公开部署，部署到可达环境留到模块11。"]},{"title":"后端让规则在请求入口执行","paragraphs":["前端输入检查帮助使用者及时纠错，后端检查则面对所有到达的请求，包括绕过页面发来的内容。后端还可以访问数据库或受控资源，并把结果转换成接口格式。浏览器不应直接持有所有服务端资源的秘密配置。","本模块先处理无身份的开发数据，后端会校验标题、类型与ID；但知道请求合法格式不等于知道谁有权操作，身份和授权留模块10验收。不要把“数据经过后端”自动说成安全隔离，后端只有实际写入并执行的规则才起作用。"]},{"title":"用最小服务看见进程与响应","paragraphs":["下面是完整Node CommonJS开发示例，可存为server.cjs后用node server.cjs运行；它只绑定127.0.0.1，提供固定演示列表，并对其他路径返回404。需先确认本机Node可执行，端口可用。它不提供静态页面、创建任务或数据库，不应把响应数组说成持久结果。","同一后端以后可以同时提供前端静态资源与API，使浏览器用相对路径访问，减少初学阶段的跨源变量。不要临时关闭浏览器安全策略来绕过连接问题。若已有项目服务，应先确认当前结构再加入路由，不要为了课程例子覆盖现有入口。"],"code":"const http = require(\"node:http\");\nconst server = http.createServer((req, res) => {\n  const ok = req.method === \"GET\" && req.url === \"/api/tasks\";\n  res.writeHead(ok ? 200 : 404, {\"Content-Type\":\"application/json; charset=utf-8\"});\n  res.end(JSON.stringify(ok\n    ? {tasks:[{id:\"t1\",title:\"演示任务\",done:false}]}\n    : {error:{code:\"NOT_FOUND\",message:\"接口不存在\"}}));\n});\nserver.listen(4100, \"127.0.0.1\", () => console.log(\"http://127.0.0.1:4100/api/tasks\"));"},{"title":"停止进程能揭示保存边界","paragraphs":["服务运行时可能把新增任务放在数组里，进程停止后这份内存就消失。重启又出现固定演示数据，是初始化行为，不是数据库自动恢复。模块09会把记录写入独立数据库，并用进程重启检验持久化来源。","练习时只停止自己刚启动的前台服务，例如在对应终端按Ctrl+C，不扫描或结束别人的进程。先读一次接口，再停止重试，最后重新启动并核对。页面旧内容仍在不说明服务还活着，必须发一次新请求，观察连接错误与服务输出是否对应。"]}],"glossary":[{"term":"进程","meaning":"一个正在执行的程序实例，停止后其内存状态通常不再保留。"},{"term":"监听","meaning":"服务在指定地址和端口等待连接或请求的状态。"},{"term":"路由","meaning":"按请求路径与方法选择处理逻辑的规则。"}],"predict":{"question":"停止后端进程后前端旧列表仍可见，此时能证明什么？","options":[{"text":"旧任务已自动进入永久数据库","correct":false,"feedback":"是否持久取决于写入来源，不取决于画面还在。"},{"text":"旧页面仍有状态，不能证明后端仍可接收新请求","correct":true,"feedback":"需重新读取并检查真实请求，区分缓存显示与服务存活。"},{"text":"后端会因页面存在自动重启","correct":false,"feedback":"页面存在本身不会让已停止的服务进程重新运行。"}]},"experiment":{"title":"同一地址在服务启停之间","brief":"比较服务停止与重启后的开发演示，明确联通和持久化边界。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"停止后再读取","input":"接口先成功返回固定t1；对应终端停止后，浏览器旧列表未清除，再点击读取。","question":"服务停止后，下一次读取应依据什么判断结果？","options":[{"text":"依据新请求失败提示，不能沿用旧成功状态","correct":true,"feedback":"旧列表不等于服务仍在，应保留旧内容并标出读取失败。"},{"text":"只要能看见t1就记作新读取成功","correct":false,"feedback":"t1来自上次成功状态，仅凭它还可见不能证明停止后的新请求成功。"},{"text":"刷新页面一定会启动后端","correct":false,"feedback":"浏览器刷新不会自动运行本机Node入口文件。"}],"output":"教学推演：新请求连接失败，前端说明未能更新；重新启动自己的服务后再请求可恢复联通。","evidence":["新请求的失败结果","同一服务终端的启停记录"]},{"name":"仅用服务数组保存","input":"开发后端初始[t1]；创建t2只放内存数组；停止再启动入口。","question":"t2应从哪里恢复，若没有持久写入会怎样？","options":[{"text":"从浏览器自动回写给所有客户端","correct":false,"feedback":"没有该传输协议就不能假设客户端补回服务数据。"},{"text":"从服务文件名自动生成原t2","correct":false,"feedback":"server.cjs文件名不会保存进程曾持有的t2，恢复需要独立持久来源。"},{"text":"没有持久来源时通常回到初始t1","correct":true,"feedback":"进程内存不是数据库，重启会重新执行初始化。"}],"output":"教学推演：重启后t2不再存在；案例只说明临时状态边界，模块09才验收独立持久数据库。","evidence":["新增后的数组","重启后的返回ID集合"]}]},"practice":{"intro":"以模块07的V1副本为起点，在本机开发测试环境操作，不公开服务；先记录当前可恢复版本与启动方法。本课目标：真实启停一个本机开发后端","steps":["在隔离副本确认Node版本与可用端口；可运行本课server.cjs或保留现有项目入口，记录完整启动命令。","访问127.0.0.1的GET /api/tasks，核对终端、监听地址、状态与JSON；未知路径应返回404。","只在对应终端停止自己启动的服务，再发新请求记录失败；重新启动后重试同一接口。","说明示例固定数组与运行内存不构成数据库；若已有新增功能，重启核对并记录当前持久限制。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“真实启停一个本机开发后端”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在隔离副本确认Node版本与可用端口；可运行本课server.cjs或保留现有项目入口，记录完整启动命令。；访问127.0.0.1的GET /api/tasks，核对终端、监听地址、状态与JSON；未知路径应返回404。；只在对应终端停止自己启动的服务，再发新请求记录失败；重新启动后重试同一接口。；说明示例固定数组与运行内存不构成数据库；若已有新增功能，重启核对并记录当前持久限制。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["实际入口文件、启动命令和监听地址","成功、停止失败与重新启动后的同一请求结果","数据究竟在固定代码、内存还是持久来源的说明"],"troubleshooting":[{"symptom":"启动提示端口被占用","check":"检查是否已经有自己启动的同一服务","action":"复用已知服务或选择新端口并同步前端地址，不盲目终止其他进程。"},{"symptom":"地址打开却404","check":"核对方法和路径是否是/api/tasks且访问同一端口","action":"访问约定接口；根路径没有页面不代表监听失败。"}]},"checks":[{"question":"server.cjs在目录里，但没有启动进程，接口应如何理解？","options":[{"text":"将文件改名为server.html即可运行","correct":false,"feedback":"扩展名更改不能替代Node执行与监听。"},{"text":"源码已准备，服务尚未运行","correct":true,"feedback":"入口文件准备好之后仍需用运行时启动，进程才能监听地址与端口。"},{"text":"只要浏览器能读目录就有后端","correct":false,"feedback":"静态目录访问和执行后端程序是不同操作。"}]},{"question":"后端校验了标题，能否说明两个用户数据已隔离？","options":[{"text":"不能，格式校验与身份授权是不同规则","correct":true,"feedback":"还需可信身份和每次数据访问的权限检查。"},{"text":"可以，经过后端的数据天然私有","correct":false,"feedback":"后端若未检查身份和归属，任何到达的请求都可能读取同一组任务。"},{"text":"只要端口随机就完成隔离","correct":false,"feedback":"随机端口只能改变连接位置，不能区分哪个用户有权读写某条记录。"}]}],"sources":[{"label":"Node.js：HTTP服务API","url":"https://nodejs.org/api/http.html","checked":"2026-10-16"},{"label":"MDN：客户端与服务端职责","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Client-Server_overview","checked":"2026-10-16"}]},{"id":"08.03","title":"先约定接口，再让两端实现","lead":"后端说“接口完成”，前端也说“接好了”，为什么一端发title，另一端却在等name？","goals":["制定方法、路径、字段、类型、成功与错误约定","用具体JSON检查列表、创建、更新、删除的两端一致性"],"sections":[{"title":"接口是双方共同使用的约定","paragraphs":["API可以理解为程序之间的操作入口和规则。对任务页而言，约定必须写明发到哪里、用什么方法、输入有哪些字段、类型是什么、成功和失败各返回什么。只写“做一个任务接口”会把关键决定留给两端各自猜测。","例如前端提交title，后端只读name，两边代码单独看都可能自洽，组合后却得到空标题。约定不是越长越好，能用一份请求和响应样例排除歧义最重要。把文档留在项目里，之后改字段就能检查影响范围。"]},{"title":"给四种操作明确入口","paragraphs":["本课采用GET /api/tasks读取，POST /api/tasks创建，PATCH /api/tasks/{id}部分更新，DELETE /api/tasks/{id}删除。列表返回{tasks:[]}，创建和更新返回{task:{...}}。删除采用204且无正文，前端不能再无条件调用json；也可选200带正文，但只能明确选一种。","路径里的ID表示目标记录，不能用显示行号替代。创建请求只给标题，ID与创建时间由后端决定；更新只允许明确字段，避免浏览器传什么就全部覆盖。这里的ID定位只回答“哪条任务”，不证明“谁有权改它”，授权会在模块10加入。"]},{"title":"类型与错误也需要协议","paragraphs":["done约定为JSON布尔值true或false，不能让字符串\"false\"、数字0与布尔值混用。错误统一形如{error:{code:\"INVALID_TITLE\",message:\"标题不能为空\"}}，状态按情况使用400、404或500，前端再把合适说明展示给使用者。","未知任务ID可以返回404，字段错误返回400；这些是本项目的选择，要写清而不是把任何错误都返回200。错误信息不能泄露服务器秘密或内部堆栈。把内部日志留给开发者，外部响应给出可理解且足够定位的代码与说明。"]},{"title":"约定变更要成对验证","paragraphs":["把接口文档当作可检查样例：先人工读一份，再让Codex实现两端，并在网络面板对照实际请求和响应。改title为name时，前端提交、后端验证、数据库映射和显示都可能受影响；不能只改文档就认为链路已同步。","最小合同不需要学习者背诵复杂规范，但至少含一条成功、一条无效输入、一条未知ID和删除无正文场景。模拟响应可以帮助开发前端，必须标注临时来源；真实联调时要换成实际服务证据，不能把预制成功数据留作验收依据。"]}],"glossary":[{"term":"接口约定","meaning":"两端共同遵守的方法、路径、输入、输出与失败规则。"},{"term":"请求体","meaning":"请求携带的内容，常用JSON表达创建或修改数据。"},{"term":"部分更新","meaning":"只改变允许提供的字段，其余字段保留原值。"}],"predict":{"question":"删除约定为204无正文，前端删除后仍调用response.json()报错，应该怎样修？","options":[{"text":"把所有删除都当失败并重新提交","correct":false,"feedback":"可能已删除，再提交不能解决空正文解析。"},{"text":"随机增加一个name字段","correct":false,"feedback":"请求字段无法补出服务已约定不返回的正文。"},{"text":"按204分支不解析空正文，并核对任务已删除","correct":true,"feedback":"错误发生在正文解析，需遵守无正文的删除约定。"}]},"experiment":{"title":"字段和正文规则不一致","brief":"比较创建字段不匹配与删除空正文，两种都可能被误叫“后端坏了”。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"标题字段不同名","input":"前端POST发送{\"title\":\"买牛奶\"}；后端校验body.name并返回400 INVALID_TITLE。","question":"该如何形成可验证的修复？","options":[{"text":"只把输入框标签改为name","correct":false,"feedback":"输入框可见标签改名不会自动修改发送代码中的JSON键，仍需统一合同。"},{"text":"按共同合同统一字段，再重发相同输入","correct":true,"feedback":"失败由两端字段不同造成，应固定名称和类型共同核对。"},{"text":"让前端忽略400并显示成功","correct":false,"feedback":"任务并未被确认创建，忽略响应会制造假成功。"}],"output":"教学推演：统一为title后创建返回201与稳定ID；前端再用该ID更新列表，而非仅显示成功文案。","evidence":["请求体字段和验证位置","修后创建响应与列表ID"]},{"name":"删除无响应正文","input":"服务按约定删除t2并返回204；前端调用json后出现解析错误。","question":"此时最准确的判断是什么？","options":[{"text":"删除可能已成功，先按约定处理并读取核对","correct":true,"feedback":"解析失败不能倒推服务未执行，需观察实际记录集合。"},{"text":"所有json解析错误都说明网络未发送","correct":false,"feedback":"请求和响应已存在，发送环节并未缺失。"},{"text":"重复创建t2再删除以消除报错","correct":false,"feedback":"增加无关写入会改变数据，不是修复解析条件。"}],"output":"教学推演：前端204分支结束解析，重新读取发现t2不存在；只改客户端处理，无需伪造响应正文。","evidence":["204状态与空正文","读取后t2不存在且其他ID保持"]}]},"practice":{"intro":"以模块07的V1副本为起点，在本机开发测试环境操作，不公开服务；先记录当前可恢复版本与启动方法。本课目标：为任务四类操作写并核对接口合同","steps":["在项目内建立简短接口说明，固定读取、创建、更新、删除的方法路径与状态；注明开发数据来源。","为每项写一份JSON样例，标出id、title、done类型；选择删除204无正文并写明前端分支。","列出400字段错误、404未知ID和500内部错误的统一结构，让Codex按合同连接两端。","真实发请求核对字段、类型、状态和正文，再在副本故意改错title字段观察失败，恢复合同后重跑。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“为任务四类操作写并核对接口合同”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在项目内建立简短接口说明，固定读取、创建、更新、删除的方法路径与状态；注明开发数据来源。；为每项写一份JSON样例，标出id、title、done类型；选择删除204无正文并写明前端分支。；列出400字段错误、404未知ID和500内部错误的统一结构，让Codex按合同连接两端。；真实发请求核对字段、类型、状态和正文，再在副本故意改错title字段观察失败，恢复合同后重跑。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["四项操作的合同和成功样例","字段错误、未知ID与204处理的实际结果","一处两端不一致的定位、修复与相同输入复验"],"troubleshooting":[{"symptom":"成功删除后仍弹失败","check":"核对状态是否204而代码仍解析JSON","action":"对无正文状态单独处理，再读取核对真实删除结果。"},{"symptom":"布尔值被当作字符串","check":"查看请求体原文及服务端类型检查","action":"统一JSON布尔值，不靠真假强制转换掩盖错误。"}]},"checks":[{"question":"请求携带title、done、admin:true，后端应怎样更新？","options":[{"text":"整体展开请求对象到数据库","correct":false,"feedback":"直接展开body可能把admin等未列入合同的字段也写入，需限制更新范围。"},{"text":"因为JSON合法就全部接受","correct":false,"feedback":"语法合法不保证业务字段与修改范围合法。"},{"text":"只接收合同允许字段，额外字段按规则拒绝或忽略","correct":true,"feedback":"不能把任意请求字段直接覆盖服务记录。"}]},{"question":"列表返回tasks，前端改读items但文档没改，应怎样处理？","options":[{"text":"清空数据库消除旧字段","correct":false,"feedback":"前端读错tasks字段是映射缺陷，删除数据库记录既无依据也不能修复读取代码。"},{"text":"以共同合同统一实际实现，并重跑读取检查","correct":true,"feedback":"字段改动要同时核对文档、服务响应和前端读取，并用真实请求复验。"},{"text":"仅给页面加一个等待动画","correct":false,"feedback":"等待动画只表达处理进度，不能使items自动对应实际返回的tasks。"}]}],"sources":[{"label":"MDN：HTTP方法","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Methods","checked":"2026-10-16"},{"label":"MDN：HTTP响应状态","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status","checked":"2026-10-16"}]},{"id":"08.04","title":"从后端读取任务","lead":"接口里已经有任务，页面却把“正在读取”“没有任务”和“读取失败”都显示成空白，使用者该相信哪一种？","goals":["把异步读取的结果接入前端状态和渲染","区分加载、成功空列表、成功有数据与失败，标明临时开发数据来源"],"sections":[{"title":"先固定服务端数据来源","paragraphs":["首次联调可让后端返回固定或内存演示任务，但要清楚写“开发测试数据，进程重启可能恢复初始值”。这样能先检查请求与显示，不把数据库问题同时引入。页面最终显示的任务应能由响应中的ID追溯，不能一边请求服务一边仍渲染旧本地数组冒充联通。","例如服务返回t8，localStorage只有t1，页面应按本课约定显示t8。若暂保留本地版本，必须明确切换来源与迁移策略，不要让两个数组都被不同函数更新。这里不需要马上删除旧备份，只要停止含糊地混用来源。"]},{"title":"加载状态表达尚未得到结论","paragraphs":["读取开始时设置loading，完成后才进入成功或失败。成功返回空数组表示当前查询没有记录，失败则表示不知道服务端实际有哪些任务。若catch直接把tasks=[]并显示“暂无任务”，会把证据不足说成确定为空。","可以保留上次成功列表，在错误区域说明“刷新失败，以下为上次结果”；首次加载失败则给出重试入口。空列表可以引导添加第一条，错误则指导检查连接。这些文字来自不同事实，需要独立状态，而不是用一个数组长度决定所有界面。"]},{"title":"等待响应，再校验再渲染","paragraphs":["fetch等待响应，response.ok判断HTTP成功，json等待正文解析，随后验证data.tasks是数组并检查关键字段，才赋给前端任务状态和render。每一步都可能失败，错误提示要尽量说明是连接、状态还是格式问题，而不泄露内部信息。","下面是读取核心流程，假设validateTasks、render与showError由项目提供，且loading在finally后重渲染；实际实现要在启动和重试入口调用它。此片段没有持久数据库或身份权限，不能把成功列表当成这些能力已经完成。"],"code":"async function loadTasks() {\n  loading = true; render();\n  try {\n    const response = await fetch(\"/api/tasks\");\n    if (!response.ok) throw new Error(\"读取失败：\" + response.status);\n    const data = await response.json();\n    tasks = validateTasks(data.tasks); // 返回合法数组，否则抛错\n  } catch (error) { showError(error.message); }\n  finally { loading = false; render(); }\n}"},{"title":"按条件验证而不是只看列表出现","paragraphs":["准备非空、空、格式错误、服务停止四种条件，记录每次请求和显示。非空要核对同一ID；空要确认确实收到成功空数组；格式错误不能使页面崩溃；服务恢复后同一重试应继续可用。用这些条件能证明读取链路如何处理变化。","若反复触发读取，还可能出现旧响应覆盖新响应，08.06会进一步讨论顺序。当前先允许一次读取或禁用重复刷新，把范围写清。代码里没数据库连接就不声称有数据库；教学页面中的预制结果也不能替代自己本机网络面板看到的请求。"]}],"glossary":[{"term":"加载状态","meaning":"请求正在进行且结果尚未确认的状态。"},{"term":"空结果","meaning":"一次成功查询没有匹配记录，与读取失败不同。"},{"term":"数据来源","meaning":"当前状态实际由哪份响应、存储或初始化值建立。"}],"predict":{"question":"服务停止，catch把tasks设为空并显示“还没有任务”，最关键的问题是什么？","options":[{"text":"把未知结果伪装成确认空列表","correct":true,"feedback":"读取失败无法证明服务中没有任务，应显示失败并保留重试。"},{"text":"空数组不能在JavaScript使用","correct":false,"feedback":"空数组本身合法，问题是它错误表达了请求结果。"},{"text":"只要界面没有报错就符合读取要求","correct":false,"feedback":"静默掩盖失败会误导用户，未满足真实状态反馈。"}]},"experiment":{"title":"空与失败需要不同反馈","brief":"同一读取入口分别得到成功空数组与503错误，预测界面应怎样变化。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"成功但没有记录","input":"GET /api/tasks返回200和{\"tasks\":[]}，格式有效，此前没有本地任务。","question":"该显示哪类结论与下一步？","options":[{"text":"读取失败，要求用户重装浏览器","correct":false,"feedback":"空列表是合法业务结果，并非环境错误。"},{"text":"自动创建三条示例当成用户任务","correct":false,"feedback":"这会改变真实数据，掩盖已确认的空状态。"},{"text":"成功空列表，提示可以添加第一条","correct":true,"feedback":"已得到有效响应，能确认本次查询没有记录。"}],"output":"教学推演：结束loading并显示空状态；网络记录保留200和空数组，用户可继续创建而不误以为断网。","evidence":["200与有效tasks空数组","空状态和添加入口"]},{"name":"服务失败保留旧列表","input":"上次读取有t1；再次GET返回503，前端仍有旧状态。","question":"已有旧列表而刷新返回503，哪种反馈最诚实？","options":[{"text":"立刻清空并提示没有任务","correct":false,"feedback":"503只能说明这次读取未成功，不能据此判断服务已经删除上次的t1。"},{"text":"提示刷新失败并标明仍显示上次数据","correct":true,"feedback":"旧列表可保留，但不能冒充本次成功读取。"},{"text":"显示“已同步最新”以免用户担心","correct":false,"feedback":"没有新成功响应，无法证明同步到最新。"}],"output":"教学推演：t1继续可见，错误说明未更新并提供重试；服务恢复后重新读取再取消过期提示。","evidence":["失败状态与旧数据标记","恢复后的同一读取成功"]}]},"practice":{"intro":"以模块07的V1副本为起点，在本机开发测试环境操作，不公开服务；先记录当前可恢复版本与启动方法。本课目标：把真实任务接口接入页面并区分四种读取状态","steps":["明确后端临时演示任务t8和前端数据来源，保留原本地导出，不无提示混合两套数组。","接入loadTasks流程，在请求前后分别维护loading、成功数据与错误，不用catch空数组伪装成功。","真实验证非空、空、返回格式错误与停止服务，分别保存请求结果和页面反馈。","重新启动服务后用重试恢复，确认返回ID进入前端状态再显示，写明进程内存的保存边界。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“把真实任务接口接入页面并区分四种读取状态”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：明确后端临时演示任务t8和前端数据来源，保留原本地导出，不无提示混合两套数组。；接入loadTasks流程，在请求前后分别维护loading、成功数据与错误，不用catch空数组伪装成功。；真实验证非空、空、返回格式错误与停止服务，分别保存请求结果和页面反馈。；重新启动服务后用重试恢复，确认返回ID进入前端状态再显示，写明进程内存的保存边界。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["响应ID到状态和页面的同一记录链路","四种条件的状态、正文和反馈对照","恢复重试结果与临时数据非持久的说明"],"troubleshooting":[{"symptom":"请求有t8页面仍显示t1","check":"检查render是否仍读取localStorage或旧数组","action":"统一当前数据来源并重跑，不先删除旧备份。"},{"symptom":"失败后一直显示加载中","check":"核对是否在所有结束分支释放loading","action":"用finally等可靠出口结束等待，并验证失败后能重试。"}]},"checks":[{"question":"收到200和{items:[]}，合同要求tasks，应该怎样显示？","options":[{"text":"按格式不符报错，不能视作成功空列表","correct":true,"feedback":"字段不一致意味着尚未获得合法任务结果。"},{"text":"把任何缺字段都改成空数组","correct":false,"feedback":"缺少tasks可能是合同被破坏，改为空数组会误导用户以为查询确认无记录。"},{"text":"将loading一直保留直到下次刷新","correct":false,"feedback":"格式错误应有明确结束状态和修复入口。"}]},{"question":"后端固定数组成功返回，能否说明记录跨重启保留？","options":[{"text":"能，因为数据是从后端来的","correct":false,"feedback":"后端也可能只使用进程内存或固定演示。"},{"text":"只要刷新前端两次就足够","correct":false,"feedback":"前端刷新未检验服务停止后的数据来源。"},{"text":"不能，要实际写持久来源并重启核对","correct":true,"feedback":"固定返回证明读取通信，不证明新增记录持久化。"}]}],"sources":[{"label":"MDN：使用Fetch API","url":"https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch","checked":"2026-10-16"},{"label":"MDN：客户端与服务端","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Client-Server_overview","checked":"2026-10-16"}]},{"id":"08.05","title":"把修改交给后端验证","lead":"页面已经拦住空标题，为什么直接发送一个请求仍能创建空任务？输入检查应该放在哪里？","goals":["在后端验证请求字段、类型、任务ID与允许修改范围","让前端根据真实响应更新状态，失败保留输入且不报假成功"],"sections":[{"title":"浏览器不是唯一请求入口","paragraphs":["页面的输入校验能帮助用户，但请求还可以从开发者工具或其他客户端发送，浏览器代码也能被修改。因此后端必须独立检查请求，不能相信“页面已经检查过”。有效格式只说明数据符合规则，仍不代表请求具有用户权限，本模块只做开发验证。","例如前端禁止空标题，后端POST仍要确认title是字符串、去首尾空白后非空且在上限内。不能先把任何值String化，因为对象会变成无意义的\"[object Object]\"；应先判断类型，再规范化，再检验长度。拒绝要返回明确状态与错误代码。"]},{"title":"目标ID和允许字段限制修改范围","paragraphs":["PATCH /api/tasks/t2先定位目标，再验证请求中明确允许的title或done。ID不存在返回404，不应自动创建；done必须是布尔值，不能把字符串\"false\"当作false。只更新提供且合法的字段，保留未修改的创建时间与稳定身份。","把整个body展开到任务对象可能让客户端覆盖id或其他内部字段，应采用白名单。归属与权限到模块10会加入，当前不接受浏览器自报某用户就当授权。记录验证顺序能帮助解释一个请求为何被拒绝，而不是只说“请求不行”。"]},{"title":"请求体也有读取与解析边界","paragraphs":["Node原生http收到请求体是分段数据，需要收集完成后按编码解析JSON；不能以为req.body天然存在。后端要限制接收大小、检查Content-Type、处理无效JSON和连接中断，再进入业务校验。已有框架可能提供解析器，但仍需确认其配置与错误行为。","教学短代码可以只展示字段校验核心，前提是body已成功解析且是非空普通对象。真正服务的路由、解析、错误响应和写入仍要补齐。把缺失上下文说清楚，避免把几行验证函数直接复制后误以为完整接口已经可运行。"],"code":"function validTitle(value) {\n  return typeof value === \"string\"\n    && value.trim().length > 0\n    && value.trim().length \u003c= 120;\n}\n// 在已解析并检查为对象的 body 上调用：\n// if (!validTitle(body.title)) 返回约定的400错误。"},{"title":"确认写入后再把成功反馈给用户","paragraphs":["简单实现可以等后端成功返回真实task后再更新前端，这称为确认后更新。若提前更新，失败时要回滚或标明未确认，复杂度更高。初学者先采用确认后更新，输入在失败时保留，错误提示对应具体操作。","测试不能只从页面提交正常标题，还要直接发送空白、错误类型、未知ID和额外字段，确认后端状态与实际数据没有被错误改变。模块09会继续让数据库约束守住有效性；多层检查各有作用，不是有一层就可以完全忽略其他层。"]}],"glossary":[{"term":"服务端校验","meaning":"后端独立检查到达请求的结构、类型和业务规则。"},{"term":"白名单","meaning":"明确列出可接受或可修改的字段，其余按规则处理。"},{"term":"确认后更新","meaning":"等待后端确认成功后，再用返回结果更新前端状态。"}],"predict":{"question":"PATCH请求携带{\"done\":\"false\"}，后端应该怎样处理？","options":[{"text":"只相信页面控件所以不检查","correct":false,"feedback":"请求可以绕过控件，后端必须独立验证。"},{"text":"拒绝错误类型并保持原记录","correct":true,"feedback":"合同要求JSON布尔值，字符串false不能靠真假转换代替。"},{"text":"用Boolean转换后写入false","correct":false,"feedback":"非空字符串会转为true，反而改变了请求含义。"}]},"experiment":{"title":"绕过页面也要遵守规则","brief":"比较合法更新与无效请求，核对响应和实际记录两份证据。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"空标题直接发送","input":"t1标题“原任务”；直接PATCH /api/tasks/t1发送{\"title\":\"   \"}，绕过页面检查。","question":"怎样才满足后端验证要求？","options":[{"text":"返回400并保持t1原标题不变","correct":true,"feedback":"拒绝与无副作用需要同时检查，不能只看响应文案。"},{"text":"返回200但把标题改成空","correct":false,"feedback":"这只是接受无效数据，违背非空业务规则。"},{"text":"删除t1以防空值传播","correct":false,"feedback":"用户请求修改失败，不应转成未请求的删除。"}],"output":"教学推演：错误代码指出标题无效，t1标题和done保持；前端保留草稿并允许重新输入。","evidence":["400错误结构","再次读取t1字段未变"]},{"name":"未知ID不是新建","input":"PATCH /api/tasks/missing提交{\"done\":true}，任务集合中没有missing。","question":"请求更新未知ID时，本课程约定应怎样响应？","options":[{"text":"创建一个无标题任务以让请求成功","correct":false,"feedback":"这会混淆更新与创建，还可能违反标题约束。"},{"text":"修改数组第一条作为替代","correct":false,"feedback":"目标missing不存在时没有可更新记录，不能把第一条任务当替代对象。"},{"text":"返回404且不创建新记录","correct":true,"feedback":"PATCH用于已有目标，未知ID应明确提示而不是猜测新建。"}],"output":"教学推演：记录集合完全不变，前端说明目标不存在并可重新读取；未知ID错误不会显示修改成功。","evidence":["404与目标ID","请求前后记录集合一致"]}]},"practice":{"intro":"以模块07的V1副本为起点，在本机开发测试环境操作，不公开服务；先记录当前可恢复版本与启动方法。本课目标：为创建和更新加入独立服务端校验","steps":["以08.03合同确认标题上限、done类型、允许字段、未知ID状态和JSON解析错误规则。","让Codex沿现有服务实现读取请求体、体积限制、解析与校验，禁止任意展开body覆盖记录。","通过页面完成正常创建和单字段更新，前端等待真实返回再显示成功，失败保留草稿。","直接发送空白标题、对象标题、字符串done、未知ID与额外字段；核对拒绝后的实际记录，再恢复正常请求。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“为创建和更新加入独立服务端校验”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：以08.03合同确认标题上限、done类型、允许字段、未知ID状态和JSON解析错误规则。；让Codex沿现有服务实现读取请求体、体积限制、解析与校验，禁止任意展开body覆盖记录。；通过页面完成正常创建和单字段更新，前端等待真实返回再显示成功，失败保留草稿。；直接发送空白标题、对象标题、字符串done、未知ID与额外字段；核对拒绝后的实际记录，再恢复正常请求。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["校验位置与字段白名单说明","正常写入返回ID及重新读取对照","五类无效请求的状态、错误和记录未被误改证据"],"troubleshooting":[{"symptom":"Node服务读不到req.body","check":"检查是否用原生http且没有请求体解析逻辑","action":"正确收集受限请求体后解析JSON，或使用项目已有解析器，不凭空假设字段存在。"},{"symptom":"页面提示成功但后端400","check":"检查成功提示是否在await和状态判断之前","action":"等待确认并按错误分支保留草稿，核对真实记录。"}]},"checks":[{"question":"前端检查通过，后端仍返回400，下一步该怎么做？","options":[{"text":"把所有400状态改为200","correct":false,"feedback":"改变数字掩盖失败，不会使数据符合规则。"},{"text":"核对实际请求字段、类型与合同错误说明","correct":true,"feedback":"前端校验条件可能与后端不一致，应依据请求定位。"},{"text":"删除后端校验以便通过","correct":false,"feedback":"这会让绕过页面的无效请求进入数据层。"}]},{"question":"只更新title时done被重置，说明哪里需修？","options":[{"text":"部分更新覆盖了未提供字段，应保留原值","correct":true,"feedback":"PATCH应只改允许且明确提供的内容。"},{"text":"创建时间应改为任务标题","correct":false,"feedback":"创建时间和标题各有职责，交换两者不能修复PATCH误重置done的问题。"},{"text":"属于CSS问题，改勾选颜色即可","correct":false,"feedback":"done已在数据中被重置，应检查服务更新逻辑而不是只改勾选颜色。"}]}],"sources":[{"label":"MDN：客户端校验与服务端校验","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Forms/Form_validation","checked":"2026-10-16"},{"label":"Node.js：HTTP请求消息","url":"https://nodejs.org/api/http.html","checked":"2026-10-16"}]},{"id":"08.06","title":"等待、失败与重复操作","lead":"点一次添加后一直转圈，再点一次出现两条任务；提示超时，又不确定第一条到底保存没有。应该重试吗？","goals":["区分等待、明确失败与结果不确定","选择并验证防重复提交与重试策略，避免旧响应覆盖新状态"],"sections":[{"title":"等待不是成功也不是失败","paragraphs":["网络操作跨越浏览器、服务与数据处理，响应需要时间。请求开始后应进入pending状态，说明正在处理并限制与本次操作冲突的动作。只有收到符合合同的成功响应才能确认完成；转圈时间长也不能直接证明服务未写入。","例如POST已到服务并创建t9，但响应在回程中断，客户端只知道没有收到确认。此时直接重试可能再创建t10。课程推演应明确区分“服务拒绝了”与“客户端未得到结论”，不能把所有catch都解释成数据库完全没变化。"]},{"title":"先采用可解释的防重复方案","paragraphs":["本课基础方案是同一提交进行中禁用提交入口，保存原草稿，结束后恢复按钮，阻止快速双击造成两个并行POST。还要防表单Enter绕过仅按钮禁用的逻辑，处理函数内应有pending检查。这个方案控制当前页面，不等于跨设备和网络重试的全局去重。","需要更可靠创建时，可由客户端给一次业务操作稳定的请求标识，后端记录该标识与结果，让重复请求返回同一结果，这称为幂等策略的一种应用。是否采用以及记录多久要明确设计，模块09.06会从数据一致性继续认识，初学练习不必直接实现复杂分布式方案。"]},{"title":"超时与取消不保证服务回滚","paragraphs":["AbortController可以中止客户端等待某个fetch，但服务可能已收到请求并继续处理。超时只是客户端在时限内未确认结果，不是后端事务自动撤销。读取通常可重试，创建则要先核对是否已存在或按服务支持的请求标识重试。","失败后保留输入、给出可理解状态并恢复操作能力。如果不能确认创建结果，可以提示先刷新核对，而不是静默自动重复提交。不同项目可选更强保证，但要写清当前策略能解决什么，不能把一个超时定时器说成全链路可靠性。"]},{"title":"响应顺序也会影响正确性","paragraphs":["先发的慢读取可能比后发的快读取更晚返回；若每个响应都无条件覆盖状态，页面会倒退到旧结果。可在本课限制一次读取，或给读取分配序号，只接受最近一次的响应；取消旧请求仍应理解只是客户端控制，不保证服务没做过事。","测试用可控延迟与一次失败，观察按钮、草稿、列表和请求次数。修复后再验证恢复正常速度、失败后再次提交和按Enter。教学演示的延迟应明确是测试条件，不把故意慢响应描述成当前真实网络质量；证据必须来自自己的独立练习服务。"]}],"glossary":[{"term":"pending","meaning":"请求已开始但尚未得到可确认结束结果的状态。"},{"term":"幂等策略","meaning":"使同一业务操作重复提交仍得到约定一致效果的处理方法。"},{"term":"超时","meaning":"在规定等待时间内未得到确认，不保证服务端没有执行。"}],"predict":{"question":"POST超时，服务日志显示已创建t9，直接重试最需要担心什么？","options":[{"text":"超时会自动回滚所有服务数据","correct":false,"feedback":"没有这样的通用保证，回滚需要服务端明确机制。"},{"text":"只要把等待动画隐藏就消除了重复","correct":false,"feedback":"动画是显示，不控制第二次请求和业务效果。"},{"text":"第二次可能再创建，需先核对或使用去重约定","correct":true,"feedback":"客户端未收到响应不代表第一次没有发生写入。"}]},"experiment":{"title":"相同按钮，不同失败时点","brief":"比较请求尚在等待与服务已成功但响应丢失，检验防重复与重试边界。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"慢请求中的快速重复","input":"创建接口延迟两秒，用户在半秒内点两次；前端pending检查拒绝第二次进入。","question":"等待期间只拦住本页面重复提交，这能证明哪项能力？","options":[{"text":"服务断电也不会丢任务","correct":false,"feedback":"pending只限制当前页面重复进入，不能证明服务断电后的数据库恢复能力。"},{"text":"本页面等待期间只发送一次创建请求","correct":true,"feedback":"处理入口防重与网络记录一起说明当前页面的并行重复受控。"},{"text":"所有设备的同名任务都会自动合并","correct":false,"feedback":"本地pending状态无法管理其他设备提交。"}],"output":"教学推演：网络面板只有一个POST，成功后显示一个返回ID；结束后可再次正常添加不同任务。","evidence":["等待时按钮与入口状态","真实POST数量及返回ID"]},{"name":"响应未确认但已经写入","input":"服务收到请求并创建t9，随后测试断开响应；前端报超时，不知道结果。","question":"创建结果未确认但服务已有t9，最合适的下一步是什么？","options":[{"text":"保留草稿并核对服务结果，避免无依据重发","correct":true,"feedback":"结果不确定时先查同次操作，或按已有幂等约定重试。"},{"text":"自动每秒POST直到有响应","correct":false,"feedback":"可能反复创建，不能把响应缺失当作未执行。"},{"text":"把列表清空当作撤销","correct":false,"feedback":"清空前端状态不会撤销服务端已创建的t9。"}],"output":"教学推演：重新读取找到t9后说明已存在，不再重复创建；若使用请求标识则验证重试返回相同结果。","evidence":["服务的演示操作标识与ID","重新读取或去重重试的结果"]}]},"practice":{"intro":"以模块07的V1副本为起点，在本机开发测试环境操作，不公开服务；先记录当前可恢复版本与启动方法。本课目标：验证慢请求、失败恢复与防重复策略","steps":["在副本给创建和读取加明确测试延迟，保持接口正常数据规则，记录未加防重时的请求数量。","实现提交函数内pending检查与按钮反馈，失败保留草稿，在所有结束出口恢复可操作状态。","连续点与按Enter验证只发送一次，模拟明确400和服务中断，分别说明失败与结果不确定。","选择一次读取限制或响应序号避免旧读取覆盖；恢复正常条件后重跑创建、重试与读取。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“验证慢请求、失败恢复与防重复策略”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在副本给创建和读取加明确测试延迟，保持接口正常数据规则，记录未加防重时的请求数量。；实现提交函数内pending检查与按钮反馈，失败保留草稿，在所有结束出口恢复可操作状态。；连续点与按Enter验证只发送一次，模拟明确400和服务中断，分别说明失败与结果不确定。；选择一次读取限制或响应序号避免旧读取覆盖；恢复正常条件后重跑创建、重试与读取。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["延迟条件、操作次数与真实请求次数","成功、400、超时或中断时的草稿与状态反馈","旧新响应处理或单次读取限制，以及恢复后可继续操作结果"],"troubleshooting":[{"symptom":"失败后按钮永远不可点","check":"查看pending是否只在成功分支清除","action":"在可靠结束出口复位并保留错误说明，验证后续正常提交。"},{"symptom":"禁止点击仍能Enter重复提交","check":"检查防重是否只写在按钮视觉状态","action":"把pending判断放到统一表单提交入口，再核对POST数量。"}]},"checks":[{"question":"客户端abort请求后，能否保证数据库未写入？","options":[{"text":"能，AbortController控制整个服务器","correct":false,"feedback":"它控制客户端请求流程，不拥有服务执行和数据库回滚权限。"},{"text":"只要界面关闭就自动删除新任务","correct":false,"feedback":"页面生命周期不会自动撤销服务端业务操作。"},{"text":"不能，服务可能已经执行，需核对结果","correct":true,"feedback":"中止等待不等于服务端取消或事务回滚。"}]},{"question":"先发慢读取A，后发快读取B，A最后返回，如何避免旧数据覆盖？","options":[{"text":"把loading颜色换成绿色","correct":false,"feedback":"把等待颜色改绿不会改变A和B何时返回，仍需序号或并行限制控制赋值。"},{"text":"限制并行或只接受当前最新读取的结果","correct":true,"feedback":"需要明确响应顺序策略，不能依赖发送顺序等于完成顺序。"},{"text":"把所有响应都当最新直接赋值","correct":false,"feedback":"最后到达的响应未必代表最近一次意图。"}]}],"sources":[{"label":"MDN：Fetch异步与取消","url":"https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch","checked":"2026-10-16"},{"label":"MDN：HTTP方法的语义","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Methods","checked":"2026-10-16"}]},{"id":"08.07","title":"用证据定位联调问题","lead":"终端接口测试成功，浏览器却说失败；另一回浏览器200但页面为空。该从地址、跨源还是渲染开始查？","goals":["按地址、连接、跨源、合同、显示分层定位","整理同一次操作的浏览器与服务证据，修复后重跑完整链路"],"sections":[{"title":"先画实际地址，不靠简称","paragraphs":["记录页面完整来源和API完整目标：协议、主机、端口与路径。localhost与127.0.0.1可能指同一机器，但在浏览器来源判断中主机文字仍有区别；不同端口也属于不同来源。配置写错时，请求可能到了另一个仍正常运行的服务。","若页面由4100提供，fetch(\"/api/tasks\")会请求页面所在来源；若后端在4200，则需明确代理或跨源访问方案。先读网络面板实际URL，而不是只看源码里的变量名“API_URL”。浏览器发出去的目标才是本次联调的有效证据。"]},{"title":"连接与HTTP失败不是同一类","paragraphs":["服务未启动可能表现为连接失败，没有正常HTTP响应；404说明某个服务已经响应但找不到该路由；400通常需查看输入与合同；500要结合后端日志。把这些都称为“网络不行”会让修复失去方向。","用同一次操作的时刻、方法和路径匹配服务日志。若服务没有收到，先查目标与连接；若收到了并返回400，先查字段；若返回正确任务但页面空，再追前端状态和render。后端日志并不是越多越好，相关错误与必要上下文即可。"]},{"title":"跨源是浏览器规则，不是登录权限","paragraphs":["浏览器限制脚本读取某些跨源响应，服务需要用CORS响应头明确允许的来源与行为；某些请求还会先发OPTIONS预检。终端工具能读到接口，不代表浏览器也允许前端读取，必须在实际浏览器观察。","开发初期可由同一服务提供页面与API，减少跨源配置。需要跨源时按具体来源、方法与头正确配置，不关闭安全策略，也不随意使用no-cors，因为得到不透明响应后通常读不到任务正文。CORS不是用户授权，允许来源不能证明某用户能访问哪些记录。"]},{"title":"把问题缩小为可重跑证据包","paragraphs":["一份联调报告可含五项：页面与API地址；触发步骤；网络状态与正文；对应服务日志；前端读取字段与显示结果。先提出能被证伪的假设，例如“前端读items而响应给tasks”，再改一处，避免同时换端口、换字段和重建服务。","修复后重跑原正常和失败操作，核对列表读取、创建、更新与删除没有假成功。保留开发数据仍在内存的限制，下一模块再接数据库。本模块完成联通不代表部署或权限已完成；不公开没有身份隔离的开发服务，也不把网站的案例推演当实际联调截图。"]}],"glossary":[{"term":"跨源","meaning":"请求目标与页面在协议、主机或端口上不同的情况。"},{"term":"CORS","meaning":"服务与浏览器用响应头协作控制脚本读取跨源响应的机制。"},{"term":"预检","meaning":"浏览器在某些跨源请求前发送OPTIONS询问允许条件的过程。"}],"predict":{"question":"命令行GET成功，浏览器报跨源读取限制，最合理的定位是？","options":[{"text":"检查页面来源、CORS与可能的预检响应","correct":true,"feedback":"终端与浏览器的限制不同，成功连接不保证脚本可读取。"},{"text":"证明数据库没有任务，应先加数据","correct":false,"feedback":"跨源读取被限制不能说明服务数据内容。"},{"text":"关闭浏览器全部安全设置作为修复","correct":false,"feedback":"这回避真实访问条件，其他使用者仍会遇到同一问题。"}]},"experiment":{"title":"连接、合同与显示分层判断","brief":"两例分别改变目标端口与读取字段，定位最早失败层。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"目标指向未运行端口","input":"页面在4100，实际fetch请求4201/api/tasks；后端日志显示只监听4200，4201无服务。","question":"请求打到未监听端口时，先修哪一个可核对差异？","options":[{"text":"先把tasks字段改成items","correct":false,"feedback":"尚未得到响应，字段不一致不是此时首要证据。"},{"text":"给数据库添加索引","correct":false,"feedback":"连接没有建立，索引无法使错误端口回应。"},{"text":"实际请求端口与已监听端口的差异","correct":true,"feedback":"连接前已指错地址，先统一目标再观察HTTP结果。"}],"output":"教学推演：改到正确目标后才出现接口响应；若随后跨源受限，再按来源规则处理，不混为一个问题。","evidence":["完整请求URL和失败类型","服务监听输出与修后状态"]},{"name":"响应成功但字段错读","input":"请求同源，200返回tasks数组；服务无错误；前端读取items后显示空。","question":"同源200但读取字段错误，此时最合理的下一步是？","options":[{"text":"增加Access-Control-Allow-Origin解决显示","correct":false,"feedback":"同源读取已成功，CORS不是此例的阻塞点。"},{"text":"对照合同修正解析到状态的字段映射","correct":true,"feedback":"通信已成功，应继续查前端如何使用正文。"},{"text":"重启所有服务直到数组变多","correct":false,"feedback":"响应已经有正确tasks，重启不会把前端读取的items自动修正成tasks。"}],"output":"教学推演：使用tasks并验证后渲染成功；以同一ID贯穿响应、状态和页面，说明修复落在哪一段。","evidence":["原正文与读取字段","修后同ID的完整链路"]}]},"practice":{"intro":"以模块07的V1副本为起点，在本机开发测试环境操作，不公开服务；先记录当前可恢复版本与启动方法。本课目标：完成一份实际联调故障定位与恢复记录","steps":["在V1联网副本画出页面来源、后端监听和实际API目标，保留08.03合同。","依次构造错误端口、错误路径、错误字段三种可恢复故障；每次只改一个条件并保存相关证据。","若页面与API跨源，记录预检和CORS结果；可优先使用同源开发服务，不关闭浏览器安全机制。","选一例写假设、证据、修改和复验，恢复后重跑读取、创建、更新、删除并列出临时数据边界。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“完成一份实际联调故障定位与恢复记录”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在V1联网副本画出页面来源、后端监听和实际API目标，保留08.03合同。；依次构造错误端口、错误路径、错误字段三种可恢复故障；每次只改一个条件并保存相关证据。；若页面与API跨源，记录预检和CORS结果；可优先使用同源开发服务，不关闭浏览器安全机制。；选一例写假设、证据、修改和复验，恢复后重跑读取、创建、更新、删除并列出临时数据边界。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["实际来源和请求链路图","三类故障的网络与服务对应证据","一个完整定位过程及恢复后四类操作结果"],"troubleshooting":[{"symptom":"终端通而浏览器不通","check":"检查浏览器是否报CORS、是否有OPTIONS失败","action":"按实际来源配置或采用同源开发，不能用终端结果替代浏览器验收。"},{"symptom":"请求200却显示空","check":"核对响应字段、状态赋值、筛选和render输入","action":"逐环节找最早不一致，修一处后重跑同一请求。"}]},"checks":[{"question":"CORS允许了页面来源，能否证明用户只能访问自己的任务？","options":[{"text":"不能，来源读取规则不代替身份与数据授权","correct":true,"feedback":"后端仍要按可信用户逐次限制记录访问。"},{"text":"能，同一来源内所有用户权限相同","correct":false,"feedback":"同源不意味着不同用户应该看到同样数据。"},{"text":"只要没有预检就无需权限","correct":false,"feedback":"预检检查浏览器跨源请求条件，不判断当前账户是否有权访问目标任务。"}]},{"question":"修复错误端口后变成404，下一步是什么？","options":[{"text":"继续说服务没有启动","correct":false,"feedback":"404说明某个服务已接收并回应请求。"},{"text":"把404在页面隐藏就算完成","correct":false,"feedback":"隐藏错误没有恢复约定接口和业务结果。"},{"text":"核对当前服务的路径与方法","correct":true,"feedback":"已有HTTP响应，说明问题已进入路由层，应继续依据新证据定位。"}]}],"sources":[{"label":"MDN：跨源资源共享","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS","checked":"2026-10-16"},{"label":"MDN：使用Fetch","url":"https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch","checked":"2026-10-16"},{"label":"MDN：HTTP状态","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status","checked":"2026-10-16"}]},{"id":"09.01","title":"从一条任务认识数据库","lead":"请求已成功，重启后端却少了新任务。数据到底留在进程、普通文件，还是数据库里？","goals":["区分内存、普通文件与数据库的组织和恢复能力","追踪页面—后端—数据库的真实数据流并核对重启来源"],"sections":[{"title":"先追一条记录的去向","paragraphs":["联网只说明程序可以交换消息，不说明数据已持久保存。前端提交标题后，后端可能只把它放进数组，返回201也不能独立证明写入磁盘。选择一个新任务ID，追踪请求、后端写入、数据库记录与再次读取，才知道它实际经过哪里。","例如创建“测试周报”得到t21，立刻读取能看到t21；若后端重启后只剩初始任务，说明当前实现没有可靠恢复它。也可能重启连接到了另一份数据库，因此不能只凭消失就断言数据库坏了，要同时记录数据位置、连接配置和工作目录。"]},{"title":"数据库不只是一个更大的数组","paragraphs":["内存便于快速读写，但进程结束通常失去状态；普通JSON文件可以留下内容，但查询、并发写入和规则维护常要自行实现。数据库把记录按结构组织，并提供查询、约束、事务等机制，让应用能够按明确规则读取和修改。","这不表示普通文件没有用途，也不表示数据库永不丢失。一个只保存设置的小工具可以合理使用JSON；需要按字段查询、多条记录一致更新时，数据库工具更合适。SQLite常把持久数据保存在磁盘文件，说明“文件”和“数据库”不是互斥物，区别还在管理机制。"]},{"title":"数据库可以嵌入，也可以独立运行","paragraphs":["SQLite通常由应用通过库访问文件，不需要单独数据库服务进程；其他数据库可能通过网络连接独立服务。后端是应用的请求入口，数据库是数据管理组件，二者职责不同，不能把后端监听端口当成数据库文件位置。","本课程开发练习可用SQLite。让Codex先核对现有运行时是否支持Node内置node:sqlite，或已有Python的sqlite3接口，再选已可用的接入方式并记录版本；不要照抄未验证依赖配置。若接口缺失，先报告真实准备条件，不用假数组冒充数据库。"]},{"title":"持久化需要实际重启和查询","paragraphs":["一次写入之后，独立查询应能找到相同ID，关闭并重开连接仍在，停止后端再启动也应能读取。若应用使用\":memory:\"数据库，则数据只在相应连接生命周期内；练习持久化必须明确磁盘文件的绝对位置，避免相对路径悄悄创建新空库。","数据库能提高组织与一致性，但仍需要备份、结构迁移、访问规则和合适存储环境。当前V2仅是本机开发测试版，未完成用户授权。连接成功、数据库有user_id或页面看不见他人任务，都不能替代模块10的允许与拒绝路径验收。"]}],"glossary":[{"term":"数据库","meaning":"提供组织、查询和规则管理的数据系统，可嵌入应用或独立运行。"},{"term":"连接","meaning":"应用访问某个数据库目标的会话或接口对象，不等于浏览器HTTP连接。"},{"term":"持久化","meaning":"把状态写到可跨相应运行生命周期读取的来源，仍需恢复验证。"}],"predict":{"question":"后端创建返回201，但重启后记录消失，最合理的下一步是什么？","options":[{"text":"核对写入来源、数据库目标和重启读取链路","correct":true,"feedback":"201说明接口宣告成功，仍需实际数据位置与恢复证据。"},{"text":"把201改成200就会永久保存","correct":false,"feedback":"状态码不决定数据是否写入持久存储，也不是恢复记录的机制。"},{"text":"只要接口联网就认定数据库已可靠保存","correct":false,"feedback":"HTTP通信并不保证后端用了数据库或正确连接。"}]},"experiment":{"title":"数据库位置改变结果","brief":"对比进程内存与磁盘数据库，两例都以同一个演示标题完成创建。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"后端数组临时保存","input":"POST创建t21放入tasks数组并返回201；没有文件或数据库写入，进程随后重启。","question":"没有持久来源，新运行通常能恢复t21吗？","options":[{"text":"能，从上次201状态码恢复全部字段","correct":false,"feedback":"状态码不保存任务对象，也不是数据恢复来源。"},{"text":"能，网页曾显示就会写回服务入口文件","correct":false,"feedback":"浏览器显示不会自动修改后端源码文件。"},{"text":"不能，除非有明确持久来源或重新导入机制","correct":true,"feedback":"运行数组已结束，新进程不会自动继承上次内存。"}],"output":"教学推演：重启回初始数组，t21消失；应诚实标为临时开发数据，而不是数据库故障。","evidence":["重启前后接口ID集合","后端没有持久写入位置"]},{"name":"磁盘文件路径稳定","input":"后端把t21提交到固定绝对路径的demo.db，独立连接查询可见，停止后端再启动连接同一路径。","question":"哪一证据支持本次持久化链路确已建立？","options":[{"text":"文件夹里有任意一个.db文件","correct":false,"feedback":"文件存在不证明它就是本次连接或含目标记录。"},{"text":"重启后从同一库查询并返回相同ID和字段","correct":true,"feedback":"稳定目标、实际查询和接口恢复共同支持本次持久化。"},{"text":"启动日志只写“数据库就绪”","correct":false,"feedback":"日志文案不能替代记录真实存在与读取成功。"}],"output":"教学推演：t21在独立查询与重启后响应里一致；仍需继续检查约束、备份与权限，不能推广成永不丢失。","evidence":["数据库绝对位置与目标ID","重启前后同记录字段"]}]},"practice":{"intro":"以模块08的本机前后端练习副本为起点，使用独立测试数据库与虚构记录，记录数据库文件或连接目标。本课目标：把一条新任务从请求追踪到持久数据库","steps":["让Codex先报告可用SQLite入口与运行时版本，确认已有支持后选用；不能使用时记录准备缺项，不标数据库实操通过。","在独立测试目录确定磁盘数据库绝对路径，沿用08.03接口合同，将任务写入从内存替换为数据库操作。","创建独特演示标题，记录返回ID，独立查询该库并对照页面；确认不是读取旧localStorage或固定数组。","停止自己启动的后端并重启，核对同一数据库目标和同ID任务；记录当前没有用户隔离的限制。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“把一条新任务从请求追踪到持久数据库”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：让Codex先报告可用SQLite入口与运行时版本，确认已有支持后选用；不能使用时记录准备缺项，不标数据库实操通过。；在独立测试目录确定磁盘数据库绝对路径，沿用08.03接口合同，将任务写入从内存替换为数据库操作。；创建独特演示标题，记录返回ID，独立查询该库并对照页面；确认不是读取旧localStorage或固定数组。；停止自己启动的后端并重启，核对同一数据库目标和同ID任务；记录当前没有用户隔离的限制。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["实际运行时、数据库接入方式和绝对目标位置","同一ID在请求响应、独立查询与页面中的对照","服务重启后的再次读取和当前开发边界"],"troubleshooting":[{"symptom":"重启后出现新空库","check":"检查相对路径与启动工作目录是否改变","action":"固定测试库绝对位置并找回原文件，不在未确认前覆盖。"},{"symptom":"接口成功但库里没有记录","check":"核对是否仍在写旧数组或连接了memory数据库","action":"定位真实写入与提交，接通后用新ID重跑全链路。"}]},"checks":[{"question":"SQLite保存在文件里，是否和直接写JSON完全一样？","options":[{"text":"不一样，还提供查询、约束与事务管理机制","correct":true,"feedback":"文件是存储载体，数据管理能力与普通文本写入仍有区别。"},{"text":"一样，只要扩展名不同内容都相同","correct":false,"feedback":"扩展名不能定义数据结构、约束和实际访问机制。"},{"text":"SQLite必然需要另一台云服务器","correct":false,"feedback":"嵌入式SQLite可以在本机应用中访问磁盘文件。"}]},{"question":"数据库连接成功就能面向多人试用吗？","options":[{"text":"可以，数据库会按网页自动分用户","correct":false,"feedback":"需要明确可信身份与访问规则，不能靠自动假设。"},{"text":"只要数据库文件名包含private即可","correct":false,"feedback":"命名没有建立请求级别的数据访问限制。"},{"text":"不能，还需身份、授权和隔离等后续验收","correct":true,"feedback":"连接只说明后端能访问库，不说明请求者的权限。"}]}],"sources":[{"label":"SQLite：适用场景","url":"https://www.sqlite.org/whentouse.html","checked":"2026-10-16"},{"label":"Node.js：SQLite入口","url":"https://nodejs.org/api/sqlite.html","checked":"2026-10-16"},{"label":"Python：sqlite3接口","url":"https://docs.python.org/3/library/sqlite3.html","checked":"2026-10-16"}]},{"id":"09.02","title":"表、字段、类型与主键","lead":"两条任务都叫“买牛奶”，修改标题时怎样只改其中一条？数据库又如何区分false、0和字符串？","goals":["设计任务表并解释ID、标题、完成值、时间与缺省值","按稳定主键更新同名记录，识别SQLite类型与约束边界"],"sections":[{"title":"一行是一条记录，列有不同职责","paragraphs":["表把同类记录按字段组织，一行代表一条任务，列分别保存身份、标题、完成状态和创建时间。标题给人阅读，会重复和修改；ID给程序稳定定位，不应因改标题或筛选而改变。把标题当主键会让同名事项难以共存。","例如t31和t32标题都叫“买牛奶”，可以一个是今天一个是周末。执行按ID更新t32后，t31必须完全不变。数据库查询显示顺序不是身份，未指定排序时也不能把“第二行”视为长期稳定对象，应始终把实际ID带到接口与页面。"]},{"title":"类型表达约定，约束保证具体规则","paragraphs":["不同数据库对类型的执行方式不同。SQLite具有灵活类型行为，只写INTEGER不应被理解为所有错误输入都会自动拒绝。完成状态可用0和1存储，并加NOT NULL与CHECK约束，确保值和类型符合当前约定；后端再映射为接口布尔值。","下面是独立SQLite示例表，TEXT主键显式NOT NULL，避免依赖某些SQLite表类型的特殊行为。CHECK标题去空白后有长度，完成值检查整数且仅为0或1。它仍不是完整输入策略，标题最大长度等规则要与后端对齐，并用实际无效写入验证。SQLite默认trim主要去除普通空格，不能当成所有Unicode空白的统一清洗器；示例约束还要结合后端规范化与实际输入测试。INTEGER亲和性也可能把可转换文本存为整数，CHECK检查的是存储后的值，不证明原始JSON类型正确。"],"code":"CREATE TABLE tasks (\n  id TEXT PRIMARY KEY NOT NULL,\n  title TEXT NOT NULL CHECK(length(trim(title)) > 0),\n  done INTEGER NOT NULL DEFAULT 0\n    CHECK(typeof(done) = 'integer' AND done IN (0, 1)),\n  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);"},{"title":"缺省值只处理未给出的值","paragraphs":["DEFAULT 0表示插入时未提供done可采用0，不表示每次更新其他字段都应把done重置。显式提供NULL与省略字段不同，NOT NULL会阻止前者。缺省值应匹配业务含义，例如新任务默认未完成，但不能拿默认值掩盖请求传错类型。","created_at记录创建时刻，和计划完成日期、最后修改时间不同。SQLite的CURRENT_TIMESTAMP产生UTC时间文本，展示到用户时需要明确时区和格式约定。不能因为某设备显示晚了八小时就重写创建时刻，应先核对存储与显示的时间解释。"]},{"title":"用读写对照验证设计","paragraphs":["先建独立测试库，再插入两条同名不同ID记录。通过参数化更新其中一个ID，查询两条并对照标题、done、created_at。再尝试重复ID、空标题、done=2与NULL，确认由哪条规则拒绝，而不是只看界面提示。","数据表设计不要求零基础者背所有SQL语法，要能解释每列职责、稳定定位与失败原因。后续09.03增加归属关联，09.05加深约束与索引。这里主键唯一不代表用户权限，也不意味着外部请求可以任意提供或修改主键。"]}],"glossary":[{"term":"表与字段","meaning":"表组织同类记录，字段是每条记录中有明确职责的一项值。"},{"term":"主键","meaning":"用于唯一识别一条记录的字段或字段组合，应稳定且符合非空要求。"},{"term":"缺省值","meaning":"插入未提供某字段时采用的约定值，不是覆盖合法旧值的命令。"}],"predict":{"question":"两条同名任务id分别t31、t32，想只编辑后一条，应使用什么条件？","options":[{"text":"按当前查询的第二行更新","correct":false,"feedback":"显示顺序可能随排序或筛选变化，不是稳定身份。"},{"text":"按t32的稳定ID定位并核对影响行数","correct":true,"feedback":"标题会重复，唯一身份才能精确指向目标记录。"},{"text":"WHERE title等于买牛奶","correct":false,"feedback":"标题条件会匹配两条，可能同时修改两条记录。"}]},"experiment":{"title":"身份与字段规则分开验证","brief":"先比较同名任务定位，再比较省略字段和显式无效值。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"同名记录更新","input":"表里t31、t32都叫“买牛奶”，done均为0；仅把t32改为“周末买牛奶”。","question":"哪项对照能说明本次更新对象准确？","options":[{"text":"t32标题变，t31与两条ID、创建时间均保持","correct":true,"feedback":"目标字段变化和非目标字段保持共同验证范围。"},{"text":"列表第一行看起来变了就通过","correct":false,"feedback":"排序可能变化，单看位置无法判断具体对象。"},{"text":"把两条同名任务合并再更新","correct":false,"feedback":"这改变了原需求，不能证明精确修改原t32。"}],"output":"教学推演：按主键更新只影响t32；查询两个ID后才能确认t31没有被误改或删除。","evidence":["按ID查询的前后字段","更新影响行数为1"]},{"name":"省略与无效完成值","input":"新建一条任务省略done，另一条显式done=2；表采用DEFAULT 0与CHECK done IN(0,1)。","question":"省略字段和非法值的两次插入会怎样？","options":[{"text":"两条都自动变成0","correct":false,"feedback":"缺省机制不承诺替换所有非法输入，还需允许值约束。"},{"text":"两条都会因没有布尔类型而拒绝","correct":false,"feedback":"本表明确用受约束整数表示完成值，省略可取0。"},{"text":"省略可用默认0，显式2违反约束","correct":true,"feedback":"默认值填缺项，不会自动改正明确传入的非法值。"}],"output":"教学推演：第一条成功且done为0，第二条被拒绝；应用把数据库0/1明确映射到JSON布尔值。","evidence":["插入返回与实际done","被拒绝后无第二条无效记录"]}]},"practice":{"intro":"以模块08的本机前后端练习副本为起点，使用独立测试数据库与虚构记录，记录数据库文件或连接目标。本课目标：建立任务表并精确更新两条同名任务之一","steps":["使用09.01已确认的SQLite接入方式，在独立测试库运行本课建表，已有同名表时先检查结构，不覆盖真实数据。","创建t31和t32两条同名任务，记录完整字段；由后端把数据库0/1映射为JSON布尔值。","按t32主键参数化修改标题，核对影响一行，t31及创建时间不变。","分别测试重复ID、空白标题、done=2和NULL，记录错误及数据未被无效写入的结果。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“建立任务表并精确更新两条同名任务之一”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：使用09.01已确认的SQLite接入方式，在独立测试库运行本课建表，已有同名表时先检查结构，不覆盖真实数据。；创建t31和t32两条同名任务，记录完整字段；由后端把数据库0/1映射为JSON布尔值。；按t32主键参数化修改标题，核对影响一行，t31及创建时间不变。；分别测试重复ID、空白标题、done=2和NULL，记录错误及数据未被无效写入的结果。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["表结构与每列职责解释","同名任务按ID更新前后及影响行数","四种非法写入的规则、错误和实际记录核对"],"troubleshooting":[{"symptom":"按标题更新改了两条","check":"检查WHERE条件是否用非唯一标题","action":"恢复测试副本，改按ID后重跑两条同名记录。"},{"symptom":"只改标题却done变0","check":"检查是否把缺省值在每次更新中强行写回","action":"部分更新只设置提供字段，保留原done并增加回归。"}]},"checks":[{"question":"SQLite列声明INTEGER，是否就保证任何错误类型都会拒绝？","options":[{"text":"不能使用任何类型声明所以全部存文本","correct":false,"feedback":"类型仍有作用，只需正确理解并配合具体约束规则。"},{"text":"不能，应结合实际类型规则和显式约束验证","correct":true,"feedback":"SQLite有灵活类型行为，需要明确约束而不是只看声明文字。"},{"text":"能，类型名等于完整业务校验","correct":false,"feedback":"类型名没有表达所有允许值和完整业务条件。"}]},{"question":"把创建时间用于截止日期，会出现什么概念问题？","options":[{"text":"记录产生时刻与计划到期时刻职责不同","correct":true,"feedback":"应建立不同字段并说明各自的时间格式与时区。"},{"text":"只要都是时间就可以互相替代","correct":false,"feedback":"两者对应不同事件，改变一个不应改另一个。"},{"text":"把字段改名id即可解决","correct":false,"feedback":"身份字段也不能表达截止日期含义或计划时刻。"}]}],"sources":[{"label":"SQLite：CREATE TABLE与约束","url":"https://www.sqlite.org/lang_createtable.html","checked":"2026-10-16"},{"label":"SQLite：INSERT与缺省值","url":"https://www.sqlite.org/lang_insert.html","checked":"2026-10-16"}]},{"id":"09.03","title":"用户、任务与关联","lead":"任务表已经有user_id，为什么这只能说明归属，却不能保证请求者看不到别人的任务？","goals":["建立用户与任务的合法关联并检查孤立记录","明确外键完整性与身份授权的不同职责，避免把关联当作权限"],"sections":[{"title":"关联表达两类记录的关系","paragraphs":["用户表一行表示一个演示用户，任务表一行表示一个任务。任务的user_id指向用户的id，表达“这条任务属于这个用户”。一个用户可有多条任务，这叫一对多关系。把用户姓名直接复制进每条任务，会让改名与同名判断更难维护。","例如用户u1与u2都叫“小林”，名字相同不代表同一个人；任务t41属于u1，t42属于u2。用稳定用户ID能保留归属关系，显示姓名则通过关联查询取得。此处用户是虚构数据行，并没有因此完成登录或证明真实请求者是谁。"]},{"title":"外键守住引用是否存在","paragraphs":["外键规定任务中的user_id应指向一条合法用户记录，可阻止任务引用根本不存在的u9。NOT NULL保证必须有归属；外键自身不一定禁止NULL，因此两个规则职责不同。删除用户时如何处理其任务也要选择明确策略，例如阻止删除或级联删除。","SQLite要在每个连接开始事务前启用并核对PRAGMA foreign_keys=ON，不能只在建表脚本里写一次就假设所有连接生效。下面片段是独立SQLite示例；真实项目给已有tasks加关联时需迁移旧数据，不应直接重建覆盖。"],"code":"PRAGMA foreign_keys = ON;\nCREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL);\nCREATE TABLE tasks (\n  id TEXT PRIMARY KEY NOT NULL,\n  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,\n  title TEXT NOT NULL CHECK(length(trim(title)) > 0)\n);\n-- 在新连接中查询 PRAGMA foreign_keys; 应确认值为1。"},{"title":"合法归属不会自动限制访问","paragraphs":["外键只检查引用关系，不检查当前HTTP请求是谁。如果后端SELECT所有tasks，即使每条user_id都合法，仍会把两人任务一起返回。浏览器发送user_id=u1也只是一个可修改值，不能作为可信身份；模块10才建立登录来源与授权规则。","这一区别可用两个问题记住：“任务是否指向存在的用户？”是完整性；“当前请求是否被允许读取该用户任务？”是授权。通过第一个不自动通过第二个。界面隐藏别人的记录也不能阻止直接请求，不能据此宣传已经隔离。"]},{"title":"先验收关系，再记录权限缺口","paragraphs":["在独立测试库建立u1、u2及对应任务，核对关联查询结果；尝试引用u9，应被外键拒绝。再观察当前无身份接口是否会返回两人的记录，明确记录缺口，不在这个阶段对真实用户开放。只使用虚构数据，不把演示变成访问真实他人记录。","如果需要删除用户，先讨论其任务保留、转移或删除的业务决定，再设置数据库行为。级联删除能维护引用一致，却可能扩大误删后果，不应为省事默认使用。归属设计为权限提供数据基础，实际允许与拒绝的验证要在模块10补齐。"]}],"glossary":[{"term":"外键","meaning":"要求某字段引用另一表合法键的数据库规则，维护关联完整性。"},{"term":"一对多","meaning":"一条用户记录可关联多条任务，每条任务按约定归属一个用户。"},{"term":"授权","meaning":"判断当前可信请求者是否允许操作目标数据，与外键存在性不同。"}],"predict":{"question":"所有任务user_id均能匹配用户表，接口却不限制查询就返回全部任务，说明什么？","options":[{"text":"数据库有外键就已经阻止跨用户读取","correct":false,"feedback":"外键不是HTTP请求授权规则，不识别访问者身份。"},{"text":"把页面他人任务隐藏就完成授权","correct":false,"feedback":"隐藏只影响显示，直接请求仍可能读到全部响应。"},{"text":"关联完整，但用户访问隔离尚未完成","correct":true,"feedback":"外键保证引用存在，不会自动按当前请求者过滤与拒绝。"}]},"experiment":{"title":"引用合法与访问允许分别判断","brief":"使用虚构u1、u2和不存在的u9，比较数据完整性与接口缺口。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"不存在的归属","input":"已启用外键且要求user_id非空；只存在u1、u2，插入t43并指向u9。","question":"数据库应拒绝这次写入的依据是什么？","options":[{"text":"任务标题长度比用户名长","correct":false,"feedback":"标题长度与用户关联是否存在没有此因果关系。"},{"text":"user_id引用了不存在的合法用户键","correct":true,"feedback":"外键针对引用完整性，而不是判断请求者是否登录。"},{"text":"u9没有在页面上点添加按钮","correct":false,"feedback":"数据库并不靠页面点击历史判断引用是否存在。"}],"output":"教学推演：外键错误使该行未插入；查询任务表无t43，有效用户与已有任务保持不变。","evidence":["连接外键开关为1","失败后t43不存在"]},{"name":"归属都合法仍可全部读取","input":"t41属于u1，t42属于u2；无身份GET /api/tasks执行无归属条件的SELECT并返回两条。","question":"关联正确的当前版本能通过哪项检查？","options":[{"text":"归属关联检查可通过，权限检查不能据此通过","correct":true,"feedback":"数据合法不等于请求被按可信身份限制。"},{"text":"两账户隔离已经通过","correct":false,"feedback":"接口仍返回两人的记录，没有允许拒绝路径的验证证据。"},{"text":"把t42颜色变浅即可阻止u1读取","correct":false,"feedback":"响应已经包含记录，外观无法撤回数据访问。"}],"output":"教学推演：关联查询能说明每条属于谁，接口仍有隔离缺口；记录为模块10待修，不开放真实多用户。","evidence":["关联查询的user_id","无身份响应含两个归属的证据"]}]},"practice":{"intro":"以模块08的本机前后端练习副本为起点，使用独立测试数据库与虚构记录，记录数据库文件或连接目标。本课目标：建立演示用户关联并明确权限尚未完成","steps":["在独立测试库建立虚构u1、u2与两条任务，记录新连接外键开关；已有结构用副本迁移而非覆盖。","按user_id关联读取用户姓名与任务ID，说明名字不是身份，验证同名用户仍可区分。","尝试指向不存在u9、空归属、删除仍有任务的用户，观察约束与RESTRICT行为。","检查现有开发接口是否按身份限制；只记录缺口和模块10验收要求，不把user_id存在称作权限完成。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“建立演示用户关联并明确权限尚未完成”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：在独立测试库建立虚构u1、u2与两条任务，记录新连接外键开关；已有结构用副本迁移而非覆盖。；按user_id关联读取用户姓名与任务ID，说明名字不是身份，验证同名用户仍可区分。；尝试指向不存在u9、空归属、删除仍有任务的用户，观察约束与RESTRICT行为。；检查现有开发接口是否按身份限制；只记录缺口和模块10验收要求，不把user_id存在称作权限完成。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["用户、任务与关联查询结果","外键启用状态与三种非法关系的拒绝结果","完整性与访问权限的两栏说明和后续待验收项"],"troubleshooting":[{"symptom":"不存在用户仍能插入任务","check":"检查当前连接PRAGMA foreign_keys和事务开始时机","action":"在连接初始化时启用并确认值为1，重新用副本试验。"},{"symptom":"想删除用户却被拒绝","check":"检查ON DELETE策略与其关联任务","action":"按业务决定先处理任务或保留拒绝，不盲目关闭外键。"}]},"checks":[{"question":"浏览器传user_id=u1，后端照此查任务，能证明访问者是u1吗？","options":[{"text":"能，外键已确认u1在表里","correct":false,"feedback":"用户行存在不证明请求者拥有该身份或操作权限。"},{"text":"只要字段名叫current_user就可信","correct":false,"feedback":"名字不能使客户端自报值成为可信身份来源。"},{"text":"不能，这只是可修改的请求数据","correct":true,"feedback":"需要可信登录身份并在服务或数据层执行授权规则。"}]},{"question":"外键允许NULL，但业务要求任务必须归属用户，还要什么？","options":[{"text":"把所有用户姓名设为唯一即可","correct":false,"feedback":"姓名唯一仍不保证每条任务有有效归属字段。"},{"text":"增加非空要求并处理已有无归属记录","correct":true,"feedback":"外键存在性与字段是否允许缺失是两种规则。"},{"text":"只把页面用户名加粗","correct":false,"feedback":"样式不会阻止数据库写入NULL或补齐归属。"}]}],"sources":[{"label":"SQLite：外键支持与启用","url":"https://www.sqlite.org/foreignkeys.html","checked":"2026-10-16"},{"label":"SQLite：foreign_keys设置","url":"https://www.sqlite.org/pragma.html#pragma_foreign_keys","checked":"2026-10-16"}]},{"id":"09.04","title":"用查询完成增删改查","lead":"数据库里有几十条任务，怎样只读取未完成、只修改一条，又不把用户输入误当SQL指令？","goals":["理解过滤、排序、分页与增删改查的范围","通过后端参数化访问数据库，对照请求、响应与实际记录"],"sections":[{"title":"查询规定想得到哪部分数据","paragraphs":["SELECT选择字段，WHERE过滤记录，ORDER BY指定顺序，LIMIT限制本次返回数量。没有明确排序时，不应承诺数据库一直按创建顺序返回。分页还要稳定的顺序，例如created_at与id组合，避免相同时间的记录在页面间漂移。","本课可用WHERE done=0找未完成，再按created_at、id排序。LIMIT和OFFSET适合认识小规模分页，但并不意味着大型数据中永远最高效；先理解结果范围，复杂优化留按需深入。筛选参数也要校验，不能让任意用户字符串决定SQL列名或排序片段。"]},{"title":"写入要有明确目标与影响行数","paragraphs":["INSERT创建新记录，UPDATE修改符合条件的记录，DELETE删除符合条件的记录。WHERE遗漏可能影响整张表，所以每次更新删除都应核对目标ID、预期影响行数和实际数据。删除一行不等于清空页面，页面还要根据响应更新状态。","例如UPDATE tasks SET title=? WHERE id=?应只改标题，不重置done或created_at。目标不存在时影响0行，应转成接口约定的404等反馈，不能照样显示已修改。当前按ID定位并未完成用户权限，模块10会把可信归属规则加入查询和写入范围。"]},{"title":"参数化让内容保持为值","paragraphs":["SQL语句结构由开发者确定，用户输入经驱动的占位符绑定为值，而不拼接进语句。标题中有单引号也应正常保存；看似SQL的文字仍只是标题，不应获得执行含义。手动替换几个引号不能作为统一可靠方案。","下面是Python sqlite3的短片段，前提是con已连接独立测试库、表结构已存在，title和task_id已通过服务校验。问号由驱动绑定，不是先用字符串替换。Node项目应使用其SQLite驱动对应的参数API，不可把Python调用直接粘进JavaScript。"],"code":"cursor = con.execute(\n    \"UPDATE tasks SET title = ? WHERE id = ?\",\n    (title, task_id)\n)\ncon.commit()\nchanged = cursor.rowcount  # 对本次UPDATE核对是否为1"},{"title":"接口和数据库要查同一条记录","paragraphs":["完成一次创建、读取、更新、删除时，保存返回ID并独立查询数据库，核对同一对象。筛选结果为空时确认查询条件；页面仍显示旧值时检查前端状态，而不是重做数据库写入。四类操作各有一次真实证据，才能说明链路接通。","用演示标题“Bob的清单”及包含引号的文本检查参数化，在隔离库验证，不对真实数据执行破坏命令。参数化解决的是值与SQL结构混淆，不自动校验业务权限或字段意义；后端验证、数据库约束与授权仍各有职责。"]}],"glossary":[{"term":"增删改查","meaning":"创建、删除、更新和读取记录的常见操作集合。"},{"term":"参数化查询","meaning":"固定语句结构，用驱动占位符绑定输入值，而非拼接SQL。"},{"term":"影响行数","meaning":"一次写入实际匹配或改变的记录数量，应与操作目标核对。"}],"predict":{"question":"用户标题含单引号，最可靠的数据访问方式是什么？","options":[{"text":"固定SQL并用驱动占位符绑定标题值","correct":true,"feedback":"输入保留为数据，避免引号改变SQL语句结构。"},{"text":"直接把标题接在SQL字符串中","correct":false,"feedback":"引号可能破坏结构或被解释成SQL的一部分。"},{"text":"删除标题中的所有标点再拼接","correct":false,"feedback":"会损失有效内容，也不能替代正确的参数绑定。"}]},"experiment":{"title":"查询范围与输入身份","brief":"比较精确更新与带引号标题，观察数据结果而非只看接口提示。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"按ID而非按标题更新","input":"t51、t52同名且均未完成；请求仅修改t52.done，后端使用WHERE id=?并绑定t52。","question":"哪种核对能支持本次更新范围正确？","options":[{"text":"只看页面弹出“成功”","correct":false,"feedback":"提示可能与实际写入脱节，不能说明影响了哪条记录。"},{"text":"任取一条已完成任务截图","correct":false,"feedback":"其他ID的结果不能证明本次t52被正确修改。"},{"text":"影响一行，t52完成，t51与其余字段保持","correct":true,"feedback":"目标与非目标记录共同验证写入范围和部分更新。"}],"output":"教学推演：更新影响一行，读取t52.done为1而t51为0；前端映射后显示相同ID的正确状态。","evidence":["UPDATE影响行数","两个ID的独立查询"]},{"name":"输入含SQL样式文字","input":"新标题为“Bob's list; DROP TABLE tasks;”，通过占位符作为title值传入。","question":"以占位符绑定这段文字，合理结果是什么？","options":[{"text":"必须把Bob也删除才安全","correct":false,"feedback":"保留合法文本与正确绑定可以同时成立，无需删改原意。"},{"text":"整段作为标题值保存，不作为SQL执行","correct":true,"feedback":"固定语句结构与绑定机制把用户文字保持在数据位置。"},{"text":"驱动会执行标题中的DROP TABLE","correct":false,"feedback":"参数值不会因包含关键字就自动变成结构指令。"}],"output":"教学推演：标题按原文读取，tasks表仍存在，其他记录未变；此结果需要在独立测试库实际验证。","evidence":["读回标题与输入一致","表和非目标任务仍可查询"]}]},"practice":{"intro":"以模块08的本机前后端练习副本为起点，使用独立测试数据库与虚构记录，记录数据库文件或连接目标。本课目标：通过后端完成参数化增删改查与筛选","steps":["以现有SQLite接口连接测试库，固定驱动占位符用法，读取当前表与08.03接口合同。","创建带独特标题的新任务，保存ID；按ID更新标题和完成值，各核对影响行数。","实现已校验的done筛选与created_at、id稳定排序，再分页查看小数据集，解释每个条件改变的结果。","用含单引号和SQL样式文字的标题验证按值处理，最后仅删除本次演示ID并核对其他记录不变。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“通过后端完成参数化增删改查与筛选”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：以现有SQLite接口连接测试库，固定驱动占位符用法，读取当前表与08.03接口合同。；创建带独特标题的新任务，保存ID；按ID更新标题和完成值，各核对影响行数。；实现已校验的done筛选与created_at、id稳定排序，再分页查看小数据集，解释每个条件改变的结果。；用含单引号和SQL样式文字的标题验证按值处理，最后仅删除本次演示ID并核对其他记录不变。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["四类真实请求与同ID数据库结果","参数化调用片段、含引号标题的完整读回","筛选排序分页结果、影响行数与非目标记录保持证据"],"troubleshooting":[{"symptom":"更新提示成功却没有变化","check":"核对目标ID、WHERE条件与影响行数是否为0","action":"按合同处理不存在目标，修正传入ID后重试。"},{"symptom":"翻页时同一记录重复或漏掉","check":"检查是否有明确稳定排序以及测试期间数据变化","action":"补充稳定键排序，在固定测试集复验；复杂并发分页按需深入。"}]},"checks":[{"question":"WHERE条件忘写，UPDATE把全部标题改了，应该怎样恢复？","options":[{"text":"停止继续写入，在副本按恢复点恢复并修正范围","correct":true,"feedback":"先保留错误证据与可恢复版本，不能继续随机覆盖。"},{"text":"只改页面显示让错误看不见","correct":false,"feedback":"实际数据库已变化，隐藏不构成数据恢复或修复。"},{"text":"给查询加LIMIT就保证每种数据库都只改目标","correct":false,"feedback":"写入限制语法和语义因数据库而异，目标ID仍需明确。"}]},{"question":"参数化后是否就无需后端类型校验和权限？","options":[{"text":"不需要，绑定会自动完成登录授权","correct":false,"feedback":"驱动不知道请求者是否有权修改目标任务。"},{"text":"只需允许用户自由选择所有列名","correct":false,"feedback":"占位符一般用于值，结构片段仍需固定与白名单。"},{"text":"仍然需要，各自保护不同边界","correct":true,"feedback":"参数化防结构混淆，不能判断值是否符合业务或谁可访问。"}]}],"sources":[{"label":"SQLite：SELECT","url":"https://www.sqlite.org/lang_select.html","checked":"2026-10-16"},{"label":"SQLite：UPDATE","url":"https://www.sqlite.org/lang_update.html","checked":"2026-10-16"},{"label":"SQLite：DELETE","url":"https://www.sqlite.org/lang_delete.html","checked":"2026-10-16"},{"label":"Python sqlite3：占位符绑定","url":"https://docs.python.org/3/library/sqlite3.html","checked":"2026-10-16"}]},{"id":"09.05","title":"约束与索引各解决什么","lead":"“加一个索引”和“阻止空标题”都在数据库里做，为什么前者主要改变查找方式，后者却决定数据能不能进入？","goals":["验证数据库约束守住有效性并解释与后端校验的关系","按给定查询理解索引的用途和代价，不把独立性能调优作为统一门槛"],"sections":[{"title":"约束在写入边界维护规则","paragraphs":["后端可能有多条写入路径，导入、脚本和以后新增接口都可能漏掉校验。NOT NULL、CHECK、UNIQUE与外键把部分规则放到数据库入口，让不符合的数据不能悄悄进入。它们各管不同问题，不能一条约束代表所有有效性。","例如title NOT NULL只拒绝NULL，空字符串仍需检查；CHECK(length(trim(title))>0)再处理空白。done要限制允许值，ID要唯一且非空。数据库约束报错后，后端应转换成清楚响应并保护原有效记录，不把原始堆栈或数据库文件位置全部暴露。这里的trim示例覆盖普通空格；制表符和其他Unicode空白需要按统一业务规则另外处理。原始请求类型仍由后端检验，不能把数据库转换后合法误说成输入类型从未出错。"]},{"title":"索引提供额外查找路径","paragraphs":["没有合适索引时，数据库可能扫描很多记录再筛选；索引维护按某些字段组织的辅助结构，帮助特定查询更快找到候选。它不是把所有查询都加速的魔法，也不应被理解为改变任务的业务内容。","假设常查某归属下未完成任务并按创建时间排序，给定查询可对应(user_id, done, created_at, id)组合索引。字段顺序与查询条件相关，不是看到四个字段就随便排列。当前user_id条件只是演示查询，不证明可信用户授权已经落实。"]},{"title":"索引要付存储与写入成本","paragraphs":["每次新增、删除或修改相关列，索引也可能需要更新，因此索引占空间并增加维护工作。小测试表中扫描可能已经很便宜，索引前后计时几乎相同并不奇怪。不能凭一次毫秒差就断言设计有效，更不应为每一列都创建索引。","SQLite的EXPLAIN QUERY PLAN可以帮助观察扫描或索引选择。必修要求是读懂给定查询与一个相关索引的关系，知道怎样取得证据；独立设计复杂优化是深入内容。若真正慢，先确认实际查询、数据量与条件，再由Codex结合计划分析。"],"code":"CREATE INDEX idx_tasks_owner_done_created\nON tasks(user_id, done, created_at, id);\nEXPLAIN QUERY PLAN\nSELECT id, title, done FROM tasks\nWHERE user_id = ? AND done = ?\nORDER BY created_at, id LIMIT 20;\n-- ? 由SQLite访问驱动绑定；在支持绑定的工具中执行。"},{"title":"把有效性与性能分成两份验收","paragraphs":["约束验收直接尝试无效写入，记录数据库拒绝且有效旧记录不变；索引认识验收固定查询，比较计划与结果集合，说明索引帮助哪类条件、带来什么成本。索引存在不代表数据有效，数据有效也不代表查询性能已足够。","有些唯一索引还承担唯一性约束，说明实现机制可能交叉，但学习上仍需分清目标。不要把“建了索引”作为阻止空标题的依据，也不要把约束错误称为性能慢。保持两类证据独立，能让后续排错更准确。"]}],"glossary":[{"term":"约束","meaning":"数据库在写入等边界执行的规则，如非空、唯一或允许值。"},{"term":"索引","meaning":"为特定查找或排序维护的辅助结构，有存储和写入成本。"},{"term":"查询计划","meaning":"数据库准备如何扫描、查找与组合数据的说明，可辅助理解性能。"}],"predict":{"question":"空白标题仍能写入，开发者建议给title建普通索引，是否解决当前问题？","options":[{"text":"只把前端提示改红就足够","correct":false,"feedback":"其他写入入口仍可能绕过页面，数据库规则也应核对。"},{"text":"不能，应增加对应有效性规则并验证拒绝","correct":true,"feedback":"普通索引主要提供查找路径，不会自动禁止空白标题。"},{"text":"能，任何索引都会拒绝空值和空白","correct":false,"feedback":"普通索引不具备非空白、非空等全部业务约束。"}]},"experiment":{"title":"拒绝无效数据与查得更快分开看","brief":"使用带归属和完成字段的演示表，分别观察约束与给定查询计划。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"跳过后端直接写入","input":"任务表有非空标题CHECK，直接尝试插入三个空格标题；接口没有参与本次操作。","question":"这次直接写入检验了哪一层保障？","options":[{"text":"数据库约束能否独立阻止无效记录","correct":true,"feedback":"绕过页面和接口仍被拒绝，说明规则在数据入口执行。"},{"text":"浏览器表单required是否正确","correct":false,"feedback":"本次没有经过表单，无法用此结果证明前端校验。"},{"text":"索引已让全部查询性能提升","correct":false,"feedback":"拒绝写入没有提供性能比较或查询计划的证据。"}],"output":"教学推演：该插入被CHECK拒绝，原任务保持；后端仍应保留友好校验和错误映射。","evidence":["实际约束错误","失败后没有无效行且旧数据不变"]},{"name":"给定查询使用相关索引","input":"演示库按user_id和done筛选，再按created_at、id排序；新增相同顺序的组合索引。","question":"面对这个给定查询，最合理的观察是什么？","options":[{"text":"认为索引会自动补全非法user_id","correct":false,"feedback":"引用有效性属于外键等规则，不是普通索引职责。"},{"text":"强制初学者独立证明所有并发性能","correct":false,"feedback":"本课必修是机制认识，复杂优化不作为统一前置。"},{"text":"比较查询计划和结果，解释用途与维护成本","correct":true,"feedback":"要看实际选择，不凭索引名称保证任何数据规模都显著加速。"}],"output":"教学推演：计划可能使用相关索引，结果应不改变；小数据计时未显著下降也不构成业务失败。","evidence":["前后计划与相同结果ID集合","说明空间与写入维护代价"]}]},"practice":{"intro":"以模块08的本机前后端练习副本为起点，使用独立测试数据库与虚构记录，记录数据库文件或连接目标。本课目标：验证关键约束并解释一个给定索引","steps":["检查独立测试表实际DDL，列出非空标题、done允许值、ID唯一与已有外键的职责。","通过后端与数据库入口分别试不合法数据，确认拒绝和原记录保持，整理错误映射。","在含user_id、done、created_at、id的副本上执行给定筛选排序查询，再创建本课组合索引。","记录前后查询计划与结果一致性，用自己的话解释索引针对什么，不要求独立完成复杂调优。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“验证关键约束并解释一个给定索引”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：检查独立测试表实际DDL，列出非空标题、done允许值、ID唯一与已有外键的职责。；通过后端与数据库入口分别试不合法数据，确认拒绝和原记录保持，整理错误映射。；在含user_id、done、created_at、id的副本上执行给定筛选排序查询，再创建本课组合索引。；记录前后查询计划与结果一致性，用自己的话解释索引针对什么，不要求独立完成复杂调优。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["约束清单与两种入口的实际拒绝结果","给定查询、索引结构和前后查询计划","相同结果集合及索引成本与尚未优化范围说明"],"troubleshooting":[{"symptom":"加了NOT NULL仍有空标题","check":"检查空字符串、空白与NULL是否混淆","action":"增加对应非空白CHECK并在副本处理旧无效记录后验证。"},{"symptom":"建索引后速度看不出变化","check":"核对数据量、实际查询与计划是否使用索引","action":"先解释计划与成本，不凭一次短计时反复随机建索引。"}]},"checks":[{"question":"所有列都建索引是否是可靠默认方案？","options":[{"text":"只要有索引就无需WHERE条件","correct":false,"feedback":"索引不会替应用决定应该读取哪部分业务数据。"},{"text":"不是，应对应实际查询并考虑写入与空间成本","correct":true,"feedback":"冗余索引可能增加维护而对当前查询没有帮助。"},{"text":"是，因为读取更快就不可能有代价","correct":false,"feedback":"索引必须占空间并随数据变化维护，不能忽略代价。"}]},{"question":"约束测试失败后页面显示友好提示，能否不查数据库？","options":[{"text":"仍需核对无效行未进入且旧记录保持","correct":true,"feedback":"提示文案不能单独证明数据库拒绝或没有副作用。"},{"text":"可以，提示出现就证明全部写入失败","correct":false,"feedback":"应用可能先改了部分数据再显示错误，仍需查询记录才能确认无副作用。"},{"text":"应删除所有已有记录防止污染","correct":false,"feedback":"范围过大，且会丢失合法数据与原有诊断依据。"}]}],"sources":[{"label":"SQLite：表约束","url":"https://www.sqlite.org/lang_createtable.html","checked":"2026-10-16"},{"label":"SQLite：查询规划与索引","url":"https://www.sqlite.org/queryplanner.html","checked":"2026-10-16"}]},{"id":"09.06","title":"多步修改、事务与并发","lead":"完成任务后还要写一条操作记录，第二步失败，第一步却已经生效。怎样理解“要一起成功”，以及重复请求的另一种风险？","goals":["判断哪些多步业务需要共同成功或一起撤销","在预置隔离示例观察事务与重复请求，不把复杂并发设计作为统一门槛"],"sections":[{"title":"一项业务可能包含多次写入","paragraphs":["界面一次点击不一定只有一条数据库指令。比如完成任务同时写入操作记录，如果业务规定两者必须一致，第一步成功第二步失败就会出现“任务已完成但没有记录”。先说明哪些动作必须共同成功，再决定事务范围，不能因为步骤多就机械包住所有网络活动。","事务把一组数据库操作作为可提交或回滚的整体。提交确认这些变化，回滚撤销本事务中尚未提交的变化。数据库事务通常不能自动撤销已经发送的邮件、外部HTTP调用或浏览器状态，因此类比“一键撤回一切”有明确边界。"]},{"title":"失败需要正确回滚，不只写BEGIN","paragraphs":["在SQLite中，某些语句错误可能只撤销当前语句，之前在同一事务中的成功修改仍待处理；应用必须按策略执行ROLLBACK或由可靠事务封装处理。不能看到一次CHECK失败就声称整个业务自动回滚，必须查询实际结果。","隔离示例使用tasks与task_events：更新t61.done后，插入一条违反约束的事件，捕获错误并回滚；再查两表。没有事务的对照会留下部分状态。学习目标是解释前后差异，实际实现时要按所用驱动确认事务控制方式和异常出口。"]},{"title":"事务不自动消除重复业务","paragraphs":["同一创建请求发两次，即使每次都完整事务提交，也可能得到两个独立任务。事务保证每次内部一致，是否把两个请求视作同一业务操作，需要请求标识、唯一约束或其他明确策略。不能把“事务成功”误说成“重试绝无重复”。","并发还可能出现两端先读同一旧值、各自计算再写，导致一方变化覆盖另一方。需要根据业务选择原子更新、版本检查、锁或重试等办法，并理解数据库具体隔离机制。本课先能预测风险与收集证据，不强迫每位初学者独立设计复杂并发架构。"]},{"title":"在隔离示例形成可观察结论","paragraphs":["由Codex在测试库准备一条任务和约束明确的事件表，运行无事务中途失败、事务回滚、相同操作重复三种条件。每次先预测两表最终值，再运行并核对。错误信息、是否提交和记录集合要对应同一次操作，不能只看页面成功或失败。","若自己的项目目前只有单行更新，可先记录哪种新增需求会引入多步风险，继续09.07。不必为了完成本课人为增加复杂业务；当项目确有多步一致性需求时，再设计和验证合适事务与重试边界。实验结论只适用本次数据库和驱动条件。"]}],"glossary":[{"term":"事务","meaning":"把一组数据库操作按约定作为整体提交或回滚的机制。"},{"term":"回滚","meaning":"撤销当前事务中尚未提交的修改，不自动撤销外部副作用。"},{"term":"并发","meaning":"多个操作在时间上交错推进，可能影响同一数据的最终结果。"}],"predict":{"question":"同一创建请求重发两次，两次各自在完整事务中成功，是否必然只生成一条？","options":[{"text":"必然，任何事务都会比较所有请求内容","correct":false,"feedback":"数据库不会自动知道两个相同标题是否代表同一意图。"},{"text":"只要前端显示一条，数据库也只能有一条","correct":false,"feedback":"界面可能隐藏重复，必须核对实际记录集合。"},{"text":"不必然，还需识别同一业务操作的去重策略","correct":true,"feedback":"事务保证每次内部一致，不自动把两次独立请求合为一次。"}]},"experiment":{"title":"部分成功与重复成功","brief":"用预置测试表比较中途失败和重复请求；此案例不替你的项目执行事务。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"第二步失败后的回滚","input":"事务内先把t61.done置1，再插入违反非空约束的事件；应用catch明确ROLLBACK，初始done为0。","question":"正确回滚后，两表应观察到什么结果？","options":[{"text":"所有历史事件都会被清空","correct":false,"feedback":"回滚范围是本事务未提交变化，不是删除整张表历史。"},{"text":"t61仍为0且没有新事件，两表共同恢复","correct":true,"feedback":"事务中的更新未提交，显式回滚应撤销此前成功步骤。"},{"text":"任务必为1，因为第一条UPDATE已运行","correct":false,"feedback":"在未提交事务中执行过不代表回滚后仍保留。"}],"output":"教学推演：与无事务对照的部分成功不同，正确回滚后两表保持原状态；须实际查询确认驱动行为。","evidence":["错误发生步骤与ROLLBACK路径","两表前后记录对照"]},{"name":"两次完整事务重复创建","input":"相同标题请求到达两次，未提供稳定操作标识；每次都生成新ID并提交任务与事件。","question":"两次事务各自成功后，最可能还有哪种风险？","options":[{"text":"两组内部都一致，却产生两次业务效果","correct":true,"feedback":"没有去重规则时，事务无法识别这是一次意图的重试。"},{"text":"第二次一定自动回滚，因为标题相同","correct":false,"feedback":"标题可重复，除非明确唯一规则，否则无此保证。"},{"text":"事务会自动比较浏览器按钮的点击次数","correct":false,"feedback":"数据库无法凭UI动作判断业务意图是否重复。"}],"output":"教学推演：可能生成t62与t63各自有事件；若加入明确操作标识与唯一规则，再验证同标识重试行为。","evidence":["两次请求与生成ID","每组一致性和整体重复数量"]}]},"practice":{"intro":"以模块08的本机前后端练习副本为起点，使用独立测试数据库与虚构记录，记录数据库文件或连接目标。本课目标：在预置隔离示例解释事务与重复操作","steps":["让Codex在独立测试库准备tasks和task_events两表，事件含明确非空约束；输出起始记录与完整操作顺序。","先无事务执行更新任务后故意写非法事件，观察是否部分成功，再恢复测试起点。","改用所选驱动的明确事务控制，失败路径执行回滚，比较两表最终值；不在真实任务库做故障注入。","执行两次相同业务请求，解释事务为何不自动去重；若项目确有此需求，再制定稳定操作标识或版本策略并验证。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“在预置隔离示例解释事务与重复操作”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：让Codex在独立测试库准备tasks和task_events两表，事件含明确非空约束；输出起始记录与完整操作顺序。；先无事务执行更新任务后故意写非法事件，观察是否部分成功，再恢复测试起点。；改用所选驱动的明确事务控制，失败路径执行回滚，比较两表最终值；不在真实任务库做故障注入。；执行两次相同业务请求，解释事务为何不自动去重；若项目确有此需求，再制定稳定操作标识或版本策略并验证。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["预置表规则、起点与三种条件预测","无事务和正确回滚后的实际两表对照","重复请求的ID数量、风险解释和自己项目是否需要深入的决定"],"troubleshooting":[{"symptom":"第二步报错第一步仍留下","check":"核对是否提前commit，错误后是否明确rollback","action":"修正事务边界与异常出口，从干净测试起点复验。"},{"symptom":"有事务仍产生重复任务","check":"检查是否把两次请求当独立操作且无去重标识","action":"区分原子性与业务去重，再按真实需求设计唯一标识或核对流程。"}]},"checks":[{"question":"事务内发出外部邮件后数据库回滚，能否保证邮件被撤回？","options":[{"text":"能，事务包含代码里所有步骤","correct":false,"feedback":"数据库事务只控制其管理的相关数据库变化。"},{"text":"只要删除前端提示邮件就未发送","correct":false,"feedback":"显示变化不能撤销外部系统已经完成的发送动作。"},{"text":"不能，数据库回滚不控制已发生的外部副作用","correct":true,"feedback":"需要另外设计通知时机或补偿流程，不能扩大事务保证。"}]},{"question":"项目只有单行标题更新，本课必须新增复杂并发功能吗？","options":[{"text":"完全无需理解任何中途失败","correct":false,"feedback":"即使当前简单，也应理解未来多步需求的一致性边界。"},{"text":"不用，先理解示例并识别何时需要进一步设计","correct":true,"feedback":"课程要求认识机制与风险，实际复杂业务出现时再验证。"},{"text":"必须，否则无法继续数据库学习","correct":false,"feedback":"这把按需深入误当所有人的统一工程门槛。"}]}],"sources":[{"label":"SQLite：事务控制","url":"https://www.sqlite.org/lang_transaction.html","checked":"2026-10-16"},{"label":"SQLite：隔离与并发","url":"https://www.sqlite.org/isolation.html","checked":"2026-10-16"}]},{"id":"09.07","title":"结构变更、备份与持久验收","lead":"给任务加“优先级”后，新记录能用，旧任务却报错。备份文件也在，但怎样证明能真正恢复？","goals":["在测试副本迁移旧记录并验证新旧结构兼容","完成数据库备份恢复、服务重启和V2端到端持久验收"],"sections":[{"title":"改代码不等于改已有数据","paragraphs":["新增priority字段既影响表结构，也影响旧行的含义、接口输出和前端显示。直接让前端读取新字段，旧库可能没有列；只给新建记录填值，旧任务又可能缺失。迁移把旧结构有计划地变成新结构，要明确缺省、允许值和兼容范围。","例如优先级采用1普通、2重要、3紧急，旧任务统一作为1是一个可解释决定，而不是让AI随意猜每条的重要性。先写业务规则，再做迁移脚本；已有用户内容不应因为缺字段被清空。迁移前的恢复点和应用版本必须能对应。"]},{"title":"在副本执行可核对的变更","paragraphs":["SQLite可用ALTER TABLE添加满足限制的新列，具体行为要对照当前版本与官方说明。下面片段用于尚未有priority的测试表，给旧行合理默认与允许值；重复运行会因列已存在失败，因此实际迁移要有版本记录或先检查，不声称它天然幂等。","执行前记录行数与ID，执行后检查旧行priority和其他字段，再让新建、更新与筛选接口支持当前合同。应用和结构发布顺序也会影响兼容，复杂线上迁移留模块11、12；本课先在本机隔离副本完成可恢复变更。"],"code":"ALTER TABLE tasks ADD COLUMN priority INTEGER NOT NULL DEFAULT 1\nCHECK(typeof(priority) = 'integer' AND priority IN (1, 2, 3));\n-- 仅在测试库尚无priority时运行，迁移后核对旧行和版本记录。"},{"title":"备份有效要靠独立恢复证明","paragraphs":["数据库正在写入时，简单复制单个文件可能缺少必要状态，尤其涉及WAL等模式。应使用所选数据库的可靠备份接口，或明确停写并按官方要求处理。SQLite有备份API；Python sqlite3也提供连接backup方法，具体使用要依据实际驱动。","恢复必须指向新的测试位置，不覆盖唯一原库。先核对恢复后的结构、行数、关键ID与字段，再让应用连接恢复副本完成增改查。只有“有备份文件”不能说明可读、完整或应用兼容；还要记录恢复点之后哪些新增记录不在备份中。"]},{"title":"V2验收贯穿请求和持久来源","paragraphs":["本机V2通过应有：页面创建任务，后端校验并参数化写入，独立库查询一致，前端刷新可读，后端重启仍读同ID，旧任务迁移后可改，失败输入不污染，备份副本能恢复并操作。每条证据都指向实际环境，不能拿教材预制结果替代。","V2仍只在开发测试范围使用，不等于用户隔离版或线上正式版。模块10会加入身份与拒绝路径，模块11再部署。完成本课后保留版本、迁移说明、数据库目标、备份位置和已知限制，使后续继续工作不依赖记住整段聊天。"]}],"glossary":[{"term":"结构迁移","meaning":"按版本把既有表和数据变成新结构的可追踪过程。"},{"term":"恢复点","meaning":"备份所覆盖的数据时刻或版本，之后的变化可能不在其中。"},{"term":"持久验收","meaning":"跨连接或服务重启核对同一数据来源与记录，并验证恢复能力。"}],"predict":{"question":"新增priority后准备迁移，最合适的第一步是什么？","options":[{"text":"记录旧结构与数据并建立可验证恢复点，再在副本试迁移","correct":true,"feedback":"先保护可恢复来源，能观察旧行变化并避免直接损坏唯一数据。"},{"text":"清空旧任务，只验证新建记录","correct":false,"feedback":"这样避开旧数据兼容需求，也丢失已有有效内容。"},{"text":"只给页面新增一个优先级图标","correct":false,"feedback":"显示控件不会创建数据库列或补齐旧记录。"}]},"experiment":{"title":"旧行兼容与备份恢复分别验收","brief":"比较给旧任务补合理默认和备份后产生新数据的恢复范围。","boundary":"以下两个案例是预制教学推演，用来比较条件变化，并非本网站实时执行、联网调用或真实数据库的结果。独立实践必须在自己的环境重现并保存证据。","cases":[{"name":"旧任务补普通优先级","input":"测试库有t71、t72且无priority，迁移加非空整数列默认1，原标题与done应保持。","question":"哪项结果支持旧行迁移与新值规则正确？","options":[{"text":"旧任务删除后创建同名新ID","correct":false,"feedback":"这不是保留旧记录，归属关联和历史可能随之丢失。"},{"text":"页面显示优先级按钮就算迁移完成","correct":false,"feedback":"控件不证明数据库列、旧值和接口已正确。"},{"text":"旧ID与字段保持，priority为1，新值2和3可按规则写入","correct":true,"feedback":"兼顾旧数据语义、合法新值和原内容保持才能验证结构变更。"}],"output":"教学推演：旧行按规则为普通优先级，新建与更新支持合法值，非法4被拒绝；需要实际检查数据库与接口。","evidence":["迁移前后同ID完整字段","新旧任务读写与无效值拒绝"]},{"name":"恢复点之后还有新增","input":"备份时有t71、t72，之后新增t73；把备份恢复到独立副本，不覆盖当前库。","question":"恢复副本应怎样解释t73的缺失？","options":[{"text":"恢复会自动从任意浏览器找回全部新数据","correct":false,"feedback":"没有明确日志或同步机制就不能承诺补齐。"},{"text":"它在恢复点之后产生，备份范围不包含它","correct":true,"feedback":"备份有效与恢复点之后的数据损失范围需分别说明。"},{"text":"只要缺一条就证明备份文件必然损坏","correct":false,"feedback":"应先核对备份时间，不能把范围差异一概当损坏。"}],"output":"教学推演：副本只有t71、t72且操作正常，当前库保留t73；报告恢复点与缺失区间，不宣传零数据损失。","evidence":["备份时刻与两处ID集合","恢复副本的结构及实际操作"]}]},"practice":{"intro":"以模块08的本机前后端练习副本为起点，使用独立测试数据库与虚构记录，记录数据库文件或连接目标。本课目标：迁移优先级并完成V2持久化与恢复验收","steps":["记录当前版本、测试库绝对目标和旧任务ID，使用实际驱动可靠备份能力生成恢复点；不要复制忙碌数据库单文件作保证。","把备份恢复到独立新位置核对可读，再在迁移副本新增priority，明确1至3及旧行默认规则。","更新后端合同与前端状态，检查旧行仍可读写，新任务、非法优先级和失败输入的正确行为。","从页面创建新任务并对照数据库，刷新、停止重启后端再读同ID；重新验证恢复副本可增改查，整理V2证据与未完成权限说明。"],"prompt":"请先读取我的练习项目并说明当前实现，再完成“迁移优先级并完成V2持久化与恢复验收”。只修改与本课有关的文件，先复述输入、处理、输出和验收条件。具体要求：记录当前版本、测试库绝对目标和旧任务ID，使用实际驱动可靠备份能力生成恢复点；不要复制忙碌数据库单文件作保证。；把备份恢复到独立新位置核对可读，再在迁移副本新增priority，明确1至3及旧行默认规则。；更新后端合同与前端状态，检查旧行仍可读写，新任务、非法优先级和失败输入的正确行为。；从页面创建新任务并对照数据库，刷新、停止重启后端再读同ID；重新验证恢复副本可增改查，整理V2证据与未完成权限说明。。沿用现有已确认视觉；如需视觉变化先给一张原型待我确认。不能用预制数组或成功提示冒充实际请求、存储或数据库结果。给我最短启动说明、修改原因和可复现的正常及失败检查；若环境缺失请报告真实错误，不擅自创建付费资源、公开部署或上传材料。","evidence":["迁移前恢复点、结构版本和备份方法","旧新任务迁移字段及合法无效输入结果","端到端创建与重启同ID证据、独立恢复操作和恢复范围说明"],"troubleshooting":[{"symptom":"重复运行提示列已存在","check":"检查迁移版本记录和实际表结构","action":"先确认已应用状态，不删除列重做；为脚本补版本判断。"},{"symptom":"恢复副本少了最新任务","check":"对照备份恢复点和新增时刻","action":"区分范围内缺失与恢复点后数据，按备份策略说明可接受损失并保留当前库。"}]},"checks":[{"question":"应用连恢复副本能查列表，但编辑就报新字段不存在，说明什么？","options":[{"text":"数据可读不代表应用结构兼容，仍需迁移或匹配版本","correct":true,"feedback":"恢复验收必须覆盖结构与关键写入，不只看列表出现。"},{"text":"查到列表就可忽略编辑失败","correct":false,"feedback":"核心操作未通过，不能宣称可用恢复已完成。"},{"text":"应立即覆盖唯一当前库尝试修复","correct":false,"feedback":"先在副本定位兼容问题，不能用唯一数据冒险试验。"}]},{"question":"V2重启保存与恢复都通过，能否称线上用户隔离已完成？","options":[{"text":"能，数据库能恢复就会自动识别用户","correct":false,"feedback":"恢复不会替应用建立登录身份或授权规则。"},{"text":"只需把localhost链接发给朋友","correct":false,"feedback":"朋友的localhost指向他自己的设备，不是你的开发后端。"},{"text":"不能，身份权限与实际部署是后续独立验收","correct":true,"feedback":"持久化只证明数据链路的一部分，不包括所有用户与环境保证。"}]}],"sources":[{"label":"SQLite：ALTER TABLE","url":"https://www.sqlite.org/lang_altertable.html","checked":"2026-10-16"},{"label":"SQLite：备份API","url":"https://www.sqlite.org/backup.html","checked":"2026-10-16"},{"label":"Python sqlite3：备份接口","url":"https://docs.python.org/3/library/sqlite3.html","checked":"2026-10-16"}]},{"id":"10.01","title":"识别身份与判断权限","lead":"小林已经登录，为什么仍然不应该看到小周的任务？如果只是把小周的卡片藏起来，规则究竟由谁执行？","goals":["能用A本人、A访问B与未登录三种请求区分认证和授权。","能写出资源与动作权限矩阵，指出界面隐藏为什么不能证明拒绝。"],"sections":[{"title":"先证明是谁，再判断能做什么","paragraphs":["认证是核实请求者身份的过程，例如身份服务核验登录材料后，将当前请求关联到账户甲。授权是在身份可信的前提下，结合资源和动作决定是否允许。知道某人是图书馆读者，不等于允许他修改其他读者的借阅记录；身份与权限解决的是连续的两个问题。","个人任务工具中，甲可以读取和修改自己创建的任务；乙同样已登录，却不能修改甲的任务。相反，登录页面或公开说明可以允许未登录访问。因此规则必须写清“谁、什么资源、哪种动作、哪些条件”，不能简化成“登录后都允许”。"]},{"title":"权限必须到达真正的数据入口","paragraphs":["前端隐藏编辑按钮能减少误操作，但浏览器由使用者控制：他可以修改请求、直接调用接口或复用旧链接。真正的允许与拒绝应在服务端或可信的数据访问层决定，因为那里才控制读取和改变数据的能力。界面状态只能反映权限，不能成为最终证明。","例如甲的列表只展示甲的任务，看似正常；若详情接口只按任务编号查询，甲换成乙的编号仍可能获得完整内容。这说明列表过滤与对象权限不是一回事。要分别验收列表、详情、修改和删除，不能用一个正确页面推断所有入口都受保护。"]},{"title":"把规则做成可检查的矩阵","paragraphs":["先写一张小表：未登录请求私人列表应拒绝；甲读甲应允许；甲读乙应拒绝；甲改甲应允许；甲删乙应拒绝。新建时归属由可信身份产生，不由提交表单中的用户编号决定。表格把“好像安全”的感受变成一组可以逐项反驳的判断。","缺少明确允许条件时默认拒绝，避免新接口悄悄获得宽泛权限。但拒绝也需要保留正常功能：如果所有请求都被挡住，数据没有泄漏，却不能说明授权实现正确。至少同时观察一个允许请求和一个拒绝请求，才能排除“服务根本没运行”的假象。"]},{"title":"拒绝结果也需要证据","paragraphs":["接口可用一致的禁止或不可见响应表示无权限；有的设计用404避免透露对象存在，有的用403表达禁止，具体取决于应用约定。状态码本身不够，还应确认响应没有他人正文、数据库没有被改、页面没有把失败显示成保存成功。","记录时用甲乙代号与虚构任务，不保存真实会话或私人内容。证据只证明本次版本、这些入口和条件，不保证未来新增功能自动继承同样规则。后续每增加导出、搜索或批量修改，都应回到矩阵补充对应动作，而不是沿用一次验收的结论。"]}],"glossary":[{"term":"认证","meaning":"核实请求者是谁，身份来源必须可以在服务端验证。"},{"term":"授权","meaning":"按照身份、资源和动作作出允许或拒绝决定。"},{"term":"默认拒绝","meaning":"没有匹配到明确允许条件时，不授予该操作权限。"}],"predict":{"question":"甲已登录，直接请求乙的任务详情；列表没有显示乙。哪个结论成立？","options":[{"text":"仍需服务端检查归属并拒绝","correct":true,"feedback":"已登录只证明身份，列表隐藏不能控制详情接口。"},{"text":"列表已过滤，可让详情按编号读取","correct":false,"feedback":"列表与详情是两个入口，前者不能替后者授权。"},{"text":"改成难猜的任务编号就足够","correct":false,"feedback":"难猜只能降低偶然发现概率，不能替代权限检查。"}]},"experiment":{"title":"识别身份与判断权限：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"允许本人访问","input":"可信身份=A；任务t1.owner=A；动作=读取。","question":"按私人任务规则应如何处理？","options":[{"text":"拒绝，因为私人数据不能通过接口返回","correct":false,"feedback":"私人数据可向有权限者提供，全部拒绝破坏功能。"},{"text":"允许且只返回t1","correct":true,"feedback":"身份、资源归属和动作满足规则；A本人读取t1有明确允许依据。"},{"text":"允许并顺便返回B的任务便于筛选","correct":false,"feedback":"服务端应限制范围，不能依赖前端再过滤。"}],"output":"教学结果：200仅返回归属A的t1；同次可信身份为A，没有把B的记录交给客户端。","evidence":["核对返回任务归属为A","确认同一次请求的可信身份为A"]},{"name":"只换资源编号","input":"可信身份仍为A；任务t2.owner=B；动作=读取；页面按钮已隐藏。","question":"身份不变而资源改为B的t2，应如何处理？","options":[{"text":"允许，因为身份验证已通过","correct":false,"feedback":"身份成立不代表拥有他人资源权限；A即使登录也不拥有B的任务。"},{"text":"返回正文但让页面不展示","correct":false,"feedback":"网络响应已把内容交给请求者，隐藏无效。"},{"text":"拒绝且不返回t2正文","correct":true,"feedback":"权限判断必须随资源一起变化；t2归属B，不能沿用t1的允许决定。"}],"output":"教学结果：按约定返回404，响应不含t2正文；数据库内容与归属保持原状，B仍能正常读取。","evidence":["响应没有B任务正文","数据库t2及归属没有变化"]}]},"practice":{"intro":"起点是模块09的开发练习副本和两条虚构任务。还没有身份组件时先完成权限矩阵，保留实际请求验收为待完成。","steps":["用A、B、未登录三个身份列出列表、详情、新建、修改、删除规则，标记每项允许条件。","请Codex只读指出每个接口的认证入口和授权位置，对照矩阵找缺失项。","在已有授权的本地测试环境分别执行本人允许与跨账户拒绝；不要对第三方资源发请求。","保存匿名化响应与前后数据对照，把未运行项明确写为待验收。"],"prompt":"请在当前任务工具的测试副本整理权限矩阵：A/B两测试身份、未登录，资源为本人/他人任务，动作含列表、详情、新建、更新、删除。说明身份从哪里可信获得，标出服务端授权入口；在本地演示数据上检查允许和拒绝，给出请求方法、脱敏结果、数据前后对照。不要创建外部账户、上传材料或部署，不要记录令牌；若缺少前置条件，列出缺项而非宣称通过。","evidence":["权限矩阵及每项理由","本人请求成功的脱敏结果","跨账户请求拒绝且数据未变的结果","当前版本与未验收入口清单"],"troubleshooting":[{"symptom":"所有请求都拒绝","check":"检查服务是否启动、测试身份是否实际生效","action":"先修复一条本人成功路径，再判断跨账户拒绝是否来自授权。"},{"symptom":"页面看不到他人任务却能获取详情","check":"核对详情查询是否只按任务编号","action":"在可信数据入口加入归属判断，并重跑详情、更新与删除。"}]},"checks":[{"question":"新加导出接口，只复用前端筛选是否足够？","options":[{"text":"需要服务端对导出范围重新授权","correct":true,"feedback":"导出也是读取入口，必须限制数据范围。"},{"text":"够，因为页面列表已按用户过滤","correct":false,"feedback":"导出可能直接访问数据库，不能继承页面效果。"},{"text":"让文件名包含用户ID即可","correct":false,"feedback":"文件名不限制文件里的记录；导出接口仍可能把他人正文写进文件。"}]},{"question":"跨账户请求和本人请求都返回503，能否认定隔离成功？","options":[{"text":"能，因为没有泄漏信息","correct":false,"feedback":"没泄漏是本次现象，不能证明规则正常。"},{"text":"不能，需恢复本人成功路径再测","correct":true,"feedback":"服务不可用与权限拒绝具有不同原因；503不能区分权限保护和整个服务停机。"},{"text":"只要重试跨账户仍失败就能认定","correct":false,"feedback":"重复同一无区分力的条件不能补足允许证据。"}]}],"sources":[{"label":"OWASP：授权机制","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html","checked":"2026-10-16"}]},{"id":"10.02","title":"登录状态怎样被使用","lead":"页面右上角还显示头像，但保存却提示重新登录。头像、会话和后端认可的身份之间，究竟有什么关系？","goals":["能解释后端为何不能凭头像或请求自报编号认可身份。","能在测试环境核对登录、刷新、退出和过期后的请求与未写入结果。"],"sections":[{"title":"每次请求都要找到可信身份","paragraphs":["HTTP请求通常彼此独立，服务端不能凭“刚才有人登录过”认定当前请求属于谁。登录后，应用可通过会话标识或令牌，把后续请求与身份关联。浏览器保存并按规则发送材料，服务端再验证其有效性；头像只是前端保存的显示状态。","会话方案常由浏览器携带一个随机标识，服务端用它查找当前会话；另一类方案携带可验证的令牌。两者实现不同，但共同要求是不可相信随意填写的用户编号。自己把本地存储中的name改成管理员，不应使后端认可新的权限。"]},{"title":"有效不只意味着字符串存在","paragraphs":["有些令牌包含到期时间、签发方与面向的服务。后端必须按所用身份方案验证，不能只把字符串拆开读出用户字段。能阅读令牌内容不等于它真实有效，正如看得到证件上的姓名不等于已经核验了证件。","可靠身份组件可以处理许多细节，仍需要按官方要求配置回调地址、有效期与服务端验证。课程不要求初学者自造密码系统，也不把任意演示字符串当成安全会话。实际练习应采用当前项目支持的成熟组件，在独立演示账户中观察状态变化。"]},{"title":"刷新、退出和过期是不同条件","paragraphs":["刷新通常保留符合规则的Cookie或其他持久状态，所以可能继续登录；关闭某个标签页不一定退出。退出应按方案清除客户端材料并使相关服务端会话失效；短期令牌是否立即失效，取决于撤销机制，不能仅凭页面跳回登录页下结论。","过期后，受保护接口应拒绝无效身份，页面明确引导重新认证，保留可以保留的非敏感草稿。若只是继续显示旧数据而悄悄丢弃保存，用户会误以为修改已生效。应以请求响应与再次读取为准，区分“旧页面仍在”与“新操作获准”。"]},{"title":"Cookie属性解决的是部分风险","paragraphs":["Cookie的发送受域、路径、HTTPS与SameSite等条件影响。HttpOnly能阻止普通页面脚本直接读取该Cookie，但不代表浏览器不能发送它，也不单独解决跨站请求伪造。跨源页面、子域变化与HTTPS上线，都可能改变身份材料是否随请求到达。","排错先看请求是否携带身份、后端为何不认可，再检查配置，不要把完整Cookie或令牌粘贴进聊天。日志只写会话检查结果、匿名身份与关联编号。通过登录、刷新、退出、过期四组操作，才能发现只测一次登录所覆盖不到的边界。"]}],"glossary":[{"term":"会话","meaning":"把一组请求与一个已认证身份关联起来的状态或机制。"},{"term":"令牌","meaning":"由系统签发、需要按规则验证的身份或访问凭证。"},{"term":"HttpOnly","meaning":"限制页面脚本读取Cookie的属性，不等于整个应用免受攻击。"}],"predict":{"question":"头像还在，受保护保存接口返回401，最该核对什么？","options":[{"text":"头像是否使用最新图片","correct":false,"feedback":"头像变化不能解释身份材料的有效性；旧头像与可用会话可能同时出现不同状态。"},{"text":"先在前端把本地登录标记重新设为已登录","correct":false,"feedback":"本地标记只能改变界面，不能让过期或缺失的会话通过服务端验证。"},{"text":"请求身份是否携带且通过后端验证","correct":true,"feedback":"页面显示可能过时，后端才决定该次身份是否有效。"}]},"experiment":{"title":"登录状态怎样被使用：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"刷新仍有效","input":"A在有效会话中刷新；请求携带符合规则的会话材料。","question":"刷新后私人列表该如何取得？","options":[{"text":"服务端验证后返回A的列表","correct":true,"feedback":"刷新没有必然使会话失效，仍需逐次验证。"},{"text":"不验证直接使用头像中的ID","correct":false,"feedback":"显示信息不能代替可信身份；姓名可由客户端修改，服务端还需验证会话。"},{"text":"必须创建新账户","correct":false,"feedback":"刷新不要求重新注册；已有账户与有效会话的恢复不需要重复注册。"}],"output":"教学结果：验证成功后重新发起请求，取得A的两条演示任务；刷新没有让服务器省略身份检查。","evidence":["确认是新请求而非旧页面缓存","确认后端身份为A"]},{"name":"令牌已经过期","input":"同一浏览器、同一页面，令牌已超过有效期，未配置自动续期。","question":"令牌已过期且没有续期，保存请求应怎样结束？","options":[{"text":"先写入数据库，稍后再验证","correct":false,"feedback":"写入在验证前发生会越过身份边界；应在确认身份有效后才允许数据库改变。"},{"text":"拒绝并引导重新登录","correct":true,"feedback":"有效性发生变化，旧头像不能延长凭证。"},{"text":"把请求里的用户ID当备用身份","correct":false,"feedback":"不可信字段不能修补认证失败；自报编号与过期令牌一样不能证明身份。"}],"output":"教学结果：保存返回401，数据库未新增记录；页面明确提示重新登录，没有把旧头像当作有效会话。","evidence":["保存前后记录一致","页面没有显示保存成功"]}]},"practice":{"intro":"起点是已选择可靠身份组件的本地开发副本。若没有可用登录环境，本课可完成推演，实际登录证据保持待完成。","steps":["记录组件版本和当前官方登录、退出、过期处理说明，先确认采用会话还是令牌。","使用已有A测试身份登录，读取本人任务；刷新后再读取，观察新请求。","退出后重新发受保护请求；按组件支持的方法在测试环境演练过期，记录结果。","核对失败时没有写入，页面给出恢复入口，保存脱敏证据并删除不必要的抓包材料。"],"prompt":"请检查当前测试副本的身份组件，解释登录后每次请求怎样得到可信身份，列出组件版本与官方依据。只使用已有演示身份，验证登录、刷新、退出、过期四种状态的受保护读取与保存；检查失败不写入、页面可重新登录。不要输出密码、Cookie或令牌，不创建外部账户或部署；不支持安全过期演练时请说明限制与替代测试方案。","evidence":["组件与验证位置说明","四种状态的匿名化请求结果","退出或过期后未写入的对照","重新登录后恢复正常的结果"],"troubleshooting":[{"symptom":"刷新后突然未登录","check":"看Cookie是否符合域、路径、Secure与SameSite条件","action":"依据组件当前文档修复对应属性，再测刷新和退出，避免通过关闭验证绕过问题。"},{"symptom":"退出后旧凭证仍可用","check":"确认采用服务端会话、撤销列表还是短期令牌","action":"按方案实现撤销或说明有效期边界，不能只删除头像后称已失效。"}]},"checks":[{"question":"把令牌解码读到了A，能直接认为请求属于A吗？","options":[{"text":"可以，字段已经有用户ID","correct":false,"feedback":"攻击者也可能构造相同字段；可构造字段不代表能生成可信签名或会话。"},{"text":"只需核对前端头像一致","correct":false,"feedback":"两个可修改的客户端值相同仍不是验证。"},{"text":"还要验证签名或会话、有效期和适用范围","correct":true,"feedback":"读取字段不证明它由可信系统签发；解码只展示声称内容，验证才检查真实性。"}]},{"question":"HttpOnly已经启用，还要检查什么？","options":[{"text":"后端验证、发送条件和跨站请求保护","correct":true,"feedback":"HttpOnly只限制脚本读取Cookie，保护范围有限。"},{"text":"不必再处理退出","correct":false,"feedback":"Cookie可读性与会话失效不是同一机制。"},{"text":"只检查浏览器能否复制Cookie","correct":false,"feedback":"复制操作不能检验完整认证链路；还需观察后端拒绝、数据未变和恢复行为。"}]}],"sources":[{"label":"OWASP：会话管理","url":"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html","checked":"2026-10-16"},{"label":"MDN：Cookie发送与属性","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Cookies","checked":"2026-10-16"}]},{"id":"10.03","title":"将规则落实到数据访问","lead":"把请求中的userId从A改成B之后，列表竟然换成了另一个人的任务。为什么“前端已经传了用户编号”反而是危险信号？","goals":["能指出可信用户身份怎样进入读取、新建、更新和删除的归属规则。","能在测试副本替换他人任务编号与owner，检查拒绝且他人数据未变。"],"sections":[{"title":"用户提交的归属只是声称","paragraphs":["浏览器可提交标题、筛选条件和任务编号，但不能替后端决定自己是谁。后端应从已验证会话得到A，再决定A能访问哪些记录。提交userId=B只是输入数据，既不能证明B在操作，也不能授予A管理B任务的能力。","新建任务时，任务归属由可信身份确定。若接受表单中的owner字段，甲可能替乙创建任务，甚至借助后续逻辑读取数据。更新时也不应任由使用者把owner改成别人；除非业务明确支持受控转移，并有独立的授权规则。"]},{"title":"查询条件同时限制对象与归属","paragraphs":["只按任务编号寻找记录，会把“找到对象”和“有权访问”混在一起。个人任务的读取或更新可以同时限定任务编号与当前用户归属，让不属于A的记录不进入本次可操作范围。不同架构可能在服务层或数据库策略落实，关键是可信入口执行一致规则。","例如更新t2时，输入是taskId=t2、title=新标题，可信身份=A。系统按id=t2且owner=A寻找目标，若t2属于B则不更新。使用参数化查询还处理输入与SQL指令的分离，但它解决注入问题，不能自动补上归属条件，两种保护缺一不可。下面是帮助阅读职责的伪代码，不是可直接运行的库API。"],"code":"user = verifySession(request)\ntask = findTask(id=request.taskId, owner=user.id)\nif task is missing: return notFound()\nreturn updateAllowedFields(task, title=request.title)"},{"title":"每条写入路径都要守规则","paragraphs":["列表安全不代表批量更新、删除、搜索与导出同样安全。尤其是更新接口若把整个请求体直接写入，可能允许改变owner等不该由用户决定的字段。明确可修改字段，并在授权之后执行写入，可以减少意外扩大操作范围。","规则写在数据库行级策略中时，还要核对后端使用的数据库角色是否会绕过策略；写在服务端时，要检查是否存在另一个不经过该服务的公开入口。不能因为某个框架提供了权限功能，就假设当前连接和所有接口已经正确启用。"]},{"title":"用替换标识检验真正的边界","paragraphs":["验收从本人正常操作开始，再只换资源编号或提交归属，观察相同动作是否被拒绝。读请求关注响应是否含他人正文，写请求还要在数据库核对受影响行和归属。对不存在编号的测试也有价值，但不能代替对确实存在的他人记录测试。","拒绝后应验证B仍能读取原始内容，A仍可修改自己的任务，从而排除服务停机、数据被误删或所有更新都失效。记录只保留演示编号、状态和变化摘要，不保存认证材料。这样的证据能够具体指出规则在何处生效、还有哪些入口没覆盖。"]}],"glossary":[{"term":"可信身份","meaning":"由服务端认可的会话或令牌验证得到的用户，而非请求自报编号。"},{"term":"归属条件","meaning":"将一条记录与允许访问它的用户或组织联系起来的限制。"},{"term":"行级策略","meaning":"数据库根据当前身份等条件控制哪些行可访问的机制，需核对角色与配置。"}],"predict":{"question":"A请求更新t2并传owner=B，t2实际属于B，应如何决定？","options":[{"text":"字段一致就更新","correct":false,"feedback":"两项输入一致不能证明请求者有权；身份必须从已验证会话取得而非表单推断。"},{"text":"依据可信身份A和实际归属拒绝","correct":true,"feedback":"客户端owner不能为A创造访问B资源的权限。"},{"text":"先更新标题但保持owner不变","correct":false,"feedback":"保留归属并不能使越权修改合法；哪怕owner不变，A改变B标题仍是越权。"}]},"experiment":{"title":"将规则落实到数据访问：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"本人修改","input":"可信身份A；t1.owner=A；提交title=买牛奶。","question":"A更新本人t1时，应由什么依据决定归属？","options":[{"text":"全部用请求体覆盖记录","correct":false,"feedback":"可能意外覆盖归属与其他受保护字段；owner不属于普通标题编辑允许的字段。"},{"text":"每次更新时重新采用请求体里的owner作为归属","correct":false,"feedback":"更新不能让客户端自行更改归属，应依据可信身份和已有资源规则。"},{"text":"保留已有归属A，仅修改允许字段","correct":true,"feedback":"身份与归属已满足规则，标题是可修改字段。"}],"output":"教学结果：t1标题更新为买牛奶，owner仍为A；只修改允许字段，没有覆盖其他账户记录。","evidence":["受影响记录仅t1","owner未由请求体覆盖"]},{"name":"只换归属和编号","input":"可信身份A；t2.owner=B；提交taskId=t2、owner=A。","question":"将输入owner改成A会怎样？","options":[{"text":"仍拒绝，查询须依据真实归属","correct":true,"feedback":"请求输入不能先改归属再通过权限检查。"},{"text":"允许，因为提交owner等于当前身份","correct":false,"feedback":"这会允许攻击者先声称拥有任意记录；攻击者可将任何目标都自报为自己的对象。"},{"text":"不返回拒绝，只忽略修改并向页面报告成功","correct":false,"feedback":"虽然没有改数据，但虚报成功会误导使用者，也掩盖权限判断的实际结果。"}],"output":"教学结果：更新被拒绝，B再次读取t2内容与归属完全一致；A仍可正常更新本人t1作对照。","evidence":["拒绝响应无t2正文","B读取前后内容相同"]}]},"practice":{"intro":"起点是开发副本、已有A/B测试身份、A的t1与B的t2演示记录。只在拥有操作权限的练习资源上测试。","steps":["定位列表、详情、新建、更新、删除的数据访问函数，标明可信身份进入的位置。","为各入口写出对象范围和可写字段，检查新建归属不由浏览器决定。","在测试副本中先完成本人操作，再替换成已存在的他人编号与owner字段。","对照数据库及B的正常读取，确认拒绝未造成变化，重跑本人操作。"],"prompt":"请审查当前练习项目的数据归属规则：从已验证身份得到user，不能信任请求中的owner/userId。检查列表、详情、新建、更新、删除和批量入口；只允许适当字段写入。使用A/B演示数据测试本人允许、跨账户编号替换、伪造owner与未登录请求，提交脱敏请求、响应及前后记录。先在本地副本修复，不连接生产数据库，不打印秘密。","evidence":["每个入口的规则与落点","本人正常读写结果","替换编号和伪造归属被拒绝的结果","B记录未变化与A仍可正常操作的对照"],"troubleshooting":[{"symptom":"写接口安全但导出泄漏","check":"核对导出是否绕过现有数据访问函数","action":"统一可信范围限制，为导出补独立拒绝用例。"},{"symptom":"行级策略存在仍可越权","check":"核对实际数据库连接角色是否绕过策略","action":"按架构调整角色或服务端检查，在同一连接方式下重新验收。"}]},"checks":[{"question":"参数化查询已经防SQL注入，还缺什么？","options":[{"text":"只需让任务ID更长","correct":false,"feedback":"长度不会限制有意提交其他编号；攻击者已知他人编号时长度完全无保护作用。"},{"text":"仍需对对象归属和动作授权","correct":true,"feedback":"输入安全与访问权限分别解决不同问题。"},{"text":"不再需要检查owner","correct":false,"feedback":"参数化不会自动知道业务归属规则；必须由业务实现显式加入可信归属条件。"}]},{"question":"跨账户修改返回404，但B的标题变了，如何判断？","options":[{"text":"算通过，因为没有显示成功","correct":false,"feedback":"失败提示不能撤销已经发生的越权；拒绝必须发生在副作用之前而非仅返回错误。"},{"text":"只需把404改成403","correct":false,"feedback":"更换状态码无法修复写入顺序；需要移动或补充授权检查而非修改响应文字。"},{"text":"授权失败，拒绝可能发生在写入之后","correct":true,"feedback":"实际数据变化比响应文案更直接；B的标题被改直接说明权限未守住写入。"}]}],"sources":[{"label":"OWASP：逐请求授权与对象权限","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html","checked":"2026-10-16"}]},{"id":"10.04","title":"密钥、配置与浏览器可见信息","lead":"数据库密码写在.env里就安全了吗？如果构建工具把它塞进网页脚本，文件名还剩下多少保护作用？","goals":["能依据实际能力区分公开配置与服务端秘密，并追踪构建和响应流向。","能用虚构标记检查泄漏出口，解释撤销轮换为何不同于删除文件。"],"sections":[{"title":"先按能力判断信息是否可公开","paragraphs":["API公开地址、产品名称与可公开项目标识通常用于连接服务，不一定是秘密。数据库管理密码、服务端高权限凭据和模型服务密钥则赋予调用或读写能力，应保留在可信服务端。不能根据字符串长得复杂就认定它秘密，也不能因为变量叫config就认为可公开。","判断方法是问：拿到它的人能做什么、是否还需要其他可信授权。某些平台专门提供可公开客户端标识，并要求依靠用户认证和数据规则限制访问；高权限服务密钥则可能绕过规则。具体性质应查所用平台当前官方说明，不能照搬另一个产品的命名习惯。"]},{"title":"环境变量不是自动保密容器","paragraphs":["环境变量是进程获取配置的一种方式。服务端进程读取秘密并仅在服务端使用，可以减少源码硬编码；但前端构建若把变量替换成JavaScript字面量，最终下载到浏览器的内容就是公开的。是否保密取决于实际流向，不取决于它最初是否在.env文件里。","例如网页调用自己的后端，后端再用服务密钥调用数据库，浏览器只得到业务结果。如果网页直接携带同一服务密钥发送请求，任何使用者都能在网络面板观察它。压缩代码、改变量名或禁用右键无法撤回已经发送的信息。"]},{"title":"检查源码之外的三个出口","paragraphs":["源码仓库只是一处可能泄漏的位置，还应检查构建产物、网络响应与日志。开发时没有提交.env，不保证打包后的脚本没有它；后端正确保管凭据，不保证错误响应不会输出完整连接字符串；截图也可能意外记录可用令牌。","检查时用变量名、结构和受控的虚构标记定位流向，结果只保存“出现在哪个文件或响应”，不要反复复制真实秘密。查看前端产物属于只读验证，实际替换凭据或改线上配置则要在明确授权的资源和范围内进行，避免随手影响他人服务。"]},{"title":"泄漏后先失效，再修复传播路径","paragraphs":["发现可用凭据暴露后，删除文件或覆盖网页不能让已被复制的秘密失效。应按服务提供方支持的方式撤销或轮换，更新合法服务的配置，核对依赖恢复正常，并查看可用的访问记录。具体步骤和影响范围取决于凭据类型与平台。","历史仓库、构建缓存和日志可能仍含旧值，需要清理与限制访问，但清理不能替代轮换。更换后重新构建，再查产物和网络，才能证明传播路径已修复。不要把“已经隐藏一行代码”当成完整处理，也不要把所有公共配置一律删掉导致应用无法连接。"]}],"glossary":[{"term":"秘密","meaning":"持有后可获得不应公开能力的凭据，例如服务端管理密钥。"},{"term":"轮换","meaning":"让旧凭据失效并为合法服务替换新的凭据，需要验证相关服务。"},{"term":"构建产物","meaning":"由源码处理生成、可能发送到浏览器或部署平台的文件。"}],"predict":{"question":"服务密钥从.env读入后，被打包到前端脚本，属于什么情况？","options":[{"text":"已向浏览器公开，需要撤销或轮换并修复流向","correct":true,"feedback":"起点是环境变量不改变最终内容可被下载的事实。"},{"text":"安全，因为仓库没有.env","correct":false,"feedback":"仓库范围不能代表浏览器产物范围；未提交源配置仍可能把值嵌入下载脚本。"},{"text":"加密脚本文件名后即可继续使用","correct":false,"feedback":"可被前端使用的秘密仍可从运行过程取得。"}]},"experiment":{"title":"密钥、配置与浏览器可见信息：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"服务端保管","input":"前端只请求/api/tasks；后端在运行环境读取演示秘密，不在响应中回传。","question":"在这种服务端保管方案中，应检查哪些结果？","options":[{"text":"看到API地址就判断泄漏","correct":false,"feedback":"公开地址通常不是秘密本身；浏览器知道服务地址通常是连接所需信息。"},{"text":"浏览器没有秘密且业务请求仍受用户权限限制","correct":true,"feedback":"保管秘密与业务授权都需要成立；服务秘密不泄漏也不自动赋予用户访问权。"},{"text":"后端有秘密就可省略用户验证","correct":false,"feedback":"服务凭据不能替代每个用户的权限判断。"}],"output":"教学结果：前端产物和响应只有公开地址与允许任务数据，秘密标记未出现；归属检查仍在服务端执行。","evidence":["浏览器产物无秘密标记","请求仍有身份和归属检查"]},{"name":"构建时嵌入","input":"源码未提交.env；前端包中出现可用服务密钥；旧包已被下载。","question":"删除.env之后应如何处理？","options":[{"text":"只重新压缩脚本","correct":false,"feedback":"压缩不会让凭据丧失调用能力；同一可用凭据换种排版仍具有相同权限。"},{"text":"只清浏览器缓存","correct":false,"feedback":"别人可能已经复制凭据，缓存不是唯一副本。"},{"text":"撤销旧密钥、修复构建流向并重新验收","correct":true,"feedback":"删除源文件无法使已下载值失效；使用者可能已经复制并在别处继续调用。"}],"output":"教学结果：处理计划要求旧值失效、新值仅留服务端，并核对访问与构建结果；此处未真实轮换。","evidence":["计划包含撤销旧值","计划包含合法服务恢复与产物复查"]}]},"practice":{"intro":"起点是可只读检查的练习仓库、构建目录和浏览器网络面板。先使用虚构的SECRET_DEMO标记演练，不往前端注入真实凭据。","steps":["列出每项配置的用途、使用位置、公开或秘密判断与官方依据。","在测试副本用虚构标记追踪环境变量如何进入构建与响应，查看仓库忽略规则。","检查脚本、响应、错误日志和截图是否出现不应公开的信息，只记录位置与类别。","编写泄漏处理演练清单；实际轮换仅在另行授权后进行，并验证业务恢复与旧值失效。"],"prompt":"请只读检查当前练习项目的配置流向，区分公开API地址/客户端标识与服务端秘密；以平台官方说明为依据，不输出任何真实值。检查源码、构建产物、网络响应和日志，必要时在本地副本用虚构标记验证。提交配置分类表与泄漏位置摘要，给出撤销轮换、更新服务、复查产物的处理步骤。不要连接生产、轮换真实凭据或发布。","evidence":["配置分类及能力解释","产物与响应检查位置摘要","虚构标记的流向结果","泄漏处理和合法服务复查清单"],"troubleshooting":[{"symptom":"前端无法连接服务","check":"检查是否误删公开地址或客户端必需配置","action":"恢复允许公开的配置，秘密调用改经服务端，重新检查权限。"},{"symptom":"清理后旧密钥仍可调用","check":"核对是否执行服务端撤销而非仅删除文件","action":"按已授权范围轮换并验证旧值失效，不继续传播旧值。"}]},"checks":[{"question":"公开客户端标识是否一定能当管理密钥使用？","options":[{"text":"不能，应查它赋予的能力及配套权限规则","correct":true,"feedback":"不同凭据能力不同，名字和外观不足以判断。"},{"text":"能，只要知道项目地址","correct":false,"feedback":"地址和客户端标识不自动拥有管理权限。"},{"text":"不能，因此客户端可不做授权","correct":false,"feedback":"可公开不代表它自行承担所有业务规则。"}]},{"question":"前端包没有秘密，错误响应却含数据库连接密码，是否通过？","options":[{"text":"通过，因为源码没问题","correct":false,"feedback":"最终接收者可从响应取得可用秘密；后端泄漏的连接值同样可被复制和滥用。"},{"text":"没有，网络响应也是泄漏出口","correct":true,"feedback":"正确保管还要求不把秘密发送给客户端。"},{"text":"把错误字体缩小就可以","correct":false,"feedback":"显示样式不限制响应内容访问；网络面板与直接请求都能取得完整内容。"}]}],"sources":[{"label":"OWASP：秘密生命周期与轮换","url":"https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html","checked":"2026-10-16"}]},{"id":"10.05","title":"两账户独立验收","lead":"A和B都能登录，列表也不同，这就足以宣布V3完成吗？一次有区分力的验收还需要哪些请求和数据证据？","goals":["能建立真正隔离的A/B测试身份，并完成本人正常操作与跨账户拒绝对照。","能提交包含版本、目标环境、脱敏响应与数据未变结果的V3验收矩阵。"],"sections":[{"title":"两账户是用来改变一个条件","paragraphs":["只用A测试本人任务，最多说明正常路径工作。增加B的目的，是在服务、版本、动作尽量相同的情况下改变归属，观察规则是否随之变化。两账户必须确实有不同可信身份，两个标签页如果共用同一Cookie，可能仍然是同一个人。","可使用独立浏览器配置、支持隔离的容器或其他可靠方式保持两个会话。先通过受保护的当前身份接口或服务端脱敏记录确认A/B，再创建带不同标记的演示任务。不要凭页面显示的昵称判断，因为旧状态或手动修改可能制造假象。"]},{"title":"允许与拒绝组成完整对照","paragraphs":["每个账户应能列表、查看、新建、更新和删除自己的记录；还要对对方已存在的记录尝试详情、更新与删除，并伪造新建归属。未登录条件单独检查。这样既验证可用性，也验证没有把可见范围之外的能力交给使用者。","尤其应验证被拒绝的写操作没有改变数据。只看到403提示，不能排除写入先发生、响应后拒绝。让B重新读取自己的原记录，并对照标题、归属和存在性，才能发现响应看似正确但数据已经受损的实现错误。"]},{"title":"把过程记录成可复核的证据","paragraphs":["每条记录包括版本、环境、匿名身份、动作、资源归属、预期、实际响应和数据变化。用A-任务一、B-任务一这样的虚构标记代替私人材料。完整Cookie、密码和服务密钥都不属于验收报告应保存的内容。","如果请求返回空列表，要区分“被权限范围过滤”“账户确实没有任务”和“接口没有连接到预期环境”。准备已知演示数据并核对目标地址，能让空结果具有解释力。没有已知起点的截图很难证明规则，因为它也可能来自空数据库或错误版本。"]},{"title":"结论限定在版本和覆盖范围","paragraphs":["V3的阶段结论应表述为：在指定开发测试环境、指定版本和列出的入口上，本人路径成功、跨账户与未登录路径按规则拒绝。教学推演、阅读完成和手动勾选都不能替代这些实际请求，缺少身份环境时应公开保留待验收项。","以后新增导出、共享或团队功能，权限矩阵会发生变化，需要重做相关检查；此前全部通过不代表新功能自动安全。失败时定位到身份、查询、写入或环境，返修对应课程，重跑受影响的对照，而不是仅重新截图好看的列表。"]}],"glossary":[{"term":"测试矩阵","meaning":"将身份、动作与资源条件组合成可逐项核对的记录。"},{"term":"隔离会话","meaning":"让两个测试账户的身份材料互不混用的浏览器或客户端环境。"},{"term":"负向验证","meaning":"主动检查不应允许的操作确实被拒绝且未造成变化。"}],"predict":{"question":"A窗口和B窗口都显示不同昵称，但请求中的可信身份都是A，测试有什么问题？","options":[{"text":"只要列表不同就能验收","correct":false,"feedback":"列表不同也可能来自缓存或过滤输入；两组不同列表不能弥补可信身份相同的缺陷。"},{"text":"再新增十条任务即可","correct":false,"feedback":"增加数据量不能解决身份条件错误；新增任务仍可能全部归同一会话身份所有。"},{"text":"没有真正改变账户条件，需先隔离会话","correct":true,"feedback":"昵称不证明身份，两组请求实际来自同一账户。"}]},"experiment":{"title":"两账户独立验收：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"正常与拒绝均成立","input":"A/B可信身份不同；双方本人更新成功；A改B的任务被拒绝；B复查记录未变。","question":"对于该版本的更新入口，这组对照支持什么？","options":[{"text":"支持该版本该更新入口的隔离结论","correct":true,"feedback":"正常与跨账户路径以及未变证据形成对照。"},{"text":"支持所有未来新增接口都安全","correct":false,"feedback":"证据范围不能超出已测版本与入口；详情、新建和删除等入口尚需分别验证。"},{"text":"只能证明页面按钮工作","correct":false,"feedback":"材料包含真实接口和数据结果，范围大于按钮显示。"}],"output":"教学结果：该版本更新入口此项可通过；本人成功与他人拒绝且未变成立，其他动作仍逐项验收。","evidence":["身份已区分","本人成功与跨账户拒绝","B记录未变"]},{"name":"拒绝提示掩盖变化","input":"A请求删除B任务收到403；B刷新后该任务消失。","question":"403之后B的任务消失，该删除项应怎样判定？","options":[{"text":"通过，因为返回了403","correct":false,"feedback":"响应码不能推翻实际副作用；删除已经发生就不能称该次请求被安全拒绝。"},{"text":"失败，必须查写入与授权顺序","correct":true,"feedback":"数据被删除说明拒绝没有守住实际边界。"},{"text":"让B重新建一条就可通过","correct":false,"feedback":"补回数据不等于修复越权原因；必须修复授权顺序并重测相同跨账户动作。"}],"output":"教学结果：删除项失败，暂停V3通过结论；先在副本恢复演示记录，再修复授权顺序并重跑原检查。","evidence":["B原记录不存在","报告标为失败而非通过"]}]},"practice":{"intro":"起点是已有身份和归属规则的V2开发副本，两个获准使用的测试账户，以及可重新生成的无敏感任务。","steps":["建立两个隔离会话，确认可信身份不同，分别创建A-检查与B-检查任务并记录编号。","完成双方本人列表、详情、新建、更新、删除；为删除准备专用演示记录。","逐项替换为对方编号、伪造owner，并检查未登录请求；拒绝后由原主人复查。","整理完整矩阵、失败返修和重测结果，只有实际完成项才记录通过。"],"prompt":"请在已有授权的本地测试环境协助执行V3验收，使用现有A/B演示账户并先确认会话隔离。覆盖列表、详情、新建、更新、删除的本人成功、跨账户拒绝与未登录拒绝；被拒绝的写入要由原主人复查未变。报告包含版本、目标环境、预期/实际、脱敏请求结果和数据对照，不保存令牌；不要创建外部账户、碰生产数据或发布。","evidence":["两账户可信身份区分依据","完整动作与身份矩阵","被拒绝写入的数据前后对照","失败修复与原步骤重测记录"],"troubleshooting":[{"symptom":"两边操作互相切换账户","check":"核对窗口是否共享同一浏览器会话","action":"改用真正隔离的客户端环境，重新确认身份后从起点测试。"},{"symptom":"拒绝后他人数据变化","check":"检查授权检查是否发生在写入之后","action":"先在副本恢复演示记录，修复授权顺序，再重测允许与拒绝两路。"}]},"checks":[{"question":"已测列表、详情，但新增批量删除，是否仍可沿用原结论？","options":[{"text":"可以，都是任务接口","correct":false,"feedback":"共同名称不保证共同授权逻辑；新增批量入口可能绕过原来的权限函数。"},{"text":"只查按钮是否隐藏即可","correct":false,"feedback":"浏览器按钮不是可信数据边界；攻击者可以绕过按钮直接提交删除请求。"},{"text":"应补批量删除的本人和跨账户检查","correct":true,"feedback":"新入口有新查询和写入范围，需要独立证据。"}]},{"question":"没有身份环境，只做完本课推演，怎样记录最准确？","options":[{"text":"概念练习完成，实际V3验收待完成","correct":true,"feedback":"明确区分教材结果与自己的系统行为；推演帮助理解规则，实际应用还未接受请求检验。"},{"text":"V3通过，因为答案都选对","correct":false,"feedback":"理解题不能证明实际系统隔离；课堂答题不能证明数据库拒绝了越权操作。"},{"text":"无需继续记录任何进度","correct":false,"feedback":"阅读与概念成果仍可以诚实记录；可分别保存阅读、概念与实际验收的状态。"}]}],"sources":[{"label":"OWASP：授权测试与逐入口校验","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html","checked":"2026-10-16"}]},{"id":"11.01","title":"拆清部署对象与环境","lead":"自己的电脑上完全正常，朋友却打不开localhost。问题可能不在代码，而在“这个地址究竟指向谁、哪个组件在哪里运行”。","goals":["能画出前端、后端、数据库与身份服务的运行位置和请求方向。","能解释localhost随设备改变，并列出不同环境的配置和数据去向。"],"sections":[{"title":"网页文件与运行中的服务不同","paragraphs":["前端通常是浏览器下载后执行的HTML、样式与脚本；后端是接收请求并执行业务规则的服务；数据库保存结构化记录。它们可能由同一平台承载，也可能分开，不能因为都叫“网站”就假设发布一个文件夹会自动启动所有组件。","例如任务页面能显示标题，却始终无法保存，可能只是静态资源发布成功，后端没有运行。反过来，后端健康接口可访问，不代表前端已经改用线上API，也不代表数据库权限正确。部署图需要画出实际请求方向，而不只是三个漂亮方框。"]},{"title":"localhost随访问者改变","paragraphs":["localhost指访问者当前使用的本机。你在电脑上访问本机后端能成功，朋友在自己的手机输入同样地址时访问的是手机本身，不会神奇地连接到你的电脑。若服务只监听本地接口，即便知道电脑局域网地址也未必能访问。","线上版本需要使用目标使用者可达的地址，并满足网络、HTTPS、身份与权限条件。本课先理解链路，不要求把自己的电脑直接暴露到公网。把开发端口转发出去也不是完成正式部署，因为运行、数据、更新与秘密管理仍缺少稳定安排。"]},{"title":"环境把相同代码与不同配置分开","paragraphs":["开发环境便于修改和观察，测试环境用于演练，正式环境供预期用户使用。相同代码可连接不同数据库和身份回调，因此版本相同不保证数据相同。环境是代码、配置、运行资源和数据去向的组合，不能仅靠页面角落一个“测试版”标签识别。","应为每个组件列出运行地址、版本、配置来源、数据环境及负责人。例如测试前端若误接正式后端，随手删除演示任务就可能触碰真实数据。练习采用无敏感数据和独立副本，访问前先核对目标，而不是操作出问题后才猜环境。"]},{"title":"部署图为故障提供分段线索","paragraphs":["将一次保存画成浏览器→前端地址提供脚本→API地址接收请求→数据库写入→响应返回。每段标明谁执行代码、谁保存秘密、谁可以访问。平台提供的代理或一体化部署可能让地址看起来相同，但内部职责仍存在。","检查时依次问：页面资源是否取得、请求是否到后端、后端是否连接数据库、写入后能否再次读回。哪一段缺证据，就保留不确定性。此图也能帮助选择平台：先确认它承载的是静态文件、长期服务还是按请求运行的函数，再查对应当前官方部署要求。"]}],"glossary":[{"term":"部署","meaning":"把明确版本及配置放到目标运行环境，并验证可用的过程。"},{"term":"环境","meaning":"一组相互配合的代码、配置、运行资源与数据去向。"},{"term":"localhost","meaning":"访问者自己设备的本机地址，不代表开发者电脑。"}],"predict":{"question":"朋友能打开页面但保存请求指向localhost:3000，最合理解释是什么？","options":[{"text":"数据库一定已损坏","correct":false,"feedback":"请求可能根本未到数据库，证据不足；应先查看浏览器究竟将请求送到何处。"},{"text":"前端仍请求朋友自己的本机，应核对API配置","correct":true,"feedback":"localhost由请求所在设备解释，页面可见不代表后端连通。"},{"text":"让朋友使用相同端口，保留localhost地址","correct":false,"feedback":"端口相同仍指朋友自己的设备，不能把本机地址变成开发者的服务地址。"}]},"experiment":{"title":"拆清部署对象与环境：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"静态页已发布","input":"前端地址可访问；脚本请求https://api.example.test；API服务尚未启动。","question":"当前只能看到首页，这一现象能证明什么？","options":[{"text":"证明整个应用可以保存","correct":false,"feedback":"静态文件返回不代表业务链路完成；任务接口可能尚未运行或尚未连接数据库。"},{"text":"证明数据库权限正确","correct":false,"feedback":"数据库可能还没收到任何请求；不能从网页标题可见推断数据保存权限。"},{"text":"只能证明相关前端资源可访问","correct":true,"feedback":"后端运行与数据库写入尚无证据；首页只是文件可见，保存链路尚未跑通。"}],"output":"教学结果：首页资源能显示，保存接口失败且未新增数据库记录；当前仅证明前端文件可访问。","evidence":["前端资源返回成功","API无业务响应","记录数量未变"]},{"name":"地址未随环境改变","input":"同一前端改用localhost:3000；手机没有运行后端。","question":"手机点击保存会请求哪里？","options":[{"text":"手机本机","correct":true,"feedback":"地址由手机浏览器解释；所以它尝试连接手机而非开发者电脑。"},{"text":"开发者电脑","correct":false,"feedback":"localhost不含开发者电脑的路由信息。"},{"text":"自动转到数据库","correct":false,"feedback":"浏览器不会自动补齐未知部署链路；必须明确填写可达API或配置代理规则。"}],"output":"教学结果：手机尝试连接本机失败，线上后端没有对应请求；原因是客户端仍使用localhost目标。","evidence":["网络目标是localhost","线上后端无对应关联记录"]}]},"practice":{"intro":"起点是V3开发副本和项目启动说明。本课只制作部署图与清单，不要求购买资源或发布。","steps":["列出前端、后端、数据库、身份服务，确认各自职责及目前运行位置。","画一次读取和一次保存的地址链路，标明秘密留在何处。","为开发、测试、正式三种环境分别列配置名与数据去向，用“未准备”标记缺项。","请Codex按当前选定平台官方资料核对承载方式，形成待授权的发布准备清单。"],"prompt":"请只读分析当前V3项目，输出前端资源、后端运行、数据库和身份服务的部署图，标明浏览器请求地址、可信验证位置、秘密位置及数据环境。解释localhost在不同设备上的含义；按开发/测试/正式整理配置清单与缺项。若尚未选平台，提供承载能力对照，不创建账户或资源，不付费、不上传、不部署。","evidence":["组件职责与实际运行位置","读取和写入的地址链路","环境及数据去向清单","待准备条件和官方依据"],"troubleshooting":[{"symptom":"不知道某个文件属于前端还是后端","check":"检查它在哪个进程执行、是否发送给浏览器","action":"按实际执行位置归类，不能只按文件夹名字判断。"},{"symptom":"页面可开但数据为空","check":"核对请求目标与连接的数据环境","action":"先确认已知演示数据所在库，逐段检查，不急着重新导入。"}]},"checks":[{"question":"前后端同一域名，是否意味着没有后端部署职责？","options":[{"text":"是，只部署前端文件即可","correct":false,"feedback":"同域名不能自动执行服务端业务；仍要有运行进程或函数处理业务请求。"},{"text":"仍需确认代理之后的运行入口与数据库连接","correct":true,"feedback":"地址相同不代表运行组件相同；同一域名可能经代理转交给独立服务。"},{"text":"只要数据库存在即可","correct":false,"feedback":"数据库存在不意味着请求能到达或获准。"}]},{"question":"测试页面连到正式数据库，最先做什么？","options":[{"text":"先删除一条已知任务，以确认是否真连到正式库","correct":false,"feedback":"这会把排查变成真实数据修改，应先只读核对连接配置和目标环境。"},{"text":"改页面标题为测试版","correct":false,"feedback":"显示标签不能改变连接去向；标题修改不会改变后端数据库连接配置。"},{"text":"停止写入并核对配置与目标","correct":true,"feedback":"避免继续把测试操作送向真实数据；先停止可避免继续删除或新增正式记录。"}]}],"sources":[{"label":"Twelve-Factor：配置与环境","url":"https://12factor.net/config","checked":"2026-10-16"},{"label":"Twelve-Factor：服务端口绑定","url":"https://12factor.net/port-binding","checked":"2026-10-16"},{"label":"MDN：客户端与服务端职责","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Client-Server_overview","checked":"2026-10-16"}]},{"id":"11.02","title":"准备可重复的发布版本","lead":"“我电脑上能跑”还缺什么？如果换一个空目录就无法启动，发布依赖的东西可能从未被写进项目说明。","goals":["能整理明确版本、运行时、依赖、构建产物与启动配置的发布说明。","能在独立干净目录按说明运行，发现并修复未声明的文件或全局依赖。"],"sections":[{"title":"版本需要能被准确指认","paragraphs":["发布版本是确定的源码状态与相应构建结果。可用版本标识、提交编号或保存的发布包加校验信息关联它们。只说“最新文件”不够，因为两台电脑可能拥有不同的最新状态；修复问题时也无法判断用户正在使用哪一版。","记录版本不是要求初学者背Git命令，而是让源码、构建日志与线上标记能互相对应。开发目录里有尚未保存的修改、临时文件或本机图片时，复制其中一部分可能产生无法重现的组合，需要明确哪些属于发布输入、哪些只是个人环境。"]},{"title":"依赖声明把隐形前置写出来","paragraphs":["项目可能依赖特定运行时、包版本、系统能力和配置名。依赖清单描述需要什么，锁文件在支持的包管理器中固定解析结果，减少不同时间安装得到不同组合的概率。它们不保证所有环境完全相同，运行时和系统差异仍要记录。","以npm项目为例，存在合适锁文件时npm ci适合干净安装，并会检查清单与锁文件是否一致；但课程不是要求所有项目都运行它。没有npm的静态站点不必为了“规范”额外加依赖。先识别技术栈，再采用项目对应的可重复安装方法。"]},{"title":"构建与启动是不同阶段","paragraphs":["构建把源码处理成目标产物，例如将多个前端模块打包；启动让后端实际监听请求。构建成功说明工具完成了转换，不等于服务已经运行，也不等于业务数据能保存。某些静态项目没有构建步骤，某些平台会代为构建，应据实际项目说明。","发布清单写清工作目录、构建命令、产物目录、启动命令、运行时版本和配置名，秘密值通过合适渠道配置。反例是依赖桌面上一张未纳入项目的图片，或依赖全局安装但没有记录的工具：本机成功、新环境失败，正是可重复性检查要发现的问题。"]},{"title":"干净目录是有意义的验证条件","paragraphs":["在新的练习目录，仅用发布说明和已声明输入安装、构建、启动，能暴露旧缓存与未声明文件带来的假成功。不要把原项目清空来制造干净环境；使用独立副本，既保留恢复点，又让缺项容易观察。","验收包括核心页面资源、后端健康检查和一条演示读写，记录实际版本及命令结果。若失败，应补充遗漏说明或修复项目后从干净条件重测。不要把手动从旧目录复制缺失文件当作最终修复，否则发布说明仍无法让另一人重现。"]}],"glossary":[{"term":"锁文件","meaning":"记录依赖具体解析结果的文件，作用依所用包管理器而定。"},{"term":"构建","meaning":"把源码转换为目标运行或发布文件的步骤，不等于服务已启动。"},{"term":"可重复发布","meaning":"使用明确输入和说明，在新环境得到可核对运行结果的能力。"}],"predict":{"question":"构建成功，但新目录启动时提示找不到桌面上的配置文件，说明什么？","options":[{"text":"存在未声明的环境依赖","correct":true,"feedback":"发布需要的输入没有完整包含在说明与配置安排中。"},{"text":"说明构建工具一定出错","correct":false,"feedback":"构建和启动依赖不同阶段，不能直接归罪构建工具。"},{"text":"只需复制整台电脑","correct":false,"feedback":"这样隐藏缺项，不能形成可重复说明；别人仍不知道哪些文件和配置才是必需输入。"}]},"experiment":{"title":"准备可重复的发布版本：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"干净安装成功","input":"Node版本已记录，清单与锁文件匹配，配置名齐全，按说明安装构建启动。","question":"安装构建成功后，仍必须补哪项运行证据？","options":[{"text":"直接复用旧目录依赖，省略新目录运行检查","correct":false,"feedback":"旧依赖可能掩盖缺失声明，不能证明发布说明能在干净环境运行。"},{"text":"核心流程实际运行结果","correct":true,"feedback":"安装日志不能证明任务读写行为正确；还需执行新增并回读等实际用户行为。"},{"text":"只保留构建日志，不再检查启动和业务行为","correct":false,"feedback":"构建转换成功不说明后端已运行，也不证明任务能够保存和重新读取。"}],"output":"教学结果：新目录按说明启动，演示任务添加后可重新读回；记录源码与运行版本均为r17。","evidence":["安装构建日志","运行版本r17","读写后再次读取结果"]},{"name":"旧目录缓存掩盖问题","input":"旧目录可运行；新目录安装发现清单与锁文件不一致。","question":"新目录发现依赖记录不一致，应如何推进？","options":[{"text":"直接上传旧node_modules","correct":false,"feedback":"可暂时掩盖错误，还可能带来平台差异。"},{"text":"先跳过锁文件检查，用任意可安装版本发布","correct":false,"feedback":"这样改变依赖组合并掩盖记录冲突，之后无法可靠重现当前发布输入。"},{"text":"修复依赖记录并在新目录重试","correct":true,"feedback":"一致输入是可重现条件，不宜绕过检查。"}],"output":"教学结果：发布准备暂未通过，清单与锁文件不一致被记录；修复依赖声明后须重新干净安装验收。","evidence":["错误指向依赖记录","未把旧目录成功替代新环境结果"]}]},"practice":{"intro":"起点是保存好的V3版本和一个新的空练习目录。不要删除原目录或拷贝真实秘密。","steps":["整理运行时、依赖安装、构建、产物、启动、配置名与演示数据准备说明。","从确定的源码版本复制到独立目录，只使用声明过的文件和工具。","按说明执行适用的安装与构建，再启动并跑一条核心读写；静态项目如实写无构建。","记录版本和结果，修复缺项后重新从干净条件验收。"],"prompt":"请为当前项目整理可重复发布说明：运行时版本、包管理器和锁文件、工作目录、构建/启动命令、产物目录、配置名称、演示数据。使用工作区内新的练习副本验证，勿删除原项目、拷贝真实.env或连接生产。检查一条核心读写并记录版本；发现未声明文件或全局依赖时先解释再修复。不要上传或部署。","evidence":["确定的源码与产物版本","完整可执行说明","干净目录安装构建启动结果","核心流程实际结果及缺项修复记录"],"troubleshooting":[{"symptom":"新目录找不到资源文件","check":"检查是否引用项目外绝对路径","action":"把合法发布资源纳入明确目录或声明获取方式，重跑验证。"},{"symptom":"本机可装而新目录失败","check":"核对运行时、锁文件、工作目录和网络错误","action":"根据最小错误修复对应条件，不盲目升级全部依赖。"}]},"checks":[{"question":"纯静态页面不需要构建，应怎样写发布说明？","options":[{"text":"明确无构建并标明实际发布文件和验证方式","correct":true,"feedback":"可重复性取决于真实输入，不取决于步骤数量。"},{"text":"必须加入npm才能发布","correct":false,"feedback":"工具选择应服从项目实际需要；静态文件可以按真实范围直接发布和检查。"},{"text":"没有构建就无需版本","correct":false,"feedback":"静态文件同样会变化，也需要追踪；发布后的样式或脚本差异同样需能定位版本。"}]},{"question":"只复制缺失文件到新目录后成功，何时算完成？","options":[{"text":"复制成功当下即可","correct":false,"feedback":"遗漏仍存在于交接流程；接手者按原说明仍会在相同位置失败。"},{"text":"补齐正式输入和说明后从干净条件重测","correct":true,"feedback":"一次手工修补不能证明别人能复现；正式输入清单仍可能漏掉刚手工复制的文件。"},{"text":"只让旧目录再启动一次","correct":false,"feedback":"重复旧条件无法检验缺失输入；要去掉旧缓存才有机会暴露未声明前置。"}]}],"sources":[{"label":"npm：干净安装与锁文件","url":"https://docs.npmjs.com/cli/v11/commands/npm-ci/","checked":"2026-10-16"},{"label":"GitHub：Node构建与测试流程","url":"https://docs.github.com/en/actions/tutorials/build-and-test-code/nodejs","checked":"2026-10-16"}]},{"id":"11.03","title":"准备线上数据库","lead":"后端终于能连接一台线上数据库，为什么还不能马上把应用接过去？连得上、表正确、权限正确和能恢复是四件事。","goals":["能分别核对线上练习库的连接、结构迁移、应用角色与数据范围。","能在副本验证旧记录处理与备份恢复，再列出需授权的真实准备步骤。"],"sections":[{"title":"连接串决定真实数据去向","paragraphs":["连接信息可能包含主机、库名、身份与加密要求。线上后端使用哪组配置，决定它读写哪套数据；前端页面名字不能改变这一点。将开发库复制到线上之前，先明确它是否含私人资料，以及是否适合进入当前服务区域与访问范围。","课程练习只使用无敏感演示数据，并要求有独立目标环境。数据库凭据由后端保管，不能为省配置步骤塞进浏览器。不同托管服务对网络访问、连接方式和TLS要求不同，实际操作应查选定平台当前官方说明，不照搬控制台截图。"]},{"title":"迁移让结构变化可追踪","paragraphs":["数据库迁移是对表、列、约束等结构的有序变更，例如为任务增加priority字段。代码发布不会自动确保表结构同步，后端可能已尝试读priority，而线上库尚无此列，结果连接成功仍然请求失败。","把迁移写成有版本的步骤，并在副本先执行，观察已有记录如何处理。给新列增加非空约束时，需要考虑旧记录的值；直接删列则可能不可逆丢数据。迁移失败后能否安全重跑，取决于脚本和事务安排，不能一概认为再点击一次即可。"]},{"title":"能连接不代表权限恰当","paragraphs":["应用账户应只拥有当前业务所需能力。管理连接适合做受控结构操作，却未必适合长期承接所有用户请求；拥有绕过行级策略的角色更需要注意。上线前用实际应用连接身份验证允许与拒绝，而不是只用管理员连接测试成功。","网络限制也不是用户授权的替代品：后端所在网络被允许连接，只表明这条链路可达；它仍要按每位用户的身份限制任务。反过来，用户权限正确却没有网络连通，也无法工作。将连接、结构、应用角色与用户隔离分别记录，问题才容易定位。"]},{"title":"变更前准备可恢复依据","paragraphs":["恢复点可以是可验证的逻辑备份、平台支持的快照或其他适合方案，范围和恢复条件并不相同。先确认包含数据、结构及必要配置的哪些部分，再在独立副本试恢复。只有一个下载文件名，不能证明它足以让应用重新运行。","创建线上资源可能涉及账户、地区、费用和访问控制，本课程制作不会替学习者自动执行。独立实践先完成准备文件；实际创建与导入仅在明确授权的练习资源中进行。完成后记录版本、迁移顺序、演示记录数量与恢复点，避免把教学推演当真实准备。"]}],"glossary":[{"term":"迁移","meaning":"以可追踪顺序改变数据库结构或相关数据的步骤。"},{"term":"应用连接角色","meaning":"应用运行时用于访问数据库的身份，应限制为必要能力。"},{"term":"恢复点","meaning":"可用于恢复某个范围和时刻数据的依据，需验证其可用性。"}],"predict":{"question":"线上库连接成功，但接口报priority列不存在，最可能缺哪一步？","options":[{"text":"让前端多刷新几次","correct":false,"feedback":"刷新不能替数据库新增列；重试同一请求无法生成数据库缺失字段。"},{"text":"先让前端请求体附带priority字段再尝试保存","correct":false,"feedback":"提交字段不会在数据库自动创建对应列，仍需匹配的结构迁移。"},{"text":"应用所需结构迁移尚未到位","correct":true,"feedback":"网络连通不意味着表结构与代码匹配；priority仍需由匹配迁移在目标库中创建。"}]},"experiment":{"title":"准备线上数据库：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"结构与版本匹配","input":"目标练习库为空；先执行建表迁移m1，再导入三条无敏感任务，应用角色权限受限。","question":"结构导入完成后，应补哪项应用角色检查？","options":[{"text":"用应用实际身份读写并验证隔离","correct":true,"feedback":"管理员导入成功不代表业务连接和规则正确。"},{"text":"先用管理员连接测试，成功就沿用为应用验证","correct":false,"feedback":"管理员可能绕过限制，应使用应用实际运行角色核对读写和拒绝。"},{"text":"只截图表名即可","correct":false,"feedback":"表存在不证明操作与权限；还要用实际运行角色检查正常与拒绝路径。"}],"output":"教学结果：应用实际运行角色可完成所需读写；跨账户请求拒绝且他人记录未变，迁移版本已记录。","evidence":["迁移记录m1","三条演示记录","应用角色与隔离结果"]},{"name":"增加必填字段","input":"已有三条任务无priority；迁移直接新增无默认值的非空字段。","question":"旧记录缺少新字段，为何必须先在副本验证？","options":[{"text":"旧记录会自动理解业务含义","correct":false,"feedback":"数据库不会自动知道正确优先级；旧记录的业务含义需要明确补值规则。"},{"text":"旧记录可能不满足新约束","correct":true,"feedback":"结构要求与旧数据可能冲突，需定义补值或分阶段迁移。"},{"text":"构建前端就能补齐数据库","correct":false,"feedback":"前端构建不改变已有记录；新脚本与旧数据是独立的持久状态。"}],"output":"教学结果：迁移准备被阻止，因为旧记录缺少必填值；改为定义补值再验证约束，未操作真实线上库。","evidence":["列出旧记录处理规则","保留变更前恢复依据"]}]},"practice":{"intro":"起点是已确定技术栈、迁移文件与无敏感演示数据。尚无获准使用的线上练习库时，先在本地独立副本验证准备步骤。","steps":["记录目标环境、版本、官方连接要求、应用角色及配置名，不抄录秘密。","在副本应用全部迁移，并对已有演示记录验证新增字段和约束。","建立可用恢复点并在另一个副本验证；整理未来线上操作和停止条件。","只有取得目标资源操作授权后才创建或连接线上练习库，执行迁移导入并用应用角色验收。"],"prompt":"请为当前项目准备线上数据库迁移包，先只在独立本地副本验证。列出目标结构、迁移顺序、已有数据处理、应用角色权限、连接配置名称和官方依据；使用三条虚构演示数据，验证正常读写与归属限制。给出变更前恢复点和副本恢复结果。不创建账户、付费资源或线上库，不上传数据、不输出连接秘密；实际线上准备保留为待授权步骤。","evidence":["迁移顺序与结构版本","旧数据处理和约束验证","应用角色读写及拒绝结果","恢复点范围与副本恢复结果"],"troubleshooting":[{"symptom":"连接成功但业务报表不存在","check":"核对库名、schema与已执行迁移版本","action":"确认连接到正确环境后执行缺失迁移，勿在未知库反复建表。"},{"symptom":"迁移失败后不知道是否执行一半","check":"检查事务、迁移日志与实际结构","action":"先在副本确认状态和恢复方案，再决定修复或重跑，避免重复破坏数据。"}]},"checks":[{"question":"用管理员连接验证了读写，足以证明应用权限正确吗？","options":[{"text":"足够，因为使用同一个数据库","correct":false,"feedback":"相同数据库内不同角色的权限不同；管理员成功不能推出应用角色能力恰当。"},{"text":"只要任务数量正确就足够","correct":false,"feedback":"数量不能证明跨账户拒绝；需要本人成功和他人拒绝形成权限对照。"},{"text":"不足，需用运行时实际角色验收","correct":true,"feedback":"管理员可能拥有额外能力或绕过限制；运行时受限角色可能得到不同结果。"}]},{"question":"要删除旧字段，最先确认什么？","options":[{"text":"代码兼容性、数据去向和可恢复依据","correct":true,"feedback":"删列可能影响旧版本并丢失不可重建数据。"},{"text":"只看前端是否还显示该字段，不查旧版本依赖","correct":false,"feedback":"当前页面没有显示不代表后端、旧客户端或导出不再依赖该列。"},{"text":"是否能通过重启恢复字段内容","correct":false,"feedback":"重启不会凭空恢复已删除值；删列内容必须有独立备份或其他恢复依据。"}]}],"sources":[{"label":"PostgreSQL：修改表结构","url":"https://www.postgresql.org/docs/current/ddl-alter.html","checked":"2026-10-16"},{"label":"PostgreSQL：备份范围与方法","url":"https://www.postgresql.org/docs/current/backup.html","checked":"2026-10-16"}]},{"id":"11.04","title":"部署后端与配置环境","lead":"平台显示“部署成功”，业务接口却没有响应。构建、启动、路由和数据库连接分别在哪一步决定服务能不能用？","goals":["能根据日志区分构建失败、启动失败和业务请求失败。","能按平台运行模型准备入口与配置，用健康和业务读写证据分别验收。"],"sections":[{"title":"先识别平台实际运行模型","paragraphs":["后端可能作为长期运行的进程，也可能由平台在请求到来时启动函数。两种方式对入口、端口、超时和文件持久性的要求不同。先看当前平台官方部署说明，识别项目所需运行时与支持方式，不能把本机启动命令机械复制到所有平台。","长期服务往往需要监听平台要求的端口和可达接口；函数平台则依赖指定导出或路由约定。课程示例只讲检查对象，不虚构通用控制台按钮。平台界面和套餐会变化，记录查看日期与所用运行模型比背下截图路径更可靠。"]},{"title":"区分构建失败与启动失败","paragraphs":["构建失败发生在生成或准备发布内容时，例如依赖缺失、语法错误；启动失败发生在运行进程初始化时，例如缺少必需环境变量。请求失败则可能在服务已启动后出现，例如某个数据库操作权限不足。三类证据应从相应阶段日志获得。","如果安装日志成功，却没有监听记录，应查看启动入口与运行时；如果健康接口成功、任务接口500，应查看该次业务请求。反复重新发布但不阅读最小错误，只会增加版本混乱。将日志与发布标识关联，才能确定看到的是刚发布的实例。"]},{"title":"环境变量需要进入正确时机","paragraphs":["服务端秘密通过平台适当配置进入运行环境；变量名存在不代表值正确，也不代表本次部署已读取新值。有的平台更新配置后需要新部署或重启生效，具体按官方机制。配置需区分构建时和运行时使用，避免把秘密作为前端构建输入。","数据库地址、身份验证配置与允许来源都要指向同一测试环境。日志可提示“缺少DATABASE_URL”，不应打印完整值。用是否存在、目标环境代号和验证结果定位，通常比把秘密贴进错误报告更有用，也更容易安全地交给协作者。"]},{"title":"健康检查只回答有限问题","paragraphs":["简单健康接口可说明服务当前能响应，不一定访问数据库；更深入的就绪检查可包含必要依赖，但也应限制敏感输出与开销。返回“ok”不能替代登录、归属和真实读写检查，否则后端可能活着，业务却完全不可用。","验收先看启动与基础响应，再用测试账户完成一条读取和一条写入，核对数据环境及拒绝路径。明确区分预期请求失败与服务异常：未登录401可能是正确行为，数据库断连500才是另一类问题。保存脱敏证据，为前端接通提供明确后端基线。"]}],"glossary":[{"term":"运行入口","meaning":"平台实际调用以启动服务或处理请求的代码位置。"},{"term":"健康检查","meaning":"验证服务某一层可响应的检查，范围由其实现决定。"},{"term":"就绪","meaning":"服务具备处理预期业务所需条件的状态，不能只看进程存在。"}],"predict":{"question":"健康接口200，任务保存500，下一步最有价值是什么？","options":[{"text":"认定平台完全不可用","correct":false,"feedback":"健康响应说明至少部分服务可用；服务基础可达不代表保存依赖也满足要求。"},{"text":"关联保存请求检查业务日志与数据库条件","correct":true,"feedback":"基础响应已成立，需缩小到失败的业务链路。"},{"text":"让健康接口直接返回固定成功，掩盖业务失败","correct":false,"feedback":"固定成功不能帮助解释保存失败，还会让监测误认为依赖已经就绪。"}]},"experiment":{"title":"部署后端与配置环境：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"启动配置缺失","input":"依赖安装成功；运行日志提示缺少数据库配置；服务没有监听。","question":"安装完成却未开始监听，这属于哪一失败阶段？","options":[{"text":"前端跨源失败","correct":false,"feedback":"还没有可响应后端，跨源不是当前首要证据。"},{"text":"任务授权正确拒绝","correct":false,"feedback":"没有具体受保护请求被处理的证据；当前是在启动前失败，尚不能评价任务权限。"},{"text":"启动失败","correct":true,"feedback":"失败在运行初始化，不是已经接收业务请求。"}],"output":"教学结果：推演定位到运行配置或入口检查，尚未处理业务请求；修正后应再核对启动与健康响应。","evidence":["安装完成记录","启动错误位置","没有业务监听记录"]},{"name":"服务活着但依赖异常","input":"健康接口200；A保存返回500；同一关联编号日志显示数据库连接被拒绝。","question":"健康可达而保存连接被拒绝，应优先检查什么？","options":[{"text":"数据库连接与实际运行角色配置","correct":true,"feedback":"失败证据指向后端到数据库这一段；相同请求日志明确显示连接数据库被拒绝。"},{"text":"先修改前端提交字段，不查看数据库访问条件","correct":false,"feedback":"同次日志已经指出连接被拒绝，应先检查这条链路而非无依据改输入。"},{"text":"删除身份验证","correct":false,"feedback":"数据库连通失败不能通过降低身份保护解决。"}],"output":"教学结果：定位到后端连接数据库的访问条件，旧数据保持不变；修复后重跑相同保存并再次读取。","evidence":["同一请求关联编号","数据库连接错误摘要","修复后写入与读回"]}]},"practice":{"intro":"起点是可重复运行的后端版本、环境配置清单和健康接口。无明确外部发布授权时，仅完成本地模拟与可 review 的部署包。","steps":["查选定平台当前官方文档，记录运行模型、入口、端口或函数要求及日志位置名称。","核对服务端配置名、数据环境与秘密处理，不将值写入报告。","在本地按目标条件启动，分别检查健康接口、登录读取、写入与拒绝路径。","整理发布步骤和恢复入口；实际获准发布后再记录真实启动日志与线上业务结果。"],"prompt":"请为当前后端生成可审查的部署准备包：依据选定平台当前官方文档确认运行模型、入口、运行时、端口/函数要求、环境变量名称、日志与健康检查。先在本地目标条件验证健康和演示读写、未登录拒绝，记录版本与脱敏结果。不要创建资源、上传、付费或部署，不输出秘密；把需外部授权步骤独立列为待执行。","evidence":["当前官方要求与运行模型","启动和健康检查结果","业务读写与拒绝结果","配置清单、版本与恢复入口"],"troubleshooting":[{"symptom":"部署提示成功但无监听","check":"核对启动命令、入口、端口与绑定接口","action":"依实际平台模型修复，重新检查启动日志和健康请求。"},{"symptom":"健康成功但业务500","check":"核对同次业务日志与数据库访问","action":"按证据修复依赖，不把重启或取消验证当作通用方案。"}]},"checks":[{"question":"未登录请求返回401，是否证明后端故障？","options":[{"text":"一定，成功状态只能是200","correct":false,"feedback":"业务规则包含合理拒绝状态；受保护业务拒绝无身份请求可能正是正确行为。"},{"text":"不一定，可能正是预期认证拒绝","correct":true,"feedback":"需结合接口规则和已登录正常路径判断。"},{"text":"改成200就解决了","correct":false,"feedback":"状态改变不能替代身份处理；身份仍需有效，响应码不应伪装为成功。"}]},{"question":"更新了平台变量却行为未变，应如何确认？","options":[{"text":"在页面再增加同名变量","correct":false,"feedback":"前端变量不能修复服务端读取时机；服务端是否读入新配置由平台实例机制决定。"},{"text":"把真实值打印到公网健康接口","correct":false,"feedback":"这会暴露秘密，并非必要诊断；只核对配置存在与验证结果通常就足够。"},{"text":"查看该平台生效机制及实际部署版本","correct":true,"feedback":"配置可能需要新实例读取，也可能改错环境。"}]}],"sources":[{"label":"Twelve-Factor：端口绑定","url":"https://12factor.net/port-binding","checked":"2026-10-16"},{"label":"Twelve-Factor：环境配置","url":"https://12factor.net/config","checked":"2026-10-16"}]},{"id":"11.05","title":"发布前端并接通服务","lead":"线上页面看起来正常，保存却失败；同一个接口在本机又能成功。浏览器额外执行的地址、跨源和身份规则可能改变了条件。","goals":["能依据实际网络请求判断API地址、构建配置、跨源与身份发送问题。","能在测试环境完成新建后刷新回读、退出拒绝和失败提示检查。"],"sections":[{"title":"前端配置可能在构建时固定","paragraphs":["前端代码中的API地址可能在构建时写进脚本，也可能由运行时配置获取。若是前一种，改变平台运行变量却不重新构建，已下载的脚本可能仍然请求旧地址。应检查真实网络目标和产物版本，而不是只看控制台里的变量已更新。","同域相对地址如/api/tasks可以配合反向代理；不同域完整地址则依赖实际部署配置。哪种方案合适取决于承载方式。无论选择哪种，都要确认不再误用localhost，并保证前端目标、后端版本和数据库环境是有意配对的。"]},{"title":"跨源限制是浏览器读响应的规则","paragraphs":["来源由协议、主机和端口共同决定。当前端和API不同源，浏览器可能要求服务端以CORS响应头允许读取，某些请求先发预检。终端请求能成功而网页失败，并不矛盾，因为终端不按浏览器相同的跨源规则工作。","CORS不是业务授权机制。允许一个页面来源读取响应，不意味着其中每位用户有权访问全部任务；非浏览器客户端也不靠CORS限制。应按当前需求精确配置允许来源、方法和凭据条件，不能为了消除报错就随意扩大权限或取消身份检查。"]},{"title":"身份发送还受Cookie条件影响","paragraphs":["浏览器是否发送Cookie，取决于请求凭据模式与Cookie的域、路径、Secure、SameSite等条件；跨源不总等于跨站，两个概念相关却不同。前后端域名变化后，开发环境原有设置可能不适用，需要依据实际站点关系和身份组件文档检查。","携带凭据的跨源响应通常不能用通配来源替代具体来源，且服务端仍需相应允许。采用Cookie认证还要考虑跨站请求伪造防护。采用令牌也应按组件推荐方式管理，不要为解决发送失败而把服务端管理密钥交给浏览器。"]},{"title":"HTTPS和业务读写共同验收","paragraphs":["HTTPS页面调用不安全的HTTP资源可能被浏览器按混合内容规则阻止。地址可达、CORS允许、身份携带和业务授权是多重条件，任一条件不满足都可能表现为“保存不了”。先确定请求是否发出、是否读到响应，再看后端处理结果。","最终用真实目标地址执行演示读取、新建、刷新后读回，并检查跨账户拒绝与失败提示。只看首页截图或点击后出现卡片不能证明数据已持久保存。未实际发布时，本课案例保持教学推演，线上验收标记待完成，不能用本机结果冒充。"]}],"glossary":[{"term":"来源","meaning":"由协议、主机与端口组成的浏览器安全边界。"},{"term":"CORS","meaning":"服务端声明允许哪些来源读取跨源响应的机制，不替代用户授权。"},{"term":"构建时配置","meaning":"在生成前端文件时固定的配置，修改后通常需重新生成产物。"}],"predict":{"question":"终端请求API成功，浏览器报CORS，说明什么？","options":[{"text":"后端可达，但浏览器跨源读取条件需核对","correct":true,"feedback":"终端成功与浏览器限制可以同时成立；浏览器对跨源响应有额外读取条件。"},{"text":"数据库一定没有表","correct":false,"feedback":"已有成功请求不足以支持该推断；终端请求已成功并不能推出数据表缺失。"},{"text":"允许所有来源后，就可以省略每用户身份检查","correct":false,"feedback":"来源读取许可不等于资源授权，跨账户操作仍需可信身份和归属判断。"}]},"experiment":{"title":"发布前端并接通服务：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"旧地址留在产物","input":"平台变量已改成线上API；前端包仍请求localhost；没有重新构建。","question":"变量已改但包仍请求localhost，最先核对什么？","options":[{"text":"先将数据库重新启动，假定前端地址已经生效","correct":false,"feedback":"请求仍指localhost时并未到达目标后端，重启远端数据库不能改写客户端脚本。"},{"text":"配置读取时机与实际包版本","correct":true,"feedback":"构建时替换不会被运行变量自动改写；已生成的静态脚本需要按机制重新构建。"},{"text":"先缩短请求超时，让失败更快提示","correct":false,"feedback":"超时长短不改变已打包的API地址，应先检查真实请求目标与构建版本。"}],"output":"教学结果：定位到旧前端构建包，重新构建后网络目标为预期测试API；仍需继续验证身份与写入。","evidence":["脚本版本前后变化","请求目标地址对照"]},{"name":"地址正确但身份未到","input":"前端与API不同源；API可达；请求未携带预期会话，后端返回401。","question":"API可达但没有会话材料，应怎样处理本次401？","options":[{"text":"取消服务端认证","correct":false,"feedback":"会把私人业务暴露，且没有解释根因；取消认证只是扩大访问能力而非恢复会话。"},{"text":"把数据库管理密码改成前端变量","correct":false,"feedback":"管理凭据不能修补用户会话发送；它既不代表A身份，也不应交到浏览器。"},{"text":"核对凭据模式和Cookie发送条件","correct":true,"feedback":"先确认身份材料为什么未随请求到达；先确认身份丢在客户端发送还是后端验证。"}],"output":"教学结果：按组件规则修复身份发送后A读取成功，退出后相同入口仍拒绝；未降低服务端验证要求。","evidence":["请求身份检查结果","允许与拒绝两路","数据环境代号"]}]},"practice":{"intro":"起点是已验证的后端基线、前端构建说明和环境清单。若无发布授权，先用独立本地不同来源模拟，线上步骤保留待执行。","steps":["确定API配置在何时读取，记录前端版本、目标地址与数据库环境。","在浏览器网络面板检查请求地址、预检、响应与身份发送，只保存脱敏摘要。","按实际来源关系核对CORS、Cookie及HTTPS要求，用A完成新建与刷新读回。","检查退出、跨账户与一次请求失败，完成可审查发布包；真实外部发布另行授权后验收。"],"prompt":"请检查当前前端接通后端的准备：识别API地址是构建时还是运行时配置，核对真实请求目标、CORS预检、Cookie或令牌发送与HTTPS。先在获准的本地测试环境验证A新增并刷新读回、退出拒绝、跨账户拒绝和失败提示。报告脱敏网络证据、版本及数据环境，不输出凭证，不创建外部资源或发布；列出线上待验收项。","evidence":["前端版本和真实API目标","跨源与身份发送检查摘要","新建后刷新读回的记录","退出/跨账户拒绝与失败提示"],"troubleshooting":[{"symptom":"终端成功而浏览器失败","check":"查看浏览器控制台和预检响应","action":"按具体来源及凭据条件修复CORS，保留业务授权。"},{"symptom":"保存成功但刷新丢失","check":"核对写入响应、再次读取与所连环境","action":"区分仅更新前端状态和后端真实写入，修复后重跑原步骤。"}]},"checks":[{"question":"配置CORS允许前端域名，是否可省略跨账户权限？","options":[{"text":"不可，CORS与业务授权分工不同","correct":true,"feedback":"获准页面中的用户仍可能请求不属于自己的对象。"},{"text":"可以，因为来源已经可信","correct":false,"feedback":"来源不能等同于每个请求者和资源权限。"},{"text":"只需要隐藏删除按钮","correct":false,"feedback":"客户端显示不能守住数据入口；真正拒绝需要发生在服务端或可信数据层。"}]},{"question":"HTTPS页面调用HTTP接口，应该先看什么？","options":[{"text":"后端是否允许了前端来源，先忽略协议差异","correct":false,"feedback":"CORS可能是另一条件，但混合内容可在它之前被阻止，应先核对浏览器证据。"},{"text":"浏览器是否按混合内容规则阻止请求","correct":true,"feedback":"协议组合可能在业务逻辑前被限制；请求可能在发送业务内容前就被浏览器挡住。"},{"text":"把所有HTTP错误统一重试，等待网络恢复","correct":false,"feedback":"浏览器协议限制通常不会被重复请求解决，应修正安全目标而非盲目重试。"}]}],"sources":[{"label":"MDN：CORS机制","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS","checked":"2026-10-16"},{"label":"MDN：Cookie与凭据发送","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Cookies","checked":"2026-10-16"},{"label":"MDN：TLS传输保护","url":"https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Transport_Layer_Security","checked":"2026-10-16"},{"label":"MDN：混合内容与浏览器阻止","url":"https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Mixed_content","checked":"2026-10-16"}]},{"id":"11.06","title":"域名、HTTPS 与访问路径","lead":"平台地址能打开，自有域名却不行；首页能看，刷新详情就404。它们看似都是“打不开”，但机制和证据完全不同。","goals":["能用证据区分DNS、证书、页面路由、资源路径与缓存问题。","能检查详情直接访问与刷新，说明自有域名可选实践的前置和边界。"],"sections":[{"title":"域名把名称指向网络目标","paragraphs":["域名是便于记忆的名称，DNS解析将名称关联到网络目标。浏览器得到目标后才进一步建立连接。域名解析正确不保证目标上有对应网站，平台通常还要将该域名与正确项目关联，具体记录类型与验证方式依平台当前要求。","不要把“买了域名”当作“已部署应用”。购买、解析、项目关联和证书配置是不同环节。课程不要求自有域名，先使用平台提供的地址验证业务链路；有明确条件与授权后，再按官方要求配置域名，可以减少同时改变多个变量。"]},{"title":"HTTPS保护传输并核对站点身份","paragraphs":["HTTPS在HTTP之上使用TLS，帮助防止传输过程被窃听或篡改，并验证连接到证书所声明的站点身份。它不负责判断任务属于谁，也不保证网站业务没有漏洞。锁形标志不能作为数据隔离或内容可靠性的证明。","证书过期、名称不匹配或链路配置异常，可能在页面业务运行前产生警告。不要把忽略警告作为正式解决方法，也不要将密码提交到无法确认的站点。应核对实际域名、证书有效状态和平台配置，在原因明确后再重试。"]},{"title":"刷新暴露服务端路径规则","paragraphs":["单页应用可能在浏览器内把/tasks/1解释为详情页，但直接刷新时服务器收到的是该路径。如果静态托管没有对应文件或回退规则，就会404；从首页点击却正常，是因为前一种导航由浏览器脚本处理，后一种需要服务端先返回页面。","修复应区分页面路由与API、静态资源路径，不能把所有404都返回首页，否则脚本文件请求可能收到HTML而报错。应用发布在子目录时，还要核对资源基路径。记录失败资源的完整路径与响应类型，比只说“页面白了”更有诊断价值。"]},{"title":"缓存可能让新旧版本并存","paragraphs":["浏览器、代理或CDN可能缓存资源，更新后有人仍看到旧脚本。资源指纹、缓存策略与版本标识可以帮助区分，不宜把清缓存当作唯一发布策略。缓存命中本身不是故障，要看返回内容是否符合当前预期与更新安排。","诊断按层进行：名称能否解析、TLS能否建立、首页与深层路径是否正确、资源返回什么、版本是否一致。平台地址正常而自有域名失败，优先检查新增的域名环节；两者同时业务500，则应回到后端。条件对照能避免把所有问题归为“网络不好”。"]}],"glossary":[{"term":"DNS","meaning":"将域名名称关联到网络目标等记录的系统。"},{"term":"TLS","meaning":"保护网络传输并验证站点身份的协议，不代替业务授权。"},{"term":"路径回退","meaning":"托管服务对没有实际文件的页面路由返回入口页的规则，应排除API与资源。"}],"predict":{"question":"从首页点击详情正常，直接刷新/tasks/1却404，优先检查什么？","options":[{"text":"先要求用户清空浏览器缓存，再假定路由已正确","correct":false,"feedback":"直接刷新404与浏览器内跳转正常的对照更指向服务端路径处理，应先核对它。"},{"text":"证书一定过期","correct":false,"feedback":"首页可正常HTTPS访问使该推断缺少支持。"},{"text":"静态托管的页面路由与回退规则","correct":true,"feedback":"两种导航到达服务器的方式不同；直接刷新先要求服务器返回对应页面入口。"}]},"experiment":{"title":"域名、HTTPS 与访问路径：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"只改变域名","input":"平台地址核心流程正常；自有域名无法解析到预期目标。","question":"最合理的检查顺序是什么？","options":[{"text":"先核对DNS和项目域名关联","correct":true,"feedback":"变化只发生在域名入口，先检查新增环节。"},{"text":"先更换后端数据库连接地址，跳过域名检查","correct":false,"feedback":"平台地址业务正常，新增失败集中在域名入口，没有依据先改变数据环境。"},{"text":"先扩大后端CORS允许范围，等待域名恢复","correct":false,"feedback":"域名尚未解析到目标时，允许来源不会修复名称到服务的映射。"}],"output":"教学结果：推演定位到DNS目标记录与预期不匹配；平台地址仍正常，未进行真实域名修改。","evidence":["平台地址对照正常","解析结果与预期不同"]},{"name":"只改变访问方式","input":"首页点击/tasks/1正常；直接打开该路径404；API与首页均可响应。","question":"同一详情点击正常而刷新404，应怎样解释？","options":[{"text":"服务器一定记住了上一次页面状态，重启即可","correct":false,"feedback":"页面路由由浏览器和服务器分别处理，重启不能替代缺少的路径规则。"},{"text":"浏览器内路由与服务端直接路径处理不同","correct":true,"feedback":"需托管规则向页面路由提供入口文件；浏览器内跳转无需同样的首次文件查找。"},{"text":"把所有路径无条件返回首页即可","correct":false,"feedback":"可能破坏API与资源，必须限定回退范围。"}],"output":"教学结果：方案限定页面路由返回入口页，并排除API与静态资源；还需检查脚本未收到HTML响应。","evidence":["直接路径响应404","回退方案排除API和资源"]}]},"practice":{"intro":"起点是已准备或已获准发布的平台地址。没有外部资源时可用本地托管模拟路径，域名实操保持可选。","steps":["记录当前地址、版本和正常核心流程，作为加入域名前的基线。","用官方说明核对DNS目标、项目关联与证书条件，不购买或修改未授权域名。","检查首页、详情直接访问、刷新及静态资源响应类型；在副本修复路径规则。","对比正常与缓存条件下的版本，形成诊断记录；真实域名变更仅在授权范围进行。"],"prompt":"请检查当前项目的访问路径准备，解释平台地址、自有域名、DNS、HTTPS证书和页面路由的分工。在本地或已有授权测试地址验证首页、详情直达/刷新、资源路径及版本缓存，避免把API或脚本404都回退为HTML。给出脱敏检查结果和按层诊断清单。不购买域名、不改DNS、不发布；自有域名实操列为可选待授权。","evidence":["平台地址基线与版本","DNS/TLS检查对象与结论","深层路径刷新及资源类型结果","缓存版本对照与修复范围"],"troubleshooting":[{"symptom":"首页正常但详情刷新404","check":"检查服务端是否理解页面路由","action":"限定页面回退，重测API和静态资源没有被错误覆盖。"},{"symptom":"只有部分设备看到旧界面","check":"检查资源版本、缓存头与实际返回内容","action":"修正适用缓存策略并验证新旧资源兼容，不只要求每位用户手动清缓存。"}]},"checks":[{"question":"看到HTTPS标志，能证明跨账户数据隔离吗？","options":[{"text":"能，因为传输已经加密","correct":false,"feedback":"加密不会决定哪个用户拥有记录；A仍可能通过加密连接发起越权请求。"},{"text":"能，只要域名属于自己","correct":false,"feedback":"拥有域名也不会自动落实授权；域名所有者也必须在服务端限制各用户能力。"},{"text":"不能，仍需业务权限验证","correct":true,"feedback":"传输保护与资源归属是不同层次；加密只保护传输，归属仍由业务规则决定。"}]},{"question":"脚本请求返回200但内容是首页HTML，应检查什么？","options":[{"text":"路径回退是否误吞静态资源","correct":true,"feedback":"状态成功并不保证内容类型与文件正确。"},{"text":"只要200就无需检查","correct":false,"feedback":"浏览器仍无法把HTML当正确脚本执行。"},{"text":"重新生成前端包，但保留所有404都回退首页","correct":false,"feedback":"新包仍会被错误回退规则影响，脚本请求返回HTML的根因尚未处理。"}]}],"sources":[{"label":"MDN：域名与解析","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/What_is_a_domain_name","checked":"2026-10-16"},{"label":"MDN：TLS","url":"https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Transport_Layer_Security","checked":"2026-10-16"},{"label":"MDN：HTTP缓存","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching","checked":"2026-10-16"}]},{"id":"11.07","title":"换设备完成上线验收","lead":"开发者自己的浏览器可能保存了缓存、旧会话和特殊配置。换一台设备，是为了改变环境条件，而不是只多拍一张首页截图。","goals":["能在独立设备或浏览器环境执行核心流程并指明版本与数据环境。","能提交两账户拒绝、刷新回读及受控请求失败后的恢复证据。"],"sections":[{"title":"新环境可以揭开本机假成功","paragraphs":["本机可能仍运行后端、保存开发Cookie或缓存旧数据，所以“我能用”不能代表朋友能用。第二台设备或独立浏览器环境减少这些隐形条件，帮助发现localhost地址、缺失资源与身份回调只适用于开发环境的问题。","独立浏览器不能替代全部设备差异，但可以隔离会话与缓存；手机还能暴露触控和布局问题。验收应记录设备、浏览器、地址、版本及数据环境，明确本次覆盖范围。没有第二台设备时可以做独立环境检查，并诚实标明尚未覆盖的实际条件。"]},{"title":"核心流程要跨过整个链路","paragraphs":["使用线上目标地址登录，新增带独特标记的演示任务，刷新后重新读取，再修改和删除。这比点完按钮看到一张卡片更有证据力，因为它验证请求到达后端、数据库保存、再次读取以及页面状态更新。","每条操作都应确认目标环境。测试账户使用的演示数据要与正式私人资料区分，删除只针对专用演示记录。即使后端日志已有写入，也要从最终用户侧再次读回；反之页面显示成功却数据库没有变化，应判定失败而非“体验基本完成”。"]},{"title":"身份隔离也必须在发布环境重测","paragraphs":["开发环境已通过两账户检查，线上身份回调、域名和数据库角色仍可能不同。用A/B隔离会话分别确认本人操作，再尝试跨账户访问已存在的任务与未登录操作，检查拒绝响应和数据未变。不能把本地V3结论直接复制成线上通过。","如果两个账户共用同一浏览器会话，身份切换可能污染结果；如果线上连接了错误数据库，空列表也可能被误认为隔离良好。用已知演示记录、可信身份与目标库代号形成对照，让拒绝证据确实与归属条件相关。"]},{"title":"网络失败也是可用性的一部分","paragraphs":["在受控测试中阻断一次请求或使用明确不可达的测试目标，观察页面是否清楚说明未保存、是否允许重试，以及重复点击会否造成重复记录。不要通过关闭共享服务或破坏数据库制造故障，避免影响其他人。","最终报告分别列通过、失败、未覆盖和已知限制，附版本及恢复入口。实际发布需要明确授权，课程制作中的预制案例没有真实访问记录。只有在获准环境完成外部操作后，才能把上线验收从待完成改为通过，并继续进入维护阶段。"]}],"glossary":[{"term":"冒烟检查","meaning":"快速覆盖最关键流程，发现阻断性问题，不代表完整验证。"},{"term":"独立环境","meaning":"尽量不共享原开发会话、缓存和本机服务的访问条件。"},{"term":"回读","meaning":"写入后重新从服务读取，以确认持久化结果而非仅看页面状态。"}],"predict":{"question":"手机首页能打开，但没有实际保存与刷新回读，能判定上线完成吗？","options":[{"text":"能，因为手机比电脑要求更高","correct":false,"feedback":"设备不同不能替代具体业务验证；更换设备只是改变条件，仍须执行具体动作。"},{"text":"不能，还缺核心链路和身份隔离证据","correct":true,"feedback":"首页资源可见仅覆盖一部分条件；登录、写入、回读与拒绝路径还没有运行证据。"},{"text":"能，只要部署平台显示成功","correct":false,"feedback":"平台状态不证明用户流程；平台提示不覆盖浏览器身份与数据结果。"}]},"experiment":{"title":"换设备完成上线验收：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"新设备暴露本机依赖","input":"电脑可保存；手机页面正常；手机请求localhost；线上API没有该次记录。","question":"按手机请求与后端记录，这次上线验收应如何判定？","options":[{"text":"通过，手机能看首页","correct":false,"feedback":"核心保存能力仍失败；发布目标包含保存，不能用首页可见代替。"},{"text":"先延长数据库连接超时，再重新在手机操作","correct":false,"feedback":"手机请求仍发向本机，延长远端数据库超时无法让请求进入线上链路。"},{"text":"上线验收失败，需修复前端目标","correct":true,"feedback":"关键请求没有进入预期线上链路；手机请求没有到达预期后端，核心闭环不成立。"}],"output":"教学结果：上线保存项失败，问题定位到前端API配置；修复后必须在独立设备重跑完整用户流程。","evidence":["请求目标为手机本机","线上无对应记录"]},{"name":"保存中断","input":"A点击新增；受控阻断请求；页面仍保留输入但提示未保存；恢复后单次重试只生成一条。","question":"请求失败提示与恢复重试的现象说明什么？","options":[{"text":"该次失败处理与重试行为符合预期","correct":true,"feedback":"未把失败当成功，恢复后也没有重复记录。"},{"text":"能证明所有断网情况都正确","correct":false,"feedback":"不同中断时机仍可能有不同结果；响应丢失但已写入的情况还需单独测试。"},{"text":"应立即清空所有输入","correct":false,"feedback":"无必要丢弃草稿会损害恢复体验；保留草稿有助恢复，也要防止误示保存成功。"}],"output":"教学结果：当前受控阻断下提示与重试可通过；请求已写入而响应丢失的时机仍列为未覆盖风险。","evidence":["未保存提示","草稿可恢复","重试后单条记录"]}]},"practice":{"intro":"起点是已获得明确授权并实际发布的测试版；若尚未发布，只准备清单，不能以本地结果标记线上通过。","steps":["记录线上地址、代码版本、后端和数据库环境，准备A/B专用演示记录。","在第二设备或独立环境完成登录、新增、刷新回读、编辑、删除，并保存脱敏结果。","用隔离会话检查两账户允许、跨账户拒绝和退出拒绝，拒绝后复查数据未变。","在客户端受控模拟一次请求失败，恢复后重试并检查重复，整理通过/失败/未覆盖与限制。"],"prompt":"请先确认当前是否已有获准发布的测试地址，没有则只生成上线验收清单并标记待完成。有则在独立设备或浏览器环境使用A/B演示身份验证登录、列表、新建、刷新回读、更新、删除、跨账户与退出拒绝。只在客户端模拟一次请求失败，检查提示与重试重复；记录地址、版本、数据环境和脱敏证据。不要创建资源、发布、关闭共享服务或保存凭证。","evidence":["设备、地址、版本与数据环境","完整用户流程及回读结果","两账户允许拒绝与未变记录","请求失败恢复、重试及未覆盖清单"],"troubleshooting":[{"symptom":"本机正常而新设备失败","check":"核对API目标、资源、身份回调与缓存差异","action":"每次只改变一个条件修复，重新执行原核心流程。"},{"symptom":"失败重试出现重复任务","check":"核对原请求是否已写入但响应未到","action":"定义请求幂等或去重策略，在测试副本覆盖不同中断时机。"}]},"checks":[{"question":"本地隔离通过，线上数据库角色变成管理员，应怎样做？","options":[{"text":"直接沿用本地结论","correct":false,"feedback":"版本相同不保证环境权限相同；线上角色可能绕过本地生效的数据规则。"},{"text":"重新检查线上实际连接及两账户拒绝","correct":true,"feedback":"运行角色变化可能改变数据策略的有效性。"},{"text":"只看线上任务数量","correct":false,"feedback":"数量不是权限边界证据；空列表也可能来自空库而非正确隔离。"}]},{"question":"暂时没有真实发布条件，课程状态怎样写？","options":[{"text":"上线已通过，因为步骤已准备","correct":false,"feedback":"准备说明不代表请求实际运行；真实地址、身份与数据库仍可能出现新条件。"},{"text":"整门课没有任何成果","correct":false,"feedback":"理解与准备仍有价值，可独立记录；可将已完成材料与线上缺项同时展示。"},{"text":"阅读与推演完成，线上实操待完成","correct":true,"feedback":"如实区分不同学习证据；准备步骤和实际请求结果应分别标记。"}]}],"sources":[{"label":"MDN：浏览器Cookie条件","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Cookies","checked":"2026-10-16"},{"label":"OWASP：授权验收","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html","checked":"2026-10-16"},{"label":"Twelve-Factor：环境配置","url":"https://12factor.net/config","checked":"2026-10-16"}]},{"id":"12.01","title":"从手动清单到有意义的测试","lead":"AI给你加了一个“测试通过”的标记，但它只是搜索源码有没有某个函数名。这样的检查能抓住筛选结果颠倒的错误吗？","goals":["能用有区分力的输入和真实结果断言，发现源码文字检查的缺陷。","能先观察测试对错误版本失败，再修复并说明通过范围与未覆盖行为。"],"sections":[{"title":"先说行为，再选测试层次","paragraphs":["行为测试观察输入与结果，例如两条任务一条完成、一条未完成，选择“未完成”应只得到后者。它不要求内部必须叫什么函数，也不以源码是否出现某个词为依据。内部实现可以变化，只要约定行为仍成立，测试就应继续具有价值。","单元测试检查较小逻辑，接口测试检查请求与响应及数据效果，端到端测试从浏览器操作跨过更多组件。层次不同，覆盖和成本不同。一个纯筛选函数适合小测试，但数据库保存与身份隔离不能只靠这个函数测试证明。"]},{"title":"错误版本让测试证明自己有用","paragraphs":["先在独立测试副本制造或保留一个明确错误，例如把completed=false错写成true，再运行测试。若测试仍通过，说明它可能没有执行目标行为、输入没有区分力，或断言没有检查真正结果。红色失败是验证测试敏感度的证据，不是要追求永远失败。","修复后重跑同一测试，再检查相关正常流程。不能为了得到绿色而把预期改成错误结果，也不能仅删除失败断言。测试是一个可反驳的行为约定：已知错误会触发它，符合约定时它通过，二者形成因果对照。"]},{"title":"测试数据要能区分不同解释","paragraphs":["若两条任务都未完成，错误的“全部返回”也可能看起来正确。要准备不同状态、不同归属或边界输入，让错误实现和正确实现产生不同结果。数据越多不自动越有价值，关键是能否把你关心的错误暴露出来。","例如空标题验证应包含纯空格，而不只包含空字符串；保存应包含刷新后的重新读取，而不只检查页面数组长度。每次测试说明为什么选择这个输入、断言哪项可观察结果，避免复制大量与实现一一对应却不能发现问题的测试。"]},{"title":"通过范围需要诚实限定","paragraphs":["测试通过说明在当前版本、环境和输入下，已检查行为符合预期。它不能证明没有未知错误，也不能把模拟数据库结果当真实线上数据库连通。不同层次应互补：逻辑单测快速，接口检查权限与写入，浏览器流程检查真实操作与反馈。","保留少量关键手动清单也有价值，特别是视觉、可理解性和新设备体验。将自动测试与人工证据并列，标明未覆盖项，比用一个总通过率掩盖缺项更可靠。新增需求时先更新行为约定，再确定最合适的检查层次。"]}],"glossary":[{"term":"断言","meaning":"明确比较实际结果与预期条件的检查。"},{"term":"单元测试","meaning":"针对相对独立的小段逻辑的自动检查。"},{"term":"端到端测试","meaning":"通过用户入口跨越多组件验证完整行为的检查，仍有环境范围限制。"}],"predict":{"question":"筛选逻辑把“未完成”写反，测试仅检查源码有filter字样，会怎样？","options":[{"text":"可能仍通过，无法证明筛选行为正确","correct":true,"feedback":"函数名存在与输入输出是否符合要求没有必然关系。"},{"text":"一定失败，因为filter能识别需求","correct":false,"feedback":"字符串检查不会理解业务预期；包含filter仍可能使用了颠倒条件。"},{"text":"可以代替浏览器验收","correct":false,"feedback":"源码文字既没运行流程，也没验证界面反馈。"}]},"experiment":{"title":"从手动清单到有意义的测试：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"有区分力的输入","input":"t1.completed=true，t2.completed=false；选择未完成；错误函数返回t1。","question":"对于颠倒筛选条件，哪条断言能够直接抓错？","options":[{"text":"源码包含filter","correct":false,"feedback":"错误函数同样可以调用filter；调用存在不代表筛选条件与业务约定一致。"},{"text":"结果ID仅为t2","correct":true,"feedback":"它具体检查业务要求而不是内部写法；ID断言可以区分t1错误结果与t2正确结果。"},{"text":"结果数组存在","correct":false,"feedback":"错误结果也可以是合法数组；数组类型正确不能说明元素身份正确。"}],"output":"教学结果：真实调用错误筛选时测试失败，预期ID为t2而实际为t1；修复后不改变预期，同一断言通过。","evidence":["错误版本失败信息","修复后同一断言通过"]},{"name":"输入无法区分错误","input":"两条任务都未完成；错误函数完全不筛选，直接返回全部。","question":"测试只核对返回两条，有什么缺陷？","options":[{"text":"证明所有状态都正确","correct":false,"feedback":"没有出现的条件不在证据覆盖内；缺少已完成项就无法观察它是否被排除。"},{"text":"需要把数组扩大到一千条相同状态","correct":false,"feedback":"数量增加仍不改变逻辑区分力；一千个相同条件仍可能让全部返回假通过。"},{"text":"不能区分正确筛选与直接全部返回","correct":true,"feedback":"两种实现对当前输入结果相同，需要补混合状态。"}],"output":"教学结果：只有未完成数据时原测试假通过；加入已完成任务后，直接返回全部的错误实现暴露。","evidence":["原条件两种实现输出相同","混合状态下结果出现差异"]}]},"practice":{"intro":"起点是任务工具的独立测试副本与现有测试命令。选择一个明确行为，例如“未完成筛选保留未完成项”，不要先追求测试数量。","steps":["写出输入、预期输出与当前担心的错误，用两个不同状态任务形成对照。","请Codex写调用真实逻辑的行为测试，在副本错误版本上先观察失败。","修复行为，重跑原测试及受影响检查，禁止通过改错预期来变绿。","另走一次浏览器核心流程，记录自动测试证明了什么、尚未覆盖什么。"],"prompt":"请在当前测试副本为未完成筛选写一项有区分力的行为测试：包含已完成t1和未完成t2，断言输出ID仅t2。先在独立副本使筛选条件颠倒并记录测试失败，再修复并运行相关回归；不要检查源码文字代替调用真实逻辑，不要改错预期。说明测试层次、运行命令、实际结果和未覆盖的保存/权限/浏览器行为。","evidence":["行为约定与区分输入","错误版本上的真实失败","修复后同一测试通过","浏览器核对及覆盖边界"],"troubleshooting":[{"symptom":"错误版本也通过","check":"核对测试是否调用目标函数与断言真实结果","action":"加入能区分错误的输入，先证明测试会失败，再保留它。"},{"symptom":"为了通过而改了预期","check":"回到已确认的业务行为与演示数据","action":"恢复正确约定，修复实现并解释为什么输出应如此。"}]},"checks":[{"question":"单元测试全部通过，数据库保存仍失败，是否矛盾？","options":[{"text":"不矛盾，单测可能未覆盖真实数据库链路","correct":true,"feedback":"检查层次不同，证据不能互相替代；小逻辑结果不覆盖网络与数据库运行条件。"},{"text":"矛盾，说明数据库故障不真实","correct":false,"feedback":"真实请求失败需要独立调查；需要接口和实际写入证据定位另一层问题。"},{"text":"应该删除单元测试","correct":false,"feedback":"测试仍可证明其覆盖的逻辑，需补接口检查。"}]},{"question":"新增“纯空格标题不允许保存”，最佳输入是什么？","options":[{"text":"只使用三个正常标题","correct":false,"feedback":"无法触发新要求的边界；正常标题不会触及空白输入的拒绝条件。"},{"text":"同时包含有效标题、空串与纯空格","correct":true,"feedback":"它们能区分长度检查与真正空白处理；纯空格能暴露只检查字符长度的缺陷。"},{"text":"只检查源码出现trim","correct":false,"feedback":"出现该词不保证实际请求按规则处理；必须执行该输入并观察拒绝与未写入。"}]}],"sources":[{"label":"Node：测试运行器与断言执行","url":"https://nodejs.org/api/test.html","checked":"2026-10-16"}]},{"id":"12.02","title":"用请求与日志定位线上问题","lead":"用户只说“保存没反应”，你应该让Codex改哪里？先把一次操作的浏览器、后端和数据库证据连起来，才能减少盲猜。","goals":["能将同一次操作的浏览器请求、后端日志与数据库结果对应起来。","能依据最小复现作有因果依据的修复，并用原步骤和相关回归检验。"],"sections":[{"title":"先固定一次可复现的操作","paragraphs":["记录目标地址、版本、匿名测试身份、输入、步骤、预期与实际。比如A在测试版r18输入“买牛奶”点击保存，预期新增一条，实际提示失败。只说“有时不好用”难以复现，也无法判断修复后是否真的改变了同一个问题。","最近改动是线索，不是结论。昨晚更新了样式，不意味着所有失败都由样式造成；今天改了数据库，也不能跳过浏览器检查。先在演示数据上复现一次，保留最少必要材料，再根据证据选择下一层。不要用生产私人数据反复试错。"]},{"title":"浏览器告诉你请求走到哪一步","paragraphs":["网络面板可查看目标地址、方法、响应状态与简化结果，控制台可指出脚本或跨源错误。请求没有发出，优先检查事件与前端异常；请求地址是localhost，先查配置；已收到500，再联系后端日志。不同现象需要不同下一步。","401可能说明身份无效，403可能是权限拒绝，404可能是路由或隐藏资源存在性的设计；状态码要结合接口约定理解。网络中断或浏览器限制也可能让脚本无法读取响应，所以不能仅凭“fetch失败”就断言数据库坏了。"]},{"title":"关联编号把证据串成同一次","paragraphs":["同一时间可能有多个人请求，单看最新一行日志容易连错。关联编号或请求ID帮助将浏览器操作、后端入口、数据库错误摘要对应起来。没有编号时可在测试中使用时间范围与独特演示标记辅助，但要明确匹配仍有不确定性。","日志写阶段、结果、耗时与脱敏错误类别即可，不要记录完整令牌、密码或私人正文。数据库侧核对目标记录是否存在、受影响行数及结构版本，帮助判断“写入没发生”和“写入成功但响应丢失”的区别，这会影响是否安全重试。"]},{"title":"修复必须回到原步骤验收","paragraphs":["根据证据只改有因果依据的最小范围，再执行原输入、原步骤与相关回归。若修复的是连接配置，应重新核对目标环境、读写与隔离；若修复的是前端错误提示，应确认服务端数据结果没有被误解。","排错记录包括哪些解释被排除、最终原因、修改、结果和剩余限制。暂时无法复现时不必乱改，可以补充可观测信息并限定影响。重启后暂时恢复是现象，不能自动视为根因已修复；需要说明为什么该措施有效、问题是否可能重现。"]}],"glossary":[{"term":"复现","meaning":"用明确条件再次触发同一现象的过程。"},{"term":"关联编号","meaning":"用于把同一次操作在不同组件中的记录对应起来的标识。"},{"term":"可观测信息","meaning":"帮助理解运行行为的请求、日志与数据结果，不应包含不必要秘密。"}],"predict":{"question":"浏览器没有发出任何保存请求，最先检查什么？","options":[{"text":"数据库索引是否足够","correct":false,"feedback":"数据库尚未收到请求，无证据指向索引。"},{"text":"先重启后端服务，假定前端保存事件已经执行","correct":false,"feedback":"浏览器没有出站请求时后端尚未参与，应先核对事件与脚本错误。"},{"text":"前端事件是否执行及脚本错误","correct":true,"feedback":"没有出站请求，先查请求前的代码路径。"}]},"experiment":{"title":"用请求与日志定位线上问题：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"请求到后端后失败","input":"浏览器请求ID=q7收到500；后端q7日志提示列priority不存在；数据库结构版本m1。","question":"针对q7响应和同次日志，最直接的原因假设是什么？","options":[{"text":"代码与数据库迁移版本不匹配","correct":true,"feedback":"相同请求证据指向具体缺列；日志与响应同属q7，缺列与结构版本能对应。"},{"text":"用户密码必然过期","correct":false,"feedback":"身份失败通常有其他证据，缺列更直接。"},{"text":"前端缓存旧页面一定是唯一原因，无需查迁移","correct":false,"feedback":"同次日志明确缺列，缓存虽可作线索，但不能替代结构版本的直接证据。"}],"output":"教学结果：确认q7所需结构迁移m2未执行；先在副本验证迁移，再用同一输入重跑保存和回读。","evidence":["浏览器与日志ID一致","结构版本缺m2","修复后原输入读写成功"]},{"name":"响应丢失但写入成功","input":"保存请求超时；后端记录成功写入t9；数据库已有t9；页面提示未保存。","question":"立即再次新增有什么风险？","options":[{"text":"没有风险，因为页面报失败","correct":false,"feedback":"页面没收到结果不能推翻服务端写入；应先核对首次写入状态再决定是否重发。"},{"text":"可能生成重复记录，先核对状态或使用幂等策略","correct":true,"feedback":"超时不等于服务器未执行，重试语义需设计。"},{"text":"超时就立即自动重试新增，不检查首次结果","correct":false,"feedback":"服务端已经写入t9，盲目再新增可能产生重复，需要状态核对或幂等设计。"}],"output":"教学结果：先核对首次操作已写入t9，避免盲目再次新增；后续按请求状态查询或幂等方案处理重试。","evidence":["服务端写入记录","数据库t9存在","客户端没有收到成功响应"]}]},"practice":{"intro":"起点是独立测试环境、一项可复现失败与无敏感演示任务。没有真实线上授权时，可在本地多组件测试中练习同样方法。","steps":["写下地址、版本、匿名身份、输入、预期、实际和复现步骤。","采集一次操作的脱敏网络结果与关联编号，判断请求是否发出、到哪里、如何结束。","匹配后端日志与数据库前后结果，列出最有证据的原因及被排除的解释。","在副本作最小修复，重跑原步骤和相关正常/拒绝路径，保留对照。"],"prompt":"请依据当前测试副本的一次保存失败排错，先复现并记录版本、环境、输入、预期/实际，再将浏览器请求、响应、后端关联日志和数据库结果对应到同一次操作。不要盲目改多层；提出有证据的最小原因后修复并重跑原步骤与回归。对超时先核对是否已写入，报告不含令牌、连接密码或私人内容；不要操作生产。","evidence":["最小复现材料","同次请求与日志关联","数据库前后结果及原因依据","修复后原步骤与回归结果"],"troubleshooting":[{"symptom":"日志很多但找不到本次请求","check":"核对版本、实例、时间范围与关联编号","action":"在测试入口增加脱敏关联标识，再只复现一次获取证据。"},{"symptom":"重试出现两条记录","check":"检查首次请求是否已提交成功","action":"保留重复演示数据作证据，设计幂等或去重后重测不同中断时机。"}]},"checks":[{"question":"接口500，最新日志却是另一个请求的401，能直接作为原因吗？","options":[{"text":"能，最新日志总是当前错误","correct":false,"feedback":"并发请求可能交错出现；另一用户的401可能恰好发生在500之后。"},{"text":"把全部日志上传即可","correct":false,"feedback":"无差别上传增加泄漏且不解决关联问题。"},{"text":"不能，先关联同次操作","correct":true,"feedback":"时间接近不等于属于同一请求；要把浏览器操作与日志通过编号等方式对应。"}]},{"question":"重启后暂时恢复，可以写根因已修复吗？","options":[{"text":"需说明原因并验证复现条件，暂时恢复不等于根因","correct":true,"feedback":"运行状态改变可能掩盖问题而未消除它。"},{"text":"可以，只要首页200","correct":false,"feedback":"首页200不能说明原保存错误不再发生。"},{"text":"不必记录最近改动","correct":false,"feedback":"缺少改动记录会削弱后续解释；无法判断恢复由哪次变化带来，也难验证复现。"}]}],"sources":[{"label":"Twelve-Factor：运行配置","url":"https://12factor.net/config","checked":"2026-10-16"},{"label":"PostgreSQL：结构变更","url":"https://www.postgresql.org/docs/current/ddl-alter.html","checked":"2026-10-16"},{"label":"Twelve-Factor：日志作为运行事件流","url":"https://12factor.net/logs","checked":"2026-10-16"}]},{"id":"12.03","title":"小步更新与版本回退","lead":"上一版代码恢复了，丢失的数据却没有回来。为什么“回退成功”必须分别讨论代码、配置和数据库？","goals":["能分别解释代码、配置、结构与记录变化的回退和兼容条件。","能在副本演练小步更新与代码回退，并明确哪些数据不会自动恢复。"],"sections":[{"title":"小步让变化与结果更容易对应","paragraphs":["一次只增加清晰的小功能，例如任务列表显示优先级，能够明确验收输入、预期和受影响入口。若同时换身份组件、数据库结构和页面交互，失败后难以知道是哪项变化导致。小步不是追求少写代码，而是控制每次需要同时判断的条件。","发布前记录当前可用版本、配置名、数据结构与恢复点，发布后先冒烟检查核心链路，再针对改动回归旧行为。只看到新按钮出现不能说明更新成功，还要确认原来的添加、筛选、保存与权限没有被破坏。"]},{"title":"代码与配置要保持可识别组合","paragraphs":["代码回退是恢复此前可用程序；配置也可能在独立平台保存，不会随代码自动改变。上一版读取旧变量名，新配置只保留新名，就可能回退后仍启动失败。版本说明应记录兼容的配置集合，秘密值本身不进入记录。","回退通常适合较快恢复服务，但不是万能撤销键。需确认旧版本仍支持当前数据库与客户端请求，前端缓存还可能让部分用户保留新脚本。设计兼容窗口、保留旧字段或分阶段切换，往往比出错后强行把所有组件倒回去更稳妥。"]},{"title":"结构变化与记录变化是另外两层","paragraphs":["新增可选字段通常比较容易保持兼容，删除或重命名字段则可能让旧版本无法运行。回退代码不会自动恢复被删列的内容，也不会恢复用户误删的任务。结构迁移的逆步骤和数据恢复需要单独设计，并在副本验证。","例如把priority列改名为rank，新代码正常，旧代码回退后还找priority就会失败。更稳妥的方案可能先增加rank、双读或迁移数据、验证后再移除旧列。具体做法依业务和数据库而定，不能把“支持回退”当作无条件保证。"]},{"title":"演练限定副作用与恢复范围","paragraphs":["在获准测试环境发布小变更，检查新旧行为，再恢复前一代码版本，验证实际版本、配置、数据读写及身份隔离。若本次改动含数据写入，要声明哪些不会随代码回退撤销，并保留独立的数据恢复依据。","演练失败时记录哪里不兼容，优先恢复可用状态，不在未知结构上反复执行反向迁移。代码回退、修复后再发布和从备份恢复是不同选择，代价也不同。通过一次明确演练，学习者应能说明为什么选择其中一种，而不是只会点击“恢复上一版”。"]}],"glossary":[{"term":"回退","meaning":"恢复此前可用代码或配置版本的操作，不自动恢复所有数据。"},{"term":"兼容性","meaning":"不同版本的组件、结构或请求仍能按约定协作的能力。"},{"term":"冒烟检查","meaning":"发布后优先检查核心链路是否被阻断的简短验证。"}],"predict":{"question":"删列后恢复旧代码，旧代码仍引用该列，会发生什么？","options":[{"text":"旧代码自动让数据库回到过去","correct":false,"feedback":"数据库通常独立保存状态，不跟随程序时光倒流。"},{"text":"可能继续失败，需独立处理结构兼容与数据恢复","correct":true,"feedback":"代码版本变化不会自动重建被删列及原值。"},{"text":"只要刷新浏览器就能恢复列内容","correct":false,"feedback":"浏览器刷新不会还原数据库历史；被删列和原值需要独立结构与数据恢复依据。"}]},"experiment":{"title":"小步更新与版本回退：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"兼容的小改动","input":"r20只增加优先级显示；数据库列仍保留，旧r19可忽略；配置兼容。","question":"回退到r19还要核对什么？","options":[{"text":"只检查按钮消失","correct":false,"feedback":"外观变化不足以证明链路恢复；按钮消失不能证明读写和归属检查恢复。"},{"text":"立即删除所有新字段","correct":false,"feedback":"没有必要且会扩大数据风险；兼容的新增列可保留，不应扩大成删列事故。"},{"text":"实际版本与核心读写、权限仍正确","correct":true,"feedback":"兼容假设需要运行结果验证；还需核对当前r19与配置结构能否正常配合。"}],"output":"教学结果：实际版本已恢复r19，列表、新建与刷新回读正常；跨账户请求仍拒绝且他人记录未变。","evidence":["实际服务版本r19","核心流程结果","跨账户未变证据"]},{"name":"数据删除不是代码问题","input":"r21执行了清理误删20条记录；恢复r20代码后，记录仍缺失。","question":"代码已回退但记录仍缺，下一步应选择什么依据？","options":[{"text":"独立数据恢复方案及可接受缺失区间","correct":true,"feedback":"记录删除属于数据状态，需要合适恢复点。"},{"text":"继续重复代码回退","correct":false,"feedback":"重复同种操作不会恢复独立数据库记录。"},{"text":"只恢复前端本地缓存，作为删除记录已恢复的依据","correct":false,"feedback":"客户端缓存不是数据库真实状态，后续其他设备仍无法读取缺失记录。"}],"output":"教学结果：程序已恢复但20条记录仍缺，不能称数据恢复完成；后续先在副本核对备份范围和恢复点。","evidence":["缺失记录清单","备份时间与范围","副本恢复结果待核对"]}]},"practice":{"intro":"起点是可恢复的测试版本、版本说明和演示数据。没有外部发布授权时，在本地两个版本与测试数据库副本完成演练。","steps":["选择一个不删除数据的小变更，写新行为、旧行为回归与兼容条件。","记录前一版本、配置名、结构版本与恢复点，在副本验证更新。","完成冒烟和回归，再恢复前一代码版本并检查实际版本、数据和权限。","解释本次回退能恢复哪些内容，哪些数据变化需要独立备份或修复，形成记录。"],"prompt":"请在独立测试副本为当前项目演练小步更新与回退，选择一个兼容的小功能，先记录旧版本、配置名称、结构版本与演示数据恢复点。验证新功能和旧核心流程，再恢复旧代码版本并重测读写及隔离。明确区分代码回退、配置恢复、结构迁移和数据恢复；不要删除真实记录、操作生产或外部发布，不能把代码回退称作数据已恢复。","evidence":["新旧版本及兼容说明","更新后冒烟与回归","回退后实际版本与核心结果","代码/配置/结构/数据恢复范围对照"],"troubleshooting":[{"symptom":"回退代码后仍启动失败","check":"核对旧版所需配置名与当前结构","action":"恢复兼容配置或采用已验证修复版本，不盲目反向迁移。"},{"symptom":"代码恢复但记录仍缺失","check":"核对删除是否发生在数据库","action":"停止重复回退，转入独立副本的数据恢复演练。"}]},"checks":[{"question":"新前端已缓存，后端回退后不认新字段，说明什么？","options":[{"text":"只需认定用户操作错误","correct":false,"feedback":"缓存与版本组合是可预测条件；应设计新旧组合兼容而非仅归咎操作方式。"},{"text":"发布兼容还需考虑客户端与服务端组合","correct":true,"feedback":"同一时刻可能存在不同客户端版本；缓存中的新脚本可能继续调用旧后端不支持的接口。"},{"text":"数据恢复可自动解决接口不兼容","correct":false,"feedback":"记录恢复与请求协议是不同层次；数据记录回来也不必然修复字段协议不一致。"}]},{"question":"准备回退时发现旧配置已被覆盖，最佳做法是什么？","options":[{"text":"继续点击回退直到成功","correct":false,"feedback":"重复操作不能补齐丢失条件；先找到与旧版匹配的配置名称与来源。"},{"text":"把秘密写进旧源码再发布","correct":false,"feedback":"会扩大泄漏并破坏配置管理；秘密进入源码还可能流入仓库和构建产物。"},{"text":"先确认可用配置与版本组合及恢复路径","correct":true,"feedback":"缺少兼容配置，直接回退可能扩大中断。"}]}],"sources":[{"label":"PostgreSQL：结构变更与约束","url":"https://www.postgresql.org/docs/current/ddl-alter.html","checked":"2026-10-16"},{"label":"Twelve-Factor：配置独立于代码","url":"https://12factor.net/config","checked":"2026-10-16"}]},{"id":"12.04","title":"备份有效性与恢复演练","lead":"下载了一个名叫backup的文件，就能保证任务回来吗？只有在独立副本恢复并检查应用，才能知道它真正包含什么。","goals":["能说明备份范围、恢复点与可能缺失的数据时间区间。","能在独立副本恢复并验证关键记录、关系和应用流程，而非只看导入成功。"],"sections":[{"title":"先问恢复什么，而不是有没有文件","paragraphs":["备份可能只含表数据，也可能含结构、部分权限或其他对象；上传附件、身份服务数据和平台配置可能另存。先列恢复对象与依赖，才能判断当前方案覆盖哪些。一个数据库备份不必然包含前端版本或外部文件，不能笼统说“整个应用都备好了”。","不同备份方法有不同条件，例如逻辑导出适合恢复到兼容数据库，物理备份与日志恢复往往需要更严格的版本和配置。课程不要求初学者掌握所有底层操作，但必须能查清所选方案范围、所需工具和访问权限。"]},{"title":"恢复点决定可能丢失的时间区间","paragraphs":["如果最后可用备份在上午10点，误删发生在12点，恢复到10点通常不包含其间新增记录。可接受损失多少数据、可接受多久恢复，应在事故前按用途决定。小规模演示与重要业务的要求不同，不能用“每天备份”自动推导“不会丢数据”。","支持时间点恢复的系统可能结合基础备份和持续日志，但是否可用、保留多久、是否额外付费，都取决于平台与配置。课程只解释机制，具体承诺需要查当前官方资料并实际验证。没有开启相关能力时，不能事后假设任意分钟都可恢复。"]},{"title":"独立副本避免演练破坏原环境","paragraphs":["恢复可能覆盖现有数据，因此先创建获准使用的独立测试副本，明确目标名称、版本和网络范围，再执行。不要直接对正式库试一遍“看看能否恢复”。本课的核心是用可控范围检查备份，而不是制造一次真实事故。","恢复后核对结构版本、关键演示记录、数量或摘要、归属关系和约束；仅看恢复工具提示成功不够。空备份也可能“成功导入”，却没有你需要的数据。选择已知标记记录作为检查点，能发现目标库错误、导出范围遗漏或时间点不符。"]},{"title":"应用能运行才完成恢复验证","paragraphs":["数据库记录出现后，还要让匹配版本的应用连接副本，完成登录、读取、新建、修改、删除与跨账户拒绝。权限和序列等配置遗漏可能使“看得到旧数据”与“能继续使用”分离，需要在业务操作中发现。","报告写明备份时间、范围、恢复目标、工具与版本、缺失区间及未覆盖对象。恢复演练不是一次完成后永久有效，结构、工具或数据规模变化后要重查。也不要把成功演练称作零损失保证；它证明的是当前方案在列出条件下可用。"]}],"glossary":[{"term":"恢复点","meaning":"可回到的数据时刻或状态，决定哪些后续变化可能缺失。"},{"term":"逻辑备份","meaning":"以可重新创建结构和记录的逻辑形式导出，兼容条件需核对。"},{"term":"恢复演练","meaning":"在受控副本实际恢复并验证数据和业务，而非只确认文件存在。"}],"predict":{"question":"10点备份，12点误删；仅有该备份，能保证11点新增任务也恢复吗？","options":[{"text":"不能，需说明10点之后可能缺失","correct":true,"feedback":"备份只能提供它实际覆盖的状态，除非另有有效日志或其他依据。"},{"text":"能，恢复程序会自动补齐历史","correct":false,"feedback":"程序不会凭空重建未保存记录；t3若不在备份或日志中，就没有可据以重建的内容。"},{"text":"只要文件名含当天日期就能","correct":false,"feedback":"文件名不是内容和时间范围的证据；需要检查实际导出时刻与记录内容而非名字。"}]},"experiment":{"title":"备份有效性与恢复演练：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"文件存在但内容不全","input":"backup.sql可读，导入成功；只含tasks结构，没有三条应有演示任务。","question":"导入成功但三条目标任务不存在，应如何判定？","options":[{"text":"通过，因为没有报错","correct":false,"feedback":"空结构也能成功创建，缺少关键内容；必须找到三条已知标记任务而非只看导入日志。"},{"text":"恢复验证失败，备份范围不满足目标","correct":true,"feedback":"工具成功不等于目标记录存在；结构创建成功还可能完全没有业务记录。"},{"text":"看到表已经存在，就将三条任务标记为已恢复","correct":false,"feedback":"表结构存在不能证明目标记录内容可读，应核对已知标记和真实数据。"}],"output":"教学结果：核对发现备份只含结构，三条目标记录都缺失；需修正导出范围并重新在独立副本恢复。","evidence":["关键记录缺失","导出选项仅结构","重新恢复需核对真实内容"]},{"name":"时间范围清楚的恢复","input":"10点备份含t1/t2，11点新增t3，12点误删；副本恢复后只有t1/t2。","question":"只恢复t1/t2没有t3时，恢复结论怎样写准确？","options":[{"text":"全部数据零损失恢复","correct":false,"feedback":"t3缺失，不能宣称零损失；10点后变化没有被当前恢复点覆盖。"},{"text":"彻底失败，因为必须恢复所有未来记录","correct":false,"feedback":"目标若是10点状态，则该范围可以成功，但需说明损失。"},{"text":"10点状态恢复成功，t3不在当前备份范围","correct":true,"feedback":"同时陈述成功范围与明确缺失；t1和t2可核对成功，t3明确在时间范围外。"}],"output":"教学结果：t1/t2内容归属与应用操作通过，10点状态恢复成功；明确10点后的t3不在本次恢复范围。","evidence":["t1/t2内容与归属","t3不在恢复范围","应用读写及拒绝路径"]}]},"practice":{"intro":"起点是演示数据库、明确备份方式与可创建的独立本地副本。线上快照或时间点恢复需要目标资源授权和当前官方条件。","steps":["列备份范围、恢复目标、时间点、版本要求和可能缺失区间，包含附件及配置缺项。","对演示库建立备份，记录已知任务标记；另建明确命名的恢复副本。","将备份恢复到副本，核对结构、记录、归属、约束及遗漏。","让匹配应用连接副本完成核心读写与两账户拒绝，整理可用范围和改进方案。"],"prompt":"请在独立本地测试副本演练数据库备份恢复，不触碰生产。先说明备份包含结构/记录/权限哪些对象，不包含哪些外部文件或配置；记录备份时刻和已知演示任务。恢复到明确命名的新副本，核对内容、归属、约束与版本，再用应用验证核心操作和跨账户拒绝。报告缺失区间与恢复限制，不声称零损失，不创建付费资源或上传备份。","evidence":["备份范围、时间点与工具版本","独立恢复目标及实际执行结果","关键记录/归属/约束核对","应用正常与拒绝路径、缺失区间"],"troubleshooting":[{"symptom":"导入成功但没有记录","check":"核对备份是否仅结构、表范围与目标库","action":"确认内容后重新生成完整演示备份，在副本再恢复。"},{"symptom":"记录可读但无法新增","check":"检查权限、约束、序列与应用版本","action":"按具体错误修复恢复缺项，再验证读写和隔离，不能只重导一次。"}]},"checks":[{"question":"数据库恢复了，但上传图片不在，如何解释？","options":[{"text":"图片可能在外部存储，未纳入本次备份","correct":true,"feedback":"恢复范围应逐对象说明，数据库未必包含文件。"},{"text":"说明所有数据库记录都不可信","correct":false,"feedback":"文件缺失不自动否定已核对记录；可确认数据库部分成功，同时记录外部对象缺项。"},{"text":"刷新即可从数据库凭空生成","correct":false,"feedback":"未保存的文件内容不能由刷新恢复；数据库没有包含的二进制内容不会自行出现。"}]},{"question":"为了证明备份有效，直接覆盖正式库试恢复合适吗？","options":[{"text":"合适，因为真实环境最准确","correct":false,"feedback":"真实性不能替代控制影响范围；演练先控制目标，避免覆盖当前仍有效的数据。"},{"text":"应先在独立副本验证","correct":true,"feedback":"恢复可能覆盖现有数据，演练不应制造事故。"},{"text":"只要事先截图就安全","correct":false,"feedback":"截图无法恢复被覆盖的全部数据；截图通常只含部分可见内容而非完整恢复材料。"}]}],"sources":[{"label":"PostgreSQL：备份与恢复分类","url":"https://www.postgresql.org/docs/current/backup.html","checked":"2026-10-16"},{"label":"PostgreSQL：逻辑导出恢复","url":"https://www.postgresql.org/docs/current/backup-dump.html","checked":"2026-10-16"},{"label":"PostgreSQL：时间点恢复条件","url":"https://www.postgresql.org/docs/current/continuous-archiving.html","checked":"2026-10-16"}]},{"id":"12.05","title":"面向小规模真实试用的交接","lead":"作品能运行不代表能持续有人使用。如果你暂时不在线，另一人怎样知道这是哪一版、出了错找谁、资源何时该停止？","goals":["能写出资源、版本、权限、当前费用依据与逐项停止方式的运行说明。","能用真实证据汇总V4状态、已知限制和脱敏反馈入口，不夸大待验收项。"],"sections":[{"title":"运行说明把依赖变成可找到的信息","paragraphs":["交接不必写厚手册，但应列入口、代码版本、前后端服务、数据库环境、身份方案、配置名称与负责人。它使接手者知道某条请求经过哪些资源，哪些需要授权访问，而不是靠开发者记忆和浏览器收藏夹维持。","秘密通过合适的凭据管理方式交接，说明只记录获取途径与权限要求，不写真实值。所有权也要清楚：谁能部署、谁能改数据库、谁负责账单与停止资源。借用一个未说明的个人账户运行，可能在账户变化后失去维护入口。"]},{"title":"费用控制需要当前规则与实际观察","paragraphs":["服务可能按请求、运行时长、存储、带宽或其他指标收费，也可能有套餐与额度限制。具体计费、免费条件和提醒能力会变化，应查当前官方页面并记录日期，不能沿用课程示例数字做承诺。","预算提醒不一定是硬上限，设置提醒后仍可能继续产生费用；实际是否自动停止要按平台机制验证。小规模试用可限制输入、上传、重复请求与试用人数，并明确如何停用服务和清理资源。停止应用不一定停止数据库、存储或域名费用，需逐项核对。"]},{"title":"已知限制帮助试用者作正确决定","paragraphs":["说明本作品适合演示或小规模试用，哪些功能尚未完成，数据是否会定期清理，能否导出以及故障时如何反馈。若没有真实生产级备份或可用性安排，就不能因为页面漂亮而暗示适合重要业务。","反馈入口应要求时间、版本、复现步骤、预期与实际，提醒不要上传密码和私人材料。当前用户授权制作课程并不等于授权对外邀请或发送消息；独立练习只准备交接材料，有明确试用授权后再按范围分享。"]},{"title":"V4是多类证据的组合","paragraphs":["可维护版需要真实访问、隔离、更新、回退和副本数据恢复证据，并清楚写出各自环境与范围。若只完成本地演练，应标为对应能力已练习，真实线上项待完成。一个总勾选不能替代这些性质不同的结果。","交接可做一次受控可读性检查：请获准的协作者仅按说明找到入口、识别版本并提交一条演示问题；若没有协作者，可自行在干净环境核对并说明局限。以实际卡点修订说明，保留更新记录，让后来者知道哪些步骤已过时。"]}],"glossary":[{"term":"运行说明","meaning":"帮助识别资源、版本、操作和恢复入口的简短交接材料。"},{"term":"预算提醒","meaning":"接近费用条件时通知的机制，不一定阻止继续消费。"},{"term":"已知限制","meaning":"已经了解但尚未解决的功能、环境或可靠性边界。"}],"predict":{"question":"平台已设置预算提醒，能保证费用不会超过该数额吗？","options":[{"text":"能，只要提醒发送成功","correct":false,"feedback":"通知送达不会自动改变资源运行；服务是否暂停仍取决于平台的硬限制设置。"},{"text":"把提醒截图放说明中就能保证","correct":false,"feedback":"截图不能替代当前计费与停止规则；当前套餐、计费项与关闭能力需要实际查阅。"},{"text":"不能，需查提醒与硬限制的实际机制","correct":true,"feedback":"提醒通常是通知条件，是否停用必须另行确认。"}]},"experiment":{"title":"面向小规模真实试用的交接：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"材料可追踪","input":"说明含版本r22、前后端地址、测试库代号、配置名、恢复记录及停止资源清单，不含秘密。","question":"对这一份交接说明，哪项检查最能证明可用？","options":[{"text":"按说明在获准环境找到并核对资源与流程","correct":true,"feedback":"实际可执行性比文档长度更有证明力；接手者能找到正确版本与资源才表明说明有用。"},{"text":"把所有资源统称为云端，不再区分服务入口","correct":false,"feedback":"这样无法定位数据库与后端的独立管理和停止步骤，交接者仍难执行。"},{"text":"把全部密码放同一页","correct":false,"feedback":"会扩大泄漏，且非必要交接方式；公开说明应写安全获取方式而不是凭据本身。"}],"output":"教学结果：自查发现停止清单漏了数据库，补齐依赖资源后仍标明未完成真人交接；不扩大为已被他人验证。","evidence":["入口与版本可识别","资源清单能对应实际对象","明确标记检查范围"]},{"name":"服务停止仍有资源","input":"前端已停用；数据库和对象存储仍运行，平台账单指标继续变化。","question":"前端已停而数据库仍运行，为什么可能继续计费？","options":[{"text":"账单一定显示错误","correct":false,"feedback":"需要先核对实际存续资源及当前规则；账单可能包含仍在运行的数据库与存储。"},{"text":"不同资源有独立生命周期与计费项","correct":true,"feedback":"停止一个组件不等于删除或暂停全部依赖。"},{"text":"只停止登录入口，不检查数据库和存储状态","correct":false,"feedback":"阻止用户进入不等于远端资源已停止，独立资源仍可能继续运行与计费。"}],"output":"教学结果：停止方案按资源逐项核对，费用结论等待官方规则与实际账单验证。","evidence":["资源列表仍有数据库/存储","停止清单区分组件","未虚构费用数额"]}]},"practice":{"intro":"起点是V4练习材料：版本与环境表、部署验收、回退记录和副本恢复结果。缺少真实线上项时明确列出，不补造证据。","steps":["整理一页入口、版本、资源职责、权限负责人和秘密获取方式说明。","查看所用服务当前官方费用与限制，记录计费维度、提醒能力和逐项停止方法。","汇总核心流程、两账户、失败、更新回退与恢复证据，列已知限制和未覆盖项。","准备不含敏感信息的反馈模板，在获准范围做可读性检查并修订；没有授权不对外发送。"],"prompt":"请依据现有真实记录整理小规模试用交接说明，包含入口/版本、前后端和数据库环境、权限负责人、配置名称与安全获取途径、当前官方计费与资源限制链接、预算提醒是否硬限制、逐项停止资源方法、已知限制、反馈模板和恢复记录。区分本地演练与真实线上验收，不编造费用或通过结果；不要发送邀请、创建资源、付费或发布。","evidence":["资源与版本说明","当前费用依据和停止清单","V4各项真实证据及缺项","已知限制与脱敏反馈模板"],"troubleshooting":[{"symptom":"说明写了地址却找不到服务","check":"核对账户归属、项目标识与访问权限","action":"补明确可授权的管理入口与负责人，不将密码写进公开说明。"},{"symptom":"试用资源无法判断是否停止","check":"核对前端、后端、数据库、存储各自状态","action":"依据平台当前机制逐项停用与核验，保留仍可能计费的对象说明。"}]},"checks":[{"question":"只有本地回退与恢复演练，如何写V4状态？","options":[{"text":"全部V4已完成，因为步骤相同","correct":false,"feedback":"线上地址、配置和权限仍需实际核对；相同说明在真实平台仍可能遇到配置差异。"},{"text":"删掉所有演练记录","correct":false,"feedback":"真实练习证据仍应保留，只需说明范围。"},{"text":"对应演练已完成，真实上线项目仍待验收","correct":true,"feedback":"不同环境的证据不能互相冒充；本地演练不能证明线上地址和权限实际正确。"}]},{"question":"反馈模板应收集哪些信息？","options":[{"text":"版本、时间、复现、预期实际与脱敏结果","correct":true,"feedback":"这些信息能定位问题而无需完整秘密；应取最小相关材料而不索要完整身份凭证。"},{"text":"密码和全部数据库导出","correct":false,"feedback":"信息过多且敏感，通常不是最小排错材料。"},{"text":"只需一句不好用","correct":false,"feedback":"缺少条件难以复现并验证修复；没有版本和步骤就无法判断是否同一问题。"}]}],"sources":[{"label":"Twelve-Factor：配置交接","url":"https://12factor.net/config","checked":"2026-10-16"},{"label":"PostgreSQL：恢复范围","url":"https://www.postgresql.org/docs/current/backup.html","checked":"2026-10-16"},{"label":"AWS官方示例：预算通知可能延迟且不自动保证硬上限","url":"https://docs.aws.amazon.com/cost-management/latest/userguide/budgets-managing-costs.html","checked":"2026-10-16"}]},{"id":"13.01","title":"选择一个新的真实问题","lead":"把“任务”改名为“读书”，页面仍只有完成勾选，这能说明你已经迁移能力了吗？先找出新使用场景真正改变了什么。","goals":["能从具体使用场景提出新问题，并找出不同于任务工具的约束。","能限定一条可完成闭环，分别列技术验收与待验证的使用价值假设。"],"sections":[{"title":"问题要包含使用者与发生时机","paragraphs":["真实问题不必宏大，可以是“我读书时常记不住某条笔记对应哪一页，复习时找不到原文”。这比“做一个读书平台”更具体，因为它说明谁在什么时候遇到什么阻碍，以及怎样观察改进是否有效。技术选型应在问题清楚之后。","选题可从读书记录、习惯打卡或物品管理出发，但先用虚构材料验证流程，不急着上传私人内容。没有真实用户访谈时，可以把当前设想标为自己的假设，并用后续观察修订；不要把AI编的用户故事当作已经完成的调研证据。"]},{"title":"迁移要求出现新的约束","paragraphs":["任务管理的核心记录可能是标题与完成状态，读书笔记则需要书籍、页码或章节与摘记之间的关联。习惯打卡可能要求同一人同一天只能有一条记录，物品借还则要区分归属与当前借用状态。至少一项这种差异会改变数据或行为。","仅换名称、图标与配色主要证明熟悉原模板，不能证明会处理新约束。反例是把书名放进任务标题，然后仍用完成状态表示读完或借出；当一书有多条笔记、多人借同一本实体书时，含混模型很快出错。要从冲突例子倒推必要结构。"]},{"title":"先缩成一条可完成的闭环","paragraphs":["最小范围应仍能解决一个问题。例如先做“新增书籍→添加带页码笔记→按书查看→修改删除本人笔记”，暂不做社交、AI推荐和电子书全文上传。这样既有新关联，也能在有限时间验证端到端链路。","缩范围不是省略身份隔离和恢复要求。若成果要联网且有私人记录，可信身份、归属、错误提示与备份仍属于基础责任。可以减少功能数量，不能因为是小项目就把他人数据访问默认放开，或只做可点击却不保存的外观。"]},{"title":"用证据区分价值假设与技术结果","paragraphs":["技术验收可以检查页码格式、关联、保存和拒绝路径；价值假设则需要观察使用者是否更容易找回记录。两者不能互相替代：代码正确不保证有人需要，用户说喜欢也不保证数据隔离正确。报告分别列出目前依据和待验证部分。","选题完成应提交问题描述、原任务工具与新需求差异、最小范围、非目标及可核对验收。后续收到只给目标的变更时，能够解释它影响哪些数据和行为，才是独立迁移的继续证据，而不是靠不断追加模板功能凑完整。"]}],"glossary":[{"term":"迁移","meaning":"将已有原理应用到条件不同的新问题，并验证必要变化。"},{"term":"最小范围","meaning":"仍能完成一条有价值闭环的有限功能集合。"},{"term":"价值假设","meaning":"关于使用者获益的待验证判断，不等于已证实事实。"}],"predict":{"question":"把任务页面改成读书记录，何种变化最能体现迁移？","options":[{"text":"换成书籍背景图但数据不变","correct":false,"feedback":"视觉修改不能证明新领域约束得到处理。"},{"text":"一书多笔记并有页码关联，重新设计与验证规则","correct":true,"feedback":"它改变了数据关系和用户行为，而不只是名称。"},{"text":"把所有按钮文案改成阅读","correct":false,"feedback":"文案更贴题，但不足以证明新行为成立。"}]},"experiment":{"title":"选择一个新的真实问题：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"名称变化但模型未变","input":"需求：一书可有多页笔记；方案：把每条书名放入任务标题，仍只有完成勾选。","question":"对于一书多页笔记，原任务表方案遗漏了什么？","options":[{"text":"先加全文搜索，暂时仍用完成状态代替笔记关系","correct":false,"feedback":"搜索不能弥补书籍与笔记定位关系缺失，应先明确记录的结构和约束。"},{"text":"继续只用任务标题保存所有信息，关系留给用户记忆","correct":false,"feedback":"书名、页码与笔记会失去明确结构，难以可靠支持一书多笔记和修改。"},{"text":"书籍与多条页码笔记的明确关系","correct":true,"feedback":"原模型未表达新需求中的关联与定位；缺少book与note关系，就无法稳定定位到书和页码。"}],"output":"教学结果：问题范围修订为书籍与笔记两类记录，首版验证一本书的两条页码笔记均能正确定位。","evidence":["列出一书两条笔记示例","每条笔记可追溯书与页码"]},{"name":"小范围有真实差异","input":"需求：同一习惯同一天只打卡一次；第一版只做新增、今日打卡与历史查看。","question":"范围是否过小而不能迁移？","options":[{"text":"仍可体现迁移，需实现日期唯一性等新约束","correct":true,"feedback":"闭环虽小，条件已与普通任务工具不同。"},{"text":"是，必须同时做社交排行榜","correct":false,"feedback":"规模大小不是迁移成立的依据；小闭环同样可以要求同日唯一等新机制。"},{"text":"无需检查重复，因为功能少","correct":false,"feedback":"重复限制正是核心需求，不能省略；若重复创建被允许，首版核心目标就失败。"}],"output":"教学结果：以同日重复受限、跨日期可独立新增形成验收，不把社交排行加入首版，保留真实数据差异。","evidence":["同日重复被限制","次日独立记录可创建"]}]},"practice":{"intro":"起点是一份你亲自遇到的问题描述与已完成的任务工具经验。只选一个方向，不同时启动多个应用。","steps":["写明使用者、发生时机、当前替代办法和想改善的具体结果，用演示材料举例。","列与任务工具至少一项数据或交互差异，写一个会让旧模型失败的例子。","限定一条核心闭环、非目标与必要身份恢复边界，避免把所有想法放进首版。","整理验收和待验证价值假设，请Codex审查遗漏，只修订问题卡，暂不实现。"],"prompt":"请协助我把一个新问题写成独立作品问题卡：使用者、发生时机、目前困难、演示输入、预期结果。比较原任务工具，指出至少一项数据/关联/日期/权限或交互差异及旧模型失败例子；限定一条可完成闭环，列非目标、验收和待验证假设。先讨论问题与范围，不写界面、不生成批量素材、不创建资源或发布。","evidence":["具体问题与假设来源","新旧需求差异和冲突例子","最小闭环与非目标","技术验收与价值待验证项"],"troubleshooting":[{"symptom":"选题只剩换名称","check":"核对新使用场景的关系、时间或权限限制","action":"找一个旧模型无法正确表达的例子，再决定是否保留方向。"},{"symptom":"首版功能越列越多","check":"检查哪些功能直接支持当前闭环","action":"把社交、推荐等推迟，只保留能验证核心问题的必要项。"}]},"checks":[{"question":"新物品工具要记录借出和归还，最该先研究什么？","options":[{"text":"直接把完成状态映射为已借出，不说明归还与冲突","correct":false,"feedback":"只有状态改名还没定义借还合法转移及重复借出条件，难以形成可验收行为。"},{"text":"物品状态、借用关系与冲突规则","correct":true,"feedback":"它们决定数据和行为，与原完成勾选不同。"},{"text":"先复制完整任务界面，再把借还规则留到上线后","correct":false,"feedback":"核心状态与关系会影响模型和接口，延后可能使首版从一开始就不符合需求。"}]},{"question":"朋友说界面好看，能证明新工具解决真实问题吗？","options":[{"text":"能，满意就是全部验收","correct":false,"feedback":"满意不覆盖价值和技术正确性；好评无法证明实际保存与隔离规则正确。"},{"text":"不能，因此外观永远不重要","correct":false,"feedback":"外观影响理解与使用，但只是部分证据。"},{"text":"还需观察具体任务是否更容易完成","correct":true,"feedback":"喜欢外观与实际获益是不同证据；找回原文是否更容易需要任务观察与结果。"}]}],"sources":[{"label":"MDN：先计划网站目标与内容","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Your_first_website/What_will_your_website_look_like","checked":"2026-10-16"}]},{"id":"13.02","title":"独立写需求与确认原型","lead":"一句“做得简洁些”让AI画出了完全不同的页面。怎样把目标、行为和视觉分开确认，让后续实现有稳定依据？","goals":["能把新作品需求写成输入、动作、结果与失败条件。","能先讨论并确认一张具体视觉原型，保留歧义修订与未展示状态说明。"],"sections":[{"title":"需求把模糊愿望变成条件","paragraphs":["“好用”需要展开成使用者能完成的动作与结果。例如读书记录要求新增书籍、在书下添加页码笔记、刷新仍可查看，A不能访问B的私人笔记。每条都能设计输入与观察，而不是只能靠主观判断。","也写失败条件：页码无效如何提示，网络失败是否保留草稿，删除是否需要确认。只写正常页面容易让实现者自行猜测这些行为。需求中区分已确认事实、当前假设和待决定项，能避免AI把一个猜测扩展成整套功能。"]},{"title":"原型回答布局与视觉的具体问题","paragraphs":["视觉原型展示信息层级、入口、文字密度、颜色和状态表达，便于发现“我说的简洁”与对方理解是否一致。它应围绕最关键页面和一个代表状态，先少量探索，经过讨论与明确确认后，再继续实现或扩展素材。","确认文字方向不等于确认最终原型图。只说“偏黑金”仍无法决定导航、留白与重点；应展示具体图并保留最终确认记录。原型中的按钮只是表现形式，不能把它当作登录、保存或错误处理已经实现，也不能用漂亮图片替代行为清单。"]},{"title":"静态图没有展示的行为要补清单","paragraphs":["一张图通常看不到加载、空数据、验证错误、网络失败、权限拒绝或手机导航。将这些列为状态说明，并写从什么动作进入、显示什么、下一步可做什么。这样实现者不会在缺少信息时自动把失败当成功，或把空页面误作无权限。","例如“保存失败时保留笔记正文，提示未保存并允许重试”，比“有错误提示”更具体。若原型为了简洁没画错误状态，也应在说明中承认并定义行为；不能凭视觉确认推断所有交互细节也已同意。"]},{"title":"修改一个误解检验表达质量","paragraphs":["请Codex复述需求并指出不明确处，再找一条可能误解的要求进行修订。例如“按时间排序”到底是笔记创建时间、书籍开始阅读时间，还是最后修改时间。换成一组明确演示数据与预期顺序，可以消除不同解释。","交付应含需求版本、验收表、最终原型、确认记录及未展示状态说明。收到新目标时先判断影响范围，需要新视觉的先补原型确认，纯行为变更则更新验收。这样既保留创作空间，也避免在用户尚未确认的方向上大量实现。"]}],"glossary":[{"term":"验收条件","meaning":"说明在什么输入与动作下应观察到什么结果。"},{"term":"视觉原型","meaning":"用于讨论和确认外观与信息结构的具体图，不等于可用应用。"},{"term":"状态说明","meaning":"描述加载、空白、成功和失败等条件下界面行为的材料。"}],"predict":{"question":"用户已同意“清爽阅读风”，是否可以直接批量实现所有页面？","options":[{"text":"应先展示具体视觉原型并取得最终确认","correct":true,"feedback":"文字方向不能确定实际布局和状态表现。"},{"text":"可以，风格词已覆盖所有视觉决定","correct":false,"feedback":"同一风格词可能对应截然不同页面；导航、留白和信息重点仍可能有很多合理版本。"},{"text":"只要先写代码再截图就无需原型","correct":false,"feedback":"这仍把大量实现放在最终视觉确认之前。"}]},"experiment":{"title":"独立写需求与确认原型：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"排序需求有歧义","input":"需求写“最近优先”；书A今天改笔记，书B昨天新建；未说明按什么时间。","question":"在A今天修改、B昨天新建的条件下，怎样让排序可检验？","options":[{"text":"让AI自行选一种就算已确认","correct":false,"feedback":"实现者选择不等于使用者认可；AI代选排序字段并不表示用户已同意该含义。"},{"text":"明确排序字段，并给出A/B预期顺序","correct":true,"feedback":"输入与预期能排除另一种合理解释；A/B数据的顺序能检验到底使用哪个时间。"},{"text":"将排序统一叫最近，不给具体字段和数据顺序","correct":false,"feedback":"同一词仍可指创建或修改，必须用字段和预期顺序消除歧义。"}],"output":"教学结果：需求n2明确按笔记修改时间降序，所以A在B前；保留旧歧义与本次修订理由供实现核对。","evidence":["确定时间字段","示例顺序可核对","修订记录说明误解"]},{"name":"原型没画失败状态","input":"最终图展示笔记页；网络失败、空列表与越权访问没有画出。","question":"原型没有展示失败与越权状态，视觉确认覆盖了什么？","options":[{"text":"覆盖全部技术实现和权限","correct":false,"feedback":"外观无法证明服务端行为；服务端授权和持久化仍需独立运行证据。"},{"text":"原型完全无用，应全部重做","correct":false,"feedback":"已有确认仍有价值，可补状态说明；可以保留已确认布局并为缺失状态补充文字。"},{"text":"覆盖图中表现，未展示行为仍需明确","correct":true,"feedback":"静态图不自动定义所有运行状态；图中看不到失败时输入保留或重试的决定。"}],"output":"教学结果：保留已经确认的页面原型，另补失败保留草稿、空列表和权限拒绝的行为及恢复入口。","evidence":["原型版本与确认","未展示状态清单","每种状态的下一步动作"]}]},"practice":{"intro":"起点是13.01的问题卡与最小范围。按用户视觉偏好，先做一张关键页原型并讨论，确认前停在可审查材料。","steps":["把闭环写成输入、动作、结果与失败条件，准备两组不同演示数据。","请Codex复述需求，找一处歧义并修订，用预期结果消除不同解释。","制作一张关键页视觉原型，讨论修改并保留最终确认；未确认时不继续界面实现。","补充原型未展示的状态与手机行为，整理需求版本、验收和待决定项。"],"prompt":"请基于我的新作品问题卡先整理需求与验收，不实现界面。写正常、空数据、无效输入、网络失败和无权限状态；用两组演示数据说明排序与保存。先复述并指出一处可能误解，修订后只做一张关键页视觉原型供讨论，必须等我确认最终图才继续实现或扩展素材。保留需求版本、原型确认和未展示行为清单，不创建资源或发布。","evidence":["需求与可观察验收表","歧义修改前后对照","具体原型与最终确认记录","未展示状态及手机说明"],"troubleshooting":[{"symptom":"每个人理解的最近不同","check":"检查究竟指创建、修改还是业务日期","action":"明确字段与示例顺序后重述需求，避免只替换同义词。"},{"symptom":"原型确认后出现全新布局","check":"核对实现是否仍对应确认版本","action":"回到批准图修正；确需新视觉时先展示修改原型再实现。"}]},"checks":[{"question":"原型有保存按钮，能否认为失败保留草稿已经明确？","options":[{"text":"不能，应补保存失败的行为条件","correct":true,"feedback":"按钮存在不说明失败时输入如何处理；网络失败后可能清空输入，也可能保留草稿。"},{"text":"可以，所有应用都应默认相同","correct":false,"feedback":"不同实现可能清空、保留或重复提交；同一按钮形态无法确定哪种数据处理发生。"},{"text":"只要按钮颜色醒目即可","correct":false,"feedback":"颜色不定义数据和恢复行为；需要明确输入生命周期与服务端写入结果。"}]},{"question":"需求变更只改变排序规则，最该更新什么？","options":[{"text":"只更新排序按钮文案，不改变验收数据","correct":false,"feedback":"文案不能证明新规则实际执行，应以能区分新旧结果的输入验证。"},{"text":"行为验收与对应演示数据","correct":true,"feedback":"需要让新规则可观察并验证旧行为影响。"},{"text":"沿用旧排序测试，不添加新规则的边界条件","correct":false,"feedback":"旧测试可能无法区分新旧顺序，需补能触发当前变化的演示数据。"}]}],"sources":[{"label":"MDN：网站规划与草图","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Your_first_website/What_will_your_website_look_like","checked":"2026-10-16"}]},{"id":"13.03","title":"解释架构与数据决定","lead":"Codex建议“直接沿用任务表”，另一个方案却拆成书籍与笔记。你不需要背架构术语，但需要说明哪种结构能守住新需求。","goals":["能用新业务示例比较至少两项架构或数据选择及其限制。","能解释归属、外键与授权的不同职责，预测跨账户关联为何应拒绝。"],"sections":[{"title":"按职责追踪一次真实动作","paragraphs":["先用新增笔记说明数据流：浏览器收集书籍、页码与正文，后端验证身份、输入和书籍权限，数据库保存关系，再把业务结果返回页面。界面验证帮助体验，可信入口验证决定是否允许，两者不能互相替代。","读书工具也许采用一体化框架，使前端和后端代码放在一个项目，但浏览器与服务端的执行位置仍不同。应能指出秘密在哪里、身份在哪里被认可、归属在哪里限制。文件数量或项目名字不能直接说明这些职责是否正确。"]},{"title":"比较方案要用具体约束","paragraphs":["方案一可把书名写进每条笔记，容易起步，但改书名可能需要更新很多记录，也难以区分同名书；方案二用书籍表和笔记表关联，结构更清楚，却需要处理外键与删除行为。选择取决于当前闭环，而不是哪种听起来更专业。","至少比较两项实际取舍，如是否支持一书多笔记、是否保留无笔记书籍、删除书籍时怎样处理笔记。用演示数据试推结果，能让取舍从偏好变成可解释决定。小应用也可以选简单方案，只要承认限制并验证关键要求。"]},{"title":"归属与关联要共同成立","paragraphs":["笔记有owner不代表可以随意关联任何bookId。A新增笔记时若引用B的私人书籍，可能泄漏关联信息或破坏B的数据视图。后端需要核对书籍属于A或A确有授权，同时以可信身份确定笔记归属。","数据库外键主要保证引用对象存在，不自动保证同一用户拥有两边对象；唯一约束可以限制同日打卡，但不能替代用户身份验证。将结构一致性与业务授权分别说明，并在合适层落实，避免把某个数据库功能当成所有问题的自动解答。"]},{"title":"限制说明让将来变化可控","paragraphs":["当前只支持私人书籍，就明确没有共享和团队编辑；如果未来需要共享，权限关系和删除规则可能调整。现阶段不必提前实现复杂组织架构，但要知道哪些假设支撑当前简化，避免把“暂时不做”写成“永远不会发生”。","架构决策记录包括选项、依据、限制与验证。让学习者用自己的话讲一次A保存笔记的全过程，再改变条件为引用B书籍，看是否能预测拒绝位置。能够解释条件改变后的结果，比背诵“前后端分离”更能证明理解。"]}],"glossary":[{"term":"外键","meaning":"约束记录引用的目标存在等关系，不自动判断用户是否有权访问。"},{"term":"架构决定","meaning":"关于职责、数据和连接方式的选择，应有需求依据与限制。"},{"term":"关系模型","meaning":"用对象及其关联表达业务，例如一本书对应多条笔记。"}],"predict":{"question":"A新建笔记，bookId指向B的私人书籍，外键检查通过，是否可以写入？","options":[{"text":"可以，外键已经证明权限","correct":false,"feedback":"外键解决结构关系，不验证当前业务授权。"},{"text":"只要笔记owner写A就够","correct":false,"feedback":"笔记归属正确仍可能引用无权访问的对象。"},{"text":"仍需核对A对书籍的访问权限并拒绝越权","correct":true,"feedback":"对象存在不等于A有权把它作为私人笔记目标。"}]},"experiment":{"title":"解释架构与数据决定：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"两个结构方案","input":"需求支持一书多笔记和改书名；方案一每条复制书名，方案二书籍ID关联笔记。","question":"比较时最有力的依据是什么？","options":[{"text":"改名与同名书场景下结果是否一致可控","correct":true,"feedback":"它直接对应需求里的变化和辨识问题；同名与改名是当前闭环必须表达的业务差异。"},{"text":"只考虑首轮录入最快，不检查改名和同名场景","correct":false,"feedback":"起步成本是一个因素，但忽略已确认场景会使选择缺少关键业务依据。"},{"text":"只看是否沿用现有表名，不比较记录关系","correct":false,"feedback":"表名不说明一书多笔记是否可表达，选择应以具体数据变化为依据。"}],"output":"教学结果：选择关联方案并记录删除书籍需定义笔记处理，不以复杂度作优越判断。","evidence":["同名书可区分","改名不需逐条改笔记","删除关联规则待确认"]},{"name":"存在不等于有权","input":"book7属于B；A提交笔记owner=A、bookId=book7；目标书确实存在。","question":"外键已证明book7存在，还应补哪方面判断？","options":[{"text":"把bookId从数字改成随机字符串即可","correct":false,"feedback":"难猜不能替代对已知编号的授权；攻击者已知book7后仍必须接受同样检查。"},{"text":"可信身份A对book7的访问与关联权限","correct":true,"feedback":"关系有效与业务允许是两项独立条件；book7存在仍不能证明A可以关联它。"},{"text":"删除外键减少报错","correct":false,"feedback":"会削弱结构保护且未补权限；移除外键会产生孤立记录却不阻止越权。"}],"output":"教学结果：后端拒绝A关联B的book7，没有新增越权笔记，B原有数据不变；A关联本人书籍则成功。","evidence":["拒绝且未新增越权关联","本人关联成功对照"]}]},"practice":{"intro":"起点是已确认需求与原型、至少两组演示数据。此课先形成决策，不直接让AI替你作不可解释的选择。","steps":["画新增与读取的数据流，标明浏览器、可信服务端和数据库各自职责。","比较至少两项结构或部署选择，用新需求的冲突例子解释利弊。","定义归属、关联、删除和唯一性规则，区分数据库约束与用户授权。","请Codex审查并用演示输入推演，自己复述关键选择和限制，保存决策记录。"],"prompt":"请根据已确认的新作品需求提出至少两项可比较的架构或数据选择，以一书多笔记为例解释前端、后端、数据库职责及秘密位置。比较复制书名与ID关联，说明同名、改名、删除和归属影响；特别检查A引用B私人书籍不能因外键存在而获准。先用演示输入推演并生成决策记录，等我选择后再实现，不创建外部资源或发布。","evidence":["一次新增与读取的数据流","两项选择的具体利弊","归属关联与删除规则","自己的复述、限制和验证依据"],"troubleshooting":[{"symptom":"模型能保存却难以改名","check":"检查是否在多条记录复制了同一业务信息","action":"按需求决定关联或受控同步，补改名与同名书验收。"},{"symptom":"外键存在却跨账户关联成功","check":"检查是否只验证对象存在","action":"在可信入口核对目标资源权限，并重测本人允许与他人拒绝。"}]},"checks":[{"question":"同日不能重复打卡，唯一约束是否替代身份验证？","options":[{"text":"能，因为重复检查最重要","correct":false,"feedback":"不同规则不能互相覆盖；唯一性不核验请求身份，身份也不自动防重复。"},{"text":"只需让前端隐藏按钮","correct":false,"feedback":"请求可以绕过页面，仍需可信层约束；前端隐藏打卡按钮仍可被直接请求绕过。"},{"text":"不能，还要可信身份与归属授权","correct":true,"feedback":"约束可限制组合重复，却不证明请求者是谁。"}]},{"question":"第一版暂不做共享，怎样写限制最好？","options":[{"text":"说明私人归属假设及未来共享需重审的规则","correct":true,"feedback":"简化有边界，便于后续迁移；明确私人假设有助识别共享新增的影响范围。"},{"text":"说明永远不可能共享","correct":false,"feedback":"当前范围不能证明未来需求；未来共享关系变化可能需要新的授权设计。"},{"text":"不必记录，代码会自动解释","correct":false,"feedback":"后来者难以知道简化依据和风险；应说明取舍及验证依据而不让代码替代决定。"}]}],"sources":[{"label":"MDN：客户端与服务端职责","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Client-Server_overview","checked":"2026-10-16"},{"label":"PostgreSQL：外键与唯一约束","url":"https://www.postgresql.org/docs/current/ddl-constraints.html","checked":"2026-10-16"},{"label":"OWASP：对象关系授权","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html","checked":"2026-10-16"}]},{"id":"13.04","title":"推进实现并处理失败","lead":"独立创作时，AI可能连续改动很多文件，却没有一项可验收成果。怎样用小阶段、失败证据和恢复点控制进展？","goals":["能围绕可观察闭环分阶段推进，保留基线和受影响行为清单。","能提交一项实际故障或明确标记的受控演练的复现、证据、修复与回归。"],"sections":[{"title":"阶段围绕可观察结果划分","paragraphs":["按用户闭环切阶段，比按“完成全部前端、再做全部后端”更容易发现接口误解。第一段可以是用演示数据新增并读取笔记，第二段加入可信身份与隔离，第三段补编辑删除与失败反馈。每段结束都有输入和结果，而不是只有文件数量。","阶段并不意味着省略前置设计。已确认的视觉与数据规则作为边界，Codex可以在其内实现；遇到新布局或业务歧义，先回到相应材料确认。把未决定项塞进实现，往往会扩大返工，因为后续代码已依赖未经确认的假设。"]},{"title":"每段保留可恢复的基线","paragraphs":["开始改动前记录可用版本、演示数据和当前通过项，改动后检查差异与受影响行为。基线让失败时可以比较前后条件，而不是在不断叠加的修补中猜哪一次起效。版本保存也应包含必要说明，避免只保存代码却不知配套结构。","恢复选择要看变化性质。纯界面错误可恢复前一代码，数据库结构变化需核对兼容，数据损坏需独立恢复。不要用一次代码撤销承诺能回到所有历史状态，也不要在共享正式库上试未经验证的修复脚本。"]},{"title":"失败从复现材料开始","paragraphs":["记录新作品的一项实际失败，例如A在书籍详情保存笔记后刷新丢失。先观察请求是否发出、目标是否正确、响应如何、数据库是否新增，再提出假设。不能为了完成“故障记录”编造一次自己没遇到的真实报错。","若开发中没有自然出现故障，可在独立测试副本有意改变一个条件，明确写受控故障演练，例如阻断请求或漏配测试变量。演练也有学习价值，但应与真实自然故障区分，不得把预制教材输出改成自己的操作日志。"]},{"title":"修复与回归要覆盖受影响关系","paragraphs":["找到原因后最小修复，再按原输入复测，并检查相邻流程。修复保存后不仅看新建，还要刷新回读、编辑和权限；修复书籍删除后要检查笔记关系。回归范围由因果影响决定，不必每次重复所有不相关检查。","多次尝试无进展时停止无依据叠加，列已试方法、结果和当前可恢复点，缩小到一个最小例子再求助。求助材料应足以解释问题且不含秘密。独立能力不是从不借助AI，而是能让帮助基于证据，并对决定与结果负责。"]}],"glossary":[{"term":"基线","meaning":"改动前已知可用、可识别并可对照的版本与状态。"},{"term":"回归","meaning":"修改后核对相关旧行为仍按约定工作的过程。"},{"term":"最小复现","meaning":"保留触发问题所需条件而去掉无关复杂度的例子。"}],"predict":{"question":"AI改了很多文件但说不清哪个阶段通过，下一步应怎样推进？","options":[{"text":"继续同时实现更多功能","correct":false,"feedback":"增加变量会使未完成原因更难定位；并行增加功能会使当前未完成路径更加交织。"},{"text":"收敛为一条可验收闭环并检查当前差异","correct":true,"feedback":"可观察结果比改动数量更能指导进展；需要明确输入和结果才能判断一段是否完成。"},{"text":"以文件都已创建作为阶段完成，不执行用户操作","correct":false,"feedback":"文件存在不代表请求、持久化与页面反馈正确，需要可观察的用户闭环。"}]},"experiment":{"title":"推进实现并处理失败：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"保存只改页面状态","input":"A新增笔记后卡片出现；网络面板没有保存请求；刷新后消失。","question":"最有依据的原因范围是什么？","options":[{"text":"数据库备份必然失效","correct":false,"feedback":"当前证据未涉及备份机制；备份机制尚未参与这次点击与刷新现象。"},{"text":"用户账户一定被删除","correct":false,"feedback":"页面正常新增且无请求，不能支持该断言。"},{"text":"前端未进入真实保存链路","correct":true,"feedback":"未发请求使数据库写入无法发生；应检查点击处理与接口接入而非先修数据库。"}],"output":"教学结果：定位到仅更新本地状态的处理函数，接入接口后需重测回读与拒绝。","evidence":["新增时无网络请求","刷新丢失","修复后请求与回读待验收"]},{"name":"受控故障演练","input":"自然开发未出明显错；在独立副本阻断一次新增请求，记录失败提示与恢复重试。","question":"这次人为阻断的测试，故障报告怎样写最准确？","options":[{"text":"标明受控演练及实际观察，勿称自然事故","correct":true,"feedback":"故障来源和真实执行范围应可区分；受控副本与生产故障具有不同影响和证据范围。"},{"text":"写成生产事故增强可信度","correct":false,"feedback":"这会伪造环境和经历；虚构生产日志无法用于复现与验证修复。"},{"text":"只能放弃故障学习","correct":false,"feedback":"受控实验可检验失败路径，只需诚实标记。"}],"output":"教学结果：记录受控客户端阻断、输入保留和单次重试成功，不声称真实生产故障。","evidence":["演练条件明确","实际脱敏结果","恢复后回归记录"]}]},"practice":{"intro":"起点是已确认需求、原型和数据决定的新作品副本。先完成一条用户闭环，再扩展；用户未确认新视觉时不继续视觉实现。","steps":["拆出每段输入、结果、依赖与验收，记录可恢复基线及演示数据。","在工作区副本推进第一段，实现后核对实际差异与正常结果，再进入下一段。","处理一项实际故障；若采用受控演练，明确标记，并采集请求、日志与数据证据。","最小修复后重跑原步骤和相关回归，保存决定；无进展时缩小问题并整理求助。"],"prompt":"请按已确认的新作品需求、原型与架构分阶段实现，每阶段提供可观察闭环、验收与恢复点，先实现最小读写再扩展。遇失败先复现、关联请求/日志/数据，再作最小修复并回归，不无依据叠加改动。记录一项实际故障，若是人为受控演练请明确标记。只在当前工作区测试副本操作，不连接生产、不创建外部资源或发布；新视觉先交原型确认。","evidence":["阶段目标和基线","实际故障或明确标记的演练材料","证据→原因→最小修复记录","原步骤及受影响流程回归"],"troubleshooting":[{"symptom":"连续改动仍不知道原因","check":"核对每次假设是否有对应观察","action":"停止叠加，回到可恢复基线，建立最小复现再推进。"},{"symptom":"修好新增却破坏编辑","check":"检查是否改动共享验证或数据函数","action":"补编辑相关回归，按共用路径修复并同时验证新增与编辑。"}]},"checks":[{"question":"没有自然故障，可以怎样完成失败路径练习？","options":[{"text":"编造一次线上报错日志","correct":false,"feedback":"伪造记录无法证明处理能力；无法复现的虚构经历不支持排错能力结论。"},{"text":"在独立副本受控改变条件并明确标记","correct":true,"feedback":"演练能观察真实行为，前提是不冒充自然事故。"},{"text":"直接抄教材推演当实操","correct":false,"feedback":"预制结果不是自己的系统运行证据；教材输出没有运行自己的新项目与配置。"}]},{"question":"多次修补无进展，应优先做什么？","options":[{"text":"把所有依赖升级一遍","correct":false,"feedback":"引入更多变化会削弱原因判断；升级更多依赖会同时改变许多潜在原因。"},{"text":"删除报错代码让日志安静","correct":false,"feedback":"隐藏现象不代表用户流程恢复；删去报错信息可能只会掩盖保存仍失败。"},{"text":"整理已试方法和基线，缩小复现条件","correct":true,"feedback":"减少变量并恢复可解释状态更有利于定位。"}]}],"sources":[{"label":"Node：行为测试执行","url":"https://nodejs.org/api/test.html","checked":"2026-10-16"},{"label":"MDN：客户端与服务端请求","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Client-Server_overview","checked":"2026-10-16"},{"label":"MDN：排查JavaScript问题","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/What_went_wrong","checked":"2026-10-16"}]},{"id":"13.05","title":"上线、变更与恢复验收","lead":"新的应用也要经历发布、改动和恢复，不能因为不是任务工具就跳过身份隔离与数据证据。你能把完整生命周期迁移过去吗？","goals":["能将新作品的环境隔离、完整发布和两账户验收与旧项目区分。","能接受一项目标式变更，并分别验证代码回退与独立副本数据恢复。"],"sections":[{"title":"新环境检验是否依赖旧项目","paragraphs":["复用代码和方法没有问题，但发布新作品时应清楚它使用哪套配置、数据和身份规则。读书笔记若误连任务工具数据库，页面可能启动，业务结构却冲突；复用高权限凭据还可能让两个项目相互影响。","独立环境不必强迫购买新服务，可以在已有获准资源内采用适当隔离方案，但必须说明边界。创建账户、资源、付费与公开发布需要具体授权；课程任务本身只要求准备可审核材料，不能替学习者自动决定这些外部动作。"]},{"title":"完整验收沿着新业务闭环走","paragraphs":["在真实目标地址从独立设备或浏览器登录，新建书籍和笔记，刷新回读，编辑删除，检查书籍与笔记关系。再换B测试身份，既验证B正常使用，也验证B无法引用、查看或修改A的私人资源。新关系需要新拒绝用例。","A和B都能看到不同列表还不够，详情、关联写入、删除连带效果都要检查。用已知演示数据与脱敏请求形成证据，不把外观截图当隔离证明。失败后查看实际数据库是否被改，尤其不能只凭错误文案断言数据没有副作用。"]},{"title":"只给目标的变更检验迁移","paragraphs":["接受一个新要求，例如“书籍页增加仅显示最近七天笔记”，由学习者自行补清日期字段、时区与空结果条件，确定是否影响数据结构，再实施。不是再照着旧项目教程复制按钮，而是把原则迁移到新的条件。","更新前记录基线和兼容性，更新后检查新行为及旧闭环。若新增可选展示功能，代码回退可能足够；若迁移和清理数据，必须说明独立恢复范围。不要在没有副本验证时直接对线上执行不可逆结构操作。"]},{"title":"恢复结果与公开结论对齐","paragraphs":["演练恢复前一可用代码，核对配置和结构兼容；另在独立副本恢复数据，核对新作品的关联、归属与业务操作。两项分别记录，才能说明“程序回来了”和“记录回来了”各有依据。","最终列真实地址、版本、数据环境、允许拒绝、变更、回退与恢复结果，以及待完成项。不能访问外部环境时仍可完成本地生命周期演练，但须明示线上待验收。独立作品完成度来自这组可核对证据，而不是一个不区分范围的总通过标记。"]}],"glossary":[{"term":"生命周期","meaning":"从准备、发布、使用、更新到故障恢复的一组持续活动。"},{"term":"新环境隔离","meaning":"明确新作品与旧资源在配置、数据和权限上的分界。"},{"term":"兼容窗口","meaning":"让新旧组件在过渡期仍可协作的安排，需验证实际组合。"}],"predict":{"question":"新作品沿用旧数据库管理凭据，首页能开，就能发布给人试用吗？","options":[{"text":"还需核对环境隔离、最小权限和新业务流程","correct":true,"feedback":"首页不证明数据边界和关联规则正确；还需核对新书籍笔记关系和真实运行角色。"},{"text":"能，因为旧项目已通过两账户检查","correct":false,"feedback":"新资源、接口和模型需要新的证据；新增数据模型使旧任务接口结论不能直接迁移。"},{"text":"只需换一个域名","correct":false,"feedback":"域名不同不能隔离数据库能力；同一高权限连接仍可能访问两个项目的数据。"}]},"experiment":{"title":"上线、变更与恢复验收：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"新关系带来新权限","input":"A有私人bookA；B能正常创建本人书籍；B提交笔记引用bookA。","question":"新作品增加书籍关联入口，这次拒绝测试为何必要？","options":[{"text":"只是重复旧测试，没有价值","correct":false,"feedback":"条件与数据关系已改变，不是照搬；B引用A书籍涉及旧工具没有的关联入口。"},{"text":"新模型增加关联入口，需验证目标资源权限","correct":true,"feedback":"旧任务编号测试不覆盖书籍引用这一新路径。"},{"text":"外键通过就应允许","correct":false,"feedback":"存在约束不能代替资源授权；外键只核对目标存在，不决定B有无关联权。"}],"output":"教学结果：B关联A书籍被拒绝且数据库无新增越权笔记；B关联本人书籍成功，新旧两路均有对照。","evidence":["新关联拒绝","数据库无越权记录","本人关联成功"]},{"name":"变更与恢复分开","input":"新版本增加七天筛选，同时测试库误删一条笔记；回退代码后筛选消失，笔记仍缺。","question":"筛选消失但笔记仍缺，怎样分别完成恢复结论？","options":[{"text":"只要筛选消失就全部恢复","correct":false,"feedback":"界面恢复不等于记录回来；缺失笔记需要备份或其他可用依据重建。"},{"text":"从旧页面截图手动推断已恢复，不再回查数据库","correct":false,"feedback":"截图显示不是恢复后的真实数据，需在副本核对记录与关联并执行业务。"},{"text":"代码回退与副本数据恢复分别验证","correct":true,"feedback":"两个状态变化由不同机制控制；程序版本和数据库记录各有独立持久状态。"}],"output":"教学结果：代码回退已核对旧版本与流程；笔记恢复另在副本检查备份时刻、目标记录与缺失区间。","evidence":["旧版本标识与核心流程","备份副本的目标笔记","恢复范围与时间"]}]},"practice":{"intro":"起点是可重复运行的新作品、明确资源边界、测试身份、备份和恢复基线。外部动作没有授权时先完成准备与本地演练。","steps":["审查新环境图、配置名、应用角色和数据归属，准备发布与停止清单。","获准发布后在目标地址执行新业务完整闭环与A/B正常和跨账户拒绝，未获准则保留待完成。","接受一项只给目标的小变更，自己写条件和验收，更新后回归旧行为。","演练代码回退与独立副本数据恢复，检查关联及归属，形成分项结论。"],"prompt":"请为我的独立作品准备完整生命周期验收，先核对与旧任务项目的配置/数据/权限边界，生成可审查发布包。未获外部授权不要创建资源或发布。有获准测试地址才实际检查新业务闭环、A/B正常及跨账户关联拒绝；否则标记待完成。随后在测试副本接受一项目标式变更、验证回归，分别演练代码回退和数据恢复，记录版本、范围及缺失区间。","evidence":["新环境与发布准备","新业务及两账户允许拒绝","目标式变更前后与回归","代码回退和副本数据恢复的独立记录"],"troubleshooting":[{"symptom":"上线能开但新业务报错","check":"核对是否误连旧项目库或缺新迁移","action":"确认数据环境与结构版本，在副本修复后重测闭环。"},{"symptom":"回退后部分字段读取失败","check":"检查旧代码与新结构是否兼容","action":"选择已验证的兼容修复或恢复路径，不对线上盲目反向迁移。"}]},"checks":[{"question":"只给目标变更后，日期条件不明确，应怎样推进？","options":[{"text":"先明确字段、边界与演示预期再实现","correct":true,"feedback":"目标需要转成可检验条件，不能让代码暗自决定。"},{"text":"照旧项目复制一个筛选按钮即可","correct":false,"feedback":"按钮不定义新领域的时间含义；需要定义七天按创建还是业务日期以及边界。"},{"text":"将七天理解为默认值，不用示例核对日期边界","correct":false,"feedback":"默认猜测可能用错时间字段或时区，应先写可检验条件再实现。"}]},{"question":"已恢复备份但未检查书籍笔记关系，结论应怎样写？","options":[{"text":"全部通过，因为导入无错误","correct":false,"feedback":"工具成功不能证明业务语义完整；恢复工具不一定了解你的书籍笔记语义。"},{"text":"数据恢复尚未完成业务关联验收","correct":true,"feedback":"记录存在不保证关系与权限正确；孤立或跨账户关联仍可能违反新作品要求。"},{"text":"恢复必然失败，应立即删库","correct":false,"feedback":"缺证据不等于已知失败，更不支持破坏性动作。"}]}],"sources":[{"label":"OWASP：授权与关系检查","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html","checked":"2026-10-16"},{"label":"PostgreSQL：恢复验证范围","url":"https://www.postgresql.org/docs/current/backup.html","checked":"2026-10-16"},{"label":"PostgreSQL：关联约束","url":"https://www.postgresql.org/docs/current/ddl-constraints.html","checked":"2026-10-16"}]},{"id":"13.06","title":"演示、解释与复盘","lead":"演示时看起来顺利，遇到“B能否改A的数据”“数据在哪保存”却答不上来。怎样让成果说明真实能力，也看清仍依赖哪些帮助？","goals":["能演示并解释新作品的数据流、身份归属、失败与恢复边界。","能按真实证据评估已掌握和仍需帮助的能力，提出下一次具体补练。"],"sections":[{"title":"演示选择能揭示机制的流程","paragraphs":["准备少量无敏感数据，展示新增、刷新回读、修改与失败提示，并用A/B条件变化展示拒绝。最好让观看者能看到输入和结果，而不是只有剪辑后的成功画面。演示环境、版本与真实操作范围要写清，预录片段也应如实标明。","演示不是追求毫无停顿。若出现问题，能记录现象、核对请求和解释下一步，比临场不断乱改更能体现方法。无法在当前环境执行的动作，展示已有记录并说明日期与限制，不用预制教材输出或生成截图冒充现场证据。"]},{"title":"用自己的话讲一次数据流","paragraphs":["选一个具体动作解释：A点保存后，输入在哪校验，身份怎样可信得到，后端如何确认目标书籍归属，数据库保存什么，响应怎样更新页面。能从浏览器讲到数据库，再讲回用户看到的状态，才不只是背组件名称。","随后改变一个条件，例如让bookId指向B，预测在哪一层拒绝、数据库应不变。再问退出后旧页面为什么仍可能显示内容、为什么代码回退不恢复删除数据。条件变化能检验理解是否足以支持决定，而不是只记住一次成功步骤。"]},{"title":"证据包对应不同能力","paragraphs":["成果地址说明可访问，需求与原型记录说明目标和视觉经过确认，数据与权限说明解释设计，一次修复记录展示排错，更新与恢复记录展示维护。它们相互补充，代码行数、页面美观和选择题分数不能单独代替整组能力。","证据也有强弱与范围：自检勾选是学习者声明，自动测试是特定条件检查，实际请求是当前版本行为。不要把三者混称独立认证。报告中列哪些由自己完成、哪些由AI协助、哪些仍依赖模板，能帮助制定真正有用的下一步。"]},{"title":"复盘要形成可执行改进","paragraphs":["复盘不只写“学到了很多”。选择一个具体卡点，说明当时错误解释、什么证据推翻了它、最终怎样修复，下次会在何处更早检查。再列一个仍不熟悉的能力，如配置生效时机，用新的练习条件补足，而不是一口气重学所有内容。","独立创作允许查资料与使用AI，重点是能定义目标、审查方案、验证结果并在失败后继续。没有真实试用或外部上线条件，就明确尚未验证价值或线上行为。这样的结课结论有边界，也更容易用于下一项作品，而不靠不实的“全部掌握”自我安慰。"]}],"glossary":[{"term":"证据包","meaning":"把成果、决定与验证结果按能力对应整理的材料。"},{"term":"复盘","meaning":"依据具体经历修订解释与后续行动，而非只评价心情。"},{"term":"能力边界","meaning":"目前能独立判断和验证的范围，以及仍需帮助或未验证的部分。"}],"predict":{"question":"网站漂亮、代码很多，但没有隔离或恢复记录，结论怎样写？","options":[{"text":"完整能力已证明，因为作品复杂","correct":false,"feedback":"复杂度不等于关键路径正确；关键能力可能被大量无关页面和代码掩盖。"},{"text":"没有任何学习成果","correct":false,"feedback":"已有成果仍有价值，只是不能扩大结论。"},{"text":"视觉成果明确，权限与维护能力仍缺证据","correct":true,"feedback":"不同成果不能互相替代，应逐项说明；外观、权限和恢复分别需要对应行为证据。"}]},"experiment":{"title":"演示、解释与复盘：先预测再核对","brief":"阅读下面两组输入，先选择判断，再对照预制结果与证据，关注只改变一个条件后结论为何改变。","boundary":"以下均为预制教学推演，未进行真实登录、网络请求、数据库操作或部署，也没有真实操作截图。它们帮助理解机制，不能作为外部实操已通过的证据。","cases":[{"name":"可以解释并改变条件","input":"演示A保存本人笔记后刷新回读；换B关联A书籍被拒绝；学习者解释可信身份与归属检查。","question":"针对本人保存与跨账户拒绝，这组材料支持什么？","options":[{"text":"支持所测流程的操作与机制理解","correct":true,"feedback":"输入、结果和自己的解释形成具体证据。"},{"text":"证明所有未知场景永久安全","correct":false,"feedback":"范围仍受版本、入口与条件限制；尚未覆盖共享与批量入口应明确列为缺项。"},{"text":"只证明背了组件名称","correct":false,"feedback":"条件改变后的预测和验证比名称复述更多。"}],"output":"教学结果：该版本所测保存与拒绝能力可以记录，学习者能够解释归属检查；共享和批量入口仍未覆盖。","evidence":["本人保存回读","跨账户拒绝未变","对应机制复述"]},{"name":"AI完成但学习者无法判断","input":"AI生成应用可运行；学习者不知道数据目标，也无法判断B能否删A记录。","question":"面对无法解释的数据目标和权限，复盘重点应是什么？","options":[{"text":"禁止以后使用AI","correct":false,"feedback":"辅助工具不是问题本身，关键是能审查结果。"},{"text":"补数据流与权限对照练习，再验收实际入口","correct":true,"feedback":"缺口是判断与验证能力，应针对性补练。"},{"text":"只增加更多页面证明进步","correct":false,"feedback":"扩大作品不能补足基础边界理解；更多功能仍可能复用同一未理解的错误边界。"}],"output":"教学结果：保留已有作品，回到身份、归属和数据流练习，暂不宣称独立隔离验收通过。","evidence":["明确缺失能力","对应补练条件","重验收结果待完成"]}]},"practice":{"intro":"起点是独立作品与现有真实材料。无法实际访问的项目先说明条件，演示不要包含私人信息与凭据。","steps":["选择五分钟左右能展示核心闭环、一次失败与跨账户拒绝的演示脚本，标环境版本。","整理成果、需求原型、数据权限、修复、变更回退与恢复证据，逐项注明真实或演练。","用自己的话解释数据流，并预测退出、跨账户和回退条件变化，再对照证据。","写一项错误解释如何被证据修正、仍需帮助的能力与下一次具体练习；缺项如实保留。"],"prompt":"请帮我整理独立作品结课证据包，只引用已有真实材料：成果地址或本地运行方式、演示数据、需求与最终原型确认、数据流和权限、一次修复、变更回归、代码回退与副本数据恢复。准备核心闭环/失败/跨账户拒绝演示及解释问题，不编造截图、日志或通过结论。复盘列我能判断的范围、AI帮助、未验收项与下一次练习；不要对外发送或发布。","evidence":["可访问成果或诚实标记的本地运行方式","核心流程与条件变化演示记录","数据权限、修复和恢复材料","具体复盘及下一次补练条件"],"troubleshooting":[{"symptom":"演示时无法回答数据在哪","check":"核对真实API目标、后端配置和数据环境","action":"画一次保存链路并用演示记录核实，不只背架构图。"},{"symptom":"材料很多却说不清证明什么","check":"检查每份记录对应的行为、条件和结果","action":"按能力建立索引，删除无关或敏感材料，保留缺项而非凑总通过。"}]},"checks":[{"question":"使用AI帮助写代码，会使独立创作验收失效吗？","options":[{"text":"会，必须脱离AI手写全部代码","correct":false,"feedback":"这不是本课程独立迁移的目标；可以使用工具，但仍应能解释并验证其成果。"},{"text":"不会，所以可以不检查结果","correct":false,"feedback":"帮助不免除验证和判断责任；自己需要确认AI实现符合需求且不越权。"},{"text":"不会，关键是能定义、审查、验证并解释决定","correct":true,"feedback":"课程允许工具帮助，验收关注可核对能力。"}]},{"question":"想补“不会判断回退是否恢复数据”的缺口，哪种练习更有力？","options":[{"text":"在副本分别改代码与删除演示记录，再独立恢复","correct":true,"feedback":"条件对照能区分版本与数据状态机制；对照能显示代码变化与记录删除不会同步撤销。"},{"text":"只重跑代码回退，不尝试记录删除后的独立恢复","correct":false,"feedback":"重复代码步骤仍不能区分数据状态，需要加入有已知记录的副本恢复对照。"},{"text":"只核对备份文件名和大小，不执行副本恢复","correct":false,"feedback":"元信息不能证明目标记录、关系和权限可恢复，需要实际恢复与应用检查。"}]}],"sources":[{"label":"MDN：客户端服务端数据流","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps/Client-Server_overview","checked":"2026-10-16"},{"label":"OWASP：授权机制与检查","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html","checked":"2026-10-16"},{"label":"PostgreSQL：恢复边界","url":"https://www.postgresql.org/docs/current/backup.html","checked":"2026-10-16"}]}],"support":[{"id":"P01","kind":"入门准备","title":"基本数字操作：找到并保留自己的文件","lead":"先完成一次下载、解压、定位和另存副本，后续遇到问题时才知道改的是哪份文件。","prerequisites":"无。准备一个浏览器和自己可以管理的练习目录。","sections":[{"title":"文件不是浏览器里的那一幅画面","paragraphs":["文件保存文字、图片或程序内容，浏览器按照文件与代码把它显示出来。截图记录某一刻看到的画面，不能用它代替可以运行的网页文件。项目目录则把相关文件放在同一个位置，使相对引用能够找到资源。","先在自己的练习目录创建一个说明文件，写下今天要学什么，再关闭并重新找到它。确认能找到真实保存位置，比记住某个软件图标更有用。文件扩展名帮助你识别类型，查看扩展名不会改变文件内容。"]},{"title":"副本让试错可以恢复","paragraphs":["解压后的目录才是可以直接读写的练习文件。先把整个目录复制成新名字，保留起始版本；只复制入口文件可能遗漏脚本或图片。另存副本与原地保存的区别，是是否保留了原有可返回版本。","对文件做一次小改动，记录你改的路径。再打开原件和副本比较，确认它们是两个独立位置。不要仅根据浏览器标签标题区分文件，因为不同文件可能显示相同标题。"]}],"steps":["下载03.04独立练习包，将整个压缩包解压到自己的练习目录。","复制整个解压目录，给副本一个能识别的名称。","在副本里找到index.html、tasks.js和render.js，写下各自路径。","打开副本并截图，将说明和截图保存在副本旁，再关闭后重新找到。"],"evidence":["可以写出原件与副本两个不同路径。","可以找到入口、数据与显示脚本，而非只有截图。","关闭窗口后，仍能重新打开正确副本。"],"boundary":"这项检查证明基本文件操作，不证明已经读懂代码；没有解压或实际打开时，不勾选为完成。","help":["找不到下载：先查看浏览器的下载记录，使用其中的文件位置入口，再记录真实路径。","改了却没变化：核对浏览器地址与编辑文件路径是否属于同一个副本，先不要重复修改代码。"],"related":["03.01","03.02"]},{"id":"P02","kind":"入门准备","title":"从输入到结果：数据、程序与模型","lead":"同样是把文字变成清单，普通规则与AI模型分别做了什么？先用一个小例子认识职责。","prerequisites":"无。使用下面的演示材料即可。","sections":[{"title":"把处理过程拆开看","paragraphs":["输入是交给系统的材料，处理是系统对材料执行的操作，输出是得到的结果。把三项费用求和时，数字是数据，加法规则是算法，执行规则的软件是程序。算法是一组处理步骤，程序是把步骤写成可运行指令的实现。","输入“明天读书，周五交报告”，可以请生成式模型整理待办。模型根据训练形成的参数处理输入，生成候选表达；外围产品还负责上传、保存和显示。模型不是整个应用，也不一定承担应用中的每一步计算。"]},{"title":"看到结果，还要核对结果从哪里来","paragraphs":["一个页面可以先写好固定答案，也可以按规则计算，还可以真正向模型发请求。界面上出现文字不能独立证明模型调用发生。反过来，模型请求成功也不保证文字忠于原始材料。","比较“把所有日期识别出来”和“求三项数字之和”时，可以让不同工具各自承担适合的步骤。先写下希望保留的事实，再核对输出，才能识别系统是漏读、错误生成还是显示了旧结果。"]}],"steps":["写一段三句演示活动记录，圈出人物、动作、时间。","先手工按已确定事项和待确认事项整理，不补充材料外事实。","如有可用对话工具，再请它做同样整理；没有工具也可比较两份人工示例。","分别写出输入、处理、输出与核对依据，标明是否真实调用过模型。"],"evidence":["能够区分数据、规则、模型和外围软件。","输出中的每项确定事实能回到输入。","能说明文字出现不能证明模型真的被调用。"],"boundary":"人工整理或预制案例只是理解练习；没有真实请求时，不记录模型调用实操已完成。","help":["概念混在一起：先只问“这是材料、处理规则，还是显示结果的软件”，一次只分一项。","输出多出事实：把原文与新增句子并排，指出材料缺失的依据，而非先要求回答更自信。"],"related":["01.01","04.01"]},{"id":"P03","kind":"入门准备","title":"环境与资源：确认自己能够开始哪条路线","lead":"能看教程、能打开练习项目和能部署应用，是不同的起点。先把可用条件查清楚。","prerequisites":"设备、浏览器；创作路线还需要可用的Codex访问与练习目录。","sections":[{"title":"按路线检查需要的条件","paragraphs":["R1可以用资料任务理解AI与协作，先不要求安装开发环境。R2需要能管理文件、进入练习项目并运行本地作品。R3在此基础上还要有可用的服务、数据库和部署条件。缺少某项资源，不等于无法先学习有关机制。","进入Codex前，查阅你当前产品的官方准备说明，确认账号能访问哪些能力。不要根据教程截图推断自己账号一定具有相同功能，也不要把API额度与产品订阅混为一项。具体版本、入口和费用以实际官方条件为准。"]},{"title":"先使用演示项目确认操作范围","paragraphs":["给第一次练习单独创建目录，并在开始时记录可修改范围、起点文件和预期结果。工具能读取一个项目，不意味着它应当读取所有目录。用一项小的读取任务确认实际打开的位置，能够减少后续误改其他文件。","如果暂时不能使用Codex，可先读正文、完成教学推演和下载练习。实际创建项目、运行命令与验收结果应等条件具备后补做，不能用看完操作图代替。"]}],"steps":["选择R1、R2或R3，列出本阶段需要的账号、文件和运行环境。","按当前官方说明确认实际访问能力与资源费用位置，记录核对日期。","在独立演示目录中，让Codex先只读文件并说明它实际读取的路径。","打开最小练习结果，记录可用条件与尚未具备的条件。"],"evidence":["知道当前路线需要哪些资源，缺项在哪里。","能指出实际练习目录与读取的文件。","把已阅读、已推演和已实操分别记录。"],"boundary":"本网站不替你创建账号、购买资源、安装未经确认的软件或发布项目；未具备的实操条件保留为缺项。","help":["界面与截图不同：先记下平台、版本、当前入口与具体差异，再查官方说明。","工具不可用：先继续不依赖该工具的原理内容，保留要补做的任务与证据要求。"],"related":["01.03","01.04","02.01"]},{"id":"P04","kind":"入门准备","title":"怎样使用这门课：理解、实验与验收","lead":"选择题、阅读记录和实际作品分别说明什么？先认识课程里的几种学习证据。","prerequisites":"无。先决定自己想获得日常协作、本地创作还是联网应用能力。","sections":[{"title":"先预测，再看解释","paragraphs":["每课从一个具体问题开始。先根据已有理解选择，再看选项各自的理由；答错是用来发现假设，并不代表不能继续。原理部分解释为什么，情境推演改变一个条件，让你判断同一解释是否仍适用。","通用课程中的推演结果是预先编写的教材案例，不是实时AI回答或真实线上系统。03.04和05.02增强样课另有可以实际改变条件的小实验。标签帮助你知道自己正在观察什么证据。"]},{"title":"用自己的操作证明会用","paragraphs":["实践区提供任务说明、起点、步骤和证据要求。你需要在自己的练习里完成，再按清单核对。笔记与自行验收勾选只记录你的判断，不会自动认证你已经掌握外部操作。","课内完成要求阅读与本课题目通过。遇到不一致时按轻提示、有关解释、复现证据逐步求助；不要一遍遍无依据地重做。阶段验收会撤去一些提示并改变条件，检查是否只会照着做。"]}],"steps":["在总览选择符合当前目标的路线，找到第一课和前置准备。","完成一次先猜、原理、案例和迁移题，比较自己的判断为什么改变。","在实践区记录一个预期、实际与仍不理解的问题。","完成相应路线后，用阶段验收换条件再做，并检查证据。"],"evidence":["能找到下一步和卡住时的帮助入口。","能区分课内完成与外部实操自行验收。","能说明自己的路线终点和当前仍缺的能力。"],"boundary":"网站本地记录不会跨设备自动同步，也不把题目通过率当作真实学习效果研究或独立技能认证。","help":["看完但不会做：先只取一项任务，列出输入、预期与检查方式，回到对应课的案例。","不知道怎么求助：记录当前文件或地址、预期、实际、复现步骤、最近改动和有关错误，每次只核对一项。"],"related":["01.01","05.04"]},{"id":"E01","kind":"可选拓展","title":"让作品使用 AI：任务拆解助手","lead":"此前是用AI帮助制作软件，这次让软件运行时真正调用模型，并把建议交给用户确认。","prerequisites":"模块04、05、08、10；公开上线还需模块11。先具备后端与访问边界。","sections":[{"title":"区分开发时帮助与运行时调用","paragraphs":["Codex帮助写好一个任务页面，不代表这个页面每次运行都调用AI。运行时功能需要把有关输入交给自己的后端，由后端向模型服务发请求，再检查输出并返回页面。凭据、费用与失败都属于这条真实链路的组成部分。","把“准备读书报告”拆为建议步骤时，模型输出只是候选。页面应先展示可编辑建议，让用户决定添加哪些任务。不要让返回文字直接变成任意代码、不可撤回操作或未经确认的最终任务。"]},{"title":"把失败与核对纳入功能","paragraphs":["先定义最小输出结构，如步骤标题数组，再验证数量、字段、长度与内容。合法JSON只证明结构可读，不证明任务建议合理；资料不足时应允许模型说明缺项。网络超时与额度错误要有明确反馈。","选择供应商后，先核对当前官方调用方式、费用依据、输入范围与停止方法。教学预录结果可以用于设计讨论，但只有真实请求与响应证据才能记录调用通过。"]}],"steps":["复制已有项目，写出只处理演示任务的最小输入输出合同。","按选定供应商当前官方文档在合适服务端位置配置凭据，先做一次最小真实请求。","检查返回结构与内容，页面先展示建议，再由用户选择写入。","演练超时、不合法输出和重复点击，记录费用依据与停止方法。"],"evidence":["能跟踪按钮、后端、模型服务、检查和显示的链路。","浏览器与仓库中没有服务端秘密。","有真实请求结果与一次失败处理证据。","用户能编辑、拒绝或选择建议，未自动执行模型文字。"],"boundary":"本页仅提供项目任务与验收，不调用付费模型；预制案例不记为真实调用。具体API、模型和费用需按制作时的官方资料核对。","help":["请求成功但结果不可用：分别检查响应结构、建议内容和任务用途，保留最小输入与无敏感响应。","无法发起调用：先核对服务端配置、官方错误信息和资源条件，不把秘密复制到前端或聊天记录。"],"related":["08.05","10.04","12.02"]},{"id":"E02","kind":"可选拓展","title":"工作流与 Agent：让多步骤任务可停止","lead":"有些流程步骤固定，有些需要模型根据结果选择下一步；先比较两者，再决定是否需要Agent。","prerequisites":"E01或等价真实模型调用经验；理解工具权限与用户确认。","sections":[{"title":"固定流程与选择动作","paragraphs":["固定工作流规定步骤与分支，例如读取演示表格、按规则计算、生成摘要。Agent通常还让模型在允许范围内选择工具或下一步。多一步自主选择也增加了误读结果、重复调用和偏离目标的可能，不能仅靠名称判断方案更好。","先把目标拆为可验证结果，能用确定规则解决的部分保持明确。只在信息会影响下一步选择时引入模型判断，给每个工具写清输入、输出、允许资源与失败含义。"]},{"title":"停止条件属于设计的一部分","paragraphs":["给流程设置次数、时间或费用上限，遇到缺资料、权限不足或连续失败时停止并报告。工具返回的文字可能包含不可信内容，不能因其出现在结果中就把它当成新的授权。","用同一组演示任务比较固定流程与Agent：记录成功率、可解释性、人工确认次数和消耗。更复杂但没有改善结果的方案，不必成为默认选择。"]}],"steps":["选一个仅使用演示资料的三步任务，先写出固定工作流。","指出真正需要根据结果选择下一步的位置，再定义可用工具。","增加最大步数、失败停止和用户确认条件。","用成功、缺资料和工具失败三种输入比较两种流程。"],"evidence":["能解释为什么需要或不需要自主选择。","工具访问限定在明确演示资源内。","失败时停止，未无限循环或擅自扩大授权。","有同一任务下的结果与消耗比较。"],"boundary":"此处是可选设计与实践任务，不自动连接外部工具；收到工具文字不等于收到人类对新操作的授权。","help":["一直循环：检查停止条件是否实际触发，先收缩为一项可验证动作。","工具成功但目标没完成：把工具返回与最终验收分开核对，补出缺少的处理步骤。"],"related":["05.04","05.05","08.06"]},{"id":"E03","kind":"可选拓展","title":"私有资料检索与 RAG：答案能回到材料吗","lead":"检索把有关片段交给模型，但找到了片段并不等于回答就正确；用有答案与无答案的问题一起检查。","prerequisites":"模块09、来源验证与模型调用。使用可公开的演示资料替代私人材料。","sections":[{"title":"检索与生成是两个步骤","paragraphs":["RAG通常先从资料中检索相关片段，再把片段与问题一起交给模型生成回答。向量相似度帮助找到可能有关的内容，但相似并不保证片段包含答案；资料版本和分段方式也会影响检索结果。","准备三份演示说明，其中两份有相同术语但不同适用条件。提问时同时检查取回了哪些片段、回答采用哪一个条件，以及引用能否准确定位到支持句。"]},{"title":"资料不足时保留空白","paragraphs":["当资料没有答案时，合适的行为可以是说明缺少依据并请求更多资料。把似乎相关的片段拼成确定回答，会掩盖检索或资料的缺口。引用标记也可能放在并不支持结论的位置，需要逐条核对。","权限应在取回资料之前或数据访问过程中生效，不能先把所有人的片段交给模型，再仅在页面上隐藏。先在没有私人数据的练习中验证归属和拒绝行为。"]}],"steps":["准备有版本标记的三份演示资料，写出答案所在位置。","建立最小检索与生成流程，分别保存检索片段和回答。","提出一项资料有答案、一项容易混淆、一项资料没有答案的问题。","逐条核对支持关系、缺项说明与访问边界。"],"evidence":["回答中的事实能回到实际检索片段。","相似但条件错误的片段没有被误当作答案。","无答案问题会说明依据不足。","不同归属资料不会在检索阶段混入他人的上下文。"],"boundary":"本页没有上传或读取你的私人资料。教学示例不能证明真实检索系统已接通或权限已验证。","help":["引用对不上：对照问题、片段原句和回答结论，先定位是哪一层多加了信息。","总是搜到同一段：检查资料切分、查询条件与可用范围，不急着更换更大的模型。"],"related":["04.03","04.07","09.04","10.03"]},{"id":"E04","kind":"可选拓展","title":"Skills：把有效方法变成可复用流程","lead":"一份长提示词不一定是好技能。把适用条件、步骤、结果与停止条件一起写清楚，才能复用。","prerequisites":"模块05；已经有一项在多个输入下验证过的重复流程。","sections":[{"title":"先找稳定的共同步骤","paragraphs":["技能把一项可重复方法整理为可被调用的说明与必要资源。先比较两次成功任务，区分稳定步骤和依具体输入变化的决定。如果流程仍依赖大量未写出的背景，换一个任务就可能失效。","例如资料摘要技能要说明可用来源、输出重点、引用方式和缺资料时的行为。只写“输出专业摘要”没有把验收方法保存下来，复用时仍要重新猜。"]},{"title":"适用范围与反例同样重要","paragraphs":["写出何时应该使用、何时不应该使用，以及哪些动作必须让人确认。技能中的外部资料和工具结果不能自动变成新的操作授权，凭据也不应写进可复用说明。","用一份普通输入、一份缺资料输入和一份超出范围输入重试。好的说明应让流程产生合适结果或明确停止，而不是对所有任务都给出看似完整的输出。"]}],"steps":["选取自己已经完成过的重复任务，列出输入、步骤、产出和核对证据。","按当前工具官方技能格式保存说明与必需资源，不加入私人凭据。","用三种不同条件重试，记录需要补充的隐含假设。","修订使用条件、失败处理和不应执行的动作，再重复验证。"],"evidence":["使用条件与目标任务可以辨别。","流程包含可观察验收与缺项处理。","换输入后有效或明确停止。","技能说明不含私人凭据与无关资料。"],"boundary":"本页是技能制作练习，不会自动安装、发布或向其他账号共享技能。格式与能力以当前工具官方说明为准。","help":["换任务就失败：找出上次聊天中才存在的关键背景，决定写成输入条件还是适用限制。","说明越来越长：保留影响判断的规则与例子，把重复背景移出流程，重新验证最小版本。"],"related":["05.03","05.05","12.01"]},{"id":"E05","kind":"可选拓展","title":"MCP：连接工具之前先看访问范围","lead":"连接成功只说明可以通信。实际能访问什么、工具做了什么、失败如何处理，都需要分别检查。","prerequisites":"理解工具调用、身份权限；已经有明确的外部连接需求与演示资源。","sections":[{"title":"协议连接不代替具体授权","paragraphs":["MCP提供连接模型应用与工具、资源的一种协议方式。协议本身不保证某个服务器可信，也不自动决定它该访问你的哪些资料。具体工具声明、连接身份和操作范围共同影响实际结果。","先只连接一个包含无敏感演示资料的范围。阅读工具有哪些参数、是只读还是会写入、返回如何解释。不要为了测试连接而把整个私人空间开放出去。"]},{"title":"把声明、调用与结果逐项对应","paragraphs":["工具声称读取成功时，要核对实际返回的资源标识和内容；写入时核对修改目标与可恢复方式。工具结果可能包含来自第三方的指令文字，应把它视为资料，不让它自行扩大原任务。","故意选择一个不存在或无权访问的演示资源，观察拒绝与失败是否清楚。再检查正确资源仍能完成任务，避免把全面失败误认为权限隔离成功。"]}],"steps":["明确需要连接的任务、演示资源与最小读写范围。","按当前官方说明检查服务器来源、身份方式与工具声明。","先做一次限定只读调用，核对实际资源与结果。","在授权范围内验证成功和拒绝路径，记录断开连接的方法。"],"evidence":["能解释协议、工具与实际任务各自职责。","访问范围限于本次演示需求。","成功与拒绝均有实际结果可核对。","第三方资料没有被当作额外授权。"],"boundary":"本网站不会自动连接你的外部账号或扩大权限。真实连接需要在实际工具中核对授权，教学说明不能代替访问检查。","help":["显示连接成功但取不到资料：分开检查身份、资源范围和具体工具参数。","结果指示继续做别的事：回到原任务和人类授权，先判断是否属于已同意的范围。"],"related":["05.05","08.03","10.01"]},{"id":"G1","kind":"阶段验收","title":"AI 理解与协作：换资料或需求再完成一次","lead":"不沿用课堂原题，改一份资料或一项需求，检查自己能否选择方式、补全背景并核实结果。","prerequisites":"模块05；R1完成01→04→05，创作路线完成对应前置。","sections":[{"title":"用条件变化检查迁移","paragraphs":["R1准备三段有关同一活动的演示资料，其中一段较旧、一段有未确定事项。先写比较标准，再完成摘要或方案比较。创作路线把任务清单换成读书记录，增加一个不同的数据或操作要求。","验收不要求脱离AI独立手写，而是要求你能指出哪项决定来自资料、哪项是待确认假设，以及如何发现并纠正一项错误。只有换名称而行为完全相同，不能充分证明迁移。"]},{"title":"交出过程证据","paragraphs":["保留原始输入、任务说明、结果和一次纠偏记录。检查新条件是否真正改变了方案，而不是只多写了一句提醒。另一人应能按你的验收条件判断结果。","未通过时回到有关课程补练：不知道选什么方式回01.01，背景缺失回05.02，无法说明错误原因回05.06。不要把一次错误当作需要重学全部内容。"]}],"steps":["选资料任务或项目任务，写出一项与课堂不同的条件。","列出输入、目标、限制和可观察验收。","完成任务并主动核对至少一项容易误判的结果。","修正一个错误假设，再重跑有关检查，保存前后对比。"],"evidence":["处理方式的选择有理由。","关键输入与输出事实可以追溯。","至少一项错误假设已识别并纠正。","另一人能够依说明判断完成与否。"],"boundary":"勾选只记录你的证据自查。真实任务未执行或纠偏前后未核对时，不把课内题目通过当作本阶段能力证明。","help":["结果看着不错却无法核实：给每项结论补出输入位置或实际运行检查。","不断改提示仍不对：区分资料缺口、需求歧义与实现问题，再决定补什么证据。"],"related":["01.01","05.02","05.06"]},{"id":"G2","kind":"阶段验收","title":"本地应用：改条件后仍可保存和恢复","lead":"让本地任务工具面对一项新需求与一次异常，检查显示、保存和恢复是否都能解释。","prerequisites":"模块07；已完成本地工具V1。","sections":[{"title":"检查完整操作链","paragraphs":["先按原有流程创建两条同名任务，只修改其中一条，再完成筛选、编辑与取消。随后改变一个字段或筛选要求，预测哪些代码和数据需要调整，哪些行为应保持。","保存要同时核对任务与完成状态。刷新页面、关闭后重开与换来源访问是不同情境，不能把其中一次成功推广到所有环境。"]},{"title":"用副本演练恢复","paragraphs":["导出无敏感演示数据，在另一个练习副本中导入并核对。再使用预先准备的损坏记录观察降级提示，确认页面没有因为解析失败而完全不能使用。","恢复之后重新走一次添加、修改和保存，避免只确认文件存在。记录恢复范围和仍无法保证的情境，为下一阶段提出跨设备和用户隔离需求。"]}],"steps":["保存V1起点与演示数据，跑完添加、编辑、删除、完成和筛选。","加入一个新字段或筛选条件，核对原功能。","在副本注入一项可恢复的异常，收集证据并修复。","导出、导入并刷新验收，写出本地存储的范围。"],"evidence":["V1可运行且身份定位准确。","刷新后任务与完成状态均恢复。","有一次异常定位和恢复结果。","能指出跨设备同步与多人隔离仍需增加的职责。"],"boundary":"只在自己的练习副本中制造异常，不清除私人应用的数据。证据勾选不是对真实操作的自动认证。","help":["刷新后丢失：核对写入、重新读取和页面来源，不先断言浏览器坏了。","导入显示正常却不能编辑：核对数据结构、ID唯一性和完整操作回归。"],"related":["06.07","07.02","07.03"]},{"id":"G3","kind":"阶段验收","title":"联网与隔离：两账户的允许和拒绝都要验证","lead":"接口能连上还不够。让两个测试账户完成正常操作，再检查跨账户请求是否真的被拒绝。","prerequisites":"模块10；V2后端和数据库已在开发测试范围接通。","sections":[{"title":"同一操作保留四层证据","paragraphs":["对一次创建任务记录页面动作、网络请求、后端响应和数据库中的归属记录。用同一任务ID把证据对应起来，避免拿不同时间的日志拼成成功结论。重启后端后再读取，区分运行内存与持久数据。","模拟一次请求失败，检查页面没有显示成功或丢失尚未保存的输入。正常成功与失败恢复都属于联网能力，不以一次返回200作为完整验收。"]},{"title":"拒绝之后还要确认没有副作用","paragraphs":["账户A尝试读取、修改和删除账户B的任务，记录响应并核对B的数据没有改变。只看A页面上没有显示B任务，不足以证明后端守住了访问边界。","再确认A仍可操作自己的记录，未登录请求也按规则拒绝。正确范围的允许与错误范围的拒绝同时成立，才是这次隔离检查的核心。"]}],"steps":["建立两个仅含演示数据的测试账户，各自创建任务。","记录一次从页面到数据库的完整写入和重启恢复。","更换演示请求中的任务标识，检查跨账户读写删除均被拒绝。","模拟请求失败并恢复，重新验收本人正常操作。"],"evidence":["请求、后端和数据库能对应到同一条记录。","后端重启后数据仍在正确数据库中。","跨账户访问被拒绝且数据未改变。","本人正常访问和失败恢复均通过。"],"boundary":"所有验证限定在自己的开发测试资源，不对他人服务探测。预制响应或页面隐藏不能替代真实的后端与数据证据。","help":["拒绝结果不确定：用第二账户核对目标记录是否被改动，并记录同一次请求。","所有账户都不能操作：先恢复本人成功路径，避免把服务全面故障当作隔离有效。"],"related":["08.07","09.07","10.05"]},{"id":"G4","kind":"阶段验收","title":"上线与维护：发布、回退和恢复连成一条链","lead":"让另一种使用环境访问线上作品，再做一个小更新并恢复，检查上线后是否仍能维护。","prerequisites":"模块12；V3已上线，具备可恢复的测试数据与版本记录。","sections":[{"title":"线上成功要在实际环境检查","paragraphs":["记录前端、后端、数据库的环境和当前版本，在第二设备或独立浏览器中完成登录、创建、刷新与退出。网络请求应指向正确的线上服务，不能残留开发时的localhost地址。","用两个测试账户复查隔离，模拟一次可控失败，再恢复正常访问。部署平台显示发布成功，只能说明发布流程的部分状态，不能代替业务行为验收。"]},{"title":"分别恢复代码、配置与数据","paragraphs":["发布一个小变更前写出恢复依据，再演练回到前一可用版本。如果这次更新修改了数据库结构或数据，回退代码可能不足以恢复，需单独验证兼容与数据恢复。","在独立测试副本恢复一次备份，核对关键记录并运行应用操作。写下恢复点和可能缺失的数据区间，使另一人理解这份备份真正能够保证的范围。"]}],"steps":["在新使用环境访问线上版本，完成两账户核心流程。","保存当前版本、配置说明与数据恢复点，发布一个小改动。","执行冒烟检查和有关回归，再演练版本回退。","在独立副本恢复数据，记录范围、结果与交接说明。"],"evidence":["可访问地址、版本与环境清楚。","核心业务与用户隔离实际通过。","小更新与代码回退均有结果。","备份已在副本恢复并核对可用性。"],"boundary":"不在没有恢复点的正式数据上演练删除或破坏。勾选只记自行核对，不能代替实际第二环境访问和恢复记录。","help":["发布成功却无法使用：按资源、请求、后端、数据库逐段取证，先定位失败位置。","回退后仍异常：检查配置和数据结构是否也改变，确认旧代码需要的兼容条件。"],"related":["11.07","12.03","12.04"]},{"id":"G5","kind":"阶段验收","title":"独立迁移：接受一次只给目标的变更","lead":"换成自己真正需要的小应用，并在没有逐步答案的情况下处理一次变更，检查是否已经能独立推进。","prerequisites":"模块13；G1—G4有关证据已具备。","sections":[{"title":"选择有实际差异的新问题","paragraphs":["读书记录、物品管理或习惯打卡都可以，但至少有一项不同于任务工具的数据或交互要求。例如借用记录需要归还关系，不能只把任务标题替换成物品名称。先控制范围，保留能实际完成和验收的核心。","写出使用者、目标、数据归属、最小功能和验收，再确认视觉原型。学习者可以继续使用AI和资料，但必须能解释关键决定及其限制，而非把方案原样转述。"]},{"title":"用一次变更检查持续创作能力","paragraphs":["让同伴只提出目标和验收，例如新增到期筛选并保留现有记录。自己提出计划、识别要改的层、保存恢复点，再实现并验证。遇到失败时收集证据，避免靠连续扩大修改碰运气。","演示作品时同时说明数据流、身份规则、一次故障修复和更新恢复。把仍依赖帮助的部分写下来，能够准确描述能力边界也是独立推进的重要组成。"]}],"steps":["完成新问题的需求、架构、数据与视觉确认。","分阶段实现并记录一次实际失败的定位和修复。","上线后执行不同账户、刷新和失败路径验收。","接受一次只给目标的变更，保存、实现、回归和恢复，再做自述复盘。"],"evidence":["成果与任务工具存在明确的实际差异。","能解释前端、后端、数据库与权限决定。","有从复现到修复和回归的完整记录。","上线、变更、恢复与能力边界均可演示。"],"boundary":"完整证据来自你自己的独立作品。不能用课程页面、题目通过数、代码行数或AI宣称完成代替成果验收。","help":["范围过大无法收尾：按真实使用场景收缩为一个完整可运行链路，记录暂缓项。","不知道改哪里：先画出这次条件变化影响的数据和请求路径，再提出最小修改与验证计划。"],"related":["13.01","13.04","13.06"]}]};if(typeof module==='object'&&module.exports)module.exports=data;else root.AICourseData=data;})(typeof globalThis!=='undefined'?globalThis:this);
